module alu(
    input var [32:0] in_a,
    input var [32:0] in_b,
    input var [4:0] alu_op,

    output [31:0] rd_val_out,
    output lt,
    output ltu,
    output eq
);

    // Internal wires for intermediate calculations
    wire [32:0] in_b_twos_complement;
    wire [32:0] add_result;
    wire [32:0] sub_result;
    wire [32:0] xor_result;
    wire [32:0] or_result;
    wire [32:0] and_result;
    wire [32:0] lui_result;

    // Two's complement conversion for in_b
    assign in_b_twos_complement = ~in_b + 1;

    // Addition
    assign add_result = in_a + in_b;

    // Subtraction (using two's complement of in_b)
    assign sub_result = in_a + in_b_twos_complement;

    // XOR
    assign xor_result = in_a ^ in_b;

    // OR
    assign or_result = in_a | in_b;

    // AND
    assign and_result = in_a & in_b;

    // LUI (Load Upper Immediate)
    assign lui_result = {in_b[31:12], 12'b0};

    // Always_comb block to select the operation and compute the result
    always_comb begin
        case (alu_op)
            5'b00000: begin // Addition
                rd_val_out = add_result[31:0];
                lt = add_result[32];
                ltu = add_result[32];
                eq = (add_result == 0);
            end
            5'b00001: begin // Subtraction
                rd_val_out = sub_result[31:0];
                lt = sub_result[32];
                ltu = sub_result[32];
                eq = (sub_result == 0);
            end
            5'b00010: begin // Signed less than
                rd_val_out = 0;
                lt = sub_result[32];
                ltu = sub_result[32];
                eq = 0;
            end
            5'b00011: begin // Unsigned less than
                rd_val_out = 0;
                lt = 0;
                ltu = sub_result[32];
                eq = 0;
            end
            5'b00100: begin // XOR
                rd_val_out = xor_result[31:0];
                lt = 0;
                ltu = 0;
                eq = (xor_result == 0);
            end
            5'b00101: begin // OR
                rd_val_out = or_result[31:0];
                lt = 0;
                ltu = 0;
                eq = (or_result == 0);
            end
            5'b00110: begin // AND
                rd_val_out = and_result[31:0];
                lt = 0;
                ltu = 0;
                eq = (and_result == 0);
            end
            5'b00111: begin // LUI
                rd_val_out = lui_result[31:0];
                lt = 0;
                ltu = 0;
                eq = 0;
            end
            default: begin // Default case
                rd_val_out = 0;
                lt = 0;
                ltu = 0;
                eq = 0;
            end
        endcase
    end

endmodule

