module fsm_global
(   
	input wire					clk,
	input wire 					rst_n,
	input wire					clk_cam,

	input wire		[9:0]		input_wrusedw,
	input wire		[11:0]		output_rdusedw,
	input wire					VSYNC_cam,
	input wire					HREF_cam,
	output wire					p_VSYNC_cam,

	input wire					wr_input_fifo,
	output wire					rd_input_fifo,

	output wire					wr_strobe,
	output wire					rd_strobe,
	output wire					write_strobe,
	output wire					read_strobe,
	output wire					wait_strobe,
	output wire					idle_strobe,

	input wire					sd_ready,
	input wire					valid_data,

	input wire					STOP_capt
);

// State definitions
typedef enum reg [1:0] {IDLE, WAIT, READ, WRITE} state_t;
state_t current_state, next_state;

// Internal registers and counters
reg [31:0] counter;
reg [31:0] p_VSYNC_counter;

// Output strobes
assign wr_strobe = (current_state == WRITE) ? 1'b1 : 1'b0;
assign rd_strobe = (current_state == READ) ? 1'b1 : 1'b0;
assign write_strobe = (current_state == WRITE) ? 1'b1 : 1'b0;
assign read_strobe = (current_state == READ) ? 1'b1 : 1'b0;
assign wait_strobe = (current_state == WAIT) ? 1'b1 : 1'b0;
assign idle_strobe = (current_state == IDLE) ? 1'b1 : 1'b0;

// State transition logic
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		current_state <= IDLE;
	end else begin
		current_state <= next_state;
	end
end

always @(*) begin
	next_state = current_state;
	case (current_state)
		IDLE: begin
			if (VSYNC_cam && HREF_cam && valid_data && !STOP_capt) begin
				next_state = READ;
			end
		end
		READ: begin
			if (input_wrusedw < 1023) begin
				next_state = WRITE;
			end else begin
				next_state = WAIT;
			end
		end
		WRITE: begin
			if (output_rdusedw < 4095 && sd_ready) begin
				next_state = READ;
			end else begin
				next_state = WAIT;
			end
		end
		WAIT: begin
			if (input_wrusedw < 1023 && output_rdusedw < 4095 && sd_ready) begin
				next_state = READ;
			end
		end
	endcase
end

// VSYNC synchronization
always @(posedge clk_cam or negedge rst_n) begin
	if (!rst_n) begin
		p_VSYNC_counter <= 0;
		p_VSYNC_cam <= 1'b0;
	end else begin
		if (VSYNC_cam) begin
			p_VSYNC_counter <= p_VSYNC_counter + 1;
			if (p_VSYNC_counter == 10) begin
				p_VSYNC_cam <= 1'b1;
			end
		end else begin
			p_VSYNC_counter <= 0;
			p_VSYNC_cam <= 1'b0;
		end
	end
end

// FIFO control
assign wr_input_fifo = (current_state == READ) ? 1'b1 : 1'b0;
assign rd_input_fifo = (current_state == WRITE) ? 1'b1 : 1'b0;

endmodule

module mulsub_3_stage_signed_18_bit(
	input signed [17:0] a,
	input signed [17:0] b,
	input signed [17:0] c,
	output [17:0] out,
	input clk);

	// Internal signals for pipeline stages
	reg signed [35:0] stage0;
	reg signed [35:0] stage1;
	reg signed [35:0] stage2;

	// Internal signal for final output
	reg signed [17:0] out_reg;

	// Pipeline stages
	always @(posedge clk) begin
		// Stage 0: Compute the product of a and b, then subtract c
		stage0 <= (a * b) - c;

		// Stage 1: Pass the result from stage0 to stage1
		stage1 <= stage0;

		// Stage 2: Pass the result from stage1 to stage2
		stage2 <= stage1;

		// Output stage: Assign the result from stage2 to the output register
		out_reg <= stage2[35:18];
	end

	// Assign the final output
	assign out = out_reg;

endmodule

module mulsubsub_1_stage_signed_13_bit(
	input signed [12:0] a,
	input signed [12:0] b,
	input signed [12:0] c,
	input signed [12:0] d,
	output [12:0] out,
	input clk);

	// Internal 26-bit register to hold intermediate results
	reg signed [25:0] stage0;

	// Always block triggered on the rising edge of the clock
	always @(posedge clk) begin
		// Compute the product of a and b
		signed [25:0] product = a * b;

		// Compute the difference of c and d
		signed [12:0] difference = c - d;

		// Store the intermediate result in stage0
		stage0 <= product - difference;

		// Assign the final result to the output
		out <= stage0[12:0];
	end

endmodule

