module top_properties (input logic clock, read, write, ready);

  // Define the FAIL macro to specify the exact timing between write and ready
  `define FAIL 2

  // Assertion to check that read and write signals are not asserted simultaneously
  property read_write_exclusion;
    @(posedge clock) disable iff (!clock) !(read && write);
  endproperty

  // Monitor for read and write exclusion
  assert property (read_write_exclusion)
    else $error("Read and write signals are asserted simultaneously");

  // Assertion to check the timing relationship between write and ready
  property write_ready_timing;
    @(posedge clock) disable iff (!clock) write |-> ##`FAIL ready;
  endproperty

  // Monitor for write to ready timing
  assert property (write_ready_timing)
    else $error("Ready signal is not asserted within %0d clock cycles after write", `FAIL);

endmodule

