	input clk);

reg [31:0] stage0;
reg [31:0] stage1;

always @(posedge clk) begin
	// First stage: compute (d + a) * b + c
	stage0 <= (d + a) * b + c;

	// Second stage: store the result from stage0 to stage1
	stage1 <= stage0;
end

// XOR reduction on the 32-bit value in stage1
assign out = {15{stage1[0] ^ stage1[1] ^ stage1[2] ^ stage1[3] ^ stage1[4] ^ stage1[5] ^ stage1[6] ^ stage1[7] ^ stage1[8] ^ stage1[9] ^ stage1[10] ^ stage1[11] ^ stage1[12] ^ stage1[13] ^ stage1[14] ^ stage1[15] ^ stage1[16] ^ stage1[17] ^ stage1[18] ^ stage1[19] ^ stage1[20] ^ stage1[21] ^ stage1[22] ^ stage1[23] ^ stage1[24] ^ stage1[25] ^ stage1[26] ^ stage1[27] ^ stage1[28] ^ stage1[29] ^ stage1[30] ^ stage1[31]}};

endmodule

