module UART2(
	input wire ipClk,
	input wire ipReset,
	input wire [7:0] ipTxData,
	input wire ipTxSend,
	output reg opTxBusy,
	output reg opTx,
	input wire ipRx,
	output reg [7:0] opRxData,
	output reg opRxValid
);

	// Define states for transmit FSM
	typedef enum reg [1:0] {TxIdle, Sending, TxDone} TxStateType;
	TxStateType TxState, TxNextState;

	// Define states for receive FSM
	typedef enum reg [1:0] {RxIdle, Receiving, RxDone} RxStateType;
	RxStateType RxState, RxNextState;

	// Baud rate counters
	reg [8:0] TxBdCount;
	reg [8:0] RxBdCount;

	// Internal registers for transmission
	reg [7:0] TxShiftReg;
	reg [3:0] TxBitCount;

	// Internal registers for reception
	reg [7:0] RxShiftReg;
	reg [3:0] RxBitCount;

	// Transmission FSM
	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			TxState <= TxIdle;
			opTxBusy <= 0;
			opTx <= 1;
		end else begin
			TxState <= TxNextState;
		end
	end

	always @(*) begin
		TxNextState = TxState;
		case (TxState)
			TxIdle: begin
				if (ipTxSend) begin
					TxNextState = Sending;
					TxShiftReg = ipTxData;
					TxBitCount = 0;
					TxBdCount = 0;
				end
			end
			Sending: begin
				if (TxBdCount == 433) begin
					TxBdCount = 0;
					if (TxBitCount < 8) begin
						TxBitCount = TxBitCount + 1;
						opTx = TxShiftReg[7 - TxBitCount];
					end else begin
						TxNextState = TxDone;
						opTx = 1; // Stop bit
					end
				end else begin
					TxBdCount = TxBdCount + 1;
				end
			end
			TxDone: begin
				if (!ipTxSend) begin
					TxNextState = TxIdle;
				end
			end
		endcase
	end

	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			opTxBusy <= 0;
		end else begin
			case (TxState)
				TxIdle: opTxBusy <= 0;
				Sending: opTxBusy <= 1;
				TxDone: opTxBusy <= 0;
			endcase
		end
	end

	// Reception FSM
	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			RxState <= RxIdle;
			opRxValid <= 0;
			opRxData <= 0;
		end else begin
			RxState <= RxNextState;
		end
	end

	always @(*) begin
		RxNextState = RxState;
		case (RxState)
			RxIdle: begin
				if (!ipRx) begin
					RxNextState = Receiving;
					RxShiftReg = 0;
					RxBitCount = 0;
					RxBdCount = 0;
				end
			end
			Receiving: begin
				if (RxBdCount == 433) begin
					RxBdCount = 0;
					if (RxBitCount < 8) begin
						RxBitCount = RxBitCount + 1;
						RxShiftReg = {RxShiftReg[6:0], ipRx};
					end else begin
						RxNextState = RxDone;
					end
				end else begin
					RxBdCount = RxBdCount + 1;
				end
			end
			RxDone: begin
				RxNextState = RxIdle;
				opRxData = RxShiftReg;
				opRxValid = 1;
			end
		endcase
	end

	always @(posedge ipClk or posedge ipReset) begin
		if (ipReset) begin
			opRxValid <= 0;
		end else begin
			case (RxState)
				RxIdle: opRxValid <= 0;
				RxDone: opRxValid <= 1;
			endcase
		end
	end

endmodule

module submulxor_2_stage_signed_10_bit_xor_reduction(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	input signed [9:0] d,
	output [9:0] out,
	input clk);

	// Internal signals
	wire signed [19:0] stage0;
	wire signed [19:0] stage1;
	wire [9:0] xor_reduction;

	// Stage 0: Perform subtraction and multiplication
	always @(posedge clk) begin
		// Subtraction of a and b
		signed [19:0] sub_result = a - b;
		// Multiplication of c and d
		signed [19:0] mul_result = c * d;
		// Store the results in stage0
		stage0 <= sub_result + mul_result;
	end

	// Stage 1: XOR reduction of stage0
	always @(posedge clk) begin
		// XOR all bits of stage0 to produce a single bit result
		xor_reduction <= ^stage0;
		// Extend the single bit result to 10 bits as per the output declaration
		out <= {9{xor_reduction}, xor_reduction};
	end

endmodule

module mulsub_3_stage_unsigned_9_bit(
	input  [8:0] a,
	input  [8:0] b,
	input  [8:0] c,
	output [8:0] out,
	input clk);

// Internal 18-bit registers for pipelining
reg [17:0] stage0;
reg [17:0] stage1;
reg [17:0] stage2;

// Internal 9-bit wire for the final output
wire [8:0] final_out;

// Computation of (a * b) - c
assign stage0 = (a * b) - c;

// Pipelining logic
always @(posedge clk) begin
    stage1 <= stage0;
    stage2 <= stage1;
    final_out <= stage2[8:0]; // Only the lower 9 bits are relevant for the output
end

// Assign the final output to the module output
assign out = final_out;

endmodule

module submuladd_3_stage_signed_8_bit_xor_reduction(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	input signed [7:0] d,
	output [7:0] out,
	input clk);

	// Internal registers to store intermediate results
	reg signed [15:0] stage0;
	reg signed [15:0] stage1;
	reg signed [15:0] stage2;

	// Combinational logic for the first stage: (d - a) * b
	always @(*) begin
		stage0 = (d - a) * b;
	end

	// Combinational logic for the second stage: stage0 + c
	always @(*) begin
		stage1 = stage0 + c;
	end

	// Combinational logic for the third stage: pass through stage1
	always @(*) begin
		stage2 = stage1;
	end

	// Sequential logic to shift results through the pipeline
	always @(posedge clk) begin
		stage0 <= stage0;
		stage1 <= stage1;
		stage2 <= stage2;
	end

	// XOR reduction on the 16-bit result from the third stage
	always @(*) begin
		out = 8'b0;
		for (int i = 0; i < 16; i = i + 1) begin
			out = out ^ stage2[i];
		end
	end

endmodule

module mulor_2_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);

reg signed [15:0] stage0;
reg signed [15:0] stage1;

always @(posedge clk) begin
	// First stage: Multiply a and b
	stage0 <= a * b;

	// Second stage: Perform bitwise OR with c and store the result
	stage1 <= stage0 | c;
end

// Output is the lower 8 bits of the final result
assign out = stage1[7:0];

endmodule

module addmulsub_1_stage_unsigned_11_bit(
	input  [10:0] a,
	input  [10:0] b,
	input  [10:0] c,
	input  [10:0] d,
	output [10:0] out,
	input clk);

reg [21:0] stage0;

always @(posedge clk) begin
	// Step 1: Add a and d
	reg [11:0] sum_ad = a + d;

	// Step 2: Multiply the result by b
	stage0 = sum_ad * b;

	// Step 3: Subtract c from the result of the multiplication
	stage0 = stage0 - c;

	// Step 4: Assign the lower 11 bits of stage0 to the output
	out = stage0[10:0];
end

endmodule

module mulsub_2_stage_unsigned_10_bit(
	input  [9:0] a,
	input  [9:0] b,
	input  [9:0] c,
	output [9:0] out,
	input clk);

	// Internal 20-bit registers to store intermediate results
	reg [19:0] stage0;
	reg [9:0] stage1;

	// Internal wire to hold the intermediate multiplication result
	wire [19:0] product;

	// Calculate the product of a and b
	assign product = a * b;

	// First stage: compute (a * b) - c and store in stage0
	always @(posedge clk) begin
		stage0 <= product - c;
	end

	// Second stage: store the result from stage0 into stage1
	always @(posedge clk) begin
		stage1 <= stage0[9:0]; // Only the lower 10 bits are needed for the final output
	end

	// Assign the final result to the output
	assign out = stage1;

endmodule

module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
    // Define the array of keypress values
    reg [9:0] keypress_array [0:9] = {
        10'b0000000001, // Example keypress values
        10'b0000000010,
        10'b0000000100,
        10'b0000001000,
        10'b0000010000,
        10'b0000100000,
        10'b0001000000,
        10'b0010000000,
        10'b0100000000,
        10'b1000000000
    };

    // Internal registers
    reg [3:0] index; // Index to track the current key
    reg [4:0] counter; // Counter to delay each keypress

    // State machine states
    typedef enum reg [1:0] {
        IDLE,
        DELAY,
        OUTPUT
    } state_t;

    state_t state, next_state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            index <= 4'b0;
            counter <= 5'b0;
            keypress <= 10'b0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (index < 10) begin
                    next_state = DELAY;
                end
            end
            DELAY: begin
                if (counter == 19) begin
                    next_state = OUTPUT;
                end
            end
            OUTPUT: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output and counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            keypress <= 10'b0;
            counter <= 5'b0;
        end else begin
            case (state)
                DELAY: begin
                    counter <= counter + 1;
                end
                OUTPUT: begin
                    keypress <= keypress_array[index];
                    index <= index + 1;
                    counter <= 5'b0;
                end
            endcase
        end
    end
endmodule

