	always @(*) begin
		// Compute (d - a) * b
		signed [17:0] temp = (d - a) * b;
		// Compute ((d - a) * b) ^ c
		stage0 = temp ^ c;
	end

	// Sequential logic for the pipeline stages
	always @(posedge clk) begin
