	input  [7:0] b,
	input  [7:0] c,
	input  [7:0] d,
	output [7:0] out,
	input clk);

reg [15:0] stage0, stage1, stage2;

always @(posedge clk) begin
	// Stage 0: Perform subtraction (a - b) and store in stage0
	stage0 <= {8'b0, a} - {8'b0, b};

	// Stage 1: Perform multiplication (stage0 * c) and store in stage1
	stage1 <= stage0 * {8'b0, c};

	// Stage 2: Perform subtraction (stage1 - d) and store in stage2
	stage2 <= stage1 - {8'b0, d};
end

// XOR reduction of the final stage's value
assign out = ^stage2;

endmodule

