module top (
    input clk,
    output bit led1_n,
    output bit led2_n,
    output bit led3_n,
    output bit led4_n,
    output bit led5_n
);

    // Registers for VRAM access address components
    reg [9:0] vram_access_y;
    reg [8:0] vram_access_x;
    reg [17:0] vram_access_addr;

    // Sequential logic to update the address components and compute the address
    always @(posedge clk) begin
        // Increment the x counter
        vram_access_x <= vram_access_x + 1;

        // Check if x counter has reached its maximum value
        if (vram_access_x == 359) begin
            // Reset x counter and increment y counter
            vram_access_x <= 0;
            vram_access_y <= vram_access_y + 1;

            // Check if y counter has reached its maximum value
            if (vram_access_y == 1023) begin
                // Reset y counter
                vram_access_y <= 0;
            end
        end

        // Compute the VRAM access address
        vram_access_addr <= (vram_access_y * 360 * 2) + (vram_access_x * 2);
    end

    // Assign the 17th bit of the address to led1_n
    assign led1_n = vram_access_addr[17];

    // Assign 0 to the other LEDs
    assign led2_n = 0;
    assign led3_n = 0;
    assign led4_n = 0;
    assign led5_n = 0;

endmodule

