module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);

logic [WIDTH-1:0] dat0, dat1;
logic [2:0] state;
logic dat0_full, dat1_full;

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
		dat0 <= '0;
		dat1 <= '0;
		dat0_full <= 0;
		dat1_full <= 0;
	end else begin
		case (state)
			S0: begin
				if (t0_valid && !dat0_full) begin
					dat0 <= t0_data;
					dat0_full <= 1;
					state <= S1;
				end
			end
			S1: begin
				if (i0_ready) begin
					i0_data <= dat0;
					i0_valid <= 1;
					dat0_full <= 0;
					state <= S2;
				end
			end
			S2: begin
				if (t0_valid && !dat1_full) begin
					dat1 <= t0_data;
					dat1_full <= 1;
					state <= S3;
				end else if (i0_ready) begin
					i0_valid <= 0;
					state <= S0;
				end
			end
			S3: begin
				if (i0_ready) begin
					i0_data <= dat1;
					i0_valid <= 1;
					dat1_full <= 0;
					state <= S4;
				end
			end
			S4: begin
				if (t0_valid && !dat0_full) begin
					dat0 <= t0_data;
					dat0_full <= 1;
					state <= S1;
				end else if (i0_ready) begin
					i0_valid <= 0;
					state <= S2;
				end
			end
			default: state <= S0;
		endcase
	end
end

assign t0_ready = (state == S0 || state == S2) && !(dat0_full || dat1_full);
assign i0_data = (state == S1) ? dat0 : dat1;

endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [$clog2(DEPTH)-1:0] write_ptr, read_ptr;
    reg [$clog2(DEPTH):0] word_count;

    assign prog_full = (word_count >= PROG_FULL);
    assign full = (word_count == DEPTH);
    assign empty = (word_count == 0);

    always @(posedge clk or posedge reset_p) begin
        if (reset_p) begin
            write_ptr <= 0;
            read_ptr <= 0;
            word_count <= 0;
            overflow <= 0;
            underflow <= 0;
        end else begin
            if (data_we && !full) begin
                mem[write_ptr] <= data_i;
                write_ptr <= (write_ptr + 1) % DEPTH;
                word_count <= word_count + 1;
                if (word_count == DEPTH - 1) begin
                    overflow <= 1;
                end
            end

            if (data_rd && !empty) begin
                data_o <= mem[read_ptr];
                read_ptr <= (read_ptr + 1) % DEPTH;
                word_count <= word_count - 1;
                if (word_count == 1) begin
                    underflow <= 1;
                end
            end

            if (data_we && data_rd) begin
                // No change in word_count if both read and write happen simultaneously
            end
        end
    end

endmodule

module submulor_2_stage_unsigned_10_bit(
