module vga_ctrl(
    input wire pixel_clk,
    output wire hsync,
    output wire vsync,
    output wire [9:0] pixel_x,
    output wire [9:0] pixel_y,
    output wire visible_region
);

    // Parameters for VGA timing
    parameter H_TOTAL = 800; // Total horizontal pixels
    parameter H_SYNC_START = 656; // Horizontal sync start
    parameter H_SYNC_END = 752; // Horizontal sync end
    parameter H_ACTIVE = 640; // Horizontal active pixels

    parameter V_TOTAL = 525; // Total vertical lines
    parameter V_SYNC_START = 490; // Vertical sync start
    parameter V_SYNC_END = 492; // Vertical sync end
    parameter V_ACTIVE = 480; // Vertical active lines

    // Horizontal and vertical counters
    reg [9:0] h_count;
    reg [9:0] v_count;

    // Synchronization signals
    reg hsync_reg;
    reg vsync_reg;

    // Visible region flag
    reg visible_region_reg;

    // Horizontal counter logic
    always @(posedge pixel_clk) begin
        if (h_count == H_TOTAL - 1) begin
            h_count <= 0;
            if (v_count == V_TOTAL - 1) begin
                v_count <= 0;
            end else begin
                v_count <= v_count + 1;
            end
        end else begin
            h_count <= h_count + 1;
        end
    end

    // Synchronization signal generation
    always @(posedge pixel_clk) begin
        if (h_count >= H_SYNC_START && h_count < H_SYNC_END) begin
            hsync_reg <= 0;
        end else begin
            hsync_reg <= 1;
        end

        if (v_count >= V_SYNC_START && v_count < V_SYNC_END) begin
            vsync_reg <= 0;
        end else begin
            vsync_reg <= 1;
        end
    end

    // Visible region detection
    always @(posedge pixel_clk) begin
        if (h_count < H_ACTIVE && v_count < V_ACTIVE) begin
            visible_region_reg <= 1;
        end else begin
            visible_region_reg <= 0;
        end
    end

    // Assign outputs
    assign hsync = hsync_reg;
    assign vsync = vsync_reg;
    assign pixel_x = h_count;
    assign pixel_y = v_count;
    assign visible_region = visible_region_reg;

endmodule

