module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
);

    parameter CLK_F = 32; // Prescaler division factor

    reg [4:0] prescaler; // 5-bit prescaler to divide the clock
    reg [31:0] counter;   // 32-bit counter to track the period

    always @(posedge CLK) begin
        // Increment the prescaler
        if (prescaler < CLK_F - 1)
            prescaler <= prescaler + 1;
        else
            prescaler <= 0;

        // Increment the counter when prescaler reaches its maximum
        if (prescaler == CLK_F - 1) begin
            if (counter < period - 1)
                counter <= counter + 1;
            else
                counter <= 0;

            // Toggle the tone output when the counter reaches the period
            if (counter == period - 1)
                tone_out <= ~tone_out;
        end
    end

endmodule

