        sp <= 2047;
        pc_high <= 16'h0000; // Example initial value for PC high part
        pc_low <= 16'h0000;  // Example initial value for PC low part
        ccr <= 0;
    end

    // Sequential logic for register operations
    always @(posedge clk) begin
        if (rst) begin
            // Reset logic
            integer i;
            for (i = 0; i < REG_NUMBER; i = i + 1) begin
                general_regs[i] <= 0;
            end
            sp <= 2047;
            pc_high <= 16'h0000; // Example initial value for PC high part
            pc_low <= 16'h0000;  // Example initial value for PC low part
            ccr <= 0;
        end else begin
            // Write operations
            if (Data_write1) begin
