module im2_control(
    input wire i_CLK_CPU,
    input wire i_reset,
    input wire i_m1_n,
    input wire i_mreq_n,
    input wire i_iorq_n,
    input wire i_rfsh_n,
    input wire [7:0] i_cpu_d,
    output wire o_reti_decode,
    output wire o_reti_seen
);

    // State definitions
    parameter S_0 = 2'b00;
    parameter S_ED_T4 = 2'b01;
    parameter S_4D_T4 = 2'b10;
    parameter S_CB_T4 = 2'b11;

    // Internal signals
    reg [1:0] current_state, next_state;
    reg ifetch_d;
    reg [7:0] cpu_opcode;
    wire ifetch;
    wire ifetch_cancel;

    // Assignments for fetch and cancel conditions
    assign ifetch = ~i_m1_n & ~i_mreq_n & ~i_iorq_n & ~i_rfsh_n;
    assign ifetch_cancel = i_rfsh_n;

    // State machine
    always @(posedge i_CLK_CPU or posedge i_reset) begin
        if (i_reset) begin
            current_state <= S_0;
            ifetch_d <= 0;
            cpu_opcode <= 8'b00000000;
        end else begin
            current_state <= next_state;
            if (ifetch) begin
                ifetch_d <= 1;
                cpu_opcode <= i_cpu_d;
            end else if (ifetch_cancel) begin
                ifetch_d <= 0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            S_0: begin
                if (ifetch_d && cpu_opcode == 8'hED) begin
                    next_state = S_ED_T4;
                end else if (ifetch_d && cpu_opcode == 8'h4D) begin
                    next_state = S_4D_T4;
                end else if (ifetch_d && cpu_opcode == 8'hCB) begin
                    next_state = S_CB_T4;
                end
            end
            S_ED_T4: begin
                if (ifetch_cancel) begin
                    next_state = S_0;
                end
            end
            S_4D_T4: begin
                if (ifetch_cancel) begin
                    next_state = S_0;
                end
            end
            S_CB_T4: begin
                if (ifetch_cancel) begin
                    next_state = S_0;
                end
            end
        endcase
    end

    // Output logic
    assign o_reti_decode = (current_state == S_ED_T4) || (current_state == S_4D_T4) || (current_state == S_CB_T4);
    assign o_reti_seen = (current_state == S_0) && ifetch_d;

endmodule

