module round
  #(parameter bits_in=0,
    parameter bits_out=0,
    parameter round_to_zero=0,       
    parameter round_to_nearest=1,    
    parameter trunc=0)               
    (input [bits_in-1:0] in,
     output [bits_out-1:0] out,
     output [bits_in-bits_out:0] err);

  // Internal signals
  wire [bits_in-bits_out:0] discarded_bits;
  wire [bits_in-bits_out:0] correction_value;
  wire [bits_in:0] temp_out;
  wire [bits_in:0] temp_err;

  // Assign discarded bits
  assign discarded_bits = in[bits_out-1:0];

  // Determine correction value based on rounding mode
  generate
    if (trunc) begin : trunc_case
      assign correction_value = 0;
    end else if (round_to_zero) begin : round_to_zero_case
      assign correction_value = 0;
    end else if (round_to_nearest) begin : round_to_nearest_case
      assign correction_value = (discarded_bits > (1 << (bits_in-bits_out-1))) ? 1 : 0;
    end else begin : default_case
      assign correction_value = 0; // Default to truncation if no valid mode is selected
    end
  endgenerate

  // Compute temporary output and error
  assign temp_out = {in[bits_in-1:bits_out], correction_value};
  assign temp_err = in - temp_out;

  // Assign final output and error
  assign out = temp_out[bits_in:bits_out];
  assign err = temp_err;

endmodule

module add_1_bit(
