    input wire x,
    input wire y,
    input wire cin,
    output reg sum,
    output reg cout
);

always @(posedge clk) begin
    // Calculate sum using XOR logic
    sum <= x ^ y ^ cin;

    // Calculate carry-out using AND and OR logic
    cout <= (x & y) | (y & cin) | (cin & x);
end

