module spdr_uart_framer
(
    input clk_50,
    input rst,

    output reg tx_busy,
    input tx_vld,
    input [7:0] tx_data,

    output rx_vld,
    output [7:0] rx_data,
    output reg rx_frame_error,

    output uart_tx,
    input uart_rx
);

    // Parameters
    parameter CLK_DIV = 104166; // 50 MHz / 4800 bps = 104166.67, rounded to 104166

    // Internal signals
    reg [15:0] tx_shift_reg;
    reg [15:0] rx_shift_reg;
    reg [15:0] sampling_clk_div;
    reg [3:0] tx_bit_count;
    reg [3:0] rx_bit_count;
    reg tx_start;
    reg rx_start;
    reg rx_sample;
    reg [7:0] rx_sample_buffer;

    // Transmission logic
    always @(posedge clk_50 or posedge rst) begin
        if (rst) begin
            tx_busy <= 0;
            tx_shift_reg <= 0;
            tx_bit_count <= 0;
            tx_start <= 0;
            uart_tx <= 1;
        end else begin
            if (tx_vld && !tx_busy) begin
                tx_busy <= 1;
                tx_shift_reg <= {1'b1, tx_data, 1'b0}; // Start bit, data, stop bit
                tx_bit_count <= 0;
                tx_start <= 1;
            end else if (tx_busy) begin
                if (tx_start) begin
                    uart_tx <= tx_shift_reg[15];
                    tx_shift_reg <= {tx_shift_reg[14:0], 1'b0};
                    tx_start <= 0;
                end else begin
                    uart_tx <= tx_shift_reg[15];
                    tx_shift_reg <= {tx_shift_reg[14:0], 1'b0};
                    tx_bit_count <= tx_bit_count + 1;
                    if (tx_bit_count == 10) begin // 10 bits: 1 start, 8 data, 1 stop
                        tx_busy <= 0;
                    end
                end
            end
        end
    end

    // Reception logic
    always @(posedge clk_50 or posedge rst) begin
        if (rst) begin
            rx_vld <= 0;
            rx_data <= 0;
            rx_frame_error <= 0;
            rx_shift_reg <= 0;
            rx_bit_count <= 0;
            rx_start <= 0;
            rx_sample <= 0;
            rx_sample_buffer <= 0;
        end else begin
            if (rx_start) begin
                rx_sample_buffer <= {rx_sample_buffer[6:0], uart_rx};
                rx_shift_reg <= {rx_shift_reg[14:0], rx_sample};
                rx_bit_count <= rx_bit_count + 1;
                if (rx_bit_count == 10) begin // 10 bits: 1 start, 8 data, 1 stop
                    rx_vld <= 1;
                    rx_data <= rx_shift_reg[8:1];
                    rx_frame_error <= (rx_shift_reg[0] != 1'b1) || (rx_shift_reg[9] != 1'b0);
                    rx_start <= 0;
                end
            end else if (uart_rx == 1'b0) begin
                rx_start <= 1;
                rx_bit_count <= 0;
            end else begin
                rx_vld <= 0;
            end
        end
    end

    // Sampling clock divider
    always @(posedge clk_50 or posedge rst) begin
        if (rst) begin
            sampling_clk_div <= 0;
            rx_sample <= 0;
        end else begin
            if (sampling_clk_div == CLK_DIV - 1) begin
                sampling_clk_div <= 0;
                rx_sample <= uart_rx;
            end else begin
                sampling_clk_div <= sampling_clk_div + 1;
            end
        end
    end

endmodule

module CAS(
	input [3:0] IN,
	output [3:0] OUT
	);

// OUT[0] is generated by a more complex expression involving three input bits
// Let's assume OUT[0] = (IN[0] & IN[1]) | (IN[2] ^ IN[3])
assign OUT[0] = (IN[0] & IN[1]) | (IN[2] ^ IN[3]);

// OUT[1] serves as a parity bit, representing the XOR of all four input bits
assign OUT[1] = IN[0] ^ IN[1] ^ IN[2] ^ IN[3];

// OUT[2] and OUT[3] are direct copies of IN[1] and IN[0], respectively
assign OUT[2] = IN[1];
assign OUT[3] = IN[0];

endmodule

