module mode0(
    input wire clk_i,
    input wire [9:0] pix_x_i,
    input wire [9:0] pix_y_i,
    output reg [16:0] vram_addr_o,
    input wire [7:0] vram_rd_data_i,
    output reg [7:0] pal_addr_o,
    input wire [11:0] pal_rd_data_i,
    input wire [16:0] mapbase_i,
    input wire [16:0] tilebase_i,
    output reg [11:0] col_o,
    output reg [9:0] delay_o
);

    // Registers for pipeline stages
    reg [9:0] pix_x_0r, pix_x_1r, pix_x_2r, pix_x_3r, pix_x_4r;
    reg [9:0] pix_y_0r, pix_y_1r, pix_y_2r, pix_y_3r, pix_y_4r;
    reg [16:0] map_addr_r, tile_addr_r;
    reg [7:0] tile_data_r;
    reg [16:0] color_addr_r;

    // Internal wires
    wire [2:0] mode;
    wire [15:0] map_data;
    wire [15:0] tile_data;
    wire [11:0] color;

    // Assign mode based on the lower 3 bits of pix_x_i
    assign mode = pix_x_i[2:0];

    // Pipeline stage 0: Store input pixel coordinates
    always @(posedge clk_i) begin
        pix_x_0r <= pix_x_i;
        pix_y_0r <= pix_y_i;
    end

    // Pipeline stage 1: Compute map address and read map data
    always @(posedge clk_i) begin
        pix_x_1r <= pix_x_0r;
        pix_y_1r <= pix_y_0r;
        map_addr_r <= mapbase_i + {pix_y_0r, pix_x_0r[9:3]};
        map_data <= vram_rd_data_i;
    end

    // Pipeline stage 2: Compute tile address and read tile data
    always @(posedge clk_i) begin
        pix_x_2r <= pix_x_1r;
        pix_y_2r <= pix_y_1r;
        tile_addr_r <= tilebase_i + {map_data[15:12], pix_x_0r[2:0]};
        tile_data_r <= vram_rd_data_i;
    end

    // Pipeline stage 3: Compute color address and read color data
    always @(posedge clk_i) begin
        pix_x_3r <= pix_x_2r;
        pix_y_3r <= pix_y_2r;
        color_addr_r <= {tile_data_r[15:12], pix_x_0r[2:0]};
        color <= pal_rd_data_i;
    end

    // Pipeline stage 4: Output final color and delay
    always @(posedge clk_i) begin
        pix_x_4r <= pix_x_3r;
        pix_y_4r <= pix_y_3r;
        col_o <= color;
        delay_o <= pix_x_4r;
    end

    // Address generation logic
    always @(*) begin
        case (mode)
            3'b000: vram_addr_o = map_addr_r;
            3'b001: vram_addr_o = tile_addr_r;
            3'b010: vram_addr_o = color_addr_r;
            default: vram_addr_o = 17'b0;
        endcase
    end

    // Palette address output
    assign pal_addr_o = color_addr_r[7:0];

endmodule

