module clk_div(
    input wire clk_i,
    output reg clk_o,
    output wire [1:0] count_o
);

reg [1:0] count;

always @(posedge clk_i) begin
    // Increment the counter on each rising edge of the input clock
    count <= count + 1;

    // Determine the output clock based on the counter value
    case (count)
        2'b00, 2'b11: clk_o <= 1'b0; // clk_o is low for count 00 and 11
        2'b01, 2'b10: clk_o <= 1'b1; // clk_o is high for count 01 and 10
    endcase
end

// Assign the current state of the counter to the output
assign count_o = count;

endmodule

module hardcopyiv_hssi_aux_clock_div (
    clk,     
    reset,   
    enable_d, 
    d,        
    clkout   
);
    input clk, reset;
    input enable_d;
    input [7:0] d;
    output clkout;

    reg [7:0] current_divide_by;
    reg [7:0] counter;
    reg clkout_reg;

    // Default division factor
    parameter clk_divide_by = 8;
    parameter extra_latency = 2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_divide_by <= clk_divide_by;
            counter <= 0;
            clkout_reg <= 0;
        end else if (enable_d) begin
            // Update division factor if enable_d is high
            current_divide_by <= d;
            counter <= 0;
            clkout_reg <= 0;
        end else begin
            // Count clock edges
            if (counter < current_divide_by - 1) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                clkout_reg <= ~clkout_reg; // Toggle output
            end
        end
    end

    // Apply extra latency
    reg [extra_latency-1:0] latency_reg;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            latency_reg <= {extra_latency{1'b0}};
        end else begin
            latency_reg <= {latency_reg[extra_latency-2:0], clkout_reg};
        end
    end

    assign clkout = latency_reg[extra_latency-1];
endmodule

