module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
                     over_time, over_weight, weight_alert, door_alert, out_current_floor) ;

    input [7:0] request_floor; 
    input [7:0] in_current_floor; 
    input clk; 
    input reset; 
    input over_time; 
    input over_weight; 

    output direction; 
    output complete;
    output door_alert;
    output weight_alert;
    output [7:0] out_current_floor;

    reg [7:0] current_floor;
    reg dir;
    reg comp;
    reg door_alert_reg;
    reg weight_alert_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_floor <= in_current_floor;
            dir <= 0;
            comp <= 0;
            door_alert_reg <= 0;
            weight_alert_reg <= 0;
        end else if (over_time || over_weight) begin
            // Safety conditions: halt movement and issue alerts
            dir <= 0;
            comp <= 0;
            door_alert_reg <= over_time;
            weight_alert_reg <= over_weight;
        end else begin
            // Normal operation
            if (request_floor > current_floor) begin
                current_floor <= current_floor + 1;
                dir <= 1;
                comp <= 0;
            end else if (request_floor < current_floor) begin
                current_floor <= current_floor - 1;
                dir <= 0;
                comp <= 0;
            end else begin
                // Requested floor reached
                dir <= 0;
                comp <= 1;
            end
            door_alert_reg <= 0;
            weight_alert_reg <= 0;
        end
    end

    assign direction = dir;
    assign complete = comp;
    assign door_alert = door_alert_reg;
    assign weight_alert = weight_alert_reg;
    assign out_current_floor = current_floor;

endmodule

