module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// State definitions
typedef enum logic [1:0] {ZERO, ONE, TWO} state_t;
state_t state, next_state;

// Data registers
reg [N-1:0] data_p1, data_p2;

// State register
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    case (state)
        ZERO: begin
            if (s_valid && m_ready) begin
                next_state = ONE;
            end else if (s_valid) begin
                next_state = ONE;
            end else begin
                next_state = ZERO;
            end
        end
        ONE: begin
            if (m_ready) begin
                next_state = TWO;
            end else begin
                next_state = ONE;
            end
        end
        TWO: begin
            if (m_ready) begin
                next_state = ZERO;
            end else begin
                next_state = TWO;
            end
        end
        default: next_state = ZERO;
    endcase
end

// Data pipeline logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= 0;
        data_p2 <= 0;
    end else begin
        case (state)
            ZERO: begin
                if (s_valid) begin
                    data_p1 <= s_data;
                end
            end
            ONE: begin
                if (s_valid) begin
                    data_p1 <= s_data;
                end
                data_p2 <= data_p1;
            end
            TWO: begin
                data_p2 <= data_p1;
            end
        endcase
    end
end

// Output assignments
assign s_ready = (state == ZERO) ? m_ready : 1'b0;
assign m_data = (state == ONE) ? data_p1 : (state == TWO) ? data_p2 : 0;
assign m_valid = (state == ONE) ? 1'b1 : (state == TWO) ? 1'b1 : 1'b0;

endmodule

