module shift_16_9 (
    input [15:0] x,
    input [15:0] y,
    input [1:0] shiftAlufn,
    output reg [15:0] shiftOut
  );

  reg [15:0] temp;
  reg [3:0] shiftAmount;

  always @(*) begin
    shiftAmount = y[3:0];
    case (shiftAlufn)
      2'b00: temp = x << shiftAmount; // Left shift
      2'b01: temp = x >> shiftAmount; // Right shift
      2'b10: temp = $signed(x) >>> shiftAmount; // Signed right shift
      2'b11: temp = $signed(x) << shiftAmount; // Signed left shift
      default: temp = 16'b0; // Default to zero for invalid control inputs
    endcase
    shiftOut = temp;
  end

endmodule

module AXI_WRITE_DATA_CHANNEL_model(
    input wire clk,
    input wire resetn,
    input wire [31:0] data,
    input wire go,
    output reg done,
    output wire [31:0] WDATA,
    output reg [3:0] WSTRB,
    output reg WVALID,
    input wire WREADY
);

    // State definitions
    typedef enum reg [1:0] {
        RESET,
        IDLE,
        RUNNING,
        COMPLETE
    } state_t;

    // State registers
    state_t current_state, next_state;

    // State transition logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_state <= RESET;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            RESET: begin
                if (resetn) begin
                    next_state = IDLE;
                end else begin
                    next_state = RESET;
                end
            end
            IDLE: begin
                if (go) begin
                    next_state = RUNNING;
                end else begin
                    next_state = IDLE;
                end
            end
            RUNNING: begin
                if (WREADY) begin
                    next_state = COMPLETE;
                end else begin
                    next_state = RUNNING;
                end
            end
            COMPLETE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = RESET;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        done = 0;
        WDATA = 32'b0;
        WSTRB = 4'b0;
        WVALID = 0;

        case (current_state)
            RESET: begin
                // No action needed in reset state
            end
            IDLE: begin
                // No action needed in idle state
            end
            RUNNING: begin
                WDATA = data;
                WSTRB = 4'b1111; // Assuming all bytes are valid
                WVALID = 1;
            end
            COMPLETE: begin
                done = 1;
                WVALID = 0;
            end
        endcase
    end

endmodule

