module reg_map (
    input               i_clk,
    input               i_rst_n,
    input       [15:0]  i_addr,
    input       [15:0]  i_wdata,
    input               i_wen,
    output  reg [15:0]  o_q,
    output  reg [15:0]  o_reg0000,
    output  reg [15:0]  o_reg0002,
    output  reg [15:0]  o_reg0004,
    output  reg [15:0]  o_reg0006
);

    // Internal register array
    reg [15:0] registers [0:6];

    // Decode logic
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            // Reset all registers to zero
            registers[0] <= 16'h0000;
            registers[1] <= 16'h0000;
            registers[2] <= 16'h0000;
            registers[3] <= 16'h0000;
            registers[4] <= 16'h0000;
            registers[5] <= 16'h0000;
            registers[6] <= 16'h0000;
        end else begin
            // Write operation
            if (i_wen) begin
                case (i_addr)
                    16'h0000: registers[0] <= i_wdata;
                    16'h0002: registers[1] <= i_wdata;
                    16'h0004: registers[2] <= i_wdata;
                    16'h0006: registers[3] <= i_wdata;
                    default: ; // No action for other addresses
                endcase
            end
        end
    end

    // Read operation
    always @(*) begin
        case (i_addr)
            16'h0000: o_q = registers[0];
            16'h0002: o_q = registers[1];
            16'h0004: o_q = registers[2];
            16'h0006: o_q = registers[3];
            default: o_q = 16'h0000; // Default read value
        endcase
    end

    // Assign output registers
    assign o_reg0000 = registers[0];
    assign o_reg0002 = registers[1];
    assign o_reg0004 = registers[2];
    assign o_reg0006 = registers[3];

endmodule

module submulxor_0_stage_signed_12_bit(
	input signed [11:0] a,
	input signed [11:0] b,
	input signed [11:0] c,
	input signed [11:0] d,
	output [11:0] out
	);

	// Step 1: Subtract a from d
	wire signed [11:0] sub_result;
	assign sub_result = d - a;

	// Step 2: Multiply the result of the subtraction by b
	wire signed [23:0] mul_result;
	assign mul_result = sub_result * b;

	// Step 3: Perform XOR with c
	wire signed [11:0] xor_result;
	assign xor_result = mul_result[11:0] ^ c;

	// Assign the final result to the output
	assign out = xor_result;

endmodule

module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);

  // State definition
  typedef enum logic [1:0] {IDLE, DATA0, DATA1} state_t;
  state_t state, next_state;

  // Internal signals
  logic match;
  logic [35:0] data_reg;

  // Combinational logic for state transition
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (src_rdy_i && (data_i & match_mask) == match_data) begin
          next_state = DATA0;
        end else if (src_rdy_i && (data_i & match_mask) != match_data) begin
          next_state = DATA1;
        end
      end
      DATA0: begin
        if (dst0_rdy_i) begin
          next_state = IDLE;
        end
      end
      DATA1: begin
        if (dst1_rdy_i) begin
          next_state = IDLE;
        end
      end
    endcase
  end

  // Sequential logic for state register
  always_ff @(posedge clk or posedge reset or posedge clear) begin
    if (reset || clear) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Combinational logic for output generation
  always_comb begin
    data0_o = 36'b0;
    data1_o = 36'b0;
    src0_rdy_o = 1'b0;
    src1_rdy_o = 1'b0;
    dst_rdy_o = 1'b0;

    case (state)
      IDLE: begin
        dst_rdy_o = 1'b1;
      end
      DATA0: begin
        data0_o = data_i;
        src0_rdy_o = dst0_rdy_i;
      end
      DATA1: begin
        data1_o = data_i;
        src1_rdy_o = dst1_rdy_i;
      end
    endcase
  end

endmodule

