module control(
    input [5:0] op,
    input [5:0] func,
    output [3:0] aluop,
    output memtoreg,
    output memwrite,
    output alusrc,
    output regwrite,
    output syscall,
    output signedext,
    output regdst,
    output beq,
    output bne,
    output jr,
    output jmp,
    output jal,
    output srlv,
    output srav,
    output lh,
    output blez
);

// Initialize all outputs to 0
assign aluop = 4'b0000;
assign memtoreg = 1'b0;
assign memwrite = 1'b0;
assign alusrc = 1'b0;
assign regwrite = 1'b0;
assign syscall = 1'b0;
assign signedext = 1'b0;
assign regdst = 1'b0;
assign beq = 1'b0;
assign bne = 1'b0;
assign jr = 1'b0;
assign jmp = 1'b0;
assign jal = 1'b0;
assign srlv = 1'b0;
assign srav = 1'b0;
assign lh = 1'b0;
assign blez = 1'b0;

// Decode logic
always @(*) begin
    case (op)
        6'b000000: // R-type instructions
            case (func)
                6'b000000: aluop = 4'b0000; // SLL
                6'b000010: aluop = 4'b0001; // SRL
                6'b000011: aluop = 4'b0010; // SRA
                6'b100000: aluop = 4'b0011; // ADD
                6'b100010: aluop = 4'b0100; // SUB
                6'b100100: aluop = 4'b0101; // AND
                6'b100101: aluop = 4'b0110; // OR
                6'b100111: aluop = 4'b0111; // NOR
                6'b001000: aluop = 4'b1000; // JR
                6'b000100: aluop = 4'b1001; // SLLV
                6'b000110: aluop = 4'b1010; // SRLV
                6'b000111: aluop = 4'b1011; // SRAV
                default: aluop = 4'b0000;
            endcase
            regwrite = 1'b1;
            regdst = 1'b1;

        6'b001000: // ADDI
            aluop = 4'b0011;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b001100: // ANDI
            aluop = 4'b0101;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b100011: // LW
            memtoreg = 1'b1;
            aluop = 4'b0011;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b101011: // SW
            aluop = 4'b0011;
            alusrc = 1'b1;
            memwrite = 1'b1;

        6'b000100: // BEQ
            aluop = 4'b0100;
            beq = 1'b1;

        6'b000101: // BNE
            aluop = 4'b0100;
            bne = 1'b1;

        6'b000010: // J
            jmp = 1'b1;

        6'b000011: // JAL
            jal = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b1;

        6'b001101: // ORI
            aluop = 4'b0110;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b001110: // XORI
            aluop = 4'b1000;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b001111: // LUI
            aluop = 4'b1001;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b100100: // LH
            lh = 1'b1;
            memtoreg = 1'b1;
            aluop = 4'b0011;
            alusrc = 1'b1;
            regwrite = 1'b1;
            regdst = 1'b0;

        6'b000110: // BLEZ
            aluop = 4'b0100;
            blez = 1'b1;

        6'b001111: // SYSCALL
            syscall = 1'b1;

        default:
            aluop = 4'b0000;
    endcase
end

endmodule

