module cla8(a, b, cin, s, cout);
    input [7:0] a, b;
    input cin;
    output [7:0] s;
    output cout;

    // Internal signals for propagate (p) and generate (g)
    wire [7:0] p, g;
    // Internal carry vector
    wire [7:0] car;

    // Generate propagate and generate signals
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : gen_pg
            assign p[i] = a[i] ^ b[i];
            assign g[i] = a[i] & b[i];
        end
    endgenerate

    // Generate carry lookahead signals
    assign car[0] = g[0] | (p[0] & cin);
    assign car[1] = g[1] | (p[1] & car[0]);
    assign car[2] = g[2] | (p[2] & car[1]);
    assign car[3] = g[3] | (p[3] & car[2]);
    assign car[4] = g[4] | (p[4] & car[3]);
    assign car[5] = g[5] | (p[5] & car[4]);
    assign car[6] = g[6] | (p[6] & car[5]);
    assign car[7] = g[7] | (p[7] & car[6]);

    // Generate sum bits
    assign s[0] = a[0] ^ b[0] ^ cin;
    assign s[1] = a[1] ^ b[1] ^ car[0];
    assign s[2] = a[2] ^ b[2] ^ car[1];
    assign s[3] = a[3] ^ b[3] ^ car[2];
    assign s[4] = a[4] ^ b[4] ^ car[3];
    assign s[5] = a[5] ^ b[5] ^ car[4];
    assign s[6] = a[6] ^ b[6] ^ car[5];
    assign s[7] = a[7] ^ b[7] ^ car[6];

    // Generate carry-out
    assign cout = g[7] | (p[7] & car[7]);
endmodule

