module receiver(input wire rx,
                output reg rdy,
                input wire rdy_clr,
                input wire clk_50m,
                input wire rst,
                input wire clken,
                output reg [7:0] data);

    // State definitions
    typedef enum reg [1:0] {START, DATA, STOP} state_t;
    state_t state, next_state;

    // Internal signals
    reg [2:0] bit_count;
    reg [7:0] data_reg;
    reg [2:0] stop_bit_count;
    reg rx_sample;
    reg rx_sample_d1;

    // Clock enable and reset logic
    always @(posedge clk_50m or posedge rst) begin
        if (rst) begin
            state <= START;
            rdy <= 0;
            data <= 0;
            bit_count <= 0;
            stop_bit_count <= 0;
        end else if (clken) begin
            state <= next_state;
            if (rdy_clr)
                rdy <= 0;
        end
    end

    // State transition logic
    always @(*) begin
        next_state = state;
        case (state)
            START: begin
                if (rx_sample_d1 && !rx_sample)
                    next_state = DATA;
            end
            DATA: begin
                if (bit_count == 7)
                    next_state = STOP;
            end
            STOP: begin
                if (stop_bit_count == 2)
                    next_state = START;
            end
        endcase
    end

    // Data sampling and bit counting
    always @(posedge clk_50m or posedge rst) begin
        if (rst) begin
            rx_sample <= 1;
            rx_sample_d1 <= 1;
            bit_count <= 0;
            stop_bit_count <= 0;
        end else if (clken) begin
            rx_sample_d1 <= rx_sample;
            rx_sample <= rx;
            case (state)
                DATA: begin
                    data_reg[bit_count] <= rx_sample;
                    bit_count <= bit_count + 1;
                end
                STOP: begin
                    stop_bit_count <= stop_bit_count + 1;
                end
                default: begin
                    bit_count <= 0;
                    stop_bit_count <= 0;
                end
            endcase
        end
    end

    // Output logic
    always @(posedge clk_50m or posedge rst) begin
        if (rst) begin
            data <= 0;
            rdy <= 0;
        end else if (clken) begin
            if (state == STOP && stop_bit_count == 2) begin
                data <= data_reg;
                rdy <= 1;
            end
        end
    end

endmodule

module arriaiigz_ff (
