module CCarryLookaheadBlock_5_5_5_InOutT(pA4,pA3,pA2,pA1,pA0, pB4,pB3,pB2,pB1,pB0, r4,r3,r2,r1,r0, cIn, cOut);

input pA4,pA3,pA2,pA1,pA0, pB4,pB3,pB2,pB1,pB0, cIn;
output r4,r3,r2,r1,r0, cOut;

// Internal wires for sum and carry generation
wire s0, c0, s1, c1, s2, c2, s3, c3, s4, c4;
wire g0, p0, g1, p1, g2, p2, g3, p3, g4, p4;
wire cGen0, cGen1, cGen2, cGen3, cGen4;

// Generate sum and carry for each bit position
assign s0 = pA0 ^ pB0 ^ cIn;
assign c0 = (pA0 & pB0) | (pA0 & cIn) | (pB0 & cIn);

assign s1 = pA1 ^ pB1 ^ c0;
assign c1 = (pA1 & pB1) | (pA1 & c0) | (pB1 & c0);

assign s2 = pA2 ^ pB2 ^ c1;
assign c2 = (pA2 & pB2) | (pA2 & c1) | (pB2 & c1);

assign s3 = pA3 ^ pB3 ^ c2;
assign c3 = (pA3 & pB3) | (pA3 & c2) | (pB3 & c2);

assign s4 = pA4 ^ pB4 ^ c3;
assign c4 = (pA4 & pB4) | (pA4 & c3) | (pB4 & c3);

// Generate generate (g) and propagate (p) signals for lookahead
assign g0 = pA0 & pB0;
assign p0 = pA0 | pB0;

assign g1 = pA1 & pB1;
assign p1 = pA1 | pB1;

assign g2 = pA2 & pB2;
assign p2 = pA2 | pB2;

assign g3 = pA3 & pB3;
assign p3 = pA3 | pB3;

assign g4 = pA4 & pB4;
assign p4 = pA4 | pB4;

// Generate lookahead carries
assign cGen0 = g0;
assign cGen1 = g0 | (p0 & g1);
assign cGen2 = g0 | (p0 & g1) | (p0 & p1 & g2);
assign cGen3 = g0 | (p0 & g1) | (p0 & p1 & g2) | (p0 & p1 & p2 & g3);
assign cGen4 = g0 | (p0 & g1) | (p0 & p1 & g2) | (p0 & p1 & p2 & g3) | (p0 & p1 & p2 & p3 & g4);

// Final carry-out
assign cOut = cGen4;

// Assign sum bits to output
assign r4 = s4;
assign r3 = s3;
assign r2 = s2;
assign r1 = s1;
assign r0 = s0;

endmodule

