module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);

    // Internal registers
    reg [AW-1:0] addr_req;
    reg [AW-1:0] cached_addr0;
    reg [AW-1:0] cached_addr1;
    reg [DW-1:0] cached_data0;
    reg [DW-1:0] cached_data1;
    reg [AW-1:0] subaddr;
    reg good;

    // Combinational logic for address request
    always @(*) begin
        case (DW)
            8:  addr_req = {addr, 2'b00};
            16: addr_req = {addr, 1'b0};
            32: addr_req = addr;
            default: addr_req = addr;
        endcase
    end

    // Cache hit detection
    wire hit0 = (addr_req == cached_addr0);
    wire hit1 = (addr_req == cached_addr1);

    // Memory request generation
    always @(*) begin
        req = !hit0 && !hit1 && addr_ok;
    end

    // SDRAM address generation
    always @(*) begin
        case (DW)
            8:  sdram_addr = {offset[21:3], addr_req[AW-1:0], 2'b00};
            16: sdram_addr = {offset[21:3], addr_req[AW-1:0], 1'b0};
            32: sdram_addr = {offset[21:3], addr_req[AW-1:0]};
            default: sdram_addr = {offset[21:3], addr_req[AW-1:0]};
        endcase
    end

    // Data output multiplexing
    always @(*) begin
        case (DW)
            8:  subaddr = addr[AW-1:0];
            16: subaddr = addr[AW-1:1];
            32: subaddr = addr;
            default: subaddr = addr;
        endcase
    end

    always @(*) begin
        if (hit0) begin
            dout = cached_data0;
            data_ok = good;
        end else if (hit1) begin
            dout = cached_data1;
            data_ok = good;
        end else begin
            dout = din[DW-1:0];
            data_ok = din_ok;
        end
    end

    // Sequential logic for cache updates
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            req <= 0;
            data_ok <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            good <= 0;
        end else if (clr) begin
            req <= 0;
            data_ok <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            good <= 0;
        end else begin
            if (we && addr_ok) begin
                if (!hit0) begin
                    cached_addr0 <= addr_req;
                    cached_data0 <= din[DW-1:0];
                    good <= 1;
                end else if (!hit1) begin
                    cached_addr1 <= addr_req;
                    cached_data1 <= din[DW-1:0];
                    good <= 1;
                end
            end
        end
    end

endmodule

module partsel_00075(ctrl, s0, s1, s2, s3, x0, x1, x2, x3, y);
  input [3:0] ctrl;
  input [2:0] s0;
  input [2:0] s1;
  input [2:0] s2;
  input [2:0] s3;
  input signed [31:0] x0;
  input [31:0] x1;
  input signed [31:0] x2;
  input signed [31:0] x3;
  output [127:0] y;

  // Local parameters
  parameter p0 = 32'd10;
  parameter p1 = 32'd20;
  parameter p2 = 32'd30;
  parameter p3 = 32'd40;

  // Internal wires
  wire signed [31:0] x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15;
  wire signed [31:0] y0, y1, y2, y3;

  // Intermediate calculations
  assign x4 = x0 + x1;
  assign x5 = x2 - x3;
  assign x6 = x0 ^ x1;
  assign x7 = x2 & x3;
  assign x8 = x0 << s0;
  assign x9 = x1 >> s1;
  assign x10 = x2 << s2;
  assign x11 = x3 >> s3;
  assign x12 = x4 + p0;
  assign x13 = x5 - p1;
  assign x14 = x6 ^ p2;
  assign x15 = x7 & p3;

  // Output calculations based on control signals
  always @(*) begin
    case (ctrl)
      4'b0000: begin
        y0 = x12;
        y1 = x13;
        y2 = x14;
        y3 = x15;
      end
      4'b0001: begin
        y0 = x8;
        y1 = x9;
        y2 = x10;
        y3 = x11;
      end
      4'b0010: begin
        y0 = x4;
        y1 = x5;
        y2 = x6;
        y3 = x7;
      end
      4'b0011: begin
        y0 = x0;
        y1 = x1;
        y2 = x2;
        y3 = x3;
      end
      default: begin
        y0 = 32'd0;
        y1 = 32'd0;
        y2 = 32'd0;
        y3 = 32'd0;
      end
    endcase
  end

  // Concatenate the results to form the 128-bit output
  assign y = {y3, y2, y1, y0};

endmodule

