    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count1 <= 4'b0000;
            count2 <= 4'b0000;
            done <= 1'b0;
        end else if (start) begin
            if (count1 < MOD - 1) begin
                count1 <= count1 + 1;
            end else if (count2 < MOD - 1) begin
                count1 <= 4'b0000;
                count2 <= count2 + 1;
            end else if (count1 == MOD - 1 && count2 == MOD - 1) begin
                count1 <= 4'b0000;
                count2 <= 4'b0000;
                done <= 1'b1;
            end
        end
    end

endmodule

