module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);

  // State encoding
  typedef enum logic [3:0] {
    IDLE = 4'b0000,
    START = 4'b0001,
    DATA = 4'b0010,
    STOP = 4'b0011
  } state_t;

  state_t state, next_state;
  logic [7:0] data_reg;
  logic [2:0] bit_count;

  // State register
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      data_reg <= 8'b0;
      bit_count <= 3'b0;
    end else begin
      state <= next_state;
      if (next_state == DATA && tick)
        data_reg <= {1'b0, data_reg[7:1]};
      if (next_state == START)
        data_reg <= io_bits;
      if (next_state == IDLE)
        bit_count <= 3'b0;
      else if (next_state == DATA && tick)
        bit_count <= bit_count + 1;
    end
  end

  // Next state logic
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (io_valid)
          next_state = START;
      end
      START: begin
        if (tick)
          next_state = DATA;
      end
      DATA: begin
        if (tick && bit_count == 3'b111)
          next_state = STOP;
        else if (tick)
          next_state = DATA;
      end
      STOP: begin
        if (tick)
          next_state = IDLE;
      end
    endcase
  end

  // Output logic
  always_comb begin
    io_ready = (state == IDLE);
    case (state)
      IDLE: tx = 1'b1;
      START: tx = 1'b0;
      DATA: tx = data_reg[0];
      STOP: tx = 1'b1;
    endcase
  end

endmodule

