module control(
    input wire [31:0] instr,
    input wire [31:0] alu_result,
    output reg [1:0] imm_type,
    output reg rf_we,
    output reg alu_imm,
    output reg [2:0] alu_funct3,
    output reg [6:0] alu_funct7,
    output reg mem_we,
    output wire [1:0] mem_access_width,
    output reg halt,
    output reg branch_taken,
    output reg jump,
    output reg jump_reg
);

    // Extract opcode, funct3, and funct7 from the instruction
    wire [6:0] opcode = instr[6:0];
    wire [2:0] funct3 = instr[14:12];
    wire [6:0] funct7 = instr[31:25];

    // Initialize control signals
    always @(*) begin
        imm_type = 2'b00;
        rf_we = 1'b0;
        alu_imm = 1'b0;
        alu_funct3 = 3'b000;
        alu_funct7 = 7'b0000000;
        mem_we = 1'b0;
        mem_access_width = 2'b00;
        halt = 1'b0;
        branch_taken = 1'b0;
        jump = 1'b0;
        jump_reg = 1'b0;

        case (opcode)
            7'b0110011: // R-type instructions
                rf_we = 1'b1;
                alu_funct3 = funct3;
                alu_funct7 = funct7;
            7'b0010011: // I-type instructions
                rf_we = 1'b1;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                imm_type = 2'b01; // Immediate type for I-type
            7'b0000011: // Load instructions
                rf_we = 1'b1;
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                imm_type = 2'b10; // Immediate type for load
                mem_access_width = funct3[1:0]; // Determine memory access width
            7'b0100011: // Store instructions
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                imm_type = 2'b11; // Immediate type for store
                mem_access_width = funct3[1:0]; // Determine memory access width
                mem_we = 1'b1;
            7'b1100011: // Branch instructions
                alu_imm = 1'b1;
                alu_funct3 = funct3;
                imm_type = 2'b00; // Immediate type for branch
                branch_taken = (alu_result == 32'b0); // Branch if ALU result is zero
            7'b1101111: // Jump instructions
                jump = 1'b1;
                imm_type = 2'b00; // Immediate type for jump
            7'b1100111: // Jump register instructions
                jump_reg = 1'b1;
                imm_type = 2'b00; // Immediate type for jump register
            7'b1110011: // System instructions (e.g., halt)
                if (funct3 == 3'b000 && funct7 == 7'b0000000) begin
                    halt = 1'b1; // Halt if opcode is ECALL
                end
            default: // Default case
                // No action
        endcase
    end

endmodule

module BRAM #(
  parameter ADDR_WIDTH = 4,
  parameter DATA_WIDTH = 8
)
(
  input clk,
  input [ADDR_WIDTH-1:0] addr,
