  reg [DATA_WIDTH-1:0] mem [0:(1<<ADDR_WIDTH)-1];

  // Sequential block for write and read operations
  always @(posedge clk) begin
    // Write operation
    if (write_en) begin
      mem[addr] <= data_in;
    end

    // Read operation
    data_out <= mem[addr];
  end

endmodule

module buart #(
  parameter FREQ_MHZ = 2,
  parameter BAUDS    = 115200
) (
    input clk,
    input resetq,
    output tx,
    input  rx,
    input  wr,
    input  rd,
    input  [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output valid
);

  // Calculate the divider for the baud rate
  localparam DIVISOR = (FREQ_MHZ * 1000000) / (BAUDS * 16);

  // Internal registers
  reg [7:0] recv_pattern;
  reg [7:0] recv_buf_data;
  reg recv_buf_valid;
  reg [3:0] recv_divcnt;
  reg [3:0] send_divcnt;
  reg [7:0] send_data;
  reg send_busy;
  reg [2:0] state;

  // State definitions
  localparam IDLE = 3'b000;
  localparam START = 3'b001;
  localparam DATA = 3'b010;
  localparam STOP = 3'b011;
  localparam TX_START = 3'b100;
  localparam TX_DATA = 3'b101;
  localparam TX_STOP = 3'b110;

  // Receive logic
  always @(posedge clk or negedge resetq) begin
    if (!resetq) begin
      recv_pattern <= 8'b0;
      recv_buf_data <= 8'b0;
      recv_buf_valid <= 0;
      recv_divcnt <= 4'b0;
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (!rx) begin
            state <= START;
            recv_divcnt <= 4'b0;
          end
        end
        START: begin
          if (recv_divcnt < DIVISOR - 1) begin
            recv_divcnt <= recv_divcnt + 1;
          end else begin
            state <= DATA;
            recv_divcnt <= 4'b0;
            recv_pattern <= 8'b0;
          end
        end
        DATA: begin
          if (recv_divcnt < DIVISOR - 1) begin
            recv_divcnt <= recv_divcnt + 1;
          end else begin
            recv_pattern <= {rx, recv_pattern[7:1]};
            if (recv_divcnt == DIVISOR - 2) begin
              recv_divcnt <= 4'b0;
              state <= STOP;
            end
          end
        end
        STOP: begin
          if (recv_divcnt < DIVISOR - 1) begin
            recv_divcnt <= recv_divcnt + 1;
          end else begin
            recv_buf_data <= recv_pattern;
            recv_buf_valid <= 1;
            state <= IDLE;
          end
        end
        default: state <= IDLE;
      endcase
    end
  end

  // Transmit logic
  always @(posedge clk or negedge resetq) begin
    if (!resetq) begin
      tx <= 1;
      send_divcnt <= 4'b0;
      send_data <= 8'b0;
      send_busy <= 0;
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (wr && !send_busy) begin
            send_data <= tx_data;
            send_busy <= 1;
            state <= TX_START;
            send_divcnt <= 4'b0;
          end
        end
        TX_START: begin
          if (send_divcnt < DIVISOR - 1) begin
            send_divcnt <= send_divcnt + 1;
          end else begin
            tx <= 0;
            state <= TX_DATA;
            send_divcnt <= 4'b0;
          end
        end
        TX_DATA: begin
          if (send_divcnt < DIVISOR - 1) begin
            send_divcnt <= send_divcnt + 1;
          end else begin
            tx <= send_data[0];
            send_data <= {1'b0, send_data[7:1]};
            if (send_divcnt == DIVISOR - 2) begin
              send_divcnt <= 4'b0;
              if (send_data == 8'b0) begin
                state <= TX_STOP;
              end
            end
          end
        end
        TX_STOP: begin
          if (send_divcnt < DIVISOR - 1) begin
            send_divcnt <= send_divcnt + 1;
          end else begin
            tx <= 1;
            send_busy <= 0;
            state <= IDLE;
          end
        end
        default: state <= IDLE;
      endcase
    end
  end

  // Output assignments
  assign rx_data = recv_buf_data;
  assign valid = recv_buf_valid;
  assign busy = send_busy;

endmodule

