	always @(posedge reset) begin
		for (int i = 0; i < 32; i = i + 1) begin
			regs[i] <= 32'b0;
		end
	end

	// Write operation on rising edge of clock
	always @(posedge clock) begin
		if (reset) begin
			// Reset condition: do nothing, registers are already reset
		end else if (Rd != 0) begin
			// Write data to register Rd if Rd is not zero
			regs[Rd] <= Rd_data;
