    input wire RD,
    input wire CLK,
    input wire RST,
    output wire WCTRL,
    output reg [6:0] Y
);

    reg [2:0] current_data;
    reg [2:0] next_data;
    reg [2:0] current_control;
    reg [2:0] next_control;

    // Sequential logic for updating registers on clock edges
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_data <= 3'b000;
            current_control <= 3'b000;
        end else begin
            current_data <= next_data;
            current_control <= next_control;
        end
    end

    // Combinational logic for determining next states based on input conditions
    always @(*) begin
        next_data = current_data;
        next_control = current_control;
        WCTRL = 1'b0;

        if (WR) begin
            next_data = D;
            next_control = A;
            WCTRL = 1'b1;
        end
    end

    // Always block to convert the stored data into a one-hot encoded output
    always @(*) begin
        case (current_data)
            3'b000: Y = 7'b0000001;
            3'b001: Y = 7'b0000010;
            3'b010: Y = 7'b0000100;
