module io_ps2_keyboard(
    input wire clk,
    input wire kbd_clk,
    input wire kbd_dat,
    output reg interrupt,
    output reg [7:0] scanCode
);

    // Parameters for clock speed and derived timing constants
    parameter CLK_SPEED = 50000000; // 50 MHz
    parameter timeout_const = CLK_SPEED / 1000; // 1 ms timeout
    parameter debounce_const = CLK_SPEED / 10000; // 100 us debounce

    // Internal registers
    reg [7:0] shift_reg; // Register to store incoming data bits
    reg [15:0] clk_filter; // Register to filter keyboard clock signal
    reg [15:0] timeout; // Register to manage timeout period
    reg [3:0] bitsCount; // Register to count the number of bits received
    reg last_kbd_clk; // Register to store the last state of keyboard clock
    reg [7:0] scanCode_buffer; // Buffer to store the scan code before output

    // State machine states
    typedef enum reg [2:0] {
        IDLE,
        START,
        DATA,
        PARITY,
        STOP
    } state_t;
    state_t state, next_state;

    // Edge detection for keyboard clock
    always @(posedge clk) begin
        last_kbd_clk <= kbd_clk;
    end

    // Clock filter to debounce keyboard clock
    always @(posedge clk) begin
        if (clk_filter < debounce_const) begin
            clk_filter <= clk_filter + 1;
        end else begin
            clk_filter <= 0;
        end
    end

    // Timeout mechanism
    always @(posedge clk) begin
        if (timeout < timeout_const) begin
            timeout <= timeout + 1;
        end else begin
            timeout <= 0;
        end
    end

    // State machine logic
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (clk_filter == debounce_const && kbd_clk == 0) begin
                    next_state <= START;
                end else begin
                    next_state <= IDLE;
                end
            end
            START: begin
                if (clk_filter == debounce_const && kbd_clk == 1) begin
                    next_state <= DATA;
                    bitsCount <= 0;
                end else begin
                    next_state <= START;
                end
            end
            DATA: begin
                if (clk_filter == debounce_const && kbd_clk == 1) begin
                    shift_reg <= {shift_reg[6:0], kbd_dat};
                    bitsCount <= bitsCount + 1;
                    if (bitsCount == 8) begin
                        next_state <= PARITY;
                    end else begin
                        next_state <= DATA;
                    end
                end else begin
                    next_state <= DATA;
                end
            end
            PARITY: begin
                if (clk_filter == debounce_const && kbd_clk == 1) begin
                    next_state <= STOP;
                end else begin
                    next_state <= PARITY;
                end
            end
            STOP: begin
                if (clk_filter == debounce_const && kbd_clk == 0) begin
                    next_state <= IDLE;
                    scanCode_buffer <= shift_reg;
                    interrupt <= 1;
                end else begin
                    next_state <= STOP;
                end
            end
            default: next_state <= IDLE;
        endcase
    end

    // State register update
    always @(posedge clk) begin
        state <= next_state;
    end

    // Output the scan code when interrupt is set
    always @(posedge clk) begin
        if (interrupt) begin
            scanCode <= scanCode_buffer;
            interrupt <= 0;
        end
    end

endmodule

