module vga_controller(
    input wire RST,
    input wire CLK,
    output wire H_SYNC,
    output wire V_SYNC,
    output wire [10:0] X,
    output wire [10:0] Y,
    output wire DISP_EN
);

    // Parameters for VGA timing
    parameter H_ACTIVE = 1280; // Active horizontal pixels
    parameter H_FRONT_PORCH = 40; // Front porch horizontal pixels
    parameter H_SYNC_PULSE = 128; // Horizontal sync pulse width
    parameter H_BACK_PORCH = 88; // Back porch horizontal pixels
    parameter H_TOTAL = 1688; // Total horizontal pixels

    parameter V_ACTIVE = 720; // Active vertical lines
    parameter V_FRONT_PORCH = 5; // Front porch vertical lines
    parameter V_SYNC_PULSE = 5; // Vertical sync pulse width
    parameter V_BACK_PORCH = 33; // Back porch vertical lines
    parameter V_TOTAL = 750; // Total vertical lines

    // Internal registers
    reg [10:0] h_count; // Horizontal counter
    reg [10:0] v_count; // Vertical counter
    reg h_sync_reg; // Horizontal sync signal
    reg v_sync_reg; // Vertical sync signal
    reg disp_en_reg; // Display enable signal

    // Horizontal sync generation
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            h_count <= 0;
            h_sync_reg <= 1;
        end else begin
            if (h_count == H_TOTAL - 1) begin
                h_count <= 0;
            end else begin
                h_count <= h_count + 1;
            end
            if (h_count >= H_ACTIVE + H_FRONT_PORCH && h_count < H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE) begin
                h_sync_reg <= 0;
            end else begin
                h_sync_reg <= 1;
            end
        end
    end

    // Vertical sync generation
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            v_count <= 0;
            v_sync_reg <= 1;
        end else begin
            if (h_count == H_TOTAL - 1) begin
                if (v_count == V_TOTAL - 1) begin
                    v_count <= 0;
                end else begin
                    v_count <= v_count + 1;
                end
            end
            if (v_count >= V_ACTIVE + V_FRONT_PORCH && v_count < V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE) begin
                v_sync_reg <= 0;
            end else begin
                v_sync_reg <= 1;
            end
        end
    end

    // Display enable generation
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            disp_en_reg <= 0;
        end else begin
            if (h_count < H_ACTIVE && v_count < V_ACTIVE) begin
                disp_en_reg <= 1;
            end else begin
                disp_en_reg <= 0;
            end
        end
    end

    // Assign outputs
    assign H_SYNC = h_sync_reg;
    assign V_SYNC = v_sync_reg;
    assign X = h_count;
    assign Y = v_count;
    assign DISP_EN = disp_en_reg;

endmodule

