module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);

    reg [7:0] scan_code_reg;
    reg [3:0] counter;
    reg [7:0] data_buffer;
    reg parity;
    reg valid_code;
    reg [3:0] parity_counter;

    assign scan_code = scan_code_reg;
    assign scan_ready = valid_code;

    always @(posedge reset or negedge i_clock) begin
        if (reset) begin
            scan_code_reg <= 8'b0;
            counter <= 4'b0;
            data_buffer <= 8'b0;
            parity <= 1'b0;
            valid_code <= 1'b0;
            parity_counter <= 4'b0;
        end else begin
            if (counter < 4'b1000) begin
                data_buffer <= {data_buffer[6:0], i_data};
                parity <= parity ^ i_data;
                counter <= counter + 1;
            end else if (counter == 4'b1000) begin
                if (i_data == parity) begin
                    scan_code_reg <= data_buffer;
                    valid_code <= 1'b1;
                end else begin
                    valid_code <= 1'b0;
                end
                counter <= counter + 1;
            end else if (counter == 4'b1001) begin
                if (i_data == 1'b1) begin
                    valid_code <= 1'b0;
                end
                counter <= 4'b0;
            end
        end
    end

endmodule

