module radix2(
	input wire [1:0] state,
	input wire signed [23:0] din_a_r,
	input wire signed [23:0] din_a_i,
	input wire signed [23:0] din_b_r,
	input wire signed [23:0] din_b_i,
	input wire signed [23:0] w_r,
	input wire signed [23:0] w_i,
	output reg signed[23:0] op_r,
	output reg signed[23:0] op_i,
	output reg signed[23:0] delay_r,
	output reg signed[23:0] delay_i,
	output reg outvalid
);

	// Internal 42-bit registers for higher precision
	reg signed [41:0] temp_r, temp_i;

	always @(*) begin
		case (state)
			2'b00, 2'b11: begin // Idle states
				op_r = 24'b0;
				op_i = 24'b0;
				delay_r = 24'b0;
				delay_i = 24'b0;
				outvalid = 1'b0;
			end
			2'b01: begin // Addition and subtraction
				op_r = din_a_r + din_b_r;
				op_i = din_a_i + din_b_i;
				delay_r = din_a_r - din_b_r;
				delay_i = din_a_i - din_b_i;
				outvalid = 1'b1;
			end
			2'b10: begin // Twiddle factor multiplication
				// Higher precision multiplication
				temp_r = din_a_r * w_r - din_a_i * w_i;
				temp_i = din_a_r * w_i + din_a_i * w_r;
				// Truncate to 24 bits
				op_r = temp_r[41:18];
				op_i = temp_i[41:18];
				outvalid = 1'b1;
			end
			default: begin
				op_r = 24'b0;
				op_i = 24'b0;
				delay_r = 24'b0;
				delay_i = 24'b0;
				outvalid = 1'b0;
			end
		endcase
	end

endmodule

module AMSG_kirsch_e(
  input [7:0] p1, p2, p3, p4, p6, p7, p8, p9,
  output reg [7:0] y1
);

  // Intermediate sums
  wire [15:0] sum1 = p1 + p2 + p3 + p4;
  wire [15:0] sum2 = p6 + p7 + p8 + p9;

  // Weighted sums
  wire [15:0] weighted_sum1 = sum1 * 2; // Example weight for sum1
  wire [15:0] weighted_sum2 = sum2 * 3; // Example weight for sum2

  // Difference of weighted sums
  wire [15:0] diff = weighted_sum1 - weighted_sum2;

  // Clamp the result to 8-bit
  always @(*) begin
    if (diff > 255)
      y1 = 255;
    else if (diff < 0)
      y1 = 0;
    else
      y1 = diff;
  end

endmodule

