module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// State definitions
typedef enum logic [1:0] {
    ZERO,
    ONE,
    TWO
} state_t;

// State register
state_t state, next_state;

// Pipeline registers
reg [N-1:0] data_p1, data_p2;
reg load_p1, load_p2, load_p1_from_p2;

// Output signals
assign s_ready = (state == ZERO) ? m_ready : 1'b0;
assign m_valid = (state == TWO) ? 1'b1 : 1'b0;
assign m_data = (state == TWO) ? data_p2 : {N{1'b0}};

// State machine logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        ZERO: begin
            if (s_valid && m_ready) begin
                next_state = ONE;
            end
        end
        ONE: begin
            if (m_ready) begin
                next_state = TWO;
            end
        end
        TWO: begin
            if (m_ready) begin
                next_state = ZERO;
            end
        end
    endcase
end

// Pipeline register logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        load_p1_from_p2 <= 1'b0;
    end else begin
        load_p1 <= (state == ZERO) ? s_valid : 1'b0;
        load_p2 <= (state == ONE) ? 1'b1 : 1'b0;
        load_p1_from_p2 <= (state == TWO) ? 1'b1 : 1'b0;

        if (load_p1) begin
            data_p1 <= s_data;
        end

        if (load_p2) begin
            data_p2 <= data_p1;
        end

        if (load_p1_from_p2) begin
            data_p1 <= data_p2;
        end
    end
end

endmodule

