		// Initialize all control signals to default values
		RegDst = 0;
		Jump = 0;
		Branch = 0;
		bne = 0;
		MemRead = 0;
		MemtoReg = 0;
		MemWrite = 0;
		ALUsrc = 0;
		RegWrite = 0;
		ALUop = 2'b00; // Default ALU operation (addition)

		// Decode the opcode and set the appropriate control signals
		case (opcode)
			6'b000000: // R-type instructions
				begin
					RegDst = 1;
					RegWrite = 1;
					ALUsrc = 0;
					case (opcode[5:0]) // Further decode based on function code
						6'b100000: ALUop = 2'b00; // add
						6'b100010: ALUop = 2'b01; // sub
						6'b100100: ALUop = 2'b10; // and
						6'b100101: ALUop = 2'b11; // or
						default: ALUop = 2'b00; // Default to addition
					endcase
				end
			6'b001000: // addi
				begin
					RegDst = 0;
					RegWrite = 1;
					ALUsrc = 1;
					ALUop = 2'b00; // add
				end
			6'b100011: // lw
				begin
					RegDst = 0;
					RegWrite = 1;
					ALUsrc = 1;
					MemRead = 1;
					MemtoReg = 1;
					ALUop = 2'b00; // add
				end
			6'b101011: // sw
				begin
					ALUsrc = 1;
					MemWrite = 1;
					ALUop = 2'b00; // add
				end
			6'b000100: // beq
				begin
					Branch = 1;
					bne = 0;
					ALUop = 2'b10; // and
				end
			6'b000101: // bne
				begin
					Branch = 1;
					bne = 1;
					ALUop = 2'b10; // and
				end
			6'b000010: // j
				begin
					Jump = 1;
				end
			default:
				// Default case, do nothing (all signals remain 0)
				;
		endcase
	end
