module hardcopyiii_ddr_gray_decoder (
        gin, 
        bout
);

parameter width = 8; // Define the width of the Gray code and binary vectors

input  [width-1 : 0] gin;
output [width-1 : 0] bout;

reg  [width-1 : 0] breg; // Internal register to store intermediate binary values

always @(*) begin
    breg = 0; // Initialize the internal register
    bout = 0; // Initialize the output vector

    // Loop through each bit position to decode the Gray code to binary
    for (int i = 0; i < width; i = i + 1) begin
        if (i == 0) begin
            // The most significant bit is the same as the Gray code
            breg[i] = gin[i];
        end else begin
            // Subsequent bits are computed using XOR with the previous binary bit
            breg[i] = breg[i-1] ^ gin[i];
        end
    end

    // Assign the final decoded binary value to the output
    bout = breg;
end

endmodule

