   reg [31:0]             sub_result;
   reg [31:0]             or_result;
   reg [31:0]             and_result;
   reg [31:0]             xor_result;
   reg [31:0]             lshift_result;
   reg [31:0]             rshift_result;
   reg [31:0]             urshift_result;
   reg [32:0]             sub_33bit; // For handling negative results in subtraction

   always @(*) begin
      case (alu_opcode)
         4'b0000: begin // Addition
            add_result = alu_src1 + alu_src2;
            alu_result = add_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         4'b0001: begin // Subtraction
            sub_33bit = {1'b0, alu_src1} - {1'b0, alu_src2};
            sub_result = sub_33bit[31:0];
            alu_result = sub_result;
            minus_is_zero = sub_33bit[32];
            less_than = sub_33bit[32];
            less_than_unsigned = (alu_src1 < alu_src2);
         end
         4'b0010: begin // Bitwise OR
            or_result = alu_src1 | alu_src2;
            alu_result = or_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         4'b0011: begin // Bitwise AND
            and_result = alu_src1 & alu_src2;
            alu_result = and_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         4'b0100: begin // Bitwise XOR
            xor_result = alu_src1 ^ alu_src2;
            alu_result = xor_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         4'b0101: begin // Left Shift (signed)
            lshift_result = alu_src1 << alu_src2[4:0];
            alu_result = lshift_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         4'b0110: begin // Right Shift (signed)
            rshift_result = $signed(alu_src1) >>> alu_src2[4:0];
            alu_result = rshift_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         4'b0111: begin // Right Shift (unsigned)
            urshift_result = alu_src1 >> alu_src2[4:0];
            alu_result = urshift_result;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
         default: begin // Default case
            alu_result = 32'b0;
            minus_is_zero = 1'b0;
            less_than = 1'b0;
            less_than_unsigned = 1'b0;
         end
      endcase
   end
