module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);

    // Internal signals
    reg [DATA_BITS-1:0] mem [0:2**DEPTH_BITS-1];
    reg [DEPTH_BITS:0] read_ptr, write_ptr;
    reg [DEPTH_BITS:0] count;

    // Empty and full flags
    assign empty_n = (count > 0);
    assign full_n = (count == 2**DEPTH_BITS);

    // Write logic
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            write_ptr <= 0;
        end else if (write && !full_n) begin
            mem[write_ptr[DEPTH_BITS-1:0]] <= din;
            write_ptr <= write_ptr + 1;
        end
    end

    // Read logic
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            read_ptr <= 0;
            dout <= 0;
        end else if (read && !empty_n) begin
            dout <= mem[read_ptr[DEPTH_BITS-1:0]];
            read_ptr <= read_ptr + 1;
        end else begin
            dout <= 0;
        end
    end

    // Count logic
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            count <= 0;
        end else begin
            if (write && !full_n && !read) begin
                count <= count + 1;
            end else if (read && !empty_n && !write) begin
                count <= count - 1;
            end else if (write && !full_n && read && !empty_n) begin
                count <= count;
            end else begin
                count <= count;
            end
        end
    end

endmodule

