module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output reg [31:0] result, 
	output reg [31:0] remainder,
	output reg done 
);

reg [31:0] divisor_reg;
reg [31:0] divider_reg;
reg [31:0] remainder_reg;
reg [31:0] result_reg;
reg start;
reg [31:0] counter;

always @(posedge CLK) begin
	if (Divisor != divisor_reg || Divider != divider_reg) begin
		// New inputs detected, start a new division
		divisor_reg <= Divisor;
		divider_reg <= Divider;
		remainder_reg <= Divider;
		result_reg <= 0;
		counter <= 0;
		start <= 1;
		done <= 0;
	end else if (start) begin
		// Perform division
		if (remainder_reg >= divisor_reg) begin
			remainder_reg <= remainder_reg - divisor_reg;
			result_reg <= result_reg + 1;
		end else begin
			// Division complete
			result <= result_reg;
			remainder <= remainder_reg;
			done <= 1;
			start <= 0;
		end
	end
end

endmodule

