   input [7:0] 	 cell1,
   input [7:0] 	 cell2,
   input [7:0] 	 cell3,
   output [31:0] argb
   );

   // Calculate the sum of the lower 7 bits of each input cell
   wire [10:0] sum = {cell0[6:0]} + {cell1[6:0]} + {cell2[6:0]} + {cell3[6:0]};

   // Shift the sum left by 3 bits to create an 8-bit value
   wire [7:0] count = sum << 3;

   // Check if any of the 8th bits of the input cells are set to 1
   wire flag = cell0[7] | cell1[7] | cell2[7] | cell3[7];

   // Assign the output based on the flag
   assign argb = flag ? 32'h00000077 : {8'h00, count, count, count};

endmodule

