	parameter [8:0] KeyMap [0:15] = {
		9'b000000000, // No key
		9'b100000001, // Key 1
		9'b100000010, // Key 2
		9'b100000011, // Key 3
		9'b100000100, // Key 4
		9'b100000101, // Key 5
