module FixedRoundSigned(
	clk,
	fixed_num,
	round,
	overflow
	);

	parameter num_width = 16; // Width of the input fixed-point number
	parameter fixed_point = 8; // Position of the fixed point
	parameter res_width = 16; // Width of the result

	input clk;
	input signed [num_width - 1 : 0] fixed_num;
	output reg signed [res_width : 0] round;
	output reg overflow;

	// Internal registers
	reg signed [num_width : 0] extended_num;
	reg signed [fixed_point - 1 : 0] fraction;
	reg signed [fixed_point : 0] rounded_fraction;
	reg signed [res_width : 0] temp_round;
	reg sign_bit;
	reg round_up;

	always @(posedge clk) begin
		// Extend the number to handle overflow
		extended_num <= {fixed_num[num_width - 1], fixed_num};

		// Extract the fraction part
		fraction <= extended_num[fixed_point - 1 : 0];

		// Determine if rounding is needed
		round_up <= fraction[fixed_point - 1];

		// Handle rounding based on the sign
		case (extended_num[num_width])
			1'b0: begin // Positive number
				rounded_fraction <= fraction + round_up;
			end
			1'b1: begin // Negative number
				rounded_fraction <= fraction - round_up;
			end
		endcase

		// Compute the rounded result
		temp_round <= {extended_num[num_width : fixed_point], rounded_fraction[fixed_point : 1]};

		// Check for overflow
		overflow <= (temp_round[num_width] != extended_num[num_width]);

		// Assign the final rounded result
		round <= temp_round;
	end

endmodule

