module fir_filter_slice #(
  parameter IN_WIDTH     = 16,
  parameter COEFF_WIDTH  = 16,
  parameter ACCUM_WIDTH  = 32,
  parameter OUT_WIDTH    = 32)
(
  input clk,
  input reset,
  input clear,
  input sample_in_stb,
  input signed [IN_WIDTH-1:0] sample_in_a,       
  input signed [IN_WIDTH-1:0] sample_in_b,       
  output signed [IN_WIDTH-1:0] sample_forward,   
  input signed [COEFF_WIDTH-1:0] coeff_in,       
  output signed [COEFF_WIDTH-1:0] coeff_forward, 
  input coeff_load_stb,                          
  input signed [ACCUM_WIDTH-1:0] sample_accum,   
  output signed [OUT_WIDTH-1:0] sample_out       
);

  // Internal registers
  reg signed [IN_WIDTH-1:0] a_reg;
  reg signed [IN_WIDTH-1:0] b_reg;
  reg signed [COEFF_WIDTH-1:0] coeff_reg;
  reg signed [ACCUM_WIDTH-1:0] m_reg;
  reg signed [ACCUM_WIDTH-1:0] p_reg;

  // Internal signals
  wire signed [ACCUM_WIDTH-1:0] add_result;

  // Multiplication result
  assign m_reg = a_reg * coeff_reg;

  // Addition result
  assign add_result = m_reg + sample_accum;

  // Accumulation result
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      p_reg <= {ACCUM_WIDTH{1'b0}};
    end else if (clear) begin
      p_reg <= {ACCUM_WIDTH{1'b0}};
    end else begin
      p_reg <= add_result;
    end
  end

  // Output truncation
  assign sample_out = p_reg[ACCUM_WIDTH-1:ACCUM_WIDTH-OUT_WIDTH];

  // Forwarding logic
  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      a_reg <= {IN_WIDTH{1'b0}};
      b_reg <= {IN_WIDTH{1'b0}};
      coeff_reg <= {COEFF_WIDTH{1'b0}};
    end else if (clear) begin
      a_reg <= {IN_WIDTH{1'b0}};
      b_reg <= {IN_WIDTH{1'b0}};
      coeff_reg <= {COEFF_WIDTH{1'b0}};
    end else begin
      if (sample_in_stb) begin
        a_reg <= sample_in_a;
        b_reg <= sample_in_b;
      end
      if (coeff_load_stb) begin
        coeff_reg <= coeff_in;
      end
    end
  end

  // Forward outputs
  assign sample_forward = b_reg;
  assign coeff_forward = coeff_reg;

endmodule

