module InputSync #(
    parameter levels_g = 2, // Number of synchronization stages
    parameter ResetValue_g = 0 // Reset value for the output
)(
    input wire Input,
    input wire clk,
    input wire clr_n,
    output wire q
);

reg [levels_g-1:0] sync_stages;
assign q = sync_stages[levels_g-1];

always @(posedge clk or negedge clr_n) begin
    if (!clr_n) begin
        sync_stages <= {levels_g{ResetValue_g}};
    end else begin
        sync_stages[0] <= Input;
        for (int i = 1; i < levels_g; i = i + 1) begin
            sync_stages[i] <= sync_stages[i-1];
        end
    end
end

endmodule

