    input async_in,
    input reset,
    output reg sync_out
);

    reg ff1, ff2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ff1 <= 1'b0;
            ff2 <= 1'b0;
            sync_out <= 1'b0;
        end else begin
            ff1 <= async_in;
            ff2 <= ff1;
            sync_out <= ff2;
        end
    end

endmodule

module pipelined_multiplier #(
    parameter size = 8,
    parameter level = 3
) (
    input [size-1 : 0] a,
    input [size-1 : 0] b,
    input clk,
    output [2*size-1 : 0] pdt
);

reg [size-1 : 0] a_int;
reg [size-1 : 0] b_int;
reg [2*size-1 : 0] pdt_int [0 : level-1];

always @(posedge clk) begin
    a_int <= a;
    b_int <= b;
    pdt_int[0] <= a_int * b_int;
    for (int i = 1; i < level; i = i + 1) begin
        pdt_int[i] <= pdt_int[i-1];
    end
    pdt <= pdt_int[level-1];
end

endmodule

