module mux8to1(
    output [31:0] mux_o,
    input  [31:0] mux0, mux1, mux2, mux3, mux4, mux5, mux6, mux7,
    input  [2:0] sel
);

    // Internal wires for intermediate results
    wire [31:0] stage1_0, stage1_1, stage1_2, stage1_3;

    // First stage of multiplexing
    assign stage1_0 = sel[0] ? mux1 : mux0;
    assign stage1_1 = sel[0] ? mux3 : mux2;
    assign stage1_2 = sel[0] ? mux5 : mux4;
    assign stage1_3 = sel[0] ? mux7 : mux6;

    // Second stage of multiplexing
    wire [31:0] stage2_0, stage2_1;
    assign stage2_0 = sel[1] ? stage1_1 : stage1_0;
    assign stage2_1 = sel[1] ? stage1_3 : stage1_2;

    // Final stage of multiplexing
    assign mux_o = sel[2] ? stage2_1 : stage2_0;

endmodule

module mult_a_signed_b_signed
#(
	parameter	A_WIDTH		= 3,
	parameter	B_WIDTH		= 3,
	parameter	Q_WIDTH		= A_WIDTH+B_WIDTH,
	parameter	LATENCY		= 1
)
(
	input	arst,
	input	clk,

	input signed	[A_WIDTH-1:0]	a,
	input signed	[B_WIDTH-1:0]	b,
	output signed	[Q_WIDTH-1:0]	o
);

// Internal registers to hold the input values
reg signed [A_WIDTH-1:0] r_a_1P;
reg signed [B_WIDTH-1:0] r_b_1P;

// Array of registers to hold the product results across pipeline stages
reg signed [Q_WIDTH-1:0] r_q_P [0:LATENCY-1];

// Combinational multiplication
wire signed [Q_WIDTH-1:0] product = a * b;

// Pipeline stages
always @(posedge clk or posedge arst) begin
	if (arst) begin
		r_a_1P <= 0;
		r_b_1P <= 0;
		for (int i = 0; i < LATENCY; i = i + 1) begin
			r_q_P[i] <= 0;
		end
	end else begin
		r_a_1P <= a;
		r_b_1P <= b;
		r_q_P[0] <= product;
		for (int i = 1; i < LATENCY; i = i + 1) begin
			r_q_P[i] <= r_q_P[i-1];
		end
	end
end

// Output the result after the specified latency
assign o = r_q_P[LATENCY-1];

endmodule

module circ3(
    input wire a,
    input wire b,
    input wire c,
    input wire e,
    input wire f,
    output wire y,
    output wire z
);

    // Intermediate wires for clarity
    wire ac;
    wire not_ac;
    wire bf;
    wire not_bf;
    wire ac_not_bf;
    wire not_ac_bf;

    // Assignments based on De Morgan's laws and logical operations
    assign ac = a & c;
    assign not_ac = ~ac;
    assign bf = b & f;
    assign not_bf = ~bf;
    assign ac_not_bf = ac & not_bf;
    assign not_ac_bf = not_ac & bf;

    // Final output assignments
    assign y = ac_not_bf | not_ac_bf;
    assign z = ac & not_bf;

endmodule

module sparc_ifu_sscan(
