module StreamingDataWidthConverter_Batch_5_regslice_both_w1
#(parameter 
    DataWidth=1
)(
    input ap_clk ,
    input ap_rst,

    input data_in , 
    input vld_in , 
    output ack_in ,
    output data_out, 
    output vld_out,
    input ack_out,
    output apdone_blk
);

// Internal state definition
typedef enum logic [1:0] {IDLE, LOAD_A, LOAD_B, SHIFT} state_t;
state_t current_state, next_state;

// Internal registers
reg [DataWidth-1:0] A_V_data_1_state;
reg [DataWidth-1:0] B_V_data_1_state;
reg sel_rd, sel_wr;
reg apdone_blk_reg;

// State transition logic
always @(posedge ap_clk or posedge ap_rst) begin
    if (ap_rst) begin
        current_state <= IDLE;
        A_V_data_1_state <= 0;
        B_V_data_1_state <= 0;
        sel_rd <= 0;
        sel_wr <= 0;
        apdone_blk_reg <= 0;
    end else begin
        current_state <= next_state;
        case (next_state)
            LOAD_A: A_V_data_1_state <= data_in;
            LOAD_B: B_V_data_1_state <= data_in;
            default: ;
        endcase
        sel_rd <= (next_state == SHIFT) ? ~sel_rd : sel_rd;
        sel_wr <= (next_state == LOAD_A || next_state == LOAD_B) ? ~sel_wr : sel_wr;
        apdone_blk_reg <= (next_state == IDLE) ? 0 : 1;
    end
end

// Next state logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        IDLE: begin
            if (vld_in && ack_out) begin
                next_state = LOAD_A;
            end
        end
        LOAD_A: begin
            if (vld_in && ack_out) begin
                next_state = LOAD_B;
            end else if (ack_out) begin
                next_state = SHIFT;
            end
        end
        LOAD_B: begin
            if (vld_in && ack_out) begin
                next_state = LOAD_A;
            end else if (ack_out) begin
                next_state = SHIFT;
            end
        end
        SHIFT: begin
            if (ack_out) begin
                next_state = IDLE;
            end
        end
    endcase
end

// Output logic
assign data_out = sel_rd ? A_V_data_1_state : B_V_data_1_state;
assign vld_out = (current_state == SHIFT);
assign ack_in = (current_state == LOAD_A || current_state == LOAD_B) ? 1 : 0;
assign apdone_blk = apdone_blk_reg;

endmodule

