module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);

  reg [3:0] state_size;
  reg [1:0] state_source;
  reg maybe_full;
  reg do_enq;
  reg do_deq;

  // Enqueue and dequeue control logic
  assign do_enq = io_enq_ready & io_enq_valid;
  assign do_deq = io_deq_ready & io_deq_valid;

  // State update logic
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      state_size <= 4'b0000;
      state_source <= 2'b00;
      maybe_full <= 1'b0;
    end else begin
      if (do_enq) begin
        state_size <= io_enq_bits_tl_state_size;
        state_source <= io_enq_bits_tl_state_source;
        maybe_full <= 1'b1;
      end
      if (do_deq) begin
        maybe_full <= 1'b0;
      end
    end
  end

  // Output assignments
  assign io_enq_ready = ~maybe_full;
  assign io_deq_valid = maybe_full;
  assign io_deq_bits_tl_state_size = state_size;
  assign io_deq_bits_tl_state_source = state_source;

endmodule

