module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);

  // Define the number of groups
  localparam NUM_GROUPS = 4;
  localparam GROUP_SIZE = NUM_RDATA / NUM_GROUPS;

  // Internal registers to store intermediate results
  reg [3*NBITS-1:0] group_results [0 :NUM_GROUPS-1];

  // Combinational logic to compute intermediate results
  always @(*) begin
    for (int i = 0; i < NUM_GROUPS; i++) begin
      group_results[i] = 32'b0;
      for (int j = 0; j < GROUP_SIZE; j++) begin
        group_results[i] = group_results[i] | rdata[i * GROUP_SIZE + j];
      end
    end
  end

  // Sequential logic to store and combine intermediate results
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      hrdata <= 32'b0;
    end else if (valid_rd) begin
      hrdata <= group_results[0] | group_results[1] | group_results[2] | group_results[3];
    end
  end

endmodule

