module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// Internal state encoding
typedef enum logic [1:0] {
    ZERO = 2'b00,
    ONE = 2'b01,
    TWO = 2'b10
} state_t;

// Internal registers
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0] state;
reg load_p1;
reg load_p2;

// Output signals
assign m_data = (state == ONE) ? data_p1 : data_p2;
assign m_valid = (state == ONE) | (state == TWO);
assign s_ready = (state == ZERO) | (state == ONE);

// State machine
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
        load_p1 <= 0;
        load_p2 <= 0;
    end else begin
        case (state)
            ZERO: begin
                if (s_valid) begin
                    load_p1 <= 1;
                    state <= ONE;
                end
            end
            ONE: begin
                if (m_ready) begin
                    load_p2 <= 1;
                    state <= TWO;
                end
            end
            TWO: begin
                if (m_ready) begin
                    state <= ZERO;
                end
            end
        endcase
    end
end

// Data register updates
always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
        load_p1 <= 0;
    end
    if (load_p2) begin
        data_p2 <= data_p1;
        load_p2 <= 0;
    end
end

endmodule

