module m2016_ram(
	input[7:0] data,
	input clk,
	input nOE,
	input nCS,
	input[10:0] addr,
	input nWE,
	output reg [7:0] q
);

	// Declare the memory array
	reg [7:0] mem [0:2047];

	// Address register declaration (not utilized in current logic)
	reg [10:0] addr_reg;

	// Sequential logic for memory operations
	always @(posedge clk) begin
		if (nCS == 0) begin // Chip select active
			if (nWE == 0) begin // Write enable active
				// Write data to memory
				mem[addr] <= data;
			end
			if (nOE == 0) begin // Output enable active
				// Read data from memory
				q <= mem[addr];
			end else begin
				// If output enable is not active, output zeros
				q <= 8'b0;
			end
		end else begin
			// If chip select is not active, output zeros
			q <= 8'b0;
		end
	end

endmodule

