module arbiter_4_enq ( 
                       flit,
                       ctrl,
                       en_dest_fifo,
                       dest_fifo,

                       flit2pass_req,   
                       ctrl2pass_req,   
                       flit2pass_rep,   
                       ctrl2pass_rep,   
                       flit2local_in_req,   
                       ctrl2local_in_req,   
                       flit2local_in_rep,   
                       ctrl2local_in_rep,   
                       en_pass_req,
                       en_pass_rep,
                       en_local_in_req,
                       en_local_in_rep
                      );

input            [15:0]  flit;              
input            [1:0]   ctrl;
input                    en_dest_fifo; 
input            [1:0]   dest_fifo;

output           [15:0]  flit2pass_req;   
output           [1:0]   ctrl2pass_req;   
output           [15:0]  flit2pass_rep;   
output           [1:0]   ctrl2pass_rep;   
output           [15:0]  flit2local_in_req;   
output           [1:0]   ctrl2local_in_req;   
output           [15:0]  flit2local_in_rep;   
output           [1:0]   ctrl2local_in_rep;   

output                   en_pass_req;  
output                   en_pass_rep;  
output                   en_local_in_req; 
output                   en_local_in_rep;

// Internal registers to store output values
reg [15:0] flit2pass_req_reg, flit2pass_rep_reg, flit2local_in_req_reg, flit2local_in_rep_reg;
reg [1:0] ctrl2pass_req_reg, ctrl2pass_rep_reg, ctrl2local_in_req_reg, ctrl2local_in_rep_reg;
reg en_pass_req_reg, en_pass_rep_reg, en_local_in_req_reg, en_local_in_rep_reg;

always @(*) begin
    // Initialize outputs to default values
    flit2pass_req_reg = 16'b0;
    flit2pass_rep_reg = 16'b0;
    flit2local_in_req_reg = 16'b0;
    flit2local_in_rep_reg = 16'b0;
    ctrl2pass_req_reg = 2'b0;
    ctrl2pass_rep_reg = 2'b0;
    ctrl2local_in_req_reg = 2'b0;
    ctrl2local_in_rep_reg = 2'b0;
    en_pass_req_reg = 1'b0;
    en_pass_rep_reg = 1'b0;
    en_local_in_req_reg = 1'b0;
    en_local_in_rep_reg = 1'b0;

    // Check if en_dest_fifo is enabled
    if (en_dest_fifo) begin
        case (dest_fifo)
            2'b00: begin
                flit2pass_req_reg = flit;
                ctrl2pass_req_reg = ctrl;
                en_pass_req_reg = 1'b1;
            end
            2'b01: begin
                flit2pass_rep_reg = flit;
                ctrl2pass_rep_reg = ctrl;
                en_pass_rep_reg = 1'b1;
            end
            2'b10: begin
                flit2local_in_req_reg = flit;
                ctrl2local_in_req_reg = ctrl;
                en_local_in_req_reg = 1'b1;
            end
            2'b11: begin
                flit2local_in_rep_reg = flit;
                ctrl2local_in_rep_reg = ctrl;
                en_local_in_rep_reg = 1'b1;
            end
            default: begin
                // Default case, no action
            end
        endcase
    end
end

// Assign outputs from registers
assign flit2pass_req = flit2pass_req_reg;
assign flit2pass_rep = flit2pass_rep_reg;
assign flit2local_in_req = flit2local_in_req_reg;
assign flit2local_in_rep = flit2local_in_rep_reg;
assign ctrl2pass_req = ctrl2pass_req_reg;
assign ctrl2pass_rep = ctrl2pass_rep_reg;
assign ctrl2local_in_req = ctrl2local_in_req_reg;
assign ctrl2local_in_rep = ctrl2local_in_rep_reg;
assign en_pass_req = en_pass_req_reg;
assign en_pass_rep = en_pass_rep_reg;
assign en_local_in_req = en_local_in_req_reg;
assign en_local_in_rep = en_local_in_rep_reg;

endmodule

module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    reg [2:0] bit_counter; // Counter to track the number of bits received

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset the module
            dout_parallel <= 8'b0;
            dout_valid <= 1'b0;
            bit_counter <= 3'b000;
        end else if (din_valid) begin
            // Shift the serial data into the parallel output register
            dout_parallel <= {din_serial, dout_parallel[7:1]};
            // Increment the bit counter
            bit_counter <= bit_counter + 1;
            // Check if a complete byte has been received
            if (bit_counter == 3'b111) begin
                dout_valid <= 1'b1; // Set the valid output flag
                bit_counter <= 3'b000; // Reset the counter for the next byte
            end else begin
                dout_valid <= 1'b0; // Clear the valid output flag
            end
        end
    end

endmodule

