module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );

    // Internal registers for intermediate results
    reg [63 : 0] a0, a1, b0, b1, b2, b3, c0, c1, d0, d1, d2, d3;

    // Combinational logic for the Blake2 G function
    always @* begin
        // Step 1: a0 = a + m0
        a0 = a + m0;

        // Step 2: b0 = b + m1
        b0 = b + m1;

        // Step 3: c0 = c + a0
        c0 = c + a0;

        // Step 4: d0 = d + b0
        d0 = d + b0;

        // Step 5: a1 = a0 ^ b0
        a1 = a0 ^ b0;

        // Step 6: b1 = c0 ^ d0
        b1 = c0 ^ d0;

        // Step 7: c1 = a1 + b1
        c1 = a1 + b1;

        // Step 8: d1 = b1 + c1
        d1 = b1 + c1;

        // Step 9: a2 = a1 ^ d1
        a1 = a1 ^ d1;

        // Step 10: b2 = c1 ^ a1
        b1 = c1 ^ a1;

        // Step 11: c2 = a2 + b2
        c1 = a1 + b1;

        // Step 12: d2 = b2 + c2
        d1 = b1 + c1;

        // Step 13: a3 = a2 ^ d2
        a1 = a1 ^ d1;

        // Step 14: b3 = c2 ^ a3
        b1 = c1 ^ a1;

        // Step 15: c3 = a3 + b3
        c1 = a1 + b1;

        // Step 16: d3 = b3 + c3
        d1 = b1 + c1;

        // Final outputs
        a_prim = a1;
        b_prim = b1;
        c_prim = c1;
        d_prim = d1;
    end

endmodule

