module sincf #(parameter win=1, wout=5)
(
	input clk,
	input [win-1:0] din,
	output reg [wout-1:0] dout
);

reg [win-1:0] mem [0:23];

always @(posedge clk) begin
	int i;
	int sum = 0;

	// Shift the register right
	for (i = 23; i > 0; i = i - 1) begin
		mem[i] <= mem[i-1];
	end
	mem[0] <= din;

	// Calculate the sum of the elements in the register
	for (i = 0; i < 24; i = i + 1) begin
		sum = sum + mem[i];
	end

	// Assign the sum to the output
	dout <= sum;
end

endmodule

