module complexmulttrial(
    input [15:0] a_r,
    input [15:0] a_i,
    input [15:0] b_r,
    input [15:0] b_i,
    input [15:0] w_r,
    input [15:0] w_i,
    output [15:0] x_r,
    output [15:0] x_i,
    output [15:0] y_r,
    output [15:0] y_i
);

    // Internal wires for intermediate calculations
    wire [31:0] add_real;
    wire [31:0] add_imag;
    wire [31:0] sub_real;
    wire [31:0] sub_imag;
    wire [31:0] mult_real;
    wire [31:0] mult_imag;

    // Addition of complex numbers a and b
    assign add_real = {16'b0, a_r} + {16'b0, b_r};
    assign add_imag = {16'b0, a_i} + {16'b0, b_i};

    // Subtraction of complex numbers a and b
    assign sub_real = {16'b0, a_r} - {16'b0, b_r};
    assign sub_imag = {16'b0, a_i} - {16'b0, b_i};

    // Multiplication of the result of subtraction with complex number w
    assign mult_real = sub_real * w_r - sub_imag * w_i;
    assign mult_imag = sub_real * w_i + sub_imag * w_r;

    // Scaling the results by selecting higher bits
    assign x_r = mult_real[31:16];
    assign x_i = mult_imag[31:16];
    assign y_r = add_real[31:16];
    assign y_i = add_imag[31:16];

endmodule

