module sbox(
	output [7:0] SubByte,
	input [7:0] num
	);

// Intermediate signals
wire [7:0] y;
wire [7:0] t;
wire [7:0] z;
wire [7:0] tc;

// First layer of operations
assign y = num ^ {num[6:0], num[7]}; // Rotate right by 1 bit and XOR with original
assign t = y ^ {y[5:0], y[7:6]}; // Rotate right by 2 bits and XOR with intermediate

// Second layer of operations
assign z = t ^ {t[4:0], t[7:5]}; // Rotate right by 3 bits and XOR with intermediate
assign tc = z ^ {z[3:0], z[7:4]}; // Rotate right by 4 bits and XOR with intermediate

// Final transformation
assign SubByte = tc ^ {tc[2:0], tc[7:3]}; // Rotate right by 5 bits and XOR with intermediate

endmodule

