module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);

  // Parameters for baud rate calculation
  parameter CLK_FREQ = 50000000; // System clock frequency in Hz
  parameter UART_BPS = 9600;     // Desired baud rate in bps
  parameter BPS_CNT = CLK_FREQ / UART_BPS; // Clock cycles per bit

  // Internal registers
  reg [31:0] clk_cnt; // Clock cycle counter
  reg [2:0] tx_cnt;  // Data bit counter
  reg tx_flag;       // Transmission flag
  reg [7:0] tx_data; // Data register to hold the data to be sent

  // Double flip-flop synchronization for uart_en
  reg uart_en_sync1;
  reg uart_en_sync2;

  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_en_sync1 <= 0;
      uart_en_sync2 <= 0;
    end else begin
      uart_en_sync1 <= uart_en;
      uart_en_sync2 <= uart_en_sync1;
    end
  end

  // Detect rising edge of uart_en
  reg uart_en_rising;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_en_rising <= 0;
    end else begin
      uart_en_rising <= uart_en_sync2 & ~uart_en_sync1;
    end
  end

  // State machine for UART transmission
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      clk_cnt <= 0;
      tx_cnt <= 0;
      tx_flag <= 0;
      tx_data <= 0;
      uart_txd <= 1; // Idle state: high
    end else begin
      if (uart_en_rising) begin
        // Load data and start transmission
        tx_data <= uart_din;
        tx_cnt <= 0;
        clk_cnt <= 0;
        tx_flag <= 1;
        uart_txd <= 0; // Start bit
      end else if (tx_flag) begin
        // Increment clock cycle counter
        if (clk_cnt < BPS_CNT - 1) begin
          clk_cnt <= clk_cnt + 1;
        end else begin
          clk_cnt <= 0;
          // Transmit data bits
          if (tx_cnt < 8) begin
            uart_txd <= tx_data[tx_cnt];
            tx_cnt <= tx_cnt + 1;
          end else begin
            // Transmit stop bit
            uart_txd <= 1;
            tx_flag <= 0; // Transmission complete
          end
        end
      end
    end
  end

endmodule

