  input [83:0] RW0_wdata,
  output [83:0] RW0_rdata
);

  // Internal registers
  reg [83:0] ram [0:63];
  reg [5:0] read_addr;
  reg read_en;

  // Initialize the RAM with random values
  initial begin
    foreach (ram[i]) begin
      ram[i] = $random;
    end
  end

  // Randomize read data when not enabled
  always @(posedge RW0_clk) begin
    if (!RW0_en) begin
      RW0_rdata <= $random;
    end
  end

  // Latch address and read enable on the rising edge of the clock
  always @(posedge RW0_clk) begin
    if (RW0_en) begin
      read_addr <= RW0_addr;
      read_en <= RW0_en;
    end
  end

  // Read operation
  always @(*) begin
    if (read_en) begin
      RW0_rdata = ram[read_addr];
    end
  end

  // Write operation
  always @(posedge RW0_clk) begin
    if (RW0_wmode && RW0_en) begin
      for (int i = 0; i < 4; i++) begin
        if (RW0_wmask[i]) begin
          ram[RW0_addr][i*21 +: 21] <= RW0_wdata[i*21 +: 21];
        end
      end
    end
  end

endmodule

module boardSynchroniser(
    input clk,
    input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
);

    reg [1:0] counter;
    reg toggleEdgeDetected;
    reg internalSynch;

    // Detect rising edge on toggle_en
    always @(posedge clk) begin
        if (!toggle_en && toggleEdgeDetected)
            toggleEdgeDetected <= 0;
        else if (toggle_en && !toggleEdgeDetected)
            toggleEdgeDetected <= 1;
    end

    // Counter logic
    always @(posedge clk) begin
        if (toggleEdgeDetected) begin
            if (counter == cnt_m)
                counter <= cnt_n;
            else
                counter <= counter + 1;
        end
    end

    // Synchronization signal logic
    always @(posedge clk) begin
        if (counter == cnt_m)
            internalSynch <= 1;
        else if (counter == cnt_n)
            internalSynch <= 0;
    end

    // Output logic based on opMode
    always @(posedge clk) begin
        if (opMode) begin
            synchroStatus <= internalSynch;
            syncInOut <= internalSynch;
        end else begin
            synchroStatus <= syncInOut;
        end
    end

endmodule

