module alu_32 (
  input_a,
  input_b,
  control,
  zero, 
  cout,
  err_overflow,
  err_invalid_control,
  result
); 

parameter WORD_SIZE = 32;
parameter CONTROL_SIGNAL_SIZE = 4;

parameter AND = 4'b0000;
parameter OR = 4'b0001;
parameter ADD = 4'b0010;
parameter ADD_UNSIGNED = 4'b0011;
parameter SUB = 4'b0100;
parameter SLT = 4'b0101;
parameter NOR = 4'b0110;

input wire [WORD_SIZE-1:0]	input_a;
input wire [WORD_SIZE-1:0]	input_b;
input wire [CONTROL_SIGNAL_SIZE-1:0]	control;
output wire       zero;
output reg	      cout;
output reg	      err_overflow;
output reg	      err_invalid_control;
output reg [WORD_SIZE-1:0]	result;

always @(*) begin
  result = 32'b0;
  zero = 1'b0;
  cout = 1'b0;
  err_overflow = 1'b0;
  err_invalid_control = 1'b0;

  case (control)
    AND: begin
      result = input_a & input_b;
    end
    OR: begin
      result = input_a | input_b;
    end
    ADD: begin
      {cout, result} = input_a + input_b;
      if ((input_a[WORD_SIZE-1] == input_b[WORD_SIZE-1]) && (result[WORD_SIZE-1] != input_a[WORD_SIZE-1])) begin
        err_overflow = 1'b1;
      end
    end
    ADD_UNSIGNED: begin
      {cout, result} = input_a + input_b;
    end
    SUB: begin
      {cout, result} = input_a - input_b;
      if ((input_a[WORD_SIZE-1] != input_b[WORD_SIZE-1]) && (result[WORD_SIZE-1] != input_a[WORD_SIZE-1])) begin
        err_overflow = 1'b1;
      end
    end
    SLT: begin
      result = (input_a < input_b) ? 32'b1 : 32'b0;
    end
    NOR: begin
      result = ~(input_a | input_b);
    end
    default: begin
      err_invalid_control = 1'b1;
    end
  endcase

  if (result == 32'b0) begin
    zero = 1'b1;
  end
end

endmodule

