module probe_fifo (
	aclr,
	data,
	rdclk,
	rdreq,
	wrclk,
	wrreq,
	q,
	rdempty,
	rdfull,
	wrfull);

	input	  aclr;
	input	[63:0]  data;
	input	  rdclk;
	input	  rdreq;
	input	  wrclk;
	input	  wrreq;
	output	[63:0]  q;
	output	  rdempty;
	output	  rdfull;
	output	  wrfull;

	// Internal signals for FIFO implementation
	reg [63:0] fifo_mem [0:63]; // Assuming a 64x64 FIFO for simplicity
	reg [5:0]  read_ptr;
	reg [5:0]  write_ptr;
	reg [5:0]  count;

	// Asynchronous clear
	always @(posedge aclr) begin
		read_ptr <= 6'b0;
		write_ptr <= 6'b0;
		count <= 6'b0;
		q <= 64'b0;
		rdempty <= 1'b1;
		rdfull <= 1'b0;
		wrfull <= 1'b0;
	end

	// Write logic
	always @(posedge wrclk) begin
		if (aclr) begin
			// Reset logic handled above
		end else if (wrreq && !wrfull) begin
			fifo_mem[write_ptr] <= data;
			write_ptr <= (write_ptr + 1) % 64;
			count <= count + 1;
			if (count == 63)
				wrfull <= 1'b1;
		end
	end

	// Read logic
	always @(posedge rdclk) begin
		if (aclr) begin
			// Reset logic handled above
		end else if (rdreq && !rdempty) begin
			q <= fifo_mem[read_ptr];
			read_ptr <= (read_ptr + 1) % 64;
			count <= count - 1;
			if (count == 0)
				rdempty <= 1'b1;
		end
	end

	// Status logic
	always @(posedge wrclk or posedge aclr) begin
		if (aclr)
			wrfull <= 1'b0;
		else if (wrreq && !wrfull)
			wrfull <= (count == 63);
	end

	always @(posedge rdclk or posedge aclr) begin
		if (aclr)
			rdempty <= 1'b1;
		else if (rdreq && !rdempty)
			rdempty <= (count == 0);
	end

	always @(posedge rdclk or posedge aclr) begin
		if (aclr)
			rdfull <= 1'b0;
		else if (rdreq && !rdempty)
			rdfull <= (count == 63);
	end

endmodule

