module BIBUF_S_8U(Y, D, E, PAD);
    parameter Tpd_E_PAD = 1.0; // Propagation delay from E to PAD
    parameter Tpd_D_PAD = 1.0; // Propagation delay from D to PAD
    parameter Tpd_PAD_Y = 1.0; // Propagation delay from PAD to Y
    parameter Tpw_MIN_PAD = 0.1; // Minimum pulse width for PAD
    parameter Tpw_MIN_D = 0.1; // Minimum pulse width for D
    parameter Tpw_MIN_E = 0.1; // Minimum pulse width for E

    input D, E;
    output Y;
    inout PAD;

    reg NOTIFY_REG;
    reg [1:0] state;

    // State encoding: 00 - Idle, 01 - Driving, 10 - Receiving, 11 - Error
    parameter IDLE = 2'b00;
    parameter DRIVING = 2'b01;
    parameter RECEIVING = 2'b10;
    parameter ERROR = 2'b11;

    always @(posedge E or negedge E) begin
        if (E) begin
            state <= DRIVING;
            PAD <= D;
        end else begin
            state <= RECEIVING;
        end
    end

    always @(posedge PAD or negedge PAD) begin
        if (state == RECEIVING) begin
            Y <= PAD;
        end
    end

    // Pulse width monitoring
    always @(posedge E or negedge E) begin
        if (E) begin
            if ($time - $past($time) < Tpw_MIN_E) begin
                NOTIFY_REG <= 1;
            end
        end
    end

    always @(posedge D or negedge D) begin
        if (D) begin
            if ($time - $past($time) < Tpw_MIN_D) begin
                NOTIFY_REG <= 1;
            end
        end
    end

    always @(posedge PAD or negedge PAD) begin
        if (PAD) begin
            if ($time - $past($time) < Tpw_MIN_PAD) begin
                NOTIFY_REG <= 1;
            end
        end
    end

    // Error handling
    always @(posedge NOTIFY_REG) begin
        state <= ERROR;
    end

endmodule

