  reg [AXI_ADDR_WIDTH-1:0] axi_read_addr;
  reg axi_read_addr_valid;
  reg [BRAM_ADDR_WIDTH-1:0] bram_addr;
  reg bram_addr_valid;
  reg [AXI_DATA_WIDTH-1:0] axi_rdata;
  reg axi_rvalid_reg;
  reg axi_rready_d1;

  // Assignments
  assign bram_porta_clk = aclk;
  assign bram_porta_rst = ~aresetn;
  assign s_axi_awready = 1'b0;
  assign s_axi_wready = 1'b0;
  assign s_axi_bresp = 2'b00;
  assign s_axi_bvalid = 1'b0;
  assign s_axi_rdata = axi_rdata;
  assign s_axi_rresp = 2'b00;
  assign s_axi_rvalid = axi_rvalid_reg;
  assign bram_porta_addr = bram_addr;

  // State machine for AXI read requests
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      axi_read_addr_valid <= 1'b0;
      axi_rvalid_reg <= 1'b0;
      bram_addr_valid <= 1'b0;
