      if (bram_addr_valid && bram_porta_rddata_valid) begin
        axi_rdata <= bram_porta_rddata;
        axi_rvalid_reg <= 1'b1;
        bram_addr_valid <= 1'b0;
      end

      // Clear read valid when data is accepted
      if (axi_rvalid_reg && s_axi_rready) begin
        axi_rvalid_reg <= 1'b0;
      end
    end
  end

  // Register s_axi_rready for edge detection
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      axi_rready_d1 <= 1'b0;
    end else begin
      axi_rready_d1 <= s_axi_rready;
    end
  end

  // Generate s_axi_arready based on edge detection
  assign s_axi_arready = !axi_read_addr_valid && (s_axi_arvalid && !axi_rready_d1);

