reg [WAVE_LEN_WIDTH-1:0] wave_counter;
reg pwm_out_reg;

assign wave_length_out = wave_length_reg;
assign pulse_width_out = pulse_width_reg;
assign active_high_out = active_high_reg;
assign pwm_out = pwm_out_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        wave_length_reg <= WAVE_WEIGHT;
        pulse_width_reg <= WAVE_WEIGHT / 2;
        active_high_reg <= 1'b0;
        weight_counter <= 0;
        wave_counter <= 0;
        pwm_out_reg <= 1'b0;
    end else begin
        if (update) begin
            wave_length_reg <= wave_length;
            pulse_width_reg <= pulse_width;
            active_high_reg <= active_high;
            weight_counter <= 0;
            wave_counter <= 0;
        end else begin
            if (weight_counter == wave_length_reg - 1) begin
                weight_counter <= 0;
                if (wave_counter == WAVE_WEIGHT - 1) begin
                    wave_counter <= 0;
                end else begin
                    wave_counter <= wave_counter + 1;
                end
            end else begin
                weight_counter <= weight_counter + 1;
            end

            if (enable) begin
                if (weight_counter < pulse_width_reg) begin
                    pwm_out_reg <= active_high_reg;
                end else begin
                    pwm_out_reg <= ~active_high_reg;
                end
            end else begin
                pwm_out_reg <= 1'b0;
            end
        end
    end
end

endmodule

module dffeas (d, clk, ena, clrn, prn, aload, asdata, sclr, sload, devclrn, devpor, q );

parameter POWER_UP_STATE = 1'b0;
parameter WYSIWYG_MODE = 1'b0;
parameter VIOLATION_HANDLING = 1'b0;

input d;
input clk;
input ena;
input clrn;
input prn;
input aload; 
input asdata;  
input sclr; 
input sload; 
input devclrn; 
input devpor; 

output q;

reg q_tmp;
reg reset;
reg d_viol;
reg sclr_viol;
reg asdata_dly;

assign q = q_tmp;

always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        q_tmp <= POWER_UP_STATE;
        reset <= 1'b1;
    end else if (!clrn) begin
        q_tmp <= 1'b0;
        reset <= 1'b1;
    end else if (!prn) begin
        q_tmp <= 1'b1;
        reset <= 1'b1;
    end else if (ena) begin
        if (sclr && !sclr_viol) begin
            q_tmp <= 1'b0;
            reset <= 1'b1;
        end else if (sload) begin
            q_tmp <= d;
            reset <= 1'b0;
        end else if (aload && !d_viol) begin
            q_tmp <= asdata_dly;
            reset <= 1'b0;
        end else begin
            q_tmp <= q_tmp;
            reset <= 1'b0;
        end
    end else begin
        q_tmp <= q_tmp;
        reset <= 1'b0;
    end
end

always @(posedge clk) begin
    asdata_dly <= asdata;
end

always @(posedge clk or negedge devclrn) begin
    if (!devclrn) begin
        d_viol <= 1'b0;
        sclr_viol <= 1'b0;
    end else begin
        d_viol <= (aload && !reset);
        sclr_viol <= (sclr && !reset);
    end
end

specify
    (posedge clk => q_tmp) = 10;
    (posedge clk => q_tmp) = 5;
    (posedge clk => q_tmp) = 10;
    (posedge clk => q_tmp) = 5;
endspecify

