module scan_hex_led_disp(
    input clk, reset,
    input [3:0] hex3, hex2, hex1, hex0,
    input [3:0] dp,
    output reg [3:0] en,
    output reg [7:0] sseg
);

    reg [1:0] digit_select;
    reg [3:0] current_hex;
    reg current_dp;

    // Counter to select the current digit
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            digit_select <= 2'b00;
        end else begin
            digit_select <= digit_select + 1;
        end
    end

    // Mux to select the current hex digit and decimal point
    always @(*) begin
        case (digit_select)
            2'b00: begin
                current_hex = hex0;
                current_dp = dp[0];
            end
            2'b01: begin
                current_hex = hex1;
                current_dp = dp[1];
            end
            2'b10: begin
                current_hex = hex2;
                current_dp = dp[2];
            end
            2'b11: begin
                current_hex = hex3;
                current_dp = dp[3];
            end
        endcase
    end

    // Decode the current hex digit to seven-segment pattern
    always @(*) begin
        case (current_hex)
            4'b0000: sseg = 8'b00111111; // 0
            4'b0001: sseg = 8'b00000110; // 1
            4'b0010: sseg = 8'b01011011; // 2
            4'b0011: sseg = 8'b01001111; // 3
            4'b0100: sseg = 8'b01100110; // 4
            4'b0101: sseg = 8'b01101101; // 5
            4'b0110: sseg = 8'b01111101; // 6
            4'b0111: sseg = 8'b00000111; // 7
            4'b1000: sseg = 8'b01111111; // 8
            4'b1001: sseg = 8'b01101111; // 9
            4'b1010: sseg = 8'b01110111; // A
            4'b1011: sseg = 8'b01111100; // B
            4'b1100: sseg = 8'b00111001; // C
            4'b1101: sseg = 8'b01011110; // D
            4'b1110: sseg = 8'b01111001; // E
            4'b1111: sseg = 8'b01110001; // F
            default: sseg = 8'b00000000; // Blank
        endcase
    end

    // Enable the current digit
    always @(*) begin
        case (digit_select)
            2'b00: en = 4'b0001;
            2'b01: en = 4'b0010;
            2'b10: en = 4'b0100;
            2'b11: en = 4'b1000;
        endcase
    end

    // Handle the decimal point
    always @(*) begin
        if (current_dp) begin
            sseg[7] = 1'b0; // Turn on decimal point
        end else begin
            sseg[7] = 1'b1; // Turn off decimal point
        end
    end

endmodule

module linear_layer (
    input [63:0] x0, x1, x2, x3, x4,
    output [63:0] o0, o1, o2, o3, o4
);

// Define rotation shifts for each input
localparam [5:0] ROT0 = 3, ROT1 = 5, ROT2 = 7, ROT3 = 9, ROT4 = 11;

// Function to perform rotation
function [63:0] rotate;
    input [63:0] data;
    input [5:0] shift;
    begin
        rotate = (data >> shift) | (data << (64 - shift));
    end
endfunction

// Compute each output using XOR and rotation
assign o0 = x0 ^ rotate(x0, ROT0);
assign o1 = x1 ^ rotate(x1, ROT1);
assign o2 = x2 ^ rotate(x2, ROT2);
assign o3 = x3 ^ rotate(x3, ROT3);
assign o4 = x4 ^ rotate(x4, ROT4);

endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
);

    // Internal wire to hold the sign-extended data
    wire [16:0] tmp;

    // Sign-extend the 14-bit input data to 17 bits
    assign tmp = { {3{data_i[13]}}, data_i };

    // Combinational logic to perform the barrel shift
    always @(*) begin
        case (shift_i)
            2'b00: data_o = tmp << 0; // No shift
            2'b01: data_o = tmp << 1; // Shift left by 1
            2'b10: data_o = tmp << 2; // Shift left by 2
            2'b11: data_o = tmp << 3; // Shift left by 3
            default: data_o = tmp;    // Default case, should not occur
        endcase
    end

endmodule

module decoder_3to8 
