        end else begin
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
        end
    end

endmodule

module Data_Memory(
    input wire clk, rst, MemWrite, MemRead, mem_to_reg,
    input wire [31:0] addr, write_data,
    output reg [31:0] read_data
);

    // Define the memory array with 32 registers, each 32 bits wide
    reg [31:0] memory [0:31];

    // Initial block to set all memory locations to zero on power-up
    initial begin
        for (int i = 0; i < 32; i = i + 1) begin
            memory[i] = 32'b0;
        end
    end

    // Always block to handle write operations on the rising edge of the clock
    always @(posedge clk) begin
        if (MemWrite) begin
            memory[addr] <= write_data;
        end
    end

    // Combinational logic to handle read operations
    always @(*) begin
        if (MemRead) begin
            read_data = memory[addr];
        end else begin
            read_data = 32'b0;
        end
    end

endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);

    reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;

    assign out = cnt;
    assign ovf = (updown & (cnt == {BITS{1'b1}})) | (~updown & (cnt == {BITS{1'b0}}));

    genvar i;
    generate
        for (i = 0; i < BITS; i = i + 1) begin : bit_enable
            if (i == 0) begin
                assign enable_wires[i] = ena;
            end else begin
                assign enable_wires[i] = enable_wires[i - 1] & (cnt[i - 1] == (updown ? 1'b1 : 1'b0));
            end
        end
    endgenerate

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt <= {BITS{1'b0}};
        end else if (ena) begin
            if (updown) begin
                if (cnt == {BITS{1'b1}}) begin
                    cnt <= {BITS{1'b0}};
                end else begin
                    cnt <= cnt + 1;
                end
            end else begin
                if (cnt == {BITS{1'b0}}) begin
                    cnt <= {BITS{1'b1}};
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end

endmodule

module BCD(
    input [15:0] binary,
    output wire [3:0] b,
    output wire [3:0] s,
    output wire [3:0] g,
    output wire [3:0] q
);
    reg [31:0] temp;
    integer i;

    always @(*) begin
        temp = {16'b0, binary}; // Initialize the 32-bit register with the binary input

        // Repeat loop to process each nibble
        for (i = 0; i < 16; i = i + 1) begin
            if (temp[3:0] > 4) temp = temp + 3;
            if (temp[7:4] > 4) temp = temp + (3 << 4);
            if (temp[11:8] > 4) temp = temp + (3 << 8);
            if (temp[15:12] > 4) temp = temp + (3 << 12);
            if (temp[19:16] > 4) temp = temp + (3 << 16);
            if (temp[23:20] > 4) temp = temp + (3 << 20);
            if (temp[27:24] > 4) temp = temp + (3 << 24);
            if (temp[31:28] > 4) temp = temp + (3 << 28);

            temp = temp >> 1; // Shift right to process the next nibble
        end

        // Assign the processed nibbles to the output ports
        b = temp[3:0];
        s = temp[7:4];
        g = temp[11:8];
        q = temp[15:12];
    end
endmodule

module risc_v_32_mem(m_addr, d_f_mem, inst_decode, mem_out);
    input  [31:0] m_addr;                                    
    input  [31:0] d_f_mem;                                   
    input  [36:0] inst_decode;								 
    output reg [31:0] mem_out;

    // Extract instruction decode signals
    wire i_lw = inst_decode[0];
    wire i_lbu = inst_decode[1];
    wire i_lb = inst_decode[2];
    wire i_lhu = inst_decode[3];
    wire i_lh = inst_decode[4];

    // Extract address alignment bits
    wire [1:0] addr_align = m_addr[1:0];

    // Temporary variables for byte and half-word loads
    wire [7:0] byte_data;
    wire [15:0] half_word_data;

    // Assign byte and half-word data based on address alignment
    assign byte_data = d_f_mem[addr_align * 8 +: 8];
    assign half_word_data = d_f_mem[addr_align * 8 +: 16];

    // Combinational logic to determine mem_out based on instruction decode
    always @(*) begin
        if (i_lw) begin
            // Load word (32 bits)
            mem_out = d_f_mem;
        end else if (i_lbu) begin
            // Load byte unsigned
            mem_out = {24'b0, byte_data};
        end else if (i_lb) begin
            // Load byte signed
            mem_out = {{24{byte_data[7]}}, byte_data};
        end else if (i_lhu) begin
            // Load half-word unsigned
            mem_out = {16'b0, half_word_data};
        end else if (i_lh) begin
            // Load half-word signed
            mem_out = {{16{half_word_data[15]}}, half_word_data};
        end else begin
            // Default case (should not happen)
            mem_out = 32'b0;
        end
    end
endmodule

module Data_Memory 
#(	
	parameter DATA_WIDTH = 32,
	parameter MEMORY_DEPTH = 64
)
(
	input clk, Write_Enable_i, 
	input [DATA_WIDTH-1:0] Write_Data_i,
	input [DATA_WIDTH-1:0]  Address_i,
	output reg [(DATA_WIDTH-1):0]  Read_Data_o
);

	// Memory array declaration
	reg [DATA_WIDTH-1:0] memory [0:MEMORY_DEPTH-1];

	// Static base address register
	reg [DATA_WIDTH-1:0] Var_i = 32'h10010000;

	// Calculate effective address
	wire [DATA_WIDTH-1:0] effective_address = (Address_i - Var_i) >> 2;

	// Write operation on the positive edge of the clock
	always @(posedge clk) begin
		if (Write_Enable_i) begin
			memory[effective_address] <= Write_Data_i;
		end
	end

	// Read operation is combinational
	assign Read_Data_o = memory[effective_address];

endmodule

