module wb_bridge_16_32
  #(parameter AWIDTH=16)
    (input wb_clk, input wb_rst,
     input A_cyc_i, input A_stb_i, input A_we_i, input [3:0] A_sel_i,
     input [AWIDTH-1:0] A_adr_i, input [31:0] A_dat_i, output [31:0] A_dat_o, output A_ack_o,
     output B_cyc_o, output B_stb_o, output B_we_o, output [1:0] B_sel_o,
     output [AWIDTH-1:0] B_adr_o, output [15:0] B_dat_o, input [15:0] B_dat_i, input B_ack_i
     );

  reg [1:0] phase;
  reg [31:0] temp_data;
  reg [AWIDTH-1:0] temp_addr;
  reg [3:0] temp_sel;
  reg A_ack_r;

  always @(posedge wb_clk or posedge wb_rst) begin
    if (wb_rst) begin
      phase <= 2'b00;
      A_ack_r <= 1'b0;
    end else begin
      case (phase)
        2'b00: begin
          if (A_cyc_i && A_stb_i) begin
            temp_data <= A_dat_i;
            temp_addr <= A_adr_i;
            temp_sel <= A_sel_i;
            B_cyc_o <= 1'b1;
            B_stb_o <= 1'b1;
            B_we_o <= A_we_i;
            B_sel_o <= A_sel_i[1:0];
            B_adr_o <= A_adr_i;
            B_dat_o <= temp_data[15:0];
            phase <= 2'b01;
          end else begin
            B_cyc_o <= 1'b0;
            B_stb_o <= 1'b0;
            A_ack_r <= 1'b0;
          end
        end
        2'b01: begin
          if (B_ack_i) begin
            if (A_we_i) begin
              B_cyc_o <= 1'b0;
              B_stb_o <= 1'b0;
              A_ack_r <= 1'b1;
              phase <= 2'b00;
            end else begin
              B_cyc_o <= 1'b1;
              B_stb_o <= 1'b1;
              B_we_o <= A_we_i;
              B_sel_o <= A_sel_i[3:2];
              B_adr_o <= temp_addr + 1'b1;
              B_dat_o <= temp_data[31:16];
              phase <= 2'b10;
            end
          end else begin
            B_cyc_o <= 1'b1;
            B_stb_o <= 1'b1;
          end
        end
        2'b10: begin
          if (B_ack_i) begin
            B_cyc_o <= 1'b0;
            B_stb_o <= 1'b0;
            A_ack_r <= 1'b1;
            phase <= 2'b00;
          end else begin
            B_cyc_o <= 1'b1;
            B_stb_o <= 1'b1;
          end
        end
      endcase
    end
  end

  assign A_ack_o = A_ack_r;
  assign A_dat_o = {B_dat_i, B_dat_i}; // Assuming read data is the same for both halves

endmodule

module Divider #(parameter Time=20)
(
    input I_CLK,
    output reg O_CLK
);

reg [31:0] counter;

always @(posedge I_CLK) begin
    if (counter == Time / 2) begin
        O_CLK <= ~O_CLK;
        counter <= 0;
    end else begin
        counter <= counter + 1;
    end
end

initial begin
    O_CLK = 0;
end

endmodule

