module IB_ENDPOINT_OP_DONE_BUFFER(
    input wire CLK,
    input wire RESET,
    input wire [15:0] RD_COMPL_TAG,
    input wire RD_COMPL_START,
    input wire RD_COMPL_DONE,
    input wire [15:0] BM_TAG,
    input wire BM_DONE,
    output wire [15:0] OP_TAG,
    output wire OP_DONE
);

    // Internal registers
    reg [15:0] rd_compl_tag_reg;
    reg rd_compl_start_reg;
    reg rd_compl_done_reg;
    reg [15:0] bm_tag_reg;
    reg bm_done_reg;
    reg [15:0] op_tag_reg;
    reg op_done_reg;

    // Combinational logic to determine the output tag and done signal
    always @(*) begin
        if (rd_compl_start_reg) begin
            OP_TAG = rd_compl_tag_reg;
            OP_DONE = rd_compl_done_reg;
        end else if (bm_done_reg) begin
            OP_TAG = bm_tag_reg;
            OP_DONE = bm_done_reg;
        end else begin
            OP_TAG = 16'b0;
            OP_DONE = 1'b0;
        end
    end

    // Sequential logic to update internal registers
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            rd_compl_tag_reg <= 16'b0;
            rd_compl_start_reg <= 1'b0;
            rd_compl_done_reg <= 1'b0;
            bm_tag_reg <= 16'b0;
            bm_done_reg <= 1'b0;
            op_tag_reg <= 16'b0;
            op_done_reg <= 1'b0;
        end else begin
            rd_compl_tag_reg <= RD_COMPL_TAG;
            rd_compl_start_reg <= RD_COMPL_START;
            rd_compl_done_reg <= RD_COMPL_DONE;
            bm_tag_reg <= BM_TAG;
            bm_done_reg <= BM_DONE;
            // op_tag_reg and op_done_reg are updated by combinational logic
        end
    end

endmodule

module BBFFloor(
    input  [63:0] in,
    output reg [63:0] out
);

always @(*) begin
    // Convert the 64-bit input to a real number
    real input_real = $bitstodp(in);

    // Apply the floor operation to the real number
    real floored_real = $floor(input_real);

    // Convert the floored real number back to a 64-bit format
    out = $dptobits(floored_real);
end

endmodule

