module mips_alu(zero, result, alu_op, first_data, second_data, shamt);
    output reg zero;                    
    output reg [31:0] result;
    input [31:0] first_data;        
    input [31:0] second_data;        
    input [3:0] alu_op;                
    input [4:0] shamt;

    always @(*) begin
        case (alu_op)
            4'b0000: result = first_data + second_data; // ADD
            4'b0001: result = first_data - second_data; // SUB
            4'b0010: result = first_data & second_data; // AND
            4'b0011: result = first_data | second_data; // OR
            4'b0100: result = ~(first_data | second_data); // NOR
            4'b0101: result = first_data << shamt; // SLL
            4'b0110: result = first_data >> shamt; // SRL
            4'b0111: result = $signed(first_data) >>> shamt; // SRA
            4'b1000: result = first_data ^ second_data; // XOR
            4'b1001: result = first_data; // LW
            4'b1010: result = second_data; // SW
            default: result = 32'b0;
        endcase

        // Check if the result is zero
        if (result == 32'b0)
            zero = 1'b1;
        else
            zero = 1'b0;
    end
endmodule

module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
);

input  clk;
input  shiftnld;
input  captnupdt;

output mainclk;
output updateclk;
output capture;
output update;

reg temp_mainclk;
reg temp_updateclk;
reg temp_capture;
reg temp_update;

assign mainclk = temp_mainclk & clk;
assign updateclk = temp_updateclk & clk;
assign capture = temp_capture;
assign update = temp_update;

always @(captnupdt or shiftnld or clk) begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11: begin
            temp_updateclk <= 1'b1;
            temp_capture <= 1'b1;
            temp_mainclk <= 1'b0;
            temp_update <= 1'b0;
        end
        2'b01: begin
            temp_updateclk <= 1'b1;
            temp_capture <= 1'b0;
            temp_mainclk <= 1'b0;
            temp_update <= 1'b0;
        end
        default: begin
            temp_updateclk <= 1'b0;
            temp_capture <= 1'b0;
            temp_mainclk <= 1'b1;
            temp_update <= 1'b1;
        end
    endcase
end

initial begin
    temp_mainclk = 1'b0;
    temp_updateclk = 1'b0;
    temp_capture = 1'b0;
    temp_update = 1'b0;
end

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);

reg [15:0] V_cnt;
reg [15:0] H_cnt;
reg Pout_de_w;
reg Pout_hs_w;
reg Pout_vs_w;
reg Rden_w;

always @(posedge I_pxl_clk or negedge I_rst_n) begin
    if (!I_rst_n) begin
        V_cnt <= 0;
        H_cnt <= 0;
    end else begin
        if (H_cnt == I_h_total - 1) begin
            H_cnt <= 0;
            if (V_cnt == I_v_total - 1) begin
                V_cnt <= 0;
            end else begin
                V_cnt <= V_cnt + 1;
            end
        end else begin
            H_cnt <= H_cnt + 1;
        end
    end
end

always @(*) begin
    Pout_de_w = (H_cnt >= I_h_sync + I_h_bporch) && (H_cnt < I_h_sync + I_h_bporch + I_h_res) &&
                (V_cnt >= I_v_sync + I_v_bporch) && (V_cnt < I_v_sync + I_v_bporch + I_v_res);
    Pout_hs_w = (H_cnt >= I_h_sync) && (H_cnt < I_h_sync + I_h_res);
    Pout_vs_w = (V_cnt >= I_v_sync) && (V_cnt < I_v_sync + I_v_res);
    Rden_w = (H_cnt < I_rd_hres) && (V_cnt < I_rd_vres);
end

always @(posedge I_pxl_clk or negedge I_rst_n) begin
    if (!I_rst_n) begin
        O_rden <= 0;
        O_de <= 0;
        O_hs <= 0;
        O_vs <= 0;
    end else begin
        O_rden <= Rden_w;
        O_de <= Pout_de_w;
        O_hs <= I_hs_pol ? ~Pout_hs_w : Pout_hs_w;
        O_vs <= I_vs_pol ? ~Pout_vs_w : Pout_vs_w;
    end
end

endmodule

