module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,
        input  [WIDTH - 1 : 0] b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );

    always @(*) begin
        case (m)
            3'b000: begin // Addition
                y = a + b;
                cf = (a[WIDTH-1] & b[WIDTH-1] & ~y[WIDTH-1]) | (~a[WIDTH-1] & ~b[WIDTH-1] & y[WIDTH-1]);
                of = (a[WIDTH-1] ^ b[WIDTH-1]) & (a[WIDTH-1] ^ y[WIDTH-1]);
            end
            3'b001: begin // Subtraction
                y = a - b;
                cf = (~a[WIDTH-1] & b[WIDTH-1] & ~y[WIDTH-1]) | (a[WIDTH-1] & ~b[WIDTH-1] & y[WIDTH-1]);
                of = (a[WIDTH-1] ^ b[WIDTH-1]) & (a[WIDTH-1] ^ ~y[WIDTH-1]);
            end
            3'b010: begin // Bitwise AND
                y = a & b;
                cf = 1'b0;
                of = 1'b0;
            end
            3'b011: begin // Bitwise OR
                y = a | b;
                cf = 1'b0;
                of = 1'b0;
            end
            3'b100: begin // Bitwise XOR
                y = a ^ b;
                cf = 1'b0;
                of = 1'b0;
            end
            default: begin // No operation
                y = {WIDTH{1'b0}};
                cf = 1'b0;
                of = 1'b0;
            end
        endcase

        zf = (y == {WIDTH{1'b0}}) ? 1'b1 : 1'b0;
    end
endmodule

module arriaii_first_stage_add_sub(
                                 dataa,
                                 datab,
                                 sign,
                                 operation,
                                 dataout
                                );

parameter dataa_width = 36;
parameter datab_width = 36;
parameter fsa_mode = "add";

input [71:0] dataa;
input [71:0] datab;
input sign;
input [3:0] operation;

output [71:0] dataout;

reg [71:0] dataout_tmp;
reg [71:0] abs_b;
reg [71:0] abs_a;
reg sign_a;
reg sign_b;

always @(*) begin
    // Determine the absolute values and signs of dataa and datab
    if (sign) begin
        abs_a = dataa;
        abs_b = datab;
        sign_a = dataa[dataa_width-1];
        sign_b = datab[datab_width-1];
    end else begin
        abs_a = {~dataa[dataa_width-1], dataa[dataa_width-2:0]};
        abs_b = {~datab[datab_width-1], datab[datab_width-2:0]};
        sign_a = dataa[dataa_width-1];
        sign_b = datab[datab_width-1];
    end

    // Default operation is addition
    case (operation)
        4'b0000: begin // Standard add
            dataout_tmp = abs_a + abs_b;
        end
        4'b0001: begin // Standard subtract
            dataout_tmp = abs_a - abs_b;
        end
        4'b0010: begin // Specialized add
            dataout_tmp = {dataa[71:36], dataa[35:0] + datab[35:0]};
        end
        default: begin // Default to addition
            dataout_tmp = abs_a + abs_b;
        end
    endcase

    // Handle sign of the result
    if (sign_a ^ sign_b) begin
        dataout = {~dataout_tmp[71], dataout_tmp[70:0]};
    end else begin
        dataout = dataout_tmp;
    end
end

endmodule

