module pddm (
	input sdi, 
	input signed_data, 
	output reg [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);

reg [31:0] sigma;
reg [31:0] undersampled_sigma;
reg [31:0] delta;
reg [31:0] deriv;

always @(posedge clk or negedge rstn) begin
	if (!rstn) begin
		sigma <= 0;
		undersampled_sigma <= 0;
		dout <= 0;
	end else begin
		if (ock) begin
			if (sdi) begin
				sigma <= sigma + delta;
			end else begin
				sigma <= sigma - delta;
			end
		end

		if (uck) begin
			undersampled_sigma <= sigma;
		end

		deriv <= sigma - undersampled_sigma;

		if (signed_data) begin
			dout <= $signed(deriv);
		end else begin
			dout <= $unsigned(deriv);
		end
	end
end

assign delta = 1; // Step size for phase adjustment

endmodule

module RegFile(
