    always @(negedge Clk) begin
        if (ReadReg1 != 0) begin
            ReadData1 <= registers[ReadReg1];
        end else begin
            ReadData1 <= 32'b0;
        end

        if (ReadReg2 != 0) begin
            ReadData2 <= registers[ReadReg2];
        end else begin
            ReadData2 <= 32'b0;
        end
    end

    // Write operation on the positive clock edge
    always @(posedge Clk) begin
        if (RegWrite && WriteReg != 0) begin
