        end
    end

endmodule

module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR
);

    // Parameters for power dissipation calculation
    parameter Vcc = 3.3; // Supply voltage in volts
    parameter C_L = 10e-12; // Load capacitance in farads
    parameter t_hmin = 10e-9; // Hold time minimum in seconds
    parameter t_hmax = 20e-9; // Hold time maximum in seconds

    // Counter to track transitions
    integer counter = 0;

    // Sequential block for flip-flop operation
    always @(posedge CLK or negedge CLR_BAR) begin
        if (!CLR_BAR) begin
            Q <= 0; // Asynchronous clear
        end else begin
            Q <= D; // Load data on clock edge
        end
    end

    // Combinational block to monitor transitions and calculate power dissipation
    always @(Q) begin
        if (Q) begin
            counter = counter + 1; // Increment counter on transition to 1
        end
    end

    // Display power dissipation
    always @(counter) begin
        $display("Power Dissipation: %f W", counter * C_L * Vcc * Vcc);
    end

endmodule

