module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);

reg [31:0] counter;
reg [31:0] step;
reg auto_clk;
reg wasReady;

always @(posedge clk or posedge rst) begin
	if (rst) begin
		counter <= 0;
		step <= 0;
		auto_clk <= 0;
		wasReady <= 0;
		clkdiv <= 0;
		Clk_CPU <= 0;
		readn <= 1;
	end else begin
		if (keyReady && !wasReady) begin
			case (BTN_OK)
				4'b0001: step <= 100000000; // 1 step
				4'b0010: step <= 200000000; // 2 steps
				4'b0100: step <= 300000000; // 3 steps
				4'b1000: step <= 400000000; // 4 steps
				default: step <= 0;
			endcase
			counter <= step;
			auto_clk <= 0;
		end

		if (counter > 0) begin
			counter <= counter - 1;
			clkdiv <= clkdiv + 1;
			if (counter == 0) begin
				Clk_CPU <= ~Clk_CPU;
				if (SW15) begin
					auto_clk <= 1;
				end
			end
		end else if (auto_clk) begin
			counter <= step;
			auto_clk <= 0;
		end

		wasReady <= keyReady;
		readn <= !keyReady;
	end
end

endmodule

