module avsdpll (
`ifdef USE_POWER_PINS
	inout vccd1,	
	inout vssd1,	
`endif
   output reg  CLK,
   input  wire VCO_IN,
   input  wire ENb_CP,
   input  wire ENb_VCO,
   input  wire REF
);

reg [31:0] period_count;
reg [31:0] next_period;
reg [31:0] current_period;
reg [31:0] phase_accumulator;
reg [31:0] phase_accumulator_incr;

// Constants
parameter MAX_PERIOD = 100000000; // Example maximum period value

// Calculate the period of the reference signal
always @(posedge REF) begin
    if (period_count < MAX_PERIOD) begin
        period_count <= period_count + 1;
    end else begin
        current_period <= period_count;
        period_count <= 0;
    end
end

// Calculate the next period based on the current period
always @(posedge REF) begin
    if (period_count == 0) begin
        next_period <= current_period;
    end
end

// Phase accumulator increment calculation
always @(posedge REF) begin
    phase_accumulator_incr <= next_period;
end

// Phase accumulator
always @(posedge CLK or posedge ENb_VCO) begin
    if (ENb_VCO) begin
        phase_accumulator <= 0;
    end else begin
        phase_accumulator <= phase_accumulator + phase_accumulator_incr;
    end
end

// Clock generation
always @(posedge REF) begin
    if (!ENb_VCO) begin
        if (phase_accumulator >= current_period) begin
            CLK <= ~CLK;
            phase_accumulator <= phase_accumulator - current_period;
        end
    end
end

endmodule

module ct_ciu_snb_dp_sel_8(
  entry16_age_vect,
  entry17_age_vect,
  entry18_age_vect,
  entry19_age_vect,
  entry20_age_vect,
  entry21_age_vect,
  entry22_age_vect,
  entry23_age_vect,
  req_vld,
  sel
);
  input   [23:0]  entry16_age_vect; 
  input   [23:0]  entry17_age_vect; 
  input   [23:0]  entry18_age_vect; 
  input   [23:0]  entry19_age_vect; 
  input   [23:0]  entry20_age_vect; 
  input   [23:0]  entry21_age_vect; 
  input   [23:0]  entry22_age_vect; 
  input   [23:0]  entry23_age_vect; 
  input   [7 :0]  req_vld;         
  output  [7 :0]  sel;

  reg [7:0] sel;

  always @(*) begin
    sel = 8'b0;
    for (int i = 7; i >= 0; i = i - 1) begin
      if (req_vld[i] && !conflict(i)) begin
        sel = 1 << i;
        break;
      end
    end
  end

  function bit conflict(int request);
    conflict = 0;
    for (int i = 0; i < 8; i = i + 1) begin
      if (i != request && req_vld[i] && !check_age(entry16_age_vect, entry17_age_vect, entry18_age_vect, entry19_age_vect, entry20_age_vect, entry21_age_vect, entry22_age_vect, entry23_age_vect, request, i)) begin
        conflict = 1;
        break;
      end
    end
  endfunction

  function bit check_age(input [23:0] entry16_age_vect, input [23:0] entry17_age_vect, input [23:0] entry18_age_vect, input [23:0] entry19_age_vect, input [23:0] entry20_age_vect, input [23:0] entry21_age_vect, input [23:0] entry22_age_vect, input [23:0] entry23_age_vect, int request, int other);
    case (request)
      0: return entry16_age_vect[other];
      1: return entry17_age_vect[other];
      2: return entry18_age_vect[other];
      3: return entry19_age_vect[other];
      4: return entry20_age_vect[other];
      5: return entry21_age_vect[other];
      6: return entry22_age_vect[other];
      7: return entry23_age_vect[other];
    endcase
  endfunction

endmodule

module processing_system7_v5_5_w_atc #
  (
   parameter         C_FAMILY                         = "rtl",

   parameter integer C_AXI_ID_WIDTH                   = 4,


   parameter integer C_AXI_DATA_WIDTH                 = 64,


   parameter integer C_AXI_WUSER_WIDTH                = 1


   )
  (

