  reg w_valid_reg;
  reg w_ready_reg;
  reg w_last_reg;
  reg w_error_reg;

  // Command write ready signal
  assign cmd_w_ready = ~w_valid_reg;

  // Command write processing
  always @(posedge ACLK or posedge ARESET) begin
    if (ARESET) begin
      w_id_reg <= {C_AXI_ID_WIDTH{1'b0}};
