        w_last_reg <= 1'b0;
        w_error_reg <= 1'b0;
      end else if (S_AXI_WLAST && S_AXI_WVALID && S_AXI_WREADY) begin
        w_last_reg <= 1'b1;
      end else if (M_AXI_WREADY && w_valid_reg) begin
        w_valid_reg <= 1'b0;
        w_ready_reg <= 1'b1;
      end
    end
  end

  // Command write response generation
  assign cmd_b_push = w_valid_reg && w_last_reg && M_AXI_WREADY;
  assign cmd_b_error = w_error_reg;
  assign cmd_b_id = w_id_reg;

  // AXI write channel signals
  assign M_AXI_WID = S_AXI_WID;
  assign M_AXI_WDATA = S_AXI_WDATA;
  assign M_AXI_WSTRB = S_AXI_WSTRB;
  assign M_AXI_WLAST = S_AXI_WLAST;
  assign M_AXI_WUSER = S_AXI_WUSER;
  assign M_AXI_WVALID = S_AXI_WVALID && w_ready_reg;
  assign S_AXI_WREADY = M_AXI_WREADY && w_ready_reg;

endmodule

module submulor_0_stage_signed_12_bit(
