	output [11:0] out
	);

	// Internal wire to hold the result of the subtraction
	wire signed [11:0] sub_result;

	// Internal wire to hold the result of the multiplication
	wire signed [23:0] mul_result;

	// Perform the subtraction: d - a
	assign sub_result = d - a;

	// Perform the multiplication: sub_result * b
	assign mul_result = sub_result * b;

	// Perform the bitwise OR operation: mul_result | c
	// Since mul_result is 24 bits and c is 12 bits, we need to truncate mul_result to 12 bits before OR
	assign out = mul_result[11:0] | c;

