module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);

    // Calculate the depth of the FIFO
    localparam DEPTH = 1 << DEPTH_BITS;

    // Internal registers
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [DEPTH_BITS-1:0] read_index;
    reg [DEPTH_BITS-1:0] write_index;
    reg empty;
    reg full;

    // Assign output signals
    assign empty_n = ~empty;
    assign full_n = ~full;
    assign dout = mem[read_index];

    // Synchronous reset
    always @(posedge aclr or posedge clk) begin
        if (aclr) begin
            read_index <= 0;
            write_index <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            // Update read index
            if (read && !empty) begin
                read_index <= (read_index + 1) % DEPTH;
                if (read_index == write_index) begin
                    empty <= 1;
                end
            end

            // Update write index
            if (write && !full) begin
                mem[write_index] <= din;
                write_index <= (write_index + 1) % DEPTH;
                if (write_index == read_index) begin
                    full <= 1;
                end
            end

            // Update empty and full status
            if (read && !write) begin
                empty <= (read_index == write_index);
            end else if (write && !read) begin
                full <= (write_index == read_index);
            end
        end
    end

endmodule

module debounce(
    input clk,
    input btn_input,
    output reg btn_output
);

reg [31:0] timer;
reg pre;

always @(posedge clk) begin
    if (timer < 1000000) begin
        timer <= timer + 1;
    end else begin
        if (btn_input == pre) begin
            btn_output <= btn_input;
        end
        timer <= 0;
        pre <= btn_input;
    end
end

endmodule

