module gray_Nbits #(
    parameter N = 4
) (
    input wire clk,
    input wire reset,
    input wire enable,
    output wire [N-1:0] gray_out
);

localparam SIZE = N + 1;
localparam Zeros = {SIZE{1'b0}};

reg [SIZE-1:0] state;
reg [SIZE-1:0] toggle;

assign gray_out = state[N-1:0];

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= Zeros;
    end else if (enable) begin
        state <= state ^ toggle;
    end
end

always @(state) begin
    toggle = Zeros;
    toggle[0] = 1'b1;
    for (int i = 1; i < SIZE; i = i + 1) begin
        toggle[i] = state[i-1] ^ state[i];
    end
end

endmodule

module partsel_00453(ctrl, s0, s1, s2, s3, x0, x1, x2, x3, y);
  input [3:0] ctrl;
  input [2:0] s0;
  input [2:0] s1;
  input [2:0] s2;
  input [2:0] s3;
  input signed [31:0] x0;
  input [31:0] x1;
  input [31:0] x2;
  input [31:0] x3;
  output [127:0] y;

  // Internal signals for intermediate results
  wire [31:0] intermediate0;
  wire [31:0] intermediate1;
  wire [31:0] intermediate2;
  wire [31:0] intermediate3;

  // Example operations based on control signals
  always @(*) begin
    case (ctrl)
      4'b0000: begin
        intermediate0 = x0 & x1;
        intermediate1 = x2 | x3;
        intermediate2 = x0 ^ x1;
        intermediate3 = x2 + x3;
      end
      4'b0001: begin
        intermediate0 = x0 << s0;
        intermediate1 = x1 >> s1;
        intermediate2 = x2 >>> s2;
        intermediate3 = x3 <<< s3;
      end
      4'b0010: begin
        intermediate0 = x0 + x1;
        intermediate1 = x2 - x3;
        intermediate2 = x0 * x1;
        intermediate3 = x2 / x3;
      end
      4'b0011: begin
        intermediate0 = x0 & x2;
        intermediate1 = x1 | x3;
        intermediate2 = x0 ^ x3;
        intermediate3 = x1 + x2;
      end
      default: begin
        intermediate0 = 32'b0;
        intermediate1 = 32'b0;
        intermediate2 = 32'b0;
        intermediate3 = 32'b0;
      end
    endcase
  end

  // Construct the 128-bit output from the intermediate results
  assign y = {intermediate3, intermediate2, intermediate1, intermediate0};

endmodule

