    reg [7:0] next_fib;
    parameter END_VALUE = 8'd55; // Example end value for the Fibonacci sequence

    always @(posedge CLK_IN or negedge RST_N) begin
        if (!RST_N) begin
            // Reset the sequence
            fib1 <= 8'd0;
            fib2 <= 8'd1;
            SEQUENCE <= 8'd0;
        end else begin
            // Calculate the next Fibonacci number
            next_fib = fib1 + fib2;

            // Check if the next Fibonacci number exceeds the end value
            if (next_fib > END_VALUE) begin
                // Stop the sequence
                SEQUENCE <= fib2;
            end else begin
                // Update the sequence
                SEQUENCE <= next_fib;
                fib1 <= fib2;
                fib2 <= next_fib;
            end
        end
    end

endmodule

