module edge_detector (
    input wire clk,          
    input wire rst_n,        
    input wire signal_in,    
    output reg rising_out,   
    output reg falling_out   
);

reg signal_in_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all outputs and the internal register
        rising_out <= 0;
        falling_out <= 0;
        signal_in_prev <= 0;
    end else begin
        // Detect rising and falling edges
        if (signal_in && !signal_in_prev) begin
            rising_out <= 1;
        end else begin
            rising_out <= 0;
        end

        if (!signal_in && signal_in_prev) begin
            falling_out <= 1;
        end else begin
            falling_out <= 0;
        end

        // Update the internal register with the current state of signal_in
        signal_in_prev <= signal_in;
    end
end

endmodule

