module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);

  // Internal state machine states
  typedef enum logic [1:0] {
    IDLE,
    READY,
    RELEASE
  } state_t;

  state_t state, next_state;
  reg [23:0] r_count;

  // State machine and counter reset
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
      r_count <= 0;
      o_ppfifo_act <= 2'b00;
      o_ppfifo_stb <= 1'b0;
      o_ppfifo_data <= {DATA_WIDTH{1'b0}};
    end else begin
      state <= next_state;
      if (next_state == IDLE) begin
        r_count <= 0;
      end else if (next_state == READY && i_data_en && !i_h_blank) begin
        r_count <= r_count + 1;
      end
    end
  end

  // State machine logic
  always @(*) begin
    next_state = state;
    o_ppfifo_act = 2'b00;
    o_ppfifo_stb = 1'b0;
    o_ppfifo_data = {DATA_WIDTH{1'b0}};

    case (state)
      IDLE: begin
        if (i_ppfifo_rdy != 2'b00) begin
          next_state = READY;
          o_ppfifo_act = i_ppfifo_rdy;
        end
      end

      READY: begin
        if (i_h_blank || r_count >= i_ppfifo_size) begin
          next_state = RELEASE;
        end else if (i_data_en && !i_h_blank) begin
          o_ppfifo_stb = 1'b1;
          o_ppfifo_data = i_rgb;
        end
      end

      RELEASE: begin
        next_state = IDLE;
        o_ppfifo_act = 2'b00;
      end
    endcase
  end

  // Directly connect the PP FIFO clock to the input clock
  assign o_ppfifo_clk = clk;

endmodule

