    input  [15:0]             data_in,   
    input                    rst,

    output [15:0]             data_out
);

    // Define parameters for memory size and data width
    parameter addr_value = 4; // 16 memory locations (2^4)
    parameter data_width = 16; // Each memory location is 16 bits wide

    // Declare the memory array
    reg [data_width-1:0] memory [0:2**addr_value-1];

    // Register to hold the read data
    reg [data_width-1:0] read_data;

    // Sequential logic for write operation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset the memory on rst signal
            integer i;
            for (i = 0; i < 2**addr_value; i = i + 1) begin
                memory[i] <= 16'b0;
            end
        end else if (write_en) begin
            // Write data to memory on write_en signal
            memory[wr_addr] <= data_in;
        end
    end

    // Combinational logic for read operation
    always @(*) begin
        if (read_en) begin
            // Read data from memory on read_en signal
            read_data = memory[rd_addr];
        end else begin
            // If read_en is not asserted, output should be zero
            read_data = 16'b0;
        end
    end

    // Assign the read data to the output
    assign data_out = read_data;

endmodule

