wire [6:0] opcode;
wire [4:0] rd;
wire [4:0] rs1;
wire [4:0] rs2;
wire [2:0] funct3;
wire [6:0] funct7;

// Decode the instruction fields
assign opcode = instr_i[6:0];
assign rd = instr_i[11:7];
assign rs1 = instr_i[19:15];
assign rs2 = instr_i[24:20];
assign funct3 = instr_i[14:12];
assign funct7 = instr_i[31:25];

// Intermediate wires for complex logic
wire [4:0] complex_logic_1;
wire [4:0] complex_logic_2;
wire [4:0] complex_logic_3;

// Example complex logic operations
assign complex_logic_1 = (opcode == 7'b0110011) ? rs1 : rs2;
assign complex_logic_2 = (funct3 == 3'b000) ? rd : rs1;
assign complex_logic_3 = (funct7 == 7'b0000001) ? rs2 : rd;

// Construct the scan output
assign scan_o = {
  1'b1, // Constant bit
  complex_logic_1,
  1'b0, // Constant bit
  complex_logic_2,
  1'b1, // Constant bit
  complex_logic_3,
  1'b0, // Constant bit
  opcode,
  1'b1, // Constant bit
  funct3,
