module matrix5arb (
    input clk,
    input rst_n,
    input [4:0] req,
    output [4:0] grant
);

// Internal state register to track the current priority level
reg [2:0] current_priority;

// Combinational logic to determine the grant signal based on current priority and requests
always @(*) begin
    grant = 5'b0;
    case (current_priority)
        3'b000: grant = req[0] ? 5'b00001 : req[1] ? 5'b00010 : req[2] ? 5'b00100 : req[3] ? 5'b01000 : req[4] ? 5'b10000 : 5'b0;
        3'b001: grant = req[1] ? 5'b00010 : req[2] ? 5'b00100 : req[3] ? 5'b01000 : req[4] ? 5'b10000 : req[0] ? 5'b00001 : 5'b0;
        3'b010: grant = req[2] ? 5'b00100 : req[3] ? 5'b01000 : req[4] ? 5'b10000 : req[0] ? 5'b00001 : req[1] ? 5'b00010 : 5'b0;
        3'b011: grant = req[3] ? 5'b01000 : req[4] ? 5'b10000 : req[0] ? 5'b00001 : req[1] ? 5'b00010 : req[2] ? 5'b00100 : 5'b0;
        3'b100: grant = req[4] ? 5'b10000 : req[0] ? 5'b00001 : req[1] ? 5'b00010 : req[2] ? 5'b00100 : req[3] ? 5'b01000 : 5'b0;
        default: grant = 5'b0;
    endcase
end

// Sequential logic to update the current priority level
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_priority <= 3'b000; // Reset to the lowest priority level
    end else if (|grant) begin
        // Increment the priority level if a grant was given
        current_priority <= current_priority + 1;
    end
end

endmodule

module routing_buffer #(
  parameter DATA_WIDTH = 32,
  parameter INSERT_REGISTER = 1
)(
  input clock,
  input resetn,
  input [DATA_WIDTH-1:0] i_datain,
  input i_datain_valid,
  output reg o_datain_stall,
  output reg [DATA_WIDTH-1:0] o_dataout,
  input i_dataout_stall,
  output reg o_dataout_valid
);

reg [DATA_WIDTH-1:0] data_reg;
reg data_valid_reg;

always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
    o_datain_stall <= 1'b0;
    o_dataout <= {DATA_WIDTH{1'b0}};
    o_dataout_valid <= 1'b0;
    data_reg <= {DATA_WIDTH{1'b0}};
    data_valid_reg <= 1'b0;
  end else begin
    // Handle input stall
    if (i_dataout_stall) begin
      o_datain_stall <= 1'b1;
    end else begin
      o_datain_stall <= 1'b0;
    end

    // Handle data output
    if (data_valid_reg && !i_dataout_stall) begin
      o_dataout <= data_reg;
      o_dataout_valid <= 1'b1;
    end else begin
      o_dataout_valid <= 1'b0;
    end

    // Handle data input
    if (i_datain_valid && !o_datain_stall) begin
      if (INSERT_REGISTER) begin
        data_reg <= i_datain;
        data_valid_reg <= 1'b1;
      end else begin
        o_dataout <= i_datain;
        o_dataout_valid <= 1'b1;
      end
    end else if (i_dataout_stall) begin
      data_valid_reg <= 1'b0;
    end
  end
end

endmodule

