module DelayLoop(MR, Timeout, Clock);
    input MR, Clock;
    output reg Timeout;

    // Parameter for the divider value
    parameter Divider = 100000;

    // 27-bit counter to track the number of clock cycles
    reg [26:0] counter;

    // Combinational logic to set the Timeout signal
    always @(*) begin
        if (counter >= Divider) begin
            Timeout = 1'b1;
        end else begin
            Timeout = 1'b0;
        end
    end

    // Sequential logic to control the counter's reset and increment operations
    always @(posedge Clock or posedge MR) begin
        if (MR) begin
            // Reset the counter and Timeout when MR is high
            counter <= 27'b0;
            Timeout <= 1'b0;
        end else begin
            // Increment the counter on each clock cycle
            if (counter < Divider) begin
                counter <= counter + 1'b1;
            end
        end
    end
endmodule

