module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// Internal registers
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg load_p1;
reg load_p2;
reg load_p1_from_p2;

// State machine states
typedef enum reg [1:0] {ZERO, ONE, TWO} state_t;
state_t state, next_state;

// State machine logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    next_state = state;
    case (state)
        ZERO: begin
            if (s_valid && m_ready) begin
                next_state = ONE;
            end
        end
        ONE: begin
            if (load_p1_from_p2) begin
                next_state = TWO;
            end
        end
        TWO: begin
            if (m_ready) begin
                next_state = ZERO;
            end
        end
    endcase
end

// Data loading logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;
    end else begin
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;

        case (state)
            ZERO: begin
                if (s_valid && m_ready) begin
                    load_p1 <= 1;
                end
            end
            ONE: begin
                if (load_p1_from_p2) begin
                    load_p2 <= 1;
                end
            end
            TWO: begin
                if (m_ready) begin
                    load_p1_from_p2 <= 1;
                end
            end
        endcase
    end
end

// Data pipeline
always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= 0;
        data_p2 <= 0;
    end else begin
        if (load_p1) begin
            data_p1 <= s_data;
        end
        if (load_p2) begin
            data_p2 <= data_p1;
        end
    end
end

// Output assignments
assign m_data = data_p2;
assign m_valid = (state == TWO) ? 1 : 0;
assign s_ready = (state == ZERO) ? m_ready : 0;

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(
    input clk,
    input arstn,
    input mode,
    input [DATA_WIDTH-1:0] din,
    output [DATA_WIDTH-1:0] dout
);

// Define states
typedef enum logic [1:0] {
    ADD_STATE,
    INC_STATE
} state_t;

// Internal registers
state_t state, next_state;
reg [DATA_WIDTH-1:0] counter, next_counter;

// State and counter update logic
always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        state <= ADD_STATE;
        counter <= {DATA_WIDTH{1'b0}};
    end else begin
        state <= next_state;
        counter <= next_counter;
    end
end

// Next state and counter logic
always @(*) begin
    next_state = state;
    next_counter = counter;
    dout = counter;

    case (state)
        ADD_STATE: begin
            if (mode) begin
                next_counter = din + 2;
                next_state = INC_STATE;
            end else begin
                next_counter = din + 1;
                next_state = ADD_STATE;
            end
        end
        INC_STATE: begin
            if (mode) begin
                next_counter = counter + 1;
                next_state = INC_STATE;
            end else begin
                next_counter = {DATA_WIDTH{1'b0}};
                next_state = ADD_STATE;
            end
        end
    endcase
end

endmodule

module edge_canny_detector_mul_mul_16s_16s_32_4_1_DSP48_3(clk, rst, ce, a, b, p);
    input clk;
    input rst;
    input ce;
    input signed [16 - 1 : 0] a;
    input signed [16 - 1 : 0] b;
    output signed [32 - 1 : 0] p;

    // Internal registers for pipelining
    reg signed [16 - 1 : 0] a_reg;
    reg signed [16 - 1 : 0] b_reg;
    reg signed [32 - 1 : 0] p_reg_tmp;
    reg signed [32 - 1 : 0] p_reg;

    // DSP48E1 multiplier block
    wire signed [31:0] product;
    DSP48E1 #(
        .DEVICE("7SERIES"), // Target device family
        .A_INPUT("DIRECT"), // A input type
        .B_INPUT("DIRECT"), // B input type
        .C_INPUT("DIRECT"), // C input type
        .DSP_MODE("MULTIPLY") // DSP mode
    ) dsp48_inst (
        .CLK(clk), // Clock input
        .CEA1(ce), // Enable for A register
        .CEA2(ce), // Enable for A register
        .CEB1(ce), // Enable for B register
        .CEB2(ce), // Enable for B register
        .CEC1(ce), // Enable for C register
        .CEC2(ce), // Enable for C register
        .CED1(ce), // Enable for D register
        .CED2(ce), // Enable for D register
        .CEM(ce), // Enable for multiplier
        .CEP(ce), // Enable for accumulator
        .A(a_reg), // A input
        .B(b_reg), // B input
        .C(16'b0), // C input (not used)
        .D(16'b0), // D input (not used)
        .P(product) // Product output
    );

    // Register pipeline stages
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_reg <= 16'b0;
            b_reg <= 16'b0;
            p_reg_tmp <= 32'b0;
            p_reg <= 32'b0;
        end else if (ce) begin
            a_reg <= a;
            b_reg <= b;
            p_reg_tmp <= product;
            p_reg <= p_reg_tmp;
        end
    end

    // Output assignment
    assign p = p_reg;
