module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);

    // Internal signals
    reg [DATA_BITS-1:0] mem [0:15];
    reg [DEPTH_BITS:0] index;
    reg empty_n_reg, full_n_reg;

    // Initialize the FIFO
    always @(posedge aclr) begin
        index <= 0;
        empty_n_reg <= 0;
        full_n_reg <= 1;
    end

    // Sequential logic for index management
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            index <= 0;
            empty_n_reg <= 0;
            full_n_reg <= 1;
        end else begin
            if (write && !full_n_reg) begin
                index <= index + 1;
                if (index == 14)
                    full_n_reg <= 0;
            end
            if (read && !empty_n_reg) begin
                index <= index - 1;
                if (index == 0)
                    empty_n_reg <= 0;
            end
        end
    end

    // Combinational logic for data output and flags
    always @(*) begin
        if (index == 0)
            empty_n = 0;
        else
            empty_n = 1;

        if (index == 14)
            full_n = 0;
        else
            full_n = 1;

        if (read && !empty_n_reg)
            dout = mem[index];
        else
            dout = {DATA_BITS{1'b0}};
    end

    // Write data to the FIFO
    always @(posedge clk or posedge aclr) begin
        if (aclr) begin
            for (int i = 0; i < 16; i = i + 1)
                mem[i] <= {DATA_BITS{1'b0}};
        end else if (write && !full_n_reg) begin
            mem[index] <= din;
        end
    end

endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);

    // State definitions
    typedef enum logic [1:0] {
        S_IDLE,
        S_RUN,
        S_DONE
    } state_t;

    // Internal signals
    state_t state, state_n;
    logic [DWIDTH-1:0] cnt_val, cnt_val_n;
    logic run, done;

    // State and counter value registers
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= {DWIDTH{1'b0}};
            run <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run;
            done <= done;
        end
    end

    // Next state and output logic
    always_comb begin
        state_n = state;
        cnt_val_n = cnt_val;
        run = 1'b0;
        done = 1'b0;

        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                    run = 1'b1;
                end
            end

            S_RUN: begin
                if (cnt_i == cnt_val) begin
                    state_n = S_DONE;
                    done = 1'b1;
                end else begin
                    run = 1'b1;
                end
            end

            S_DONE: begin
                state_n = S_IDLE;
            end
        endcase
    end

    // Assign outputs
    assign run_o = run;
    assign done_o = done;

endmodule

module muland_1_stage_unsigned_18_bit(
	input  [17:0] a,
	input  [17:0] b,
	input  [17:0] c,
	output [17:0] out,
	input clk);

reg [35:0] stage0;

always @(posedge clk) begin
	// Multiply a and b, then AND with c (zero-extended to 36 bits)
	stage0 <= {18{1'b0}} | (a * b) & {c, 18{1'b0}};
end

assign out = stage0[17:0]; // Directly assign the lower 18 bits to the output

endmodule

