module AXIS_WB_WB_Queue( 
  input         clock, 
  input         reset, 
  output        io_enq_ready, 
  input         io_enq_valid, 
  input  [31:0] io_enq_bits, 
  input         io_deq_ready, 
  output        io_deq_valid, 
  output [31:0] io_deq_bits 
);

  // Parameters
  localparam DEPTH = 512;
  localparam ADDR_WIDTH = $clog2(DEPTH);

  // Internal signals
  reg [ADDR_WIDTH-1:0] value;
  reg [ADDR_WIDTH-1:0] value_1;
  reg maybe_full;
  reg [31:0] ram [0:DEPTH-1];

  // Output assignments
  assign io_enq_ready = ~maybe_full;
  assign io_deq_valid = (value != value_1);

  // Sequential logic
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      value <= 0;
      value_1 <= 0;
      maybe_full <= 0;
    end else begin
      // Enqueue operation
      if (io_enq_valid && io_enq_ready) begin
        ram[value] <= io_enq_bits;
        value <= (value + 1) % DEPTH;
        if (value == value_1) begin
          maybe_full <= 1;
        end
      end

      // Dequeue operation
      if (io_deq_ready && io_deq_valid) begin
        value_1 <= (value_1 + 1) % DEPTH;
        if (maybe_full && value == value_1) begin
          maybe_full <= 0;
        end
      end
    end
  end

  // Dequeue data output
  always @(posedge clock) begin
    if (reset) begin
      io_deq_bits <= 0;
    end else if (io_deq_ready && io_deq_valid) begin
      io_deq_bits <= ram[value_1];
    end
  end

endmodule

