module Control(
	input clk,
	input start,
	output reg [3:0] direction,
	output reg ready
);

	// Define the states
	typedef enum reg [2:0] {
		IDLE = 3'b000,
		STATE1 = 3'b001,
		STATE2 = 3'b010,
		STATE3 = 3'b011,
		STATE4 = 3'b100,
		STATE5 = 3'b101,
		STATE6 = 3'b110,
		STATE7 = 3'b111
	} state_t;

	// Internal state register
	state_t state, next_state;

	// State transition logic
	always @(posedge clk) begin
		if (start)
			state <= IDLE;
		else
			state <= next_state;
	end

	// Next state logic
	always @(*) begin
		case (state)
			IDLE: next_state = STATE1;
			STATE1: next_state = STATE2;
			STATE2: next_state = STATE3;
			STATE3: next_state = STATE4;
			STATE4: next_state = STATE5;
			STATE5: next_state = STATE6;
			STATE6: next_state = STATE7;
			STATE7: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	// Output logic
	always @(*) begin
		case (state)
			IDLE: begin
				direction = 4'b0000;
				ready = 1'b1;
			end
			STATE1: begin
				direction = 4'b0001;
				ready = 1'b0;
			end
			STATE2: begin
				direction = 4'b0010;
				ready = 1'b0;
			end
			STATE3: begin
				direction = 4'b0011;
				ready = 1'b0;
			end
			STATE4: begin
				direction = 4'b0100;
				ready = 1'b0;
			end
			STATE5: begin
				direction = 4'b0101;
				ready = 1'b0;
			end
			STATE6: begin
				direction = 4'b0110;
				ready = 1'b0;
			end
			STATE7: begin
				direction = 4'b0111;
				ready = 1'b0;
			end
			default: begin
				direction = 4'b0000;
				ready = 1'b0;
			end
		endcase
	end

endmodule

