module wideexpr_00377(ctrl, u0, u1, u2, u3, u4, u5, u6, u7, s0, s1, s2, s3, s4, s5, s6, s7, y);
  input [7:0] ctrl;
  input [0:0] u0;
  input [1:0] u1;
  input [2:0] u2;
  input [3:0] u3;
  input [4:0] u4;
  input [5:0] u5;
  input [6:0] u6;
  input [7:0] u7;
  input signed [0:0] s0;
  input signed [1:0] s1;
  input signed [2:0] s2;
  input signed [3:0] s3;
  input signed [4:0] s4;
  input signed [5:0] s5;
  input signed [6:0] s6;
  input signed [7:0] s7;
  output [127:0] y;

  // Internal signals
  wire [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  // Computation for y0
  assign y0 = (ctrl[0] & u0) | (ctrl[1] & u1) | (ctrl[2] & u2) | (ctrl[3] & u3);

  // Computation for y1
  assign y1 = (ctrl[4] & u4) | (ctrl[5] & u5) | (ctrl[6] & u6) | (ctrl[7] & u7);

  // Computation for y2
  assign y2 = (ctrl[0] & s0) | (ctrl[1] & s1) | (ctrl[2] & s2) | (ctrl[3] & s3);

  // Computation for y3
  assign y3 = (ctrl[4] & s4) | (ctrl[5] & s5) | (ctrl[6] & s6) | (ctrl[7] & s7);

  // Computation for y4
  assign y4 = (ctrl[0] & {u0, u1}) | (ctrl[1] & {u2, u3}) | (ctrl[2] & {u4, u5}) | (ctrl[3] & {u6, u7});

  // Computation for y5
  assign y5 = (ctrl[4] & {s0, s1}) | (ctrl[5] & {s2, s3}) | (ctrl[6] & {s4, s5}) | (ctrl[7] & {s6, s7});

  // Computation for y6
  assign y6 = (ctrl[0] & {u0, u1, u2}) | (ctrl[1] & {u3, u4, u5}) | (ctrl[2] & {u6, u7, u0}) | (ctrl[3] & {u1, u2, u3});

  // Computation for y7
  assign y7 = (ctrl[4] & {s0, s1, s2}) | (ctrl[5] & {s3, s4, s5}) | (ctrl[6] & {s6, s7, s0}) | (ctrl[7] & {s1, s2, s3});

  // Concatenate all y0 to y7 to form the final output y
  assign y = {y7, y6, y5, y4, y3, y2, y1, y0};

endmodule

module create_node_test;

