module SplitDigitsTest;

    // Inputs
    reg [6:0] Number;

    // Outputs
    wire [3:0] Hundreds;
    wire [3:0] Tens;
    wire [3:0] Ones;

    // Instantiate the module under test
    SplitDigits uut (
        .Number(Number),
        .Hundreds(Hundreds),
        .Tens(Tens),
        .Ones(Ones)
    );

    // Test cases
    initial begin
        // Test case 1: Number = 0
        Number = 7'b0000000;
        #10;
        assert (Hundreds == 4'b0000 && Tens == 4'b0000 && Ones == 4'b0000) else $error("Test case 1 failed");

        // Test case 2: Single-digit number
        Number = 7'b0000001;
        #10;
        assert (Hundreds == 4'b0000 && Tens == 4'b0000 && Ones == 4'b0001) else $error("Test case 2 failed");

        // Test case 3: Number with hundreds
        Number = 7'b1000000;
        #10;
        assert (Hundreds == 4'b0001 && Tens == 4'b0000 && Ones == 4'b0000) else $error("Test case 3 failed");

        // Test case 4: Number with tens
        Number = 7'b0010000;
        #10;
        assert (Hundreds == 4'b0000 && Tens == 4'b0001 && Ones == 4'b0000) else $error("Test case 4 failed");

        // Test case 5: Number with ones
        Number = 7'b0000100;
        #10;
        assert (Hundreds == 4'b0000 && Tens == 4'b0000 && Ones == 4'b0001) else $error("Test case 5 failed");

        // Test case 6: Number with all digits
        Number = 7'b1010100;
        #10;
        assert (Hundreds == 4'b0001 && Tens == 4'b0010 && Ones == 4'b0001) else $error("Test case 6 failed");

        // Test case 7: Maximum value
        Number = 7'b1111111;
        #10;
        assert (Hundreds == 4'b0001 && Tens == 4'b1111 && Ones == 4'b1111) else $error("Test case 7 failed");

        // End simulation
        $finish;
    end

