module preaddmul_1_stage_unsigned_11_bit(
	input  [10:0] a,
	input  [10:0] b,
	input  [10:0] d,
	output [10:0] out,
	input clk);

	// Internal 22-bit register to store the intermediate multiplication result
	reg [21:0] stage0;

	// Combinatorial logic to compute the sum of a and d
	wire [11:0] sum_ad = a + d;

	// Sequential logic to perform multiplication and store the result in stage0
	always @(posedge clk) begin
		// Multiply the sum of a and d by b
		stage0 <= sum_ad * b;
	end

	// Assign the lower 11 bits of stage0 to the output
	assign out = stage0[10:0];

endmodule

module SR_SYNC_LATCH #(
    parameter DATA_WIDTH = 32
)(
    input wire CLK,
    input wire SET,
    input wire RESET,
    input wire [DATA_WIDTH - 1:0] DATA_IN,
    output wire [DATA_WIDTH - 1:0] LATCH_OUT
);

reg [DATA_WIDTH - 1:0] latch_out_int;

assign LATCH_OUT = latch_out_int;

always @(posedge CLK) begin
    if (SET && !RESET) begin
        // Load DATA_IN into the latch
        latch_out_int <= DATA_IN;
    end else if (!SET && RESET) begin
        // Reset the latch to all zeros
        latch_out_int <= {DATA_WIDTH{1'b0}};
    end
    // If both SET and RESET are high or low, the latch holds its current value
end

endmodule

