module partsel_00215(ctrl, s0, s1, s2, s3, x0, x1, x2, x3, y);
  input [3:0] ctrl;
  input [2:0] s0;
  input [2:0] s1;
  input [2:0] s2;
  input [2:0] s3;
  input signed [31:0] x0;
  input signed [31:0] x1;
  input signed [31:0] x2;
  input [31:0] x3;
  output [127:0] y;

  // Local parameters
  parameter signed [31:0] p0 = 32'd1;
  parameter signed [31:0] p1 = 32'd2;
  parameter signed [31:0] p2 = 32'd3;
  parameter signed [31:0] p3 = 32'd4;

  // Intermediate wires
  wire signed [31:0] x4;
  wire signed [31:0] x5;
  wire signed [31:0] x6;
  wire signed [31:0] x7;
  wire signed [31:0] x8;
  wire signed [31:0] x9;
  wire signed [31:0] x10;
  wire signed [31:0] x11;
  wire signed [31:0] x12;
  wire signed [31:0] x13;
  wire signed [31:0] x14;
  wire signed [31:0] x15;

  // Intermediate results
  wire signed [31:0] y0;
  wire signed [31:0] y1;
  wire signed [31:0] y2;
  wire signed [31:0] y3;

  // Bit selection and shifting
  assign x4 = (s0 == 3'b000) ? x0 : (s0 == 3'b001) ? x1 : (s0 == 3'b010) ? x2 : x3;
  assign x5 = (s1 == 3'b000) ? x0 : (s1 == 3'b001) ? x1 : (s1 == 3'b010) ? x2 : x3;
  assign x6 = (s2 == 3'b000) ? x0 : (s2 == 3'b001) ? x1 : (s2 == 3'b010) ? x2 : x3;
  assign x7 = (s3 == 3'b000) ? x0 : (s3 == 3'b001) ? x1 : (s3 == 3'b010) ? x2 : x3;

  // Arithmetic operations
  assign x8 = x4 + p0;
  assign x9 = x5 * p1;
  assign x10 = x6 - p2;
  assign x11 = x7 >> s0;

  // Conditional logic
  assign x12 = (ctrl[0]) ? x8 : x9;
  assign x13 = (ctrl[1]) ? x10 : x11;
  assign x14 = (ctrl[2]) ? x12 : x13;
  assign x15 = (ctrl[3]) ? x14 : x13;

  // Final processing
  assign y0 = x12;
  assign y1 = x13;
  assign y2 = x14;
  assign y3 = x15;

  // Concatenate results to form the output
  assign y = {y3, y2, y1, y0};

endmodule

module submulsub_0_stage_signed_14_bit(
