	input signed [13:0] b,
	input signed [13:0] c,
	input signed [13:0] d,
	output [13:0] out
	);

	// Internal wire to hold the intermediate result of (d - a)
	wire signed [13:0] diff;

	// Internal wire to hold the intermediate result of (diff * b)
	wire signed [27:0] product;

	// Calculate the difference (d - a)
	assign diff = d - a;

	// Calculate the product (diff * b)
	assign product = diff * b;

	// Calculate the final result ((d - a) * b) - c
	assign out = product[27:14] - c;

endmodule

