module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,

    input [15:0]        lfsr_seed,
    input               lfsr_ld,

    input               lfsr_step,

    output reg [15:0]   lfsr_state_f,
    output reg          lfsr_out_f
);

    // Internal register to hold the current state of the LFSR
    reg [15:0] lfsr_state;

    // Feedback taps for the LFSR (example taps, adjust as needed)
    // For a 16-bit LFSR, these taps determine the sequence properties
    // Example: taps for a maximal-length LFSR
    wire feedback_bit = lfsr_state[15] ^ lfsr_state[14] ^ lfsr_state[13] ^ lfsr_state[4];

    // Combinational logic to determine the next state of the LFSR
    always @(*) begin
        if (lfsr_ld) begin
            // Load the seed value into the LFSR
            lfsr_state_f = lfsr_seed;
        end else if (lfsr_step) begin
            // Shift the current state and apply feedback
            lfsr_state_f = {feedback_bit, lfsr_state[15:1]};
        end else begin
            // Hold the current state
            lfsr_state_f = lfsr_state;
        end
    end

    // Sequential logic to update the LFSR state on the clock edge
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Asynchronous reset to zero state
            lfsr_state <= 16'b0;
        end else begin
            // Update the LFSR state
            lfsr_state <= lfsr_state_f;
        end
    end

    // Output the most significant bit of the current state
    assign lfsr_out_f = lfsr_state[15];

endmodule

