module FFlr(
    input wire clk,
    input wire [31:0] f,
    output reg [31:0] g
);

reg [7:0] len_raw;
reg [7:0] len;
reg [31:0] x_mask;
reg [31:0] f_masked;
reg [31:0] f_incr;
reg [31:0] f_out;
reg [31:0] res;
reg [31:0] reg1;
reg [31:0] reg2;

always @(posedge clk) begin
    // Compute len_raw by subtracting 255 from bits 30:23 of f
    len_raw <= f[30:23] - 8'hFF;

    // Determine len based on specific conditions
    if (len_raw < 8'h08)
        len <= 8'h08;
    else if (len_raw > 8'h1F)
        len <= 8'h1F;
    else
        len <= len_raw;

    // Create x_mask by right-shifting 1 by (32 - len)
    x_mask <= 32'hFFFFFFFF >> len;

    // Clear bits beyond the position determined by x_mask in f
    f_masked <= f & x_mask;

    // Increment f_masked at the x_mask's first set bit
    f_incr <= f_masked + x_mask;

    // Conditionally select between f_masked and f_incr based on f's value
    if (f[31] == 1'b0)
        f_out <= f_masked;
    else
        f_out <= f_incr;

    // Combine f's sign with modified lower bits
    if (f[31] == 1'b0)
        res <= {f[31], f_out[30:0]};
    else if (f[30:23] == 8'h00)
        res <= {f[31], f_out[30:0]};
    else
        res <= {f[31], f_out[30:0]};

    // Pipeline res into g through two registers
    reg1 <= res;
    reg2 <= reg1;
    g <= reg2;
end

endmodule

module murmur3_data(
    input clk,
    input rstn,
    input [127:0] i_data,
    input ld_init,
    input ld_partial,
    input [1:0]sel_mux,
    input ld_seed,
    input sel_init_seed,
    input ld_result,
    input ld_partial_hash_sub,
    input ld_res_sub_1,
    input ld_res_sub_2,
    input ld_final,
    output [31:0] o_hash_key   
);

    // Constants used in Murmur3 algorithm
    localparam C1 = 32'hcc9e2d51;
    localparam C2 = 32'h1b873593;
    localparam C3 = 32'he6546b64;
    localparam C4 = 32'h91520d9d;
    localparam C5 = 32'h5c1b1e1b;
    localparam C6 = 32'h1e377abb;
    localparam C7 = 32'h561c2563;

    // Internal registers
    reg [31:0] k0, k1, k2, k3;
    reg [31:0] h1, h2;
    reg [31:0] seed;
    reg [31:0] partial_hash;
    reg [31:0] res_sub_1, res_sub_2;
    reg [31:0] final_hash;

    // Break down input data into four 32-bit chunks
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            k0 <= 32'h0;
            k1 <= 32'h0;
            k2 <= 32'h0;
            k3 <= 32'h0;
        end else if (ld_init) begin
            k0 <= i_data[127:96];
            k1 <= i_data[95:64];
            k2 <= i_data[63:32];
            k3 <= i_data[31:0];
        end
    end

    // Initialize seed
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            seed <= 32'h0;
        end else if (ld_seed) begin
            if (sel_init_seed)
                seed <= i_data[127:96];
            else
                seed <= 32'h0;
        end
    end

    // Partial hash computation
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            partial_hash <= 32'h0;
        end else if (ld_partial) begin
            case (sel_mux)
                2'b00: partial_hash <= k0;
                2'b01: partial_hash <= k1;
                2'b10: partial_hash <= k2;
                2'b11: partial_hash <= k3;
            endcase
        end
    end

    // Hash mixing
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            h1 <= 32'h0;
            h2 <= 32'h0;
        end else if (ld_partial_hash_sub) begin
            h1 <= h1 + (partial_hash * C1);
            h1 = (h1 << 15) | (h1 >> 17);
            h1 = h1 + C2;
            h2 <= h2 + (partial_hash * C3);
            h2 = (h2 << 13) | (h2 >> 19);
            h2 = h2 + C4;
        end
    end

    // Result sub-1 computation
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            res_sub_1 <= 32'h0;
        end else if (ld_res_sub_1) begin
            res_sub_1 <= h1 + h2;
        end
    end

    // Result sub-2 computation
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            res_sub_2 <= 32'h0;
        end else if (ld_res_sub_2) begin
            res_sub_2 <= res_sub_1 + seed;
        end
    end

    // Final hash computation
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            final_hash <= 32'h0;
        end else if (ld_final) begin
            final_hash <= res_sub_2;
            final_hash = (final_hash * C5);
            final_hash = (final_hash << 13) | (final_hash >> 19);
            final_hash = final_hash + C6;
            final_hash = (final_hash * C7);
            final_hash = (final_hash << 15) | (final_hash >> 17);
            final_hash = final_hash + C4;
        end
    end

    // Output the final hash key
    assign o_hash_key = final_hash;

endmodule

module main(
    input X4,
    input X3,
    input X2,
    input X1,
    input X0,
    output F
);

// Internal signals
wire not_X0, not_X1, xor_X0_X1, and_X0_X1;

// NOT gates
assign not_X0 = ~X0;
assign not_X1 = ~X1;

// XOR gate
assign xor_X0_X1 = X0 ^ X1;

// AND gate
assign and_X0_X1 = X0 & X1;

// Decoder logic to select between different intermediate signals
// This is a simple 2-to-4 decoder using X0 and X1
wire sel0, sel1, sel2, sel3;
assign sel0 = not_X0 & not_X1;
assign sel1 = not_X0 & X1;
assign sel2 = X0 & not_X1;
assign sel3 = X0 & X1;

// Multiplexer logic to select the final output F
// The select lines are X2, X3, and X4
assign F = (sel0 & not_X2 & not_X3 & not_X4) |
           (sel1 & not_X2 & not_X3 & X4) |
           (sel2 & not_X2 & X3 & not_X4) |
           (sel3 & not_X2 & X3 & X4) |
           (xor_X0_X1 & X2 & not_X3 & not_X4) |
           (and_X0_X1 & X2 & not_X3 & X4) |
           (not_X0 & X2 & X3 & not_X4) |
           (not_X1 & X2 & X3 & X4);

endmodule

