module FullAdder(
  input wire a, 
  input wire b,
  input wire carry_in,
  output wire sum,
  output wire carry_out
);

  // Continuous assignment for sum using XOR
  assign sum = a ^ b ^ carry_in;

  // Continuous assignment for carry_out using OR and AND operations
  assign carry_out = (a & b) | (b & carry_in) | (carry_in & a);

endmodule

module AOI31X1TS (Y, A0, A1, A2, B0);
