    // Specify block for timing constraints
    specify
        // Conditional timing constraints based on A0, A1, A2
        if ((A0 == 1'b0) || (A1 == 1'b0) || (A2 == 1'b0)) begin
            // If any of A0, A1, A2 is low, the delay from B0 to Y is 10ns
            (B0 => Y) = 10ns;
        end else begin
            // If all A0, A1, A2 are high, the delay from B0 to Y is 15ns
            (B0 => Y) = 15ns;
        end
    endspecify
