    output reg latch = 0,
    output reg data = 0
);

reg [2:0] step_count = 0;
reg [7:0] current_anodes = 0;

always @(posedge sysclk) begin
    // Check if the anodes have changed
    if (anodes != current_anodes) begin
        // Reset the step count and update the current anodes
        step_count <= 0;
        current_anodes <= anodes;
    end else begin
        // Increment the step count
        step_count <= step_count + 1;
    end

    // Determine the shift and latch signals based on the step count
    case (step_count)
        3'b000: begin
            data <= anodes[7];
            shift <= 1;
            latch <= 0;
        end
        3'b001: begin
            shift <= 0;
            latch <= 0;
        end
        3'b010: begin
            data <= anodes[6];
            shift <= 1;
            latch <= 0;
        end
        3'b011: begin
            shift <= 0;
            latch <= 0;
        end
        3'b100: begin
            data <= anodes[5];
            shift <= 1;
            latch <= 0;
        end
        3'b101: begin
            shift <= 0;
            latch <= 0;
