module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);

reg [31:0] count;
reg [31:0] comp;
reg pulse_reg;

assign pulse = pulse_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 0;
        comp <= MAX_COUNT - 1;
        pulse_reg <= 0;
    end else if (clk_en) begin
        if (button) begin
            if (count == 0) begin
                pulse_reg <= 1;
                count <= comp;
            end else begin
                count <= count - 1;
                pulse_reg <= 0;
            end
        end else begin
            count <= 0;
            pulse_reg <= 0;
            if (comp > MIN_COUNT) begin
                comp <= comp - DEC_COUNT;
            end
        end
    end
end

endmodule

