module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);

// Define states for the FSM
typedef enum logic [1:0] {ZERO, ONE, TWO} state_t;
state_t state, next_state;

// Registers to stage data
reg [N-1:0] data_p1, data_p2;

// Control signals
reg load_p1, load_p2, load_p1_from_p2;
reg s_ready_t;

// State transition logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= ZERO;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        ZERO: begin
            if (s_valid && m_ready) begin
                next_state = ONE;
            end
        end
        ONE: begin
            if (s_valid && m_ready) begin
                next_state = TWO;
            end else if (!m_ready) begin
                next_state = ONE;
            end
        end
        TWO: begin
            if (s_valid && m_ready) begin
                next_state = ONE;
            end else if (!m_ready) begin
                next_state = TWO;
            end
        end
    endcase
end

// Data loading logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= 0;
        data_p2 <= 0;
    end else begin
        if (load_p1) begin
            data_p1 <= s_data;
        end
        if (load_p2) begin
            data_p2 <= data_p1;
        end
    end
end

// Control signal logic
always @(*) begin
    load_p1 = 0;
    load_p2 = 0;
    load_p1_from_p2 = 0;
    s_ready_t = 0;
    m_valid = 0;

    case (state)
        ZERO: begin
            if (s_valid && m_ready) begin
                load_p1 = 1;
                s_ready_t = 1;
                m_valid = 1;
            end
        end
        ONE: begin
            if (s_valid && m_ready) begin
                load_p1 = 1;
                s_ready_t = 1;
                m_valid = 1;
            end else if (!m_ready) begin
                load_p2 = 1;
                s_ready_t = 0;
                m_valid = 0;
            end
        end
        TWO: begin
            if (s_valid && m_ready) begin
                load_p1 = 1;
                s_ready_t = 1;
                m_valid = 1;
            end else if (!m_ready) begin
                load_p1_from_p2 = 1;
                s_ready_t = 0;
                m_valid = 0;
            end
        end
    endcase
end

// Output assignments
assign s_ready = s_ready_t;
assign m_data = (state == TWO) ? data_p2 : data_p1;

endmodule

