module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
);

    // Define the states as parameters
    parameter S1 = 3'b000;
    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;

    // Current and next state registers
    reg [2:0] state, next;

    // Output assignment
    assign z = (state == S6) ? 1'b1 : 1'b0;

    // State transition logic
    always @(*) begin
        case (state)
            S1: next = (x == 1'b0) ? S2 : S1;
            S2: next = (x == 1'b0) ? S3 : S1;
            S3: next = (x == 1'b1) ? S4 : S1;
            S4: next = (x == 1'b0) ? S5 : S1;
            S5: next = (x == 1'b0) ? S6 : S1;
            S6: next = S6; // Stay in S6 if x is either 0 or 1
            default: next = S1; // Default case to ensure proper initialization
        endcase
    end

    // State register update
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S1; // Asynchronous reset to S1
        end else begin
            state <= next; // Synchronous update of state
        end
    end

endmodule

module SRAM64x32(
    input CLK,
    input [3:0] WE,
    input EN,
    input [31:0] Di,
    output [31:0] Do,
    input [5:0] A
);

    // Internal memory array
    reg [31:0] memory [0:63];

    // Internal register for output data
    reg [31:0] data_out;

    // Address decoder
    reg [63:0] address_decoder;
    always @(*) begin
        address_decoder = 64'b0;
        address_decoder[A] = 1'b1;
    end

    // Write operation
    always @(posedge CLK) begin
        if (EN) begin
            for (integer i = 0; i < 4; i = i + 1) begin
                if (WE[i]) begin
                    memory[A][i*8 +: 8] <= Di[i*8 +: 8];
                end
            end
        end
    end

    // Read operation
    always @(*) begin
        if (EN) begin
            data_out = memory[A];
        end else begin
            data_out = 32'b0;
        end
    end

    // Output buffer
    assign Do = data_out;

endmodule

