module aes_cha(
	input CLK_24M,
	input nSDROM, nSDMRD,
	input [15:0] SDA,
	input SDRD1, SDRD0, 
	input [23:0] PBUS,
	input CA4, LOAD, H, EVEN, S2H1,
	input CLK_12M,
	input PCK2B, PCK1B,
	output [7:0] FIXD,
	output DOTA, DOTB,
	output [3:0] GAD,
	output [3:0] GBD,
	inout [7:0] SDD,
	input CLK_8M
);

	// Internal registers
	reg [7:0] C_LATCH;
	reg [7:0] S_LATCH;
	reg [3:0] ROM_ADDR;
	reg [7:0] ROM_DATA;
	reg [7:0] FIXD_reg;
	reg DOTA_reg;
	reg DOTB_reg;
	reg [3:0] GAD_reg;
	reg [3:0] GBD_reg;

