	rom_mix_columns mix_columns (
		.address(ROM_ADDR),
		.clock(CLK_24M),
		.q(ROM_DATA)
	);

	rom_shift_rows shift_rows (
		.address(ROM_ADDR),
		.clock(CLK_24M),
		.q(ROM_DATA)
	);

	// Control logic
	always @(posedge CLK_12M) begin
		if (LOAD) begin
			C_LATCH <= PBUS[15:8];
			S_LATCH <= PBUS[7:0];
			ROM_ADDR <= PBUS[23:16];
