module leddec16(
    input wire [1:0] dig,
    input wire [15:0] data,
    output wire [3:0] anode,
    output wire [6:0] seg
);

// Lookup table for 7-segment display
// Each 4-bit input maps to a 7-segment pattern
// 0: 0000, 1: 0001, ..., F: 1111
reg [6:0] seg_pattern [0:15];
initial begin
    seg_pattern[0] = 7'b1000000; // 0
    seg_pattern[1] = 7'b1111001; // 1
    seg_pattern[2] = 7'b0100100; // 2
    seg_pattern[3] = 7'b0110000; // 3
    seg_pattern[4] = 7'b0011001; // 4
    seg_pattern[5] = 7'b0010010; // 5
    seg_pattern[6] = 7'b0000010; // 6
    seg_pattern[7] = 7'b1111000; // 7
    seg_pattern[8] = 7'b0000000; // 8
    seg_pattern[9] = 7'b0010000; // 9
    seg_pattern[10] = 7'b0001000; // A
    seg_pattern[11] = 7'b0000011; // b
    seg_pattern[12] = 7'b1000110; // C
    seg_pattern[13] = 7'b0100001; // d
    seg_pattern[14] = 7'b0000110; // E
    seg_pattern[15] = 7'b0001110; // F
end

// Select the appropriate 4-bit data based on the digit select input
wire [3:0] selected_data;
assign selected_data = (dig == 2'b00) ? data[3:0] :
                     (dig == 2'b01) ? data[7:4] :
                     (dig == 2'b10) ? data[11:8] : data[15:12];

// Determine if the selected data is non-zero
wire data_non_zero = |selected_data;

// Generate the anode control signal
assign anode[0] = (dig == 2'b00) & data_non_zero;
assign anode[1] = (dig == 2'b01) & data_non_zero;
assign anode[2] = (dig == 2'b10) & data_non_zero;
assign anode[3] = (dig == 2'b11) & data_non_zero;

// Generate the seven-segment pattern
assign seg = seg_pattern[selected_data];

endmodule

module bsg_fifo_1r1w_small_width_p109_els_p2_ready_THEN_valid_p1
(
  clk_i,
  reset_i,
  v_i,
  ready_o,
  data_i,
  v_o,
  data_o,
  yumi_i
);

parameter WIDTH = 109;
parameter DEPTH = 109;

input [WIDTH-1:0] data_i;
output [WIDTH-1:0] data_o;
input clk_i;
input reset_i;
input v_i;
input yumi_i;
output ready_o;
output v_o;

reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [DEPTH-1:0] write_ptr;
reg [DEPTH-1:0] read_ptr;
reg full;
reg empty;

assign ready_o = ~full;
assign v_o = ~empty;

always @(posedge clk_i or posedge reset_i) begin
  if (reset_i) begin
    write_ptr <= 0;
    read_ptr <= 0;
    full <= 0;
    empty <= 1;
  end else begin
    if (v_i & ~full & ~yumi_i) begin
      mem[write_ptr] <= data_i;
      write_ptr <= (write_ptr + 1) % DEPTH;
      if (write_ptr == read_ptr) begin
        full <= 1;
      end
      empty <= 0;
    end else if (yumi_i & ~empty & ~v_i) begin
      read_ptr <= (read_ptr + 1) % DEPTH;
      if (read_ptr == write_ptr) begin
        empty <= 1;
      end
      full <= 0;
    end
  end
end

always @(posedge clk_i) begin
  if (v_o) begin
    data_o <= mem[read_ptr];
  end
end

endmodule

module muladd_3_stage_unsigned_17_bit_xor_reduction(
	input  [16:0] a,
	input  [16:0] b,
	input  [16:0] c,
	output [16:0] out,
	input clk);

	// Internal 34-bit signals for pipeline stages
	reg [33:0] stage0, stage1, stage2;

	// Internal signal for XOR reduction
	reg xor_result;

	// Pipeline stage 0: Compute the product of a and b, then add c
	always @(posedge clk) begin
		stage0 <= {a * b} + c;
	end

	// Pipeline stage 1: Pass the result from stage0 to stage1
	always @(posedge clk) begin
		stage1 <= stage0;
	end

	// Pipeline stage 2: Pass the result from stage1 to stage2
	always @(posedge clk) begin
		stage2 <= stage1;
	end

	// XOR reduction of the final 34-bit result from stage2
	always @(posedge clk) begin
		xor_result <= 0;
		for (int i = 0; i < 34; i = i + 1) begin
			xor_result <= xor_result ^ stage2[i];
		end
	end

	// Assign the XOR result to the output
	assign out = xor_result;

endmodule

