module IF_stage #(parameter MEM_WIDTH=8, parameter WIDTH=32, parameter OFF_WIDTH=6)
(
	input clk, reset, jump, stall,
	output reg [WIDTH-1:0] instr,
	output reg [MEM_WIDTH-1:0] addr,
	input [OFF_WIDTH-1:0] jumpOffset
);

	// Internal signals
	reg [WIDTH-1:0] pc;
	reg [WIDTH-1:0] next_pc;
	reg [WIDTH-1:0] jump_target;

	// Instruction memory
	reg [WIDTH-1:0] instruction_memory [0:255]; // Assuming a small memory for demonstration

	// Sign extension unit
	always @(*) begin
		if (jumpOffset[OFF_WIDTH-1])
			jump_target = {26'b1111111111111111111111111111, jumpOffset};
		else
			jump_target = {26'b0, jumpOffset};
	end

	// PC register
	always @(posedge clk or posedge reset) begin
		if (reset)
			pc <= 32'b0;
		else if (!stall)
			pc <= next_pc;
	end

	// Next PC calculation
	always @(*) begin
		if (jump)
			next_pc = pc + jump_target;
		else
			next_pc = pc + 4;
	end

	// Instruction fetch
	always @(posedge clk or posedge reset) begin
		if (reset) begin
			instr <= 32'b0;
			addr <= 8'b0;
		end else if (!stall) begin
			instr <= instruction_memory[pc[MEM_WIDTH-1:0]];
			addr <= pc[MEM_WIDTH-1:0];
		end
	end

	// Initialize instruction memory with some dummy instructions
	initial begin
		instruction_memory[0] = 32'h00000000; // NOP
		instruction_memory[4] = 32'h00000004; // NOP
		instruction_memory[8] = 32'h00000008; // NOP
		// Add more instructions as needed
	end

endmodule

