module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(
    input clk,
    input arstn,
    input [DATA_WIDTH-1:0] data_in,
    input wrreq,
    input rdreq,
    output [DATA_WIDTH-1:0] data_out,
    output reg [clog2(FIFO_DEPTH):0] usedw,
    output empty,
    output full
);

// Internal signals
reg [clog2(FIFO_DEPTH)-1:0] wr_ptr;
reg [clog2(FIFO_DEPTH)-1:0] rd_ptr;
reg [DATA_WIDTH-1:0] mem [0:FIFO_DEPTH-1];
reg wr_en;
reg rd_en;

// Calculate log2 of FIFO_DEPTH
function integer clog2;
    input integer value;
    begin
        value = value - 1;
        for (clog2 = 0; value > 0; clog2 = clog2 + 1)
            value = value >> 1;
    end
endfunction

// Asynchronous reset
always @(negedge arstn) begin
    wr_ptr <= 0;
    rd_ptr <= 0;
    usedw <= 0;
    empty <= 1;
    full <= 0;
end

// Synchronous operations
always @(posedge clk or negedge arstn) begin
    if (!arstn) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty <= 1;
        full <= 0;
    end else begin
        // Write operation
        if (wr_en) begin
            mem[wr_ptr] <= data_in;
            wr_ptr <= wr_ptr + 1;
            if (wr_ptr == FIFO_DEPTH - 1)
                wr_ptr <= 0;
        end

        // Read operation
        if (rd_en) begin
            rd_ptr <= rd_ptr + 1;
            if (rd_ptr == FIFO_DEPTH - 1)
                rd_ptr <= 0;
        end

        // Update status signals
        if (wr_en && !rd_en) begin
            if (usedw == FIFO_DEPTH - 1)
                full <= 1;
            else
                full <= 0;
            usedw <= usedw + 1;
        end else if (!wr_en && rd_en) begin
            if (usedw == 1)
                empty <= 1;
            else
                empty <= 0;
            usedw <= usedw - 1;
        end else if (wr_en && rd_en) begin
            // No change in usedw
        end
    end
end

// Combinatorial logic for data output and enable signals
assign data_out = mem[rd_ptr];
assign wr_en = wrreq && !full;
assign rd_en = rdreq && !empty;

endmodule

