    reg [2:0] SyncA_clkB;
    reg [7:0] clkA_data;
    reg [7:0] clkB_data;

    // Synchronize FlagIn_clkA to clkB domain
    always @(posedge clkA) begin
        FlagToggle_clkA <= ~FlagToggle_clkA & FlagIn_clkA;
    end

    always @(posedge clkB) begin
        SyncA_clkB <= {SyncA_clkB[1:0], FlagToggle_clkA};
    end

    // Synchronize dataA to clkB domain
    always @(posedge clkA) begin
        if (FlagIn_clkA) begin
            clkA_data <= dataA;
        end
    end

    always @(posedge clkB) begin
        if (SyncA_clkB == 3'b100) begin
            clkB_data <= clkA_data;
            FlagOut_clkB <= 1'b1;
        end else begin
            FlagOut_clkB <= 1'b0;
        end
    end

    assign dataB = clkB_data;

