module mulor_3_stage_signed_10_bit(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	output [9:0] out,
	input clk);

	// Internal 20-bit registers to store intermediate results
	reg signed [19:0] stage0;
	reg signed [19:0] stage1;
	reg signed [19:0] stage2;

	// Internal 10-bit register to store the final output
	reg signed [9:0] out_reg;

	// Pipeline stages
	always @(posedge clk) begin
		// Stage 0: Multiply a and b
		stage0 <= a * b;

		// Stage 1: Perform bitwise OR with c
		stage1 <= stage0 | (c << 10);

		// Stage 2: Shift right to get the 10-bit result
		stage2 <= stage1 >> 10;

		// Output stage: Assign the result to out_reg
		out_reg <= stage2;
	end

	// Assign the final result to the output
	assign out = out_reg;

endmodule

module countUD5L(
