        if (reset) begin
            Q <= 5'b00000;
            UTC <= 1'b0;
            DTC <= 1'b0;
        end else if (LD) begin
            Q <= D;
            UTC <= 1'b0;
            DTC <= 1'b0;
        end else if (Up) begin
            if (Q == 5'b11111) begin
                Q <= 5'b00000;
                UTC <= 1'b1;
            end else begin
                Q <= Q + 1;
                UTC <= 1'b0;
            end
        end else if (Dw) begin
            if (Q == 5'b00000) begin
                Q <= 5'b11111;
                DTC <= 1'b1;
            end else begin
                Q <= Q - 1;
                DTC <= 1'b0;
            end
        end
    end
endmodule

