    uart_core uart_inst (
        .clk(clk),
        .rst(rst),
        .rxd(uart_rxd),
        .txd(uart_txd),
        .tx_data(cobs_encoded_data),
        .tx_valid(cobs_encoded_valid),
        .tx_ready(tx_fifo_empty),
        .rx_data(rx_fifo_din),
        .rx_valid(cobs_decoded_valid),
        .rx_ready(rx_fifo_full),
        .prescale(prescale)
    );

    // TX FIFO instantiation
    fifo #(
        .DEPTH(TX_FIFO_DEPTH),
        .WIDTH(DATA_WIDTH)
    ) tx_fifo_inst (
        .clk(clk),
        .rst(rst),
        .din(down_xfcp_in_tdata),
        .wr_en(down_xfcp_in_tvalid & down_xfcp_in_tready),
        .full(tx_fifo_full),
        .dout(tx_fifo_dout),
        .empty(tx_fifo_empty),
        .rd_en(tx_fifo_rd_en)
    );

    // RX FIFO instantiation
    fifo #(
        .DEPTH(RX_FIFO_DEPTH),
        .WIDTH(DATA_WIDTH)
    ) rx_fifo_inst (
        .clk(clk),
        .rst(rst),
        .din(rx_fifo_din),
        .wr_en(cobs_decoded_valid & ~rx_fifo_full),
        .full(rx_fifo_full),
        .dout(down_xfcp_out_tdata),
        .empty(rx_fifo_empty),
        .rd_en(down_xfcp_out_tready & down_xfcp_out_tvalid)
    );

    // COBS Encoder instantiation
    cobs_encoder cobs_enc_inst (
        .clk(clk),
        .rst(rst),
        .din(tx_fifo_dout),
        .din_valid(~tx_fifo_empty),
