    assign down_xfcp_in_tready = ~tx_fifo_full;
    assign down_xfcp_out_tvalid = ~rx_fifo_empty;
    assign down_xfcp_out_tlast = cobs_decoded_last;

    // FIFO read enable logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx_fifo_rd_en <= 0;
            rx_fifo_rd_en <= 0;
