module mux8to1(Q, S, i1, i2, i3, i4, i5, i6, i7, i8);

input i1, i2, i3, i4, i5, i6, i7, i8;
input [2:0]S;
output Q;

// Internal signals for decoder outputs
wire sel0, sel1, sel2, sel3, sel4, sel5, sel6, sel7;

// Decoder implementation
assign sel0 = ~S[2] & ~S[1] & ~S[0];
assign sel1 = ~S[2] & ~S[1] & S[0];
assign sel2 = ~S[2] & S[1] & ~S[0];
assign sel3 = ~S[2] & S[1] & S[0];
assign sel4 = S[2] & ~S[1] & ~S[0];
assign sel5 = S[2] & ~S[1] & S[0];
assign sel6 = S[2] & S[1] & ~S[0];
assign sel7 = S[2] & S[1] & S[0];

// Multiplexer logic using AND and OR gates
assign Q = (i1 & sel0) | (i2 & sel1) | (i3 & sel2) | (i4 & sel3) |
          (i5 & sel4) | (i6 & sel5) | (i7 & sel6) | (i8 & sel7);

endmodule

