module lfsr24(
    input wire Clk,
    input wire one,
    input wire tick,
    input wire [6:0] coreCount,
    output reg data
);

reg [23:0] lfsr_p; // Current state of the LFSR
reg [23:0] lfsr_n; // Next state of the LFSR

// Feedback polynomial: x^24 + x^23 + x^22 + x^16 + 1
// Feedback bit is the XOR of bits 23, 22, 21, 15, and the LSB (0)

always @(posedge Clk or posedge one) begin
    if (one) begin
        // Reset mode: Set LFSR to predefined value
        lfsr_p <= 24'h020000;
    end else if (tick) begin
        // Shift mode: Advance the LFSR state
        lfsr_n = {lfsr_p[22:0], lfsr_p[23] ^ lfsr_p[22] ^ lfsr_p[21] ^ lfsr_p[15] ^ lfsr_p[0]};
        if (coreCount < 24) begin
            // Rotate mode: Rotate the LFSR bits
            lfsr_n = {lfsr_n[coreCount-1:0], lfsr_n[23:coreCount]};
        end
        lfsr_p <= lfsr_n;
    end
end

// Output selection based on coreCount
always @(*) begin
    case (coreCount)
        7'd0: data = lfsr_p[0];
        7'd1: data = lfsr_p[1];
        7'd2: data = lfsr_p[2];
        7'd3: data = lfsr_p[3];
        7'd4: data = lfsr_p[4];
        7'd5: data = lfsr_p[5];
        7'd6: data = lfsr_p[6];
        7'd7: data = lfsr_p[7];
        7'd8: data = lfsr_p[8];
        7'd9: data = lfsr_p[9];
        7'd10: data = lfsr_p[10];
        7'd11: data = lfsr_p[11];
        7'd12: data = lfsr_p[12];
        7'd13: data = lfsr_p[13];
        7'd14: data = lfsr_p[14];
        7'd15: data = lfsr_p[15];
        7'd16: data = lfsr_p[16];
        7'd17: data = lfsr_p[17];
        7'd18: data = lfsr_p[18];
        7'd19: data = lfsr_p[19];
        7'd20: data = lfsr_p[20];
        7'd21: data = lfsr_p[21];
        7'd22: data = lfsr_p[22];
        7'd23: data = lfsr_p[23];
        default: data = 1'b0;
    endcase
end

endmodule

