module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    reg [7:0] shift_reg; // 8-bit shift register
    reg [3:0] bit_count; // 4-bit counter to track the number of bits received

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset the shift register, bit counter, and output signals
            shift_reg <= 8'b0;
            bit_count <= 4'b0;
            dout_parallel <= 8'b0;
            dout_valid <= 1'b0;
        end else begin
            if (din_valid) begin
                // Shift the serial data into the shift register
                shift_reg <= {shift_reg[6:0], din_serial};
                // Increment the bit counter
                bit_count <= bit_count + 1;
            end

            // Check if 8 bits have been received
            if (bit_count == 4'b1000) begin
                // Output the accumulated byte
                dout_parallel <= shift_reg;
                // Assert the output validity signal
                dout_valid <= 1'b1;
                // Reset the bit counter
                bit_count <= 4'b0;
            end else begin
                // Deassert the output validity signal
                dout_valid <= 1'b0;
            end
        end
    end

endmodule

module fa(sum, cout, a, b, cin);
    input a, b, cin;
    output sum, cout;
    wire w0, w1, w2;

    // First XOR operation to generate intermediate sum
    assign w0 = a ^ b;

    // First AND operation to detect carry from a and b
    assign w1 = a & b;

    // Second XOR operation to generate final sum
    assign sum = w0 ^ cin;

    // Second AND operation to detect carry from intermediate sum and cin
    assign w2 = w0 & cin;

    // OR operation to combine both carry signals
    assign cout = w1 | w2;
endmodule

module pe(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] c
);
    // Internal 64-bit wire to store the product of a and b
    wire [63:0] product;

    // Combinational logic to compute the product of a and b
    assign product = a * b;

    // Sequential logic to accumulate the lower 32 bits of the product
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset the output register c to zero
            c <= 32'b0;
        end else begin
            // Accumulate the lower 32 bits of the product into c
            c <= c + product[31:0];
        end
    end
endmodule

module testbench;

    // Parameters
    parameter WIDTH = 3;
    parameter NUM_TEST_CASES = 100;

    // Inputs
    reg [WIDTH-1:0] A;
    reg [WIDTH-1:0] B;

    // Outputs
    wire A_greater;
    wire A_equal;
    wire A_less;

    // Instantiate the comparator module
    comparator_3bit uut (
        .A(A),
        .B(B),
        .A_greater(A_greater),
        .A_equal(A_equal),
        .A_less(A_less)
    );

    // Test variables
    integer i;
    integer error;

    // Initial block for test execution
    initial begin
        // Initialize error counter
        error = 0;

        // Iterate through the number of test cases
        for (i = 0; i < NUM_TEST_CASES; i = i + 1) begin
            // Generate random 3-bit values for A and B
            A = $random;
            B = $random;

            // Wait for a short period to ensure signal propagation
            #10;

            // Check the outputs against expected results
            if (A > B && !A_greater) begin
                $display("Test case %0d: Error - A_greater should be 1", i);
                error = error + 1;
            end else if (A == B && !A_equal) begin
                $display("Test case %0d: Error - A_equal should be 1", i);
                error = error + 1;
            end else if (A < B && !A_less) begin
                $display("Test case %0d: Error - A_less should be 1", i);
                error = error + 1;
            end
        end

