module bsg_fifo_1rw_large_width_p62_els_p64_verbose_p0
(
  clk_i,
  reset_i,
  data_i,
  v_i,
  enq_not_deq_i,
  full_o,
  empty_o,
  data_o
);
  parameter WIDTH = 62;
  parameter DEPTH = 64;

  input [WIDTH-1:0] data_i;
  output [WIDTH-1:0] data_o;
  input clk_i;
  input reset_i;
  input v_i;
  input enq_not_deq_i;
  output full_o;
  output empty_o;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [$clog2(DEPTH)-1:0] read_ptr, write_ptr;
  reg full, empty;
  reg last_was_enqueue;

  always @(posedge clk_i or posedge reset_i) begin
    if (reset_i) begin
      read_ptr <= 0;
      write_ptr <= 0;
      full <= 0;
      empty <= 1;
      last_was_enqueue <= 0;
    end else begin
      if (v_i) begin
        if (enq_not_deq_i) begin
          if (!full) begin
            mem[write_ptr] <= data_i;
            write_ptr <= (write_ptr + 1) % DEPTH;
            if (write_ptr == read_ptr) full <= 1;
            empty <= 0;
            last_was_enqueue <= 1;
          end
        end else begin
          if (!empty) begin
            data_o <= mem[read_ptr];
            read_ptr <= (read_ptr + 1) % DEPTH;
            if (read_ptr == write_ptr) empty <= 1;
            full <= 0;
            last_was_enqueue <= 0;
          end
        end
      end
    end
  end

  assign full_o = full;
  assign empty_o = empty;

endmodule

module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );

  // Internal registers
  reg [31:0] M_x_q, M_x_d;
  reg [31:0] M_y_q, M_y_d;
  reg [31:0] M_z_q, M_z_d;
  reg [31:0] M_w_q, M_w_d;

  // Local parameter (SEED is not used directly in the module's ports)
  localparam SEED = 32'h12345678;

  // Combinational logic to compute next state values
  always @(*) begin
    M_x_d = M_x_q;
    M_y_d = M_y_q;
    M_z_d = M_z_q;
    M_w_d = M_w_q;

    if (next) begin
      // Feedback term t derived from M_x_q
      reg [31:0] t;
      t = M_x_q ^ (M_x_q >> 13) ^ (M_x_q >> 17) ^ (M_x_q >> 25);

      // Update registers with new values
      M_x_d = M_y_q;
      M_y_d = M_z_q;
      M_z_d = M_w_q;
      M_w_d = t;
    end
  end

  // Sequential logic to update registers on clock edge
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      // Initialize registers with constant and seed during reset
      M_x_q <= SEED ^ seed;
      M_y_q <= SEED ^ seed;
      M_z_q <= SEED ^ seed;
      M_w_q <= SEED ^ seed;
      num <= SEED ^ seed;
    end else begin
      // Update registers with next state values
      M_x_q <= M_x_d;
      M_y_q <= M_y_d;
      M_z_q <= M_z_d;
      M_w_q <= M_w_d;
      num <= M_w_q;
    end
  end

endmodule

