module clock_divider(
    input wire clock,
    output wire clock_div
);

    // Parameters for input and output frequencies
    parameter INPUT_FREQ = 50000000; // Example input frequency in Hz
    parameter OUTPUT_FREQ = 1000000;  // Example output frequency in Hz

    // Calculate the division factor
    localparam DIVISION_FACTOR = INPUT_FREQ / OUTPUT_FREQ;

    // Counter to track the number of input clock cycles
    reg [31:0] counter = 0;

    // Register to hold the current state of the output clock
    reg clock_signal = 0;

    // Always block triggered by the positive edge of the input clock
    always @(posedge clock) begin
        // Increment the counter
        counter <= counter + 1;

        // Check if the counter has reached the division factor
        if (counter == DIVISION_FACTOR - 1) begin
            // Reset the counter
            counter <= 0;
            // Invert the output clock signal
            clock_signal <= ~clock_signal;
        end
    end

    // Assign the output clock signal
    assign clock_div = clock_signal;

endmodule

