module ps2_host_to_kb (
    input wire clk,          
    inout wire ps2clk_ext,
    inout wire ps2data_ext,
    input wire [7:0] data,
    input wire dataload,
    output wire ps2busy,
    output wire ps2error
);

    // Internal signals
    reg [7:0] shift_reg;
    reg [3:0] bit_count;
    reg [3:0] timeout_counter;
    reg state;
    reg ps2clk_int;
    reg ps2data_int;
    reg ps2busy_int;
    reg ps2error_int;

    // State definitions
    localparam IDLE = 4'b0000;
    localparam START = 4'b0001;
    localparam DATA = 4'b0010;
    localparam PARITY = 4'b0011;
    localparam STOP = 4'b0100;
    localparam TIMEOUT = 4'b0101;

    // Assign outputs
    assign ps2busy = ps2busy_int;
    assign ps2error = ps2error_int;

    // Clock and data synchronization
    always @(posedge clk) begin
        ps2clk_int <= ps2clk_ext;
        ps2data_int <= ps2data_ext;
    end

    // State machine
    always @(posedge clk) begin
        case (state)
            IDLE: begin
                ps2busy_int <= 0;
                ps2error_int <= 0;
                if (dataload) begin
                    shift_reg <= data;
                    bit_count <= 0;
                    timeout_counter <= 0;
                    state <= START;
                    ps2busy_int <= 1;
                end
            end

            START: begin
                ps2clk_ext <= 0;
                ps2data_ext <= 0;
                state <= DATA;
            end

            DATA: begin
                ps2clk_ext <= 1;
                ps2data_ext <= shift_reg[7];
                shift_reg <= {shift_reg[6:0], 1'b0};
                bit_count <= bit_count + 1;
                if (bit_count == 8) begin
                    state <= PARITY;
                end
            end

            PARITY: begin
                ps2clk_ext <= 1;
                ps2data_ext <= ^shift_reg;
                state <= STOP;
            end

            STOP: begin
                ps2clk_ext <= 1;
                ps2data_ext <= 1;
                state <= IDLE;
            end

            TIMEOUT: begin
                ps2error_int <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end

    // Timeout monitoring
    always @(posedge clk) begin
        if (state == DATA || state == PARITY || state == STOP) begin
            if (ps2clk_int == ps2clk_ext) begin
                timeout_counter <= timeout_counter + 1;
                if (timeout_counter > 100) begin // Arbitrary timeout value
                    state <= TIMEOUT;
                end
            end else begin
                timeout_counter <= 0;
            end
        end else begin
            timeout_counter <= 0;
        end
    end

endmodule

