            RED: {red, yellow, green} = 3'b100; // Red light on
            YELLOW1: {red, yellow, green} = 3'b010; // Yellow light on
            GREEN: {red, yellow, green} = 3'b001; // Green light on
            YELLOW2: {red, yellow, green} = 3'b010; // Yellow light on
            default: {red, yellow, green} = 3'b100; // Red light on
        endcase
    end
