module partsel_00900(ctrl, s0, s1, s2, s3, x0, x1, x2, x3, y);
  input [3:0] ctrl;
  input [2:0] s0;
  input [2:0] s1;
  input [2:0] s2;
  input [2:0] s3;
  input [31:0] x0;
  input [31:0] x1;
  input signed [31:0] x2;
  input [31:0] x3;
  output [127:0] y;

  // Internal wires
  wire [31:0] w0, w1, w2, w3;
  wire [31:0] w4, w5, w6, w7;
  wire [31:0] w8, w9, w10, w11;
  wire [31:0] w12, w13, w14, w15;

  // Constants
  parameter [31:0] CONST1 = 32'h12345678;
  parameter [31:0] CONST2 = 32'h87654321;

  // Combinatorial logic for each segment of the output
  assign w0 = (ctrl[0]) ? x0 + CONST1 : x0 & CONST2;
  assign w1 = (ctrl[1]) ? x1 - CONST1 : x1 | CONST2;
  assign w2 = (ctrl[2]) ? x2 * CONST1 : x2 ^ CONST2;
  assign w3 = (ctrl[3]) ? x3 / CONST1 : x3 << 2;

  assign w4 = (s0[0]) ? w0 + w1 : w0 - w1;
  assign w5 = (s0[1]) ? w2 + w3 : w2 - w3;
  assign w6 = (s0[2]) ? w4 + w5 : w4 - w5;

  assign w7 = (s1[0]) ? w0 & w1 : w0 | w1;
  assign w8 = (s1[1]) ? w2 & w3 : w2 | w3;
  assign w9 = (s1[2]) ? w7 & w8 : w7 | w8;

  assign w10 = (s2[0]) ? w0 ^ w1 : w0 << 2;
  assign w11 = (s2[1]) ? w2 ^ w3 : w2 << 2;
  assign w12 = (s2[2]) ? w10 ^ w11 : w10 << 2;

  assign w13 = (s3[0]) ? w0 >> 2 : w0 >>> 2;
  assign w14 = (s3[1]) ? w2 >> 2 : w2 >>> 2;
  assign w15 = (s3[2]) ? w13 >> 2 : w13 >>> 2;

  // Combine the segments to form the final output
  assign y = {w15, w14, w13, w12, w11, w10, w9, w8, w7, w6, w5, w4, w3, w2, w1, w0};

endmodule

