module mul3bc(input[2:0] x, y, output[5:0] out);
    // Declare registers to store partial products
    reg [5:0] partial_product0, partial_product1, partial_product2;

    // Generate partial products based on the value of y
    always @(*) begin
        // Partial product for y[0]
        if (y[0])
            partial_product0 = x << 0; // x shifted by 0 positions
        else
            partial_product0 = 6'b0;

        // Partial product for y[1]
        if (y[1])
            partial_product1 = x << 1; // x shifted by 1 position
        else
            partial_product1 = 6'b0;

        // Partial product for y[2]
        if (y[2])
            partial_product2 = x << 2; // x shifted by 2 positions
        else
            partial_product2 = 6'b0;
    end

    // Compute the final output as the sum of the partial products
    assign out = partial_product0 + partial_product1 + partial_product2;
endmodule

