module RC_16_16_12_approx_fa_51_15(IN1, IN2, Out);
    input [15:0] IN1;
    input [15:0] IN2;
    output [16:0] Out;

    // Internal signals
    wire [15:0] sum_approx;
    wire [15:0] sum_full;
    wire [15:0] carry_in_full;
    wire [15:0] carry_out_approx;
    wire [15:0] carry_out_full;
    wire [15:0] carry_in_full_next;
    wire [15:0] carry_out_full_next;

    // Approximate Full Adders for lower 12 bits
    genvar i;
    generate
        for (i = 0; i < 12; i = i + 1) begin : approx_adders
            assign sum_approx[i] = IN1[i] ^ IN2[i] ^ carry_in_full[i];
            assign carry_out_approx[i] = (IN1[i] & IN2[i]) | (IN1[i] & carry_in_full[i]) | (IN2[i] & carry_in_full[i]);
            assign carry_in_full_next[i] = carry_out_approx[i];
        end
    endgenerate

    // Standard Full Adders for higher 4 bits
    generate
        for (i = 12; i < 16; i = i + 1) begin : full_adders
            assign sum_full[i] = IN1[i] ^ IN2[i] ^ carry_in_full[i];
            assign carry_out_full[i] = (IN1[i] & IN2[i]) | (IN1[i] & carry_in_full[i]) | (IN2[i] & carry_in_full[i]);
            assign carry_in_full_next[i] = carry_out_full[i];
        end
    endgenerate

    // Combine the sums and carry outs
    assign Out[15:0] = sum_approx[11:0] ^ sum_full[15:12];
    assign Out[16] = carry_out_full[15];

    // Initialize carry_in_full for the first stage
    assign carry_in_full[0] = 0;

    // Propagate carry_in_full to the next stage
    assign carry_in_full[1:11] = carry_in_full_next[0:10];
    assign carry_in_full[12:15] = carry_in_full_next[12:15];

endmodule

