    assign stage3_0 = (din12[1] == 1'b0) ? stage2_0 : stage2_1;

    // Fourth stage of multiplexing (final output)
    assign dout = (din12[0] == 1'b0) ? stage3_0 : din8;

endmodule

module RC_16_16_2_approx_fa_187_14(IN1, IN2, Out);
    input [15:0] IN1;
    input [15:0] IN2;
    output [16:0] Out;

    // Internal wires for carry signals
    wire w33, w34, w35, w36, w37, w38, w39, w40, w41, w42, w43, w44, w45, w46, w47, w48, w49, w50, w51, w52, w53, w54, w55, w56, w57, w58, w59, w60, w61;

    // Approximate Full Adder for the first bit
    approximate_full_adder U0 (
        .a(IN1[0]),
        .b(IN2[0]),
        .cin(1'b0),
        .sum(Out[0]),
        .cout(w33)
    );

    // Approximate Full Adder for the second bit
    approximate_full_adder U1 (
        .a(IN1[1]),
        .b(IN2[1]),
        .cin(w33),
        .sum(Out[1]),
        .cout(w34)
    );

    // Standard Full Adders for the remaining bits
    genvar i;
    generate
        for (i = 2; i < 16; i = i + 1) begin : standard_adders
            full_adder U2 (
                .a(IN1[i]),
                .b(IN2[i]),
                .cin(w34 + (i-2)),
                .sum(Out[i]),
                .cout(w34 + (i-1))
            );
        end
    endgenerate

    // Final carry-out becomes the 17th bit of the output
    assign Out[16] = w34 + 14;

endmodule

