    wire [24:0] M_A_shifted;
    wire [24:0] M_B_shifted;

    // Shift M_A when EA_LT_EB is high
    assign M_A_shifted = {2'b00, M_A >> shamt};

    // Shift M_B when EA_LT_EB is low
    assign M_B_shifted = {2'b00, M_B >> shamt};

    // Mux to select between M_A_shifted and M_B_shifted based on EA_LT_EB
    assign MA_shift = EA_LT_EB ? M_A_shifted : {2'b00, 23'b0};
    assign MB_shift = ~EA_LT_EB ? M_B_shifted : {2'b00, 23'b0};

endmodule

module sum22bit(a, b, kIn, sum);
    input [21:0] a;
    input [21:0] b;
    input [1:0] kIn;
    output [22:0] sum;

    // Internal signals for carry generation
    wire [21:0] g, p;
    wire [22:0] carry;

    // Generate and propagate carry signals
    genvar i;
    generate
        for (i = 0; i <= 21; i = i + 1) begin : gen_carry
            assign g[i] = a[i] & b[i];
            assign p[i] = a[i] ^ b[i];
        end

        // First level of carry lookahead
        assign carry[0] = kIn[0];
        assign carry[1] = kIn[1] | (kIn[0] & p[0]);
        for (i = 2; i <= 21; i = i + 2) begin : gen_carry_level1
            assign carry[i] = carry[i-2] | (carry[i-1] & p[i-1]);
            assign carry[i+1] = carry[i] | (carry[i-1] & p[i]);
        end
    endgenerate

    // Compute the sum using XOR gates
    genvar j;
    generate
        for (j = 0; j <= 21; j = j + 1) begin : gen_sum
            assign sum[j] = a[j] ^ b[j] ^ carry[j];
        end
    endgenerate

    // Final carry-out
    assign sum[22] = carry[21];

endmodule

module submuladd_1_stage_signed_16_bit(
