	// Internal 32-bit register to store the result of the computation
	reg signed [31:0] stage0;

	// Computation logic
	always @(posedge clk) begin
		// Calculate (d - a) * b
		signed [31:0] mul_result = (d - a) * b;
		// Calculate ((d - a) * b) + c
		stage0 <= mul_result + c;
		// Assign the lower 16 bits of stage0 to the output
		out <= stage0[15:0];
	end

endmodule

