module cycloneiv_hssi_tx_pma_sub_tx_rx_det_rcv_det_control (
	input wire clk, 
	input wire rcv_det_en, 
	input wire rcv_det_pdb, 
	input wire com_pass, 
	input wire probe_pass, 
	output wire det_on, 
	output wire detect_valid, 
	output wire rcv_found
);

// Synchronization submodule to prevent metastability
reg sync_det_pdb;
always @(posedge clk) begin
	sync_det_pdb <= rcv_det_pdb;
end

// Finite State Machine (FSM) states
typedef enum reg [1:0] {IDLE, DETECT, VALIDATE, FOUND} state_t;
state_t state, next_state;

// State transition logic
always @(posedge clk) begin
	if (rcv_det_en) begin
		state <= next_state;
	end else begin
		state <= IDLE;
	end
end

// Next state logic
always @(*) begin
	case (state)
		IDLE: begin
			if (com_pass && probe_pass) begin
				next_state = DETECT;
			end else begin
				next_state = IDLE;
			end
		end
		DETECT: begin
			next_state = VALIDATE;
		end
		VALIDATE: begin
			if (sync_det_pdb) begin
				next_state = FOUND;
			end else begin
				next_state = IDLE;
			end
		end
		FOUND: begin
			next_state = IDLE;
		end
		default: begin
			next_state = IDLE;
		end
	endcase
end

// Output logic
assign det_on = (state == DETECT);
assign detect_valid = (state == VALIDATE);
assign rcv_found = (state == FOUND);

endmodule

