module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);

    // State definitions
    typedef enum reg [2:0] {
        IDLE,
        START_BIT,
        DATA_BITS,
        PARITY_BIT,
        STOP_BIT
    } state_t;

    state_t state, next_state;
    reg [3:0] bit_counter;
    reg [7:0] shift_reg;
    reg parity;

    // Baud rate generator
    reg [15:0] baud_counter;
    localparam BAUD_RATE = 9600;
    localparam CLK_FREQ = 50000000; // 50 MHz clock
    localparam BAUD_PERIOD = CLK_FREQ / BAUD_RATE;

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_counter <= 0;
            shift_reg <= 0;
            parity <= 0;
            baud_counter <= 0;
            data_out <= 0;
            done <= 0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    if (start) begin
                        shift_reg <= data_in;
                        parity <= data_in[0];
                        for (int i = 1; i < 8; i = i + 1) begin
                            parity <= parity ^ data_in[i];
                        end
                        bit_counter <= 0;
                        baud_counter <= 0;
                    end
                end
                START_BIT: begin
                    if (baud_counter == BAUD_PERIOD - 1) begin
                        baud_counter <= 0;
                        next_state <= DATA_BITS;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                DATA_BITS: begin
                    if (baud_counter == BAUD_PERIOD - 1) begin
                        baud_counter <= 0;
                        data_out <= shift_reg[6:0];
                        shift_reg <= {shift_reg[6:0], 1'b0};
                        bit_counter <= bit_counter + 1;
                        if (bit_counter == 7) begin
                            next_state <= PARITY_BIT;
                        end
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                PARITY_BIT: begin
                    if (baud_counter == BAUD_PERIOD - 1) begin
                        baud_counter <= 0;
                        data_out <= parity;
                        next_state <= STOP_BIT;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                STOP_BIT: begin
                    if (baud_counter == BAUD_PERIOD - 1) begin
                        baud_counter <= 0;
                        data_out <= 1'b1;
                        done <= 1;
                        next_state <= IDLE;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
            endcase
        end
    end

    // Output done flag
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
        end else if (state == IDLE) begin
            done <= 0;
        end
    end

endmodule

module muladd_3_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);

	// Internal 16-bit registers to hold intermediate results
	reg signed [15:0] stage0;
	reg signed [15:0] stage1;
	reg signed [15:0] stage2;

	// Internal 8-bit register to hold the final output
	reg signed [7:0] out_reg;

	// Pipeline stages
	always @(posedge clk) begin
		// Stage 0: Compute (a * b) + c
		stage0 <= (a * b) + c;

		// Stage 1: Pass the result from stage0 to stage1
		stage1 <= stage0;

		// Stage 2: Pass the result from stage1 to stage2
		stage2 <= stage1;

		// Output stage: Assign the result from stage2 to out_reg
		out_reg <= stage2[7:0];
	end

	// Assign the final output
	assign out = out_reg;

endmodule

