module addr_decode #(
  parameter int unsigned NoIndices = 32'd0, 
  parameter int unsigned NoRules   = 32'd0, 
  parameter type         addr_t    = logic, 
  parameter type         rule_t    = logic, 

  parameter int unsigned IdxWidth  = (NoIndices > 32'd1) ? $clog2(NoIndices) : 32'd1,
  parameter type         idx_t     = logic [IdxWidth-1:0]
) (
  input  addr_t               addr_i,           
  input  rule_t [NoRules-1:0] addr_map_i,       
  output idx_t                idx_o,            
  output logic                dec_valid_o,      
  output logic                dec_error_o,      

  input  logic                en_default_idx_i, 
  input  idx_t                default_idx_i     
);

  // Local variables
  logic [NoRules-1:0] match;
  logic [NoRules-1:0] valid_rules;
  logic [NoRules-1:0] overlap;

  // Initialize outputs
  assign idx_o = default_idx_i;
  assign dec_valid_o = 1'b0;
  assign dec_error_o = 1'b0;

  // Check for overlaps and valid rules
  always_comb begin
    valid_rules = '0;
    overlap = '0;
    for (int i = 0; i < NoRules; i++) begin
      if (addr_map_i[i].start_addr < addr_map_i[i].end_addr) begin
        valid_rules[i] = 1'b1;
      end else begin
        $fatal("Rule %0d: start address is not less than end address", i);
      end
      for (int j = i + 1; j < NoRules; j++) begin
        if (addr_map_i[i].end_addr > addr_map_i[j].start_addr && addr_map_i[j].end_addr > addr_map_i[i].start_addr) begin
          overlap[i] = 1'b1;
          overlap[j] = 1'b1;
        end
      end
    end
  end

  // Decode address
  always_comb begin
    match = '0;
    for (int i = 0; i < NoRules; i++) begin
      if (valid_rules[i] && addr_i >= addr_map_i[i].start_addr && addr_i < addr_map_i[i].end_addr) begin
        match[i] = 1'b1;
      end
    end
  end

  // Check for multiple matches
  always_comb begin
    int match_count = 0;
    for (int i = 0; i < NoRules; i++) begin
      if (match[i]) begin
        match_count++;
      end
    end
    if (match_count > 1) begin
      $fatal("Multiple rules match the address");
    end
  end

  // Assign decoded index and validity
  always_comb begin
    dec_valid_o = 1'b0;
    dec_error_o = 1'b0;
    for (int i = 0; i < NoRules; i++) begin
      if (match[i]) begin
        idx_o = addr_map_i[i].index;
        dec_valid_o = 1'b1;
      end
    end
    if (!dec_valid_o && en_default_idx_i) begin
      idx_o = default_idx_i;
      dec_valid_o = 1'b1;
    end
    if (!dec_valid_o) begin
      dec_error_o = 1'b1;
    end
  end

endmodule

