      rd_reg2 <= rd_reg1;
      wr_reg1 <= zpos ? ~wr_n : wr_reg1;
      wr_reg2 <= wr_reg1;
    end
  end

  // Assign outputs
  assign rst = ~rst_n;
  assign m1 = m1_reg2;
  assign rfsh = rfsh_reg2;
  assign rd = rd_reg2;
  assign wr = wr_reg2;
  assign iorq = iorq_reg2;
