  assign memrw = mreq_reg2 & (rd_reg2 ^ wr_reg2);
  assign opfetch = m1_reg2 & ~rfsh_reg2;
  assign intack = 1'b0; // Placeholder for intack, not specified in the interface

  // Synchronized outputs
