module key_filter(clk, rst_n, key_pin, key_status, key_event);
    input clk;
    input rst_n;
    input key_pin;
    output reg key_status;
    output reg key_event;

    // Internal signals
    reg [1:0] key_history;
    reg [3:0] counter;
    reg last_key_event;

    // State definitions
    parameter IDLE = 2'b00;
    parameter PRESS = 2'b01;
    parameter STEADY = 2'b10;
    parameter RELEASE = 2'b11;

    // State register
    reg [1:0] current_state;

    // Edge detection
    wire key_falling_edge = ~key_history[1] & key_history[0];
    wire key_rising_edge = key_history[1] & ~key_history[0];

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 4'b0000;
        end else if (current_state == IDLE || current_state == STEADY) begin
            counter <= 4'b0000;
        end else if (counter < 4'b1111) begin
            counter <= counter + 1;
        end
    end

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            key_status <= 1'b0;
            key_event <= 1'b0;
        end else begin
            case (current_state)
                IDLE: begin
                    if (key_falling_edge) begin
                        current_state <= PRESS;
                    end
                    key_status <= 1'b0;
                    key_event <= 1'b0;
                end
                PRESS: begin
                    if (counter == 4'b1111) begin
                        current_state <= STEADY;
                        key_status <= 1'b1;
                        key_event <= 1'b1;
                    end
                end
                STEADY: begin
                    if (key_rising_edge) begin
                        current_state <= RELEASE;
                    end
                    key_status <= 1'b1;
                    key_event <= 1'b0;
                end
                RELEASE: begin
                    if (counter == 4'b1111) begin
                        current_state <= IDLE;
                        key_status <= 1'b0;
                        key_event <= 1'b1;
                    end
                end
            endcase
        end
    end

    // Key history update
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            key_history <= 2'b00;
        end else begin
            key_history <= {key_history[0], key_pin};
        end
    end

    // Key event pulse generation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            last_key_event <= 1'b0;
        end else begin
            last_key_event <= key_event;
        end
    end

    assign key_event = key_event & ~last_key_event;

endmodule

module apb_master(
    input     [7:0]       addr,
    input                 data_valid,  
    input     [31:0]      data,
    input                 data_dir,
    output [31:0]      read_out_data,
    output            transaction_done,

    input                 apb_clk,
    input                 apb_reset,
    output                apb_write,
    output                apb_selx,
    output                apb_en,
    output   [31:0]       apb_wdata,
    input    [31:0]       apb_rdata,
    input                 apb_ready,
    output   [7:0]        apb_addr,
    output                apb_tranerr
);

    // State definitions
    typedef enum logic [1:0] {
        IDLE,
        SETUP,
        ACCESS
    } state_t;

    // State register
    state_t current_state, next_state;

    // Timeout counter
    reg [7:0] timeout_counter;

    // Internal signals
    reg [31:0] read_data_reg;
    reg transaction_done_reg;
    reg apb_write_reg;
    reg apb_selx_reg;
    reg apb_en_reg;
    reg [31:0] apb_wdata_reg;
    reg [7:0] apb_addr_reg;
    reg apb_tranerr_reg;

    // State transition logic
    always @(posedge apb_clk or posedge apb_reset) begin
        if (apb_reset) begin
            current_state <= IDLE;
            timeout_counter <= 0;
            read_data_reg <= 0;
            transaction_done_reg <= 0;
            apb_write_reg <= 0;
            apb_selx_reg <= 0;
            apb_en_reg <= 0;
            apb_wdata_reg <= 0;
            apb_addr_reg <= 0;
            apb_tranerr_reg <= 0;
        end else begin
            current_state <= next_state;
            case (current_state)
                IDLE: begin
                    if (data_valid) begin
                        timeout_counter <= 0;
                    end
                end
                SETUP: begin
                    // No timeout reset needed here
                end
                ACCESS: begin
                    if (apb_ready || timeout_counter == 255) begin
                        timeout_counter <= 0;
                    end else begin
                        timeout_counter <= timeout_counter + 1;
                    end
                end
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (data_valid) begin
                    next_state = SETUP;
                end
            end
            SETUP: begin
                next_state = ACCESS;
            end
            ACCESS: begin
                if (apb_ready) begin
                    next_state = IDLE;
                end else if (timeout_counter == 255) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Output logic
    always @(*) begin
        read_out_data = read_data_reg;
        transaction_done = transaction_done_reg;
        apb_write = apb_write_reg;
        apb_selx = apb_selx_reg;
        apb_en = apb_en_reg;
        apb_wdata = apb_wdata_reg;
        apb_addr = apb_addr_reg;
        apb_tranerr = apb_tranerr_reg;
    end

    // Combinational logic for state actions
    always @(*) begin
        case (current_state)
            IDLE: begin
                apb_write_reg = 0;
                apb_selx_reg = 0;
                apb_en_reg = 0;
                apb_wdata_reg = 0;
                apb_addr_reg = 0;
                apb_tranerr_reg = 0;
                transaction_done_reg = 0;
            end
            SETUP: begin
                apb_write_reg = ~data_dir;
                apb_selx_reg = 1;
                apb_en_reg = 1;
                apb_wdata_reg = data;
                apb_addr_reg = addr;
                apb_tranerr_reg = 0;
                transaction_done_reg = 0;
            end
            ACCESS: begin
                if (apb_ready) begin
                    read_data_reg = apb_rdata;
                    transaction_done_reg = 1;
                end else if (timeout_counter == 255) begin
                    apb_tranerr_reg = 1;
                    transaction_done_reg = 1;
                end
            end
        endcase
    end

endmodule

module data_path(
    output [31:0] IR_OUT,
    output MOC,
    output Cond,
    input SE,
    input [1:0] size,
    input FR_ld,
    input RF_ld,
    input IR_ld,
    input MAR_ld,
    input MDR_ld,
    input R_W,
    input MOV,
    input MA_1, MA_0, MB_1, MB_0, MC_2, MC_1, MC_0, MD, ME,
    input [4:0] OP,
    input clk, clr
);

    // Internal registers
    reg [31:0] IR;
    reg [31:0] MAR;
    reg [31:0] MDR;
    reg [31:0] FR;

    // Internal signals
    reg [31:0] mux_A_out;
    reg [31:0] mux_B_out;
    reg [31:0] alu_out;
    reg [31:0] shifter_out;
    reg [31:0] sign_ext_out;
    reg [31:0] ram_out;

    // Instruction Register
    always @(posedge clk or posedge clr) begin
        if (clr)
            IR <= 32'b0;
        else if (IR_ld)
            IR <= ram_out;
    end

    // Memory Address Register
    always @(posedge clk or posedge clr) begin
        if (clr)
            MAR <= 32'b0;
        else if (MAR_ld)
            MAR <= alu_out;
    end

    // Memory Data Register
    always @(posedge clk or posedge clr) begin
        if (clr)
            MDR <= 32'b0;
        else if (MDR_ld)
            MDR <= ram_out;
    end

    // Frame Register
    always @(posedge clk or posedge clr) begin
        if (clr)
            FR <= 32'b0;
        else if (FR_ld)
            FR <= alu_out;
    end

    // Multiplexers
    always @(*) begin
        case ({MA_1, MA_0})
            2'b00: mux_A_out = IR;
            2'b01: mux_A_out = FR;
            2'b10: mux_A_out = MDR;
            2'b11: mux_A_out = 32'b0; // Default case
        endcase
    end

    always @(*) begin
        case ({MB_1, MB_0})
            2'b00: mux_B_out = FR;
            2'b01: mux_B_out = MDR;
            2'b10: mux_B_out = 32'b0; // Default case
            2'b11: mux_B_out = 32'b0; // Default case
        endcase
    end

    // ALU
    always @(*) begin
        case (OP)
            5'b00000: alu_out = mux_A_out + mux_B_out; // ADD
            5'b00001: alu_out = mux_A_out - mux_B_out; // SUB
            5'b00010: alu_out = mux_A_out & mux_B_out; // AND
            5'b00011: alu_out = mux_A_out | mux_B_out; // OR
            5'b00100: alu_out = mux_A_out ^ mux_B_out; // XOR
            5'b00101: alu_out = ~mux_A_out; // NOT
            5'b00110: alu_out = mux_A_out << 1; // SHL
            5'b00111: alu_out = mux_A_out >> 1; // SHR
            default: alu_out = 32'b0; // Default case
        endcase
    end

    // Shifter
    always @(*) begin
        case ({MC_2, MC_1, MC_0})
            3'b000: shifter_out = mux_A_out << 0;
            3'b001: shifter_out = mux_A_out << 1;
            3'b010: shifter_out = mux_A_out << 2;
            3'b011: shifter_out = mux_A_out << 3;
            3'b100: shifter_out = mux_A_out >> 0;
            3'b101: shifter_out = mux_A_out >> 1;
            3'b110: shifter_out = mux_A_out >> 2;
            3'b111: shifter_out = mux_A_out >> 3;
            default: shifter_out = 32'b0; // Default case
        endcase
    end

    // Sign Extender
    always @(*) begin
        case (size)
            2'b00: sign_ext_out = {24{mux_A_out[7]}}, mux_A_out[7:0]; // 8-bit
            2'b01: sign_ext_out = {16{mux_A_out[15]}}, mux_A_out[15:0]; // 16-bit
            2'b10: sign_ext_out = {8{mux_A_out[23]}}, mux_A_out[23:0]; // 24-bit
            2'b11: sign_ext_out = mux_A_out; // 32-bit
            default: sign_ext_out = 32'b0; // Default case
        endcase
    end

    // RAM
    ram_256 ram (
        .address(MAR[7:0]),
        .data_in(MDR),
        .data_out(ram_out),
        .write_enable(R_W),
        .clk(clk)
    );

    // Outputs
    assign IR_OUT = IR;
    assign MOC = 1'b0; // Placeholder for memory operation control
    assign Cond = 1'b0; // Placeholder for condition flags

endmodule

