module VGA_Sig_Gen(
            input CLK,
            input RESET,
            input RE,

            input [15:0] CONFIG_COLOURS,

            output DPR_CLK,
            output [14:0] VGA_ADDR,
            input VGA_DATA,

            output reg VGA_HS,
            output reg VGA_VS,
            output reg [7:0] VGA_COLOUR
            );

    // Parameters for VGA timing
    parameter H_TOTAL = 800; // Total horizontal pixels
    parameter H_DISPLAY = 640; // Active display area
    parameter H_SYNC_START = 656; // Horizontal sync start
    parameter H_SYNC_END = 752; // Horizontal sync end
    parameter V_TOTAL = 525; // Total vertical lines
    parameter V_DISPLAY = 480; // Active display area
    parameter V_SYNC_START = 490; // Vertical sync start
    parameter V_SYNC_END = 492; // Vertical sync end

    // Internal counters
    reg [9:0] h_count; // Horizontal counter
    reg [9:0] v_count; // Vertical counter

    // Internal signals
    reg h_sync; // Horizontal sync signal
    reg v_sync; // Vertical sync signal
    reg [14:0] addr; // Address for memory

    // Clock generation
    assign DPR_CLK = CLK;

    // Horizontal and vertical sync generation
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            h_count <= 0;
            v_count <= 0;
            VGA_HS <= 1'b1;
            VGA_VS <= 1'b1;
        end else begin
            // Increment horizontal counter
            if (h_count == H_TOTAL - 1) begin
                h_count <= 0;
                // Increment vertical counter
                if (v_count == V_TOTAL - 1) begin
                    v_count <= 0;
                end else begin
                    v_count <= v_count + 1;
                end
            end else begin
                h_count <= h_count + 1;
            end

            // Generate horizontal sync signal
            if (h_count >= H_SYNC_START && h_count < H_SYNC_END) begin
                VGA_HS <= 1'b0;
            end else begin
                VGA_HS <= 1'b1;
            end

            // Generate vertical sync signal
            if (v_count >= V_SYNC_START && v_count < V_SYNC_END) begin
                VGA_VS <= 1'b0;
            end else begin
                VGA_VS <= 1'b1;
            end
        end
    end

    // Address generation for memory
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            addr <= 0;
        end else if (h_count < H_DISPLAY && v_count < V_DISPLAY) begin
            addr <= addr + 1;
        end else begin
            addr <= 0;
        end
    end

    // Assign address to output
    assign VGA_ADDR = addr;

    // Color generation based on VGA_DATA and CONFIG_COLOURS
    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            VGA_COLOUR <= 8'b00000000;
        end else if (h_count < H_DISPLAY && v_count < V_DISPLAY) begin
            if (VGA_DATA) begin
                VGA_COLOUR <= CONFIG_COLOURS[15:8];
            end else begin
                VGA_COLOUR <= CONFIG_COLOURS[7:0];
            end
        end else begin
            VGA_COLOUR <= 8'b00000000;
        end
    end

endmodule

module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);

    // State definition
    typedef enum reg [1:0] {IDLE, SETUP, ACCESS} state_t;
    state_t state, next_state;

    // State register
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (Transfer)
                    next_state = SETUP;
                else
                    next_state = IDLE;
            end
            SETUP: begin
                if (PREADY)
                    next_state = ACCESS;
                else
                    next_state = SETUP;
            end
            ACCESS: begin
                if (PREADY)
                    next_state = IDLE;
                else
                    next_state = ACCESS;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(*) begin
        PADDR = Address;
        PSELx = 1'b1;
        PENABLE = 1'b0;
        PWRITE = Wr_Rd;
        PWDATA = write_data;
        read_data = 32'b0;

        case (state)
            IDLE: begin
                PENABLE = 1'b0;
            end
            SETUP: begin
                PENABLE = 1'b1;
            end
            ACCESS: begin
                if (PREADY) begin
                    if (!Wr_Rd)
                        read_data = PRDATA;
                end
            end
        endcase
    end

endmodule

module BBFASin(
