module mux_256x1 (in, sel, out);
    input [255:0] in;
    input [7:0] sel;
    output out;

    // Internal signals for intermediate multiplexer outputs
    wire [127:0] lower_half;
    wire [127:0] upper_half;
    wire [1:0] lower_select;
    wire [1:0] upper_select;
    wire [1:0] final_select;

    // Assign the lower 7 bits of the select signal to the lower and upper selects
    assign lower_select = sel[6:5];
    assign upper_select = sel[6:5];
    assign final_select = sel[7:7];

    // Lower 128x1 multiplexer
    assign lower_half = (sel[4] == 1'b0) ? in[127:0] : in[255:128];

    // Upper 128x1 multiplexer
    assign upper_half = (sel[4] == 1'b0) ? in[127:0] : in[255:128];

    // Final 2x1 multiplexer
    assign out = (final_select == 2'b0) ? lower_half[sel[3:0]] : upper_half[sel[3:0]];
endmodule

