module FIFO_toe_ackDelayFifoReadCount_V_V #(
    parameter MEMORY_STYLE = "shiftreg",
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 4,
    parameter DEPTH = 16
) (
    input clk,
    input reset,
    output reg if_empty_n,
    input if_read_ce,
    input if_read,
    output reg [DATA_WIDTH - 1:0] if_dout,
    output reg if_full_n,
    input if_write_ce,
    input if_write,
    input [DATA_WIDTH - 1:0] if_din
);

reg [ADDR_WIDTH:0] read_ptr;
reg [ADDR_WIDTH:0] write_ptr;
reg [DATA_WIDTH - 1:0] mem [0:DEPTH - 1];

always @(posedge clk or posedge reset) begin
    if (reset) begin
        read_ptr <= 0;
        write_ptr <= 0;
        if_empty_n <= 1'b0;
        if_full_n <= 1'b1;
    end else begin
        if (if_write && if_write_ce && !if_full_n) begin
            mem[write_ptr[ADDR_WIDTH - 1:0]] <= if_din;
            write_ptr <= write_ptr + 1;
            if (write_ptr == DEPTH - 1) begin
                if_full_n <= 1'b0;
            end
        end

        if (if_read && if_read_ce && !if_empty_n) begin
            if_dout <= mem[read_ptr[ADDR_WIDTH - 1:0]];
            read_ptr <= read_ptr + 1;
            if (read_ptr == DEPTH - 1) begin
                if_empty_n <= 1'b0;
            end
        end

        if (write_ptr == read_ptr) begin
            if_empty_n <= 1'b1;
            if_full_n <= 1'b1;
        end else if (write_ptr > read_ptr) begin
            if_empty_n <= 1'b0;
            if_full_n <= 1'b0;
        end else begin
            if_empty_n <= 1'b0;
            if_full_n <= 1'b1;
        end
    end
end

endmodule

