    );

    // BarrelShifter32 module instantiation
    BarrelShifter32 shifter_inst (
        .Data(A),
        .ShiftAmount(SH),
        .Out(shifter_out)
    );

    // Multiplexer to select between ALU and Shifter output
    assign final_out = shift_enable ? shifter_out : alu_out;

    // Assign final output to module output
    assign Out = final_out;

endmodule

// ALU module definition
module ALU (
    input [BITS-1:0] A,
    input [BITS-1:0] B,
    input [4:0] FS,
    output wire [BITS-1:0] Out,
    output wire statC,
    output wire statN,
    output wire statV,
    output wire statZ,
    output wire shift_enable
);

    // Internal signals
    wire [BITS-1:0] alu_result;
    wire carry_out;
    wire overflow_out;

    // ALU logic
    always @(*) begin
        case (FS)
            5'b00000: alu_result = A + B; // ADD
            5'b00001: alu_result = A - B; // SUB
            5'b00010: alu_result = A & B; // AND
            5'b00011: alu_result = A | B; // OR
            5'b00100: alu_result = A ^ B; // XOR
            5'b00101: alu_result = ~A;    // NOT
            5'b00110: alu_result = A << B[4:0]; // SHL
            5'b00111: alu_result = A >> B[4:0]; // SHR
            default: alu_result = A; // Default to A
        endcase
    end

    // Carry flag
    assign carry_out = (FS == 5'b00000) ? (A[BITS-1] & B[BITS-1] & ~alu_result[BITS-1]) | (~A[BITS-1] & B[BITS-1] & alu_result[BITS-1]) : 1'b0;

    // Overflow flag
    assign overflow_out = (FS == 5'b00000) ? (A[BITS-1] ^ B[BITS-1]) & (A[BITS-1] ^ alu_result[BITS-1]) : 1'b0;

    // Status flags
    assign statC = carry_out;
    assign statN = alu_result[BITS-1];
    assign statV = overflow_out;
    assign statZ = (alu_result == 0);

    // Shift enable signal
    assign shift_enable = (FS == 5'b00110) | (FS == 5'b00111);

    // ALU output
    assign Out = alu_result;

endmodule

