module gates(
    input wire a_i,
    input wire b_i,
    input wire c_i,
    output wire out_o,
    output wire out2_o,
    output wire out3_o,
    output wire out4_o,
    output wire out5_o,
    output wire out6_o,
    output wire out7_o,
    output wire out8_o
);

    // out_o and out2_o showcase fundamental contradictions
    assign out_o = 0; // Always 0
    assign out2_o = 1; // Always 1

    // out3_o and out4_o highlight redundancy, simplifying to a_i
    assign out3_o = a_i;
    assign out4_o = a_i;

    // out5_o and out6_o are equivalent, illustrating logical distributive properties
    assign out5_o = a_i & (b_i | c_i); // Distributive law: a & (b | c) = (a & b) | (a & c)
    assign out6_o = (a_i & b_i) | (a_i & c_i);

    // out7_o and out8_o are equivalent, illustrating De Morgan's laws
    assign out7_o = ~(a_i | b_i); // De Morgan's law: ~(a | b) = ~a & ~b
    assign out8_o = ~a_i & ~b_i;

endmodule

