                if (data_ready == 1) begin
                    display_data <= bcd_output >> (current_digit * 8);
                    current_digit <= current_digit - 1;
                    if (current_digit < 0) begin
                        data_ready <= 0;
                    end
                end
            end
            default: begin
                // Default state
            end
        endcase
    end

    // Instantiate DispHexMux module
    DispHexMux dispHexMux (
