module PulseCounter(
    input wire clk,
    output wire pulse
);

    // Parameter for the upper bound of the counter
    parameter COUNT_MAX = 28'hFFFFFFF; // 28-bit maximum value

    // Internal register to hold the current count
    reg [27:0] count;

    // Combinational logic to generate the pulse
    assign pulse = (count == COUNT_MAX) ? 1'b1 : 1'b0;

    // Sequential logic to increment the counter
    always @(posedge clk) begin
        if (count == COUNT_MAX) begin
            count <= 28'b0; // Reset to zero when the upper bound is reached
        end else begin
            count <= count + 1; // Increment the counter
        end
    end

endmodule

