    // Extract the upper byte (bits 30 to 23) of the real part
    wire [7:0] upper_byte_re = a_re[30:23];
    // Decrement the upper byte by 7
    wire [7:0] modified_upper_byte_re = upper_byte_re - 7;
    // Reconstruct the modified real part
    assign a1_re = {a_re[31], modified_upper_byte_re, a_re[22:0]};

    // Extract the upper byte (bits 30 to 23) of the imaginary part
    wire [7:0] upper_byte_img = a_img[30:23];
    // Decrement the upper byte by 7
    wire [7:0] modified_upper_byte_img = upper_byte_img - 7;
    // Reconstruct the modified imaginary part
    assign a1_img = {a_img[31], modified_upper_byte_img, a_img[22:0]};

endmodule

