	.b(b[0]),
	.c_in(c_in),
	.s(s[0]),
	.g(g0),
	.p(p0)
);

// ADD submodule instantiation for bit 1
ADD add1 (
	.a(a[1]),
	.b(b[1]),
	.c_in(add0.g),
	.s(s[1]),
	.g(g1),
	.p(p1)
);

// G_P submodule instantiation to compute final carry and propagate
G_P gp (
	.g0(g0),
	.g1(g1),
	.p0(p0),
	.p1(p1),
	.g_out(g_out),
	.p_out(p_out)
);

