module tb_file_to_dvp
#(
	parameter FILE     = "in.bin",
	parameter BITS     = 8, 
	parameter H_FRONT  = 50,
	parameter H_PULSE  = 100,
	parameter H_BACK   = 50,
	parameter H_DISP   = 1280,
	parameter V_FRONT  = 10,
	parameter V_PULSE  = 20,
	parameter V_BACK   = 10,
	parameter V_DISP   = 960,
	parameter H_POL    = 0,
	parameter V_POL    = 1
)
(
	input             xclk,
	input             rst_n,
	output            pclk,
	output reg        href,
	output reg        hsync,
	output reg        vsync,
	output [BITS-1:0] data
);

// Internal parameters
localparam H_TOTAL = H_FRONT + H_PULSE + H_BACK + H_DISP;
localparam V_TOTAL = V_FRONT + V_PULSE + V_BACK + V_DISP;

// Internal signals
reg [31:0] pix_cnt;
reg [31:0] line_cnt;
reg [31:0] data_cnt;
reg [BITS-1:0] raw_data;
reg [BITS-1:0] buffer [0:H_DISP*V_DISP-1];

// Initialize buffer with file data
initial begin
	$readmemh(FILE, buffer);
end

// Sequential logic
always @(posedge xclk or negedge rst_n) begin
	if (!rst_n) begin
		pix_cnt <= 0;
		line_cnt <= 0;
		data_cnt <= 0;
		href <= 0;
		hsync <= H_POL;
		vsync <= V_POL;
		data <= 0;
	end else begin
		// Increment pixel counter
		if (pix_cnt < H_TOTAL - 1) begin
			pix_cnt <= pix_cnt + 1;
		end else begin
			pix_cnt <= 0;
			// Increment line counter
			if (line_cnt < V_TOTAL - 1) begin
				line_cnt <= line_cnt + 1;
			end else begin
				line_cnt <= 0;
			end
		end

		// Generate href
		if (pix_cnt >= H_FRONT && pix_cnt < H_FRONT + H_DISP) begin
			href <= 1;
		} else begin
			href <= 0;
		end

		// Generate hsync
		if (pix_cnt >= H_FRONT + H_DISP && pix_cnt < H_FRONT + H_DISP + H_PULSE) begin
			hsync <= ~H_POL;
		} else begin
			hsync <= H_POL;
		end

		// Generate vsync
		if (line_cnt >= V_FRONT && line_cnt < V_FRONT + V_PULSE) begin
			vsync <= ~V_POL;
		} else begin
			vsync <= V_POL;
		end

		// Output pixel data
		if (href) begin
			data <= buffer[data_cnt];
			if (data_cnt < H_DISP*V_DISP - 1) begin
				data_cnt <= data_cnt + 1;
			end else begin
				data_cnt <= 0;
			end
		end else begin
			data <= 0;
		end
	end
end

// Assign pclk to xclk
assign pclk = xclk;

endmodule

