module uart_tx_tester (
    input clk_50M,
    input run_test_raw,
    input tx_busy,
    output reg [7:0] data_out,
    output reg trigger
);

    // Parameters
    parameter MSG_DELAY = 1000000; // Delay between messages in clock cycles
    parameter DATA_LENGTH = 13; // Length of the message "Hello World! "

    // States
    typedef enum reg [2:0] {
        IDLE,
        LOAD_DATA,
        TRIGGER_TX,
        POLL_BUSY,
        PAUSE
    } state_t;

    state_t current_state, next_state;

    // Internal registers
    reg [31:0] delay_counter;
    reg [3:0] data_index;
    reg [7:0] message [DATA_LENGTH-1:0] = {
        8'h48, 8'h65, 8'h6C, 8'h6C, 8'h6F, 8'h20, 8'h57, 8'h6F, 8'h72, 8'h6C, 8'h64, 8'h21, 8'h20
    };

    // State machine
    always @(posedge clk_50M) begin
        if (run_test_raw) begin
            current_state <= next_state;
        end else begin
            current_state <= IDLE;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (run_test_raw) begin
                    next_state = LOAD_DATA;
                end
            end
            LOAD_DATA: begin
                if (data_index < DATA_LENGTH) begin
                    next_state = TRIGGER_TX;
                end else begin
                    next_state = PAUSE;
                end
            end
            TRIGGER_TX: begin
                next_state = POLL_BUSY;
            end
            POLL_BUSY: begin
                if (!tx_busy) begin
                    next_state = LOAD_DATA;
                end
            end
            PAUSE: begin
                if (delay_counter == MSG_DELAY) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Output logic
    always @(posedge clk_50M) begin
        case (current_state)
            IDLE: begin
                data_out <= 8'h00;
                trigger <= 1'b0;
                delay_counter <= 0;
                data_index <= 0;
            end
            LOAD_DATA: begin
                data_out <= message[data_index];
                data_index <= data_index + 1;
            end
            TRIGGER_TX: begin
                trigger <= 1'b1;
            end
            POLL_BUSY: begin
                trigger <= 1'b0;
            end
            PAUSE: begin
                if (delay_counter < MSG_DELAY) begin
                    delay_counter <= delay_counter + 1;
                end
            end
        endcase
    end

endmodule

module add8_456(A, B, O);
  input [7:0] A;
  input [7:0] B;
  output [8:0] O;

  wire [15:0] N;

  // Duplicate input bits in N
  assign N[0] = A[0];
  assign N[1] = A[0];
  assign N[2] = B[0];
  assign N[3] = B[0];
  assign N[4] = A[1];
  assign N[5] = A[1];
  assign N[6] = B[1];
  assign N[7] = B[1];
  assign N[8] = A[2];
  assign N[9] = A[2];
  assign N[10] = B[2];
  assign N[11] = B[2];
  assign N[12] = A[3];
  assign N[13] = A[3];
  assign N[14] = B[3];
  assign N[15] = B[3];

  // Custom logic gates to compute intermediate results
  wire [15:0] NAND_out;
  wire [15:0] NOR_out;
  wire [15:0] AOI_out;

  genvar i;
  generate
    for (i = 0; i < 16; i = i + 4) begin : nand_gen
      NAND_out[i] = ~(N[i] & N[i+1] & N[i+2]);
      NAND_out[i+1] = ~(N[i] & N[i+1] & N[i+3]);
      NAND_out[i+2] = ~(N[i] & N[i+2] & N[i+3]);
      NAND_out[i+3] = ~(N[i+1] & N[i+2] & N[i+3]);
    end

    for (i = 0; i < 16; i = i + 4) begin : nor_gen
      NOR_out[i] = ~(N[i] | N[i+1] | N[i+2]);
      NOR_out[i+1] = ~(N[i] | N[i+1] | N[i+3]);
      NOR_out[i+2] = ~(N[i] | N[i+2] | N[i+3]);
      NOR_out[i+3] = ~(N[i+1] | N[i+2] | N[i+3]);
    end

    for (i = 0; i < 16; i = i + 4) begin : aoi_gen
      AOI_out[i] = ~(N[i] & N[i+1]) | ~(N[i+2] & N[i+3]);
      AOI_out[i+1] = ~(N[i] & N[i+2]) | ~(N[i+1] & N[i+3]);
      AOI_out[i+2] = ~(N[i] & N[i+3]) | ~(N[i+1] & N[i+2]);
      AOI_out[i+3] = ~(N[i+1] & N[i+2]) | ~(N[i] & N[i+3]);
    end
  endgenerate

  // Combine intermediate results to form final output bits
  assign O[0] = NAND_out[0] | NOR_out[0] | AOI_out[0];
  assign O[1] = NAND_out[4] | NOR_out[4] | AOI_out[4];
  assign O[2] = NAND_out[8] | NOR_out[8] | AOI_out[8];
  assign O[3] = NAND_out[12] | NOR_out[12] | AOI_out[12];
  assign O[4] = NAND_out[1] | NOR_out[1] | AOI_out[1];
  assign O[5] = NAND_out[5] | NOR_out[5] | AOI_out[5];
  assign O[6] = NAND_out[9] | NOR_out[9] | AOI_out[9];
  assign O[7] = NAND_out[13] | NOR_out[13] | AOI_out[13];
  assign O[8] = NAND_out[2] | NOR_out[2] | AOI_out[2];

endmodule

