module maxFinder #(parameter numInput=10, parameter inputWidth=16)(
    input           i_clk,
    input [(numInput*inputWidth)-1:0]   i_data,
    input           i_valid,
    output reg [31:0] o_data,
    output  reg     o_data_valid
);

    reg [inputWidth-1:0] maxValue;
    reg [inputWidth-1:0] inDataBuffer [0:numInput-1];
    reg [31:0] counter;
    reg [31:0] maxIndex;

    always @(posedge i_clk) begin
        if (i_valid) begin
            // Initialize variables
            counter <= 0;
            o_data_valid <= 0;
            maxValue <= i_data[(numInput*inputWidth)-1 -: inputWidth];
            maxIndex <= 0;

            // Load input data into buffer
            for (int i = 0; i < numInput; i = i + 1) begin
                inDataBuffer[i] <= i_data[(i*inputWidth) +: inputWidth];
            end
        end else if (counter < numInput) begin
            // Find the maximum value
            if (inDataBuffer[counter] > maxValue) begin
                maxValue <= inDataBuffer[counter];
                maxIndex <= counter;
            end
            counter <= counter + 1;
        end else begin
            // Output the result
            o_data <= maxIndex;
            o_data_valid <= 1;
        end
    end

endmodule

