module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);

// State definitions
parameter [1:0] IDLE = 2'b00;
parameter [1:0] CAPTURE1 = 2'b01;
parameter [1:0] CAPTURE2 = 2'b10;
parameter [1:0] CAPTURE3 = 2'b11;

// Internal registers
reg [1:0] S, NS; // Current and next state
reg [7:0] in1, in2, in3, out; // Registers to store scan code data

// State machine logic
always @(posedge PS2_CLK) begin
	if (scan_code) begin
		case (S)
			IDLE: NS = CAPTURE1;
			CAPTURE1: NS = CAPTURE2;
			CAPTURE2: NS = CAPTURE3;
			CAPTURE3: NS = IDLE;
			default: NS = IDLE;
		endcase
	end else begin
		NS = S; // Stay in the same state if no scan code is detected
	end
end

// Data capture logic
always @(posedge PS2_CLK) begin
	if (scan_code) begin
		case (S)
			IDLE: in1 <= scan_code;
			CAPTURE1: in2 <= scan_code;
			CAPTURE2: in3 <= scan_code;
			CAPTURE3: out <= scan_code;
			default: out <= 8'b0;
		endcase
	end
end

// State transition
always @(posedge PS2_CLK) begin
	S <= NS;
end

// Output logic
assign LEDR[3:0] = S;
assign LEDR[9:4] = NS;
assign HEX0 = seven_segment_decode(out);
assign HEX1 = seven_segment_decode(S);

// Seven-segment decoder function
function [6:0] seven_segment_decode(input [7:0] data);
	case (data)
		8'h00: seven_segment_decode = 7'b1000000; // 0
		8'h01: seven_segment_decode = 7'b1111001; // 1
