	input signed [10:0] c,
	input signed [10:0] d,
	output [10:0] out
);

	// Step 1: Add inputs a and d
	wire signed [11:0] add_result = a + d;

	// Step 2: Multiply the result of the addition by input b
	wire signed [11:0] mul_result = add_result * b;

	// Step 3: Perform a bitwise OR operation with input c
	wire signed [11:0] or_result = mul_result | c;

	// Step 4: Assign the result to the output, truncating to 11 bits
	assign out = or_result[10:0];

endmodule

