module gtx_tx_reset_controller(
    input wire clk,
    input wire ref_clk,
    input wire powerup_channel,
    output reg tx_running,
    output reg txreset,
    output reg txuserrdy,
    output reg txpmareset,
    output reg txpcsreset,
    output reg pllpd,
    output reg pllreset,
    output reg plllocken,
    input wire plllock,
    output reg resetsel,
    input wire txresetdone
);

    // State machine states
    typedef enum reg [2:0] {
        INIT,
        REF_CLK_DETECT,
        PLL_RESET,
        PLL_LOCK_WAIT,
        TX_RESET,
        TX_RESET_WAIT,
        TX_USERRDY_SET,
        TX_RUNNING
    } state_t;

    state_t state, next_state;

    // Meta registers for clock domain crossing
    reg powerup_channel_meta;
    reg plllock_meta;
    reg txresetdone_meta;

    // Counters
    reg [15:0] ref_clk_counter;

    // State machine state register
    always @(posedge clk) begin
        if (!powerup_channel) begin
            state <= INIT;
        end else begin
            state <= next_state;
        end
    end

    // Meta register synchronization
    always @(posedge ref_clk) begin
        powerup_channel_meta <= powerup_channel;
    end

    always @(posedge clk) begin
        plllock_meta <= plllock;
        txresetdone_meta <= txresetdone;
    end

    // State machine logic
    always @(*) begin
        next_state = state;
        tx_running = 1'b0;
        txreset = 1'b0;
        txuserrdy = 1'b0;
        txpmareset = 1'b0;
        txpcsreset = 1'b0;
        pllpd = 1'b0;
        pllreset = 1'b0;
        plllocken = 1'b0;
        resetsel = 1'b0;

        case (state)
            INIT: begin
                if (!powerup_channel_meta) begin
                    next_state = INIT;
                end else begin
                    next_state = REF_CLK_DETECT;
                end
            end

            REF_CLK_DETECT: begin
                ref_clk_counter <= ref_clk_counter + 1;
                if (ref_clk_counter == 16'd10000) begin // Example threshold
                    next_state = PLL_RESET;
                end
            end

            PLL_RESET: begin
                pllreset = 1'b1;
                pllpd = 1'b0;
                plllocken = 1'b1;
                next_state = PLL_LOCK_WAIT;
            end

            PLL_LOCK_WAIT: begin
                if (plllock_meta) begin
                    next_state = TX_RESET;
                end
            end

            TX_RESET: begin
                txreset = 1'b1;
                txpmareset = 1'b1;
                txpcsreset = 1'b1;
                next_state = TX_RESET_WAIT;
            end

            TX_RESET_WAIT: begin
                if (txresetdone_meta) begin
                    next_state = TX_USERRDY_SET;
                end
            end

            TX_USERRDY_SET: begin
                txuserrdy = 1'b1;
                next_state = TX_RUNNING;
            end

            TX_RUNNING: begin
                tx_running = 1'b1;
            end
        endcase
    end

endmodule

