module addr_decode #(
  parameter int unsigned NoIndices = 32'd0,
  parameter int unsigned NoRules   = 32'd0,
  parameter type         addr_t    = logic,
  parameter type         rule_t    = logic,
  parameter int unsigned IdxWidth  = cf_math_pkg::idx_width(NoIndices),
  parameter type         idx_t     = logic [IdxWidth-1:0]
) (
  input  addr_t               addr_i,
  input  rule_t [NoRules-1:0] addr_map_i,
  output idx_t                idx_o,
  output logic                dec_valid_o,
  output logic                dec_error_o,
  input  logic                en_default_idx_i,
  input  idx_t                default_idx_i
);

  // Internal signals
  logic [NoRules-1:0] matched_rules;
  idx_t [NoRules-1:0] indices;
  logic [NoRules-1:0] valid_rules;

  // Initialize outputs
  assign idx_o = default_idx_i;
  assign dec_valid_o = 1'b0;
  assign dec_error_o = 1'b0;

  // Decode logic
  always_comb begin
    matched_rules = '0;
    valid_rules = '0;

    for (int i = 0; i < NoRules; i++) begin
      // Assuming rule_t is a struct with fields start_addr, end_addr, and index
      // rule_t rule = addr_map_i[i];
      // logic [addr_t'width-1:0] start_addr = rule.start_addr;
      // logic [addr_t'width-1:0] end_addr = rule.end_addr;
      // idx_t index = rule.index;

      // Example: Extracting fields from rule_t
      logic [addr_t'width-1:0] start_addr = addr_map_i[i][addr_t'width*2 + IdxWidth - 1 : addr_t'width + IdxWidth];
      logic [addr_t'width-1:0] end_addr = addr_map_i[i][addr_t'width + IdxWidth - 1 : IdxWidth];
      idx_t index = addr_map_i[i][IdxWidth - 1 : 0];

      // Check if address is within the range
      if (addr_i >= start_addr && addr_i <= end_addr) begin
        matched_rules[i] = 1'b1;
        indices[i] = index;
      end

      // Check if the index is within valid bounds
      if (index < NoIndices) begin
        valid_rules[i] = 1'b1;
      end
    end

    // Determine the output index and validity
    for (int i = 0; i < NoRules; i++) begin
      if (matched_rules[i] && valid_rules[i]) begin
        idx_o = indices[i];
        dec_valid_o = 1'b1;
        break;
      end
    end

    // Check for overlapping address ranges
    for (int i = 0; i < NoRules; i++) begin
      for (int j = i + 1; j < NoRules; j++) begin
        logic [addr_t'width-1:0] start_addr_i = addr_map_i[i][addr_t'width*2 + IdxWidth - 1 : addr_t'width + IdxWidth];
        logic [addr_t'width-1:0] end_addr_i = addr_map_i[i][addr_t'width + IdxWidth - 1 : IdxWidth];
        logic [addr_t'width-1:0] start_addr_j = addr_map_i[j][addr_t'width*2 + IdxWidth - 1 : addr_t'width + IdxWidth];
        logic [addr_t'width-1:0] end_addr_j = addr_map_i[j][addr_t'width + IdxWidth - 1 : IdxWidth];

        if (!(end_addr_i < start_addr_j || end_addr_j < start_addr_i)) begin
          dec_error_o = 1'b1;
        end
      end
    end

    // Use default index if no match and default is enabled
    if (!dec_valid_o && en_default_idx_i) begin
      idx_o = default_idx_i;
      dec_valid_o = 1'b1;
    end
  end

endmodule

