module Start_UP_Handler(
    input wire i_CLK,
    output wire o_RST
);

    // Parameters for clock frequency and initial reset time
    parameter g_Clock_Frequency = 50000000; // Example: 50 MHz
    parameter g_Initial_Reset_Time = 10000; // Example: 10 ms

    // Calculate the number of clock cycles for the initial reset
    localparam c_Initial_Reset_Clocks = (g_Clock_Frequency * g_Initial_Reset_Time) / 1000000;

    // Registers to manage the reset state and count clock cycles
    reg r_RST;
    reg [31:0] r_RST_Counter;

    // Initialize the reset signal to high
    initial begin
        r_RST = 1'b1;
        r_RST_Counter = 32'b0;
    end

    // Sequential logic to count clock cycles and de-assert the reset
    always @(posedge i_CLK) begin
        if (r_RST_Counter < c_Initial_Reset_Clocks) begin
            r_RST_Counter <= r_RST_Counter + 1;
        end else begin
            r_RST <= 1'b0;
        end
    end

    // Assign the reset output
    assign o_RST = r_RST;

endmodule

module sonar(
    input clk, rst_n, 
    input do_measure,
    input sonar_pulse,
    output reg [7:0] inches,
    output reg sonar_trigger = 0,
    output reg READY = 0
);

    // State definitions
    typedef enum reg [1:0] {
        STANDBY,
        STARTMEASURE,
        WAITFORPULSE,
        COUNTPULSE
    } state_t;

    state_t state, next_state;

    // Internal registers
    reg [15:0] timeCount;
    reg [15:0] timeoutCounter;

    // Constants
    localparam TIMEOUT_THRESHOLD = 10000; // Example timeout threshold

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STANDBY;
            timeCount <= 0;
            timeoutCounter <= 0;
            inches <= 0;
            sonar_trigger <= 0;
            READY <= 0;
        end else begin
            state <= next_state;
            case (state)
                STARTMEASURE: begin
                    sonar_trigger <= 1;
                    timeoutCounter <= 0;
                end
                WAITFORPULSE: begin
                    if (sonar_pulse)
                        timeoutCounter <= 0;
                    else if (timeoutCounter < TIMEOUT_THRESHOLD)
                        timeoutCounter <= timeoutCounter + 1;
                end
                COUNTPULSE: begin
                    if (sonar_pulse)
                        timeCount <= timeCount + 1;
                end
                default: begin
                    timeCount <= 0;
                    sonar_trigger <= 0;
                    READY <= 0;
                end
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            STANDBY: begin
                if (do_measure)
                    next_state = STARTMEASURE;
            end
            STARTMEASURE: begin
                if (sonar_pulse)
                    next_state = WAITFORPULSE;
            end
            WAITFORPULSE: begin
                if (sonar_pulse)
                    next_state = COUNTPULSE;
                else if (timeoutCounter >= TIMEOUT_THRESHOLD)
                    next_state = STANDBY;
            end
            COUNTPULSE: begin
                if (!sonar_pulse) begin
                    inches <= timeCount / 148; // Example conversion factor
                    READY <= 1;
                    next_state = STANDBY;
                end
            end
        endcase
    end

endmodule

module sky130_fd_sc_hs__mux4 (
