    A1  ,
    A2  ,
    A3  ,
    S0  ,
    S1  ,
    VPWR,
    VGND
);

    output X;
    input  A0;
    input  A1;
    input  A2;
    input  A3;
    input  S0;
    input  S1;
    input  VPWR;
    input  VGND;

    // Internal signals
    wire sel;
    wire mux_out;
    wire buffered_out;

    // 4-input multiplexer cell
    assign sel = {S1, S0}; // Combine select inputs to form a 2-bit selector
    assign mux_out = (sel == 2'b00) ? A0 :
                     (sel == 2'b01) ? A1 :
                     (sel == 2'b10) ? A2 :
                     (sel == 2'b11) ? A3 : 1'bz; // Default case to avoid latches

    // Power gating cell
    assign buffered_out = VPWR ? mux_out : VGND;

    // Final output buffer
    assign X = buffered_out;

endmodule

module voting (a0, a1, a2, a3, a4, out);

input    [2:0]   a0, a1, a2, a3, a4;
output reg [2:0]   out;

// Internal signals for summing votes
wire [3:0] sum0, sum1, sum2;

// Full adder module declaration
module full_adder (a, b, cin, sum, cout);
    input a, b, cin;
    output sum, cout;
    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (b & cin) | (a & cin);
endmodule

// Instantiate full adders to sum the votes for each bit position
full_adder fa0 (a0[0], a1[0], a2[0], sum0[0], sum0[1]);
full_adder fa1 (a3[0], a4[0], sum0[1], sum0[2], sum0[3]);
full_adder fa2 (a0[1], a1[1], a2[1], sum1[0], sum1[1]);
full_adder fa3 (a3[1], a4[1], sum1[1], sum1[2], sum1[3]);
full_adder fa4 (a0[2], a1[2], a2[2], sum2[0], sum2[1]);
full_adder fa5 (a3[2], a4[2], sum2[1], sum2[2], sum2[3]);

// Determine the majority vote
always @(*) begin
    if (sum0[3] > sum1[3] && sum0[3] > sum2[3]) begin
        out = 3'b000; // Majority vote for bit 0
    end else if (sum1[3] > sum0[3] && sum1[3] > sum2[3]) begin
        out = 3'b001; // Majority vote for bit 1
    end else if (sum2[3] > sum0[3] && sum2[3] > sum1[3]) begin
        out = 3'b010; // Majority vote for bit 2
    end else begin
        out = 3'b111; // Error: no clear majority
    end
end

endmodule

module soc_system_mm_interconnect_4_cmd_mux_002
(
    input                       sink0_valid,
    input [128: 0]  sink0_data,
    input [10: 0]  sink0_channel,
    input                       sink0_startofpacket,
    input                       sink0_endofpacket,
    output                      sink0_ready,

    input                       sink1_valid,
    input [128: 0]  sink1_data,
    input [10: 0]  sink1_channel,
    input                       sink1_startofpacket,
    input                       sink1_endofpacket,
    output                      sink1_ready,

    output                      src_valid,
    output [128: 0] src_data,
    output [10: 0] src_channel,
    output                      src_startofpacket,
    output                      src_endofpacket,
    input                       src_ready,

    input clk,
    input reset
);

    // Internal signals
    reg [1:0] current_grant;
    reg [1:0] next_grant;
    reg [1:0] grant_counter;
    reg [128: 0] payload_data;
    reg [10: 0] payload_channel;
    reg payload_startofpacket;
    reg payload_endofpacket;
    reg payload_valid;
    reg [1:0] payload_source;

    // State encoding
    // 00: Idle
    // 01: Processing sink0
    // 10: Processing sink1
    // 11: Transition state

    // Combinational logic for next grant determination
    always @(*) begin
        case (current_grant)
            2'b00: next_grant = 2'b01; // Start with sink0
            2'b01: next_grant = 2'b10; // Then sink1
            2'b10: next_grant = 2'b01; // Back to sink0
            2'b11: next_grant = 2'b01; // Transition to sink0
        endcase
    end

    // Sequential logic for grant and payload management
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_grant <= 2'b00;
            grant_counter <= 2'b00;
            payload_valid <= 1'b0;
            sink0_ready <= 1'b1;
            sink1_ready <= 1'b1;
        end else begin
            // Update grant based on counter
            if (grant_counter == 2'b11) begin
                current_grant <= next_grant;
                grant_counter <= 2'b00;
            end else begin
                grant_counter <= grant_counter + 1;
            end

            // Handle payload transfer
            if (payload_valid && src_ready) begin
                payload_valid <= 1'b0;
            end

            // Source ready signals
            sink0_ready <= (current_grant == 2'b01) && !payload_valid;
            sink1_ready <= (current_grant == 2'b10) && !payload_valid;

            // Load new payload
            if (sink0_valid && sink0_ready) begin
                payload_data <= sink0_data;
                payload_channel <= sink0_channel;
                payload_startofpacket <= sink0_startofpacket;
                payload_endofpacket <= sink0_endofpacket;
                payload_valid <= 1'b1;
                payload_source <= 2'b01;
            end else if (sink1_valid && sink1_ready) begin
                payload_data <= sink1_data;
                payload_channel <= sink1_channel;
                payload_startofpacket <= sink1_startofpacket;
                payload_endofpacket <= sink1_endofpacket;
                payload_valid <= 1'b1;
                payload_source <= 2'b10;
            end
        end
    end

    // Output assignments
    assign src_valid = payload_valid;
    assign src_data = payload_data;
    assign src_channel = payload_channel;
    assign src_startofpacket = payload_startofpacket;
    assign src_endofpacket = payload_endofpacket;

endmodule

module file_writer(
  input     clk,
  input     rst,
  input     [63:0] input_a,
  input     input_a_stb,
  output    input_a_ack
);

  // Internal signals
  reg [1:0] state;
  reg [63:0] value;
  reg s_input_a_ack;
  integer file_handle;

  // Output assignment
  assign input_a_ack = s_input_a_ack;

  // State definitions
  parameter IDLE = 2'b00;
  parameter WRITE = 2'b01;

  // FSM logic
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= IDLE;
      s_input_a_ack <= 0;
      file_handle = 0;
    end else begin
      case (state)
        IDLE: begin
          if (input_a_stb) begin
            value <= input_a;
            s_input_a_ack <= 1;
            state <= WRITE;
          end else begin
            s_input_a_ack <= 0;
          end
        end
        WRITE: begin
          if (file_handle == 0) begin
            file_handle = $fopena("resp_z", "a");
          end
          $fdisplay(file_handle, "%h %h", value[63:32], value[31:0]);
          $fclose(file_handle);
          file_handle = 0;
          state <= IDLE;
        end
        default: state <= IDLE;
      endcase
    end
  end

endmodule

module DT_16_16_28_approx_fa_21_174(IN1, IN2, Out);
    input [15:0] IN1;
    input [15:0] IN2;
    output [31:0] Out;

    // Internal signals
    wire [27:0] partial_products [0:15];
    wire [29:0] sum_stage;
    wire [31:0] refined_result;

    // First stage: Generate partial products
    genvar i;
    generate
        for (i = 0; i < 16; i = i + 1) begin : gen_partial_products
            U_SP_16_16 pp (
                .A(IN1[i]),
                .B(IN2),
                .P(partial_products[i])
            );
        end
    endgenerate

    // Second stage: Sum the partial products
    DT sum (
        .PP(partial_products),
        .Sum(sum_stage)
    );

    // Third stage: Refine the result
    RC_30_30 refine (
        .In(sum_stage),
        .Out(refined_result)
    );

    // Assign the final result to the output
    assign Out = refined_result;

endmodule

