module CIRCUIT2(a, b, c, x, z, Clk, Rst);
    input [31:0] a, b, c;
    input Clk, Rst;
    output [31:0] x, z;

    // Internal signals
    reg [31:0] sum_ab, sum_ac, diff_ab;
    reg [31:0] mux_out_x, mux_out_z;
    reg [31:0] shift_left, shift_right;
    reg [31:0] reg_x, reg_z;

    // Comparator signals
    wire cmp_ab_ac, cmp_ab_diff;

    // Adders
    assign sum_ab = a + b;
    assign sum_ac = a + c;
    assign diff_ab = a - b;

    // Comparators
    assign cmp_ab_ac = (sum_ab > sum_ac);
    assign cmp_ab_diff = (sum_ab > diff_ab);

    // Multiplexers
    assign mux_out_x = cmp_ab_ac ? sum_ab : diff_ab;
    assign mux_out_z = cmp_ab_diff ? sum_ac : diff_ab;

    // Shifters
    assign shift_left = mux_out_x << 1;
    assign shift_right = mux_out_z >> 1;

    // Registers
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            reg_x <= 32'b0;
            reg_z <= 32'b0;
        end else begin
            reg_x <= shift_left;
            reg_z <= shift_right;
        end
    end

    // Output assignments
    assign x = reg_x;
    assign z = reg_z;

endmodule

