module pre_norm_fmul(clk, fpu_op, opa, opb, fracta, fractb, exp_out, sign,
                     sign_exe, inf, exp_ovf, underflow);
    input clk;
    input [2:0] fpu_op;
    input [31:0] opa, opb;
    output [23:0] fracta, fractb;
    output [7:0] exp_out;
    output sign, sign_exe;
    output inf;
    output [1:0] exp_ovf;
    output [2:0] underflow;

    // Internal signals
    reg [23:0] fracta_reg, fractb_reg;
    reg [7:0] expa, expb, exp_out_reg;
    reg signa, signb, sign_reg, sign_exe_reg;
    reg inf_reg;
    reg [1:0] exp_ovf_reg;
    reg [2:0] underflow_reg;

    // Extract sign, exponent, and fraction from input operands
    always @(*) begin
        signa = opa[31];
        expa = opa[30:23];
        fracta = {opa[22:0], 1'b0}; // Normalize the fraction by adding an implicit 1

        signb = opb[31];
        expb = opb[30:23];
        fractb = {opb[22:0], 1'b0}; // Normalize the fraction by adding an implicit 1
    end

    // Determine the sign of the result
    always @(*) begin
        if (fpu_op == 3'b000) // Multiplication
            sign_exe = signa ^ signb;
        else // Division
            sign_exe = signa ^ signb;
    end

    // Calculate the exponent of the result
    always @(*) begin
        exp_out = expa + expb - 127; // Subtract 127 to account for bias
    end

    // Handle overflow and underflow conditions
    always @(*) begin
        if (exp_out > 254) begin
            exp_ovf = 2'b11; // Exponent overflow
            inf_reg = 1'b1; // Result is infinity
        end else if (exp_out < 0) begin
            exp_ovf = 2'b00; // No overflow
            underflow_reg = 3'b111; // Underflow
        end else begin
            exp_ovf = 2'b00; // No overflow
            underflow_reg = 3'b000; // No underflow
        end
    end

    // Register outputs on the positive edge of the clock
    always @(posedge clk) begin
        fracta_reg <= fracta;
        fractb_reg <= fractb;
        exp_out_reg <= exp_out;
        sign_reg <= sign_exe;
        inf_reg <= inf;
        exp_ovf_reg <= exp_ovf;
        underflow_reg <= underflow;
    end

    // Assign registered outputs to module outputs
    assign fracta = fracta_reg;
    assign fractb = fractb_reg;
    assign exp_out = exp_out_reg;
    assign sign = sign_reg;
    assign sign_exe = sign_exe_reg;
    assign inf = inf_reg;
    assign exp_ovf = exp_ovf_reg;
    assign underflow = underflow_reg;
endmodule

module HWORD (
    input CLK,
    input WE,
    input SELW,
    input SELR,
    input [15:0] Di,
    output [15:0] Do
);

    // Internal register to store data
    reg [15:0] data_reg;

    // Gated clock signal
    wire GCLK = WE & SELW;

    // Sequential logic to store data
    always @(posedge GCLK or negedge CLK) begin
        if (!CLK) begin
            // Asynchronous reset on falling edge of CLK
            data_reg <= 16'b0;
        end else if (GCLK) begin
            // Write data on rising edge of GCLK
            data_reg <= Di;
        end
    end

    // Tri-state buffer for output
    assign Do = SELR ? data_reg : 16'bz;

endmodule

module FPAddSub_reduced(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    input operation,
    output [31:0] result,
    output [4:0] flags
);

    // Internal signals for pipeline stages
    reg [31:0] pipe_1;
    reg [31:0] pipe_2;
    reg [31:0] pipe_3;

    // Internal signals for each stage
    reg [31:0] sign_exp_stage;
    reg [31:0] mantissa_stage;
    reg [31:0] normalize_stage;
    reg [31:0] result_stage;
    reg [4:0] flags_stage;

    // Stage 1: Sign and Exponent Processing
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            pipe_1 <= 32'b0;
        end else begin
            // Extract sign, exponent, and mantissa
            reg [31:0] a_sign = a[31];
            reg [31:0] a_exp = a[30:23];
            reg [31:0] a_mant = {1'b1, a[22:0]};
            reg [31:0] b_sign = b[31];
            reg [31:0] b_exp = b[30:23];
            reg [31:0] b_mant = {1'b1, b[22:0]};

            // Determine the larger exponent
            reg [31:0] exp_diff = a_exp - b_exp;
            reg [31:0] larger_exp = (exp_diff[31] == 1'b0) ? a_exp : b_exp;
            reg [31:0] smaller_exp = (exp_diff[31] == 1'b0) ? b_exp : a_exp;
            reg [31:0] smaller_mant = (exp_diff[31] == 1'b0) ? b_mant : a_mant;

            // Align the smaller mantissa
            reg [31:0] align_shift = larger_exp - smaller_exp;
            reg [31:0] aligned_mant = smaller_mant >> align_shift;

            // Determine the operation (add or subtract)
            reg [31:0] mant_op = (operation == 1'b0) ? aligned_mant : ~aligned_mant + 1;

            // Store intermediate result
            pipe_1 <= {a_sign, larger_exp, mant_op};
        end
    end

    // Stage 2: Mantissa Addition
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            pipe_2 <= 32'b0;
        end else begin
            // Extract sign, exponent, and mantissa from pipe_1
            reg [31:0] sign = pipe_1[31];
            reg [31:0] exp = pipe_1[30:23];
            reg [31:0] mant = pipe_1[22:0];

            // Add the mantissas
            reg [32:0] mant_sum = mant + pipe_1[22:0];

            // Store intermediate result
            pipe_2 <= {sign, exp, mant_sum};
        end
    end

    // Stage 3: Normalization
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            pipe_3 <= 32'b0;
        end else begin
            // Extract sign, exponent, and mantissa from pipe_2
            reg [31:0] sign = pipe_2[31];
            reg [31:0] exp = pipe_2[30:23];
            reg [32:0] mant = pipe_2[22:0];

            // Normalize the mantissa
            reg [31:0] norm_mant = mant;
            reg [31:0] norm_exp = exp;
            reg [31:0] shift_count = 0;

            while (norm_mant[31] == 1'b0) begin
                norm_mant = norm_mant << 1;
                shift_count = shift_count + 1;
            end

            norm_exp = exp - shift_count;

            // Store intermediate result
            pipe_3 <= {sign, norm_exp, norm_mant[22:0]};
        end
    end

    // Stage 4: Result Packaging and Flags
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result <= 32'b0;
            flags <= 5'b0;
        end else begin
            // Extract sign, exponent, and mantissa from pipe_3
            reg [31:0] sign = pipe_3[31];
            reg [31:0] exp = pipe_3[30:23];
            reg [31:0] mant = pipe_3[22:0];

            // Determine flags
            reg [4:0] flags_temp = 5'b0;
            if (exp == 255) begin
                flags_temp[0] = 1'b1; // Overflow
            end else if (exp == 0) begin
                flags_temp[1] = 1'b1; // Underflow
            end

            // Package the result
            result <= {sign, exp, mant};
            flags <= flags_temp;
        end
    end

endmodule

