module FPAddSub_d(
    ZeroSum,
    NormE,
    NormM,
    R,
    S,
    G,
    Sa,
    Sb,
    Ctrl,
    MaxAB,
    NegE,
    InputExc,
    P,
    Flags
);

    input ZeroSum;                     // Zero sum flag
    input [8:0] NormE;                 // Normalized exponent
    input [22:0] NormM;                // Normalized mantissa
    input R;                           // Rounding control
    input S;                           // Sticky bit
    input G;                           // Guard bit
    input Sa;                          // Sign of operand A
    input Sb;                          // Sign of operand B
    input Ctrl;                        // Control signal for addition/subtraction
    input MaxAB;                       // Maximum of A and B
    input NegE;                        // Negative exponent flag
    input [4:0] InputExc;              // Input exception flags

    output [31:0] P;                   // Result
    output [4:0] Flags;                // Flags for overflow, underflow, etc.

    // Internal signals
    reg [8:0] ExpDiff;
    reg [23:0] MantissaSum;
    reg [23:0] MantissaA, MantissaB;
    reg [8:0] ResultExp;
    reg [22:0] ResultMant;
    reg ResultSign;
    reg Overflow, Underflow, DivideByZero, InvalidOp, Inexact;

    // Calculate exponent difference
    assign ExpDiff = NormE - NormM;

    // Determine mantissas
    assign MantissaA = {1'b1, NormM};
    assign MantissaB = {1'b1, NormM};

    // Perform addition or subtraction
    always @(Ctrl, MantissaA, MantissaB, ExpDiff) begin
        if (Ctrl) begin
            // Addition
            MantissaSum = MantissaA + MantissaB;
        end else begin
            // Subtraction
            MantissaSum = MantissaA - MantissaB;
        end
    end

    // Normalize result
    always @(MantissaSum, ExpDiff) begin
        if (MantissaSum[23]) begin
            ResultMant = MantissaSum[22:0];
            ResultExp = NormE;
        end else begin
            ResultMant = {1'b1, MantissaSum[21:0]};
            ResultExp = NormE - 1;
        end
    end

    // Determine result sign
    assign ResultSign = (Ctrl) ? (Sa & Sb) : (Sa ^ Sb);

    // Exception handling
    always @(InputExc, MantissaSum, ExpDiff) begin
        Overflow = (ExpDiff > 127) ? 1'b1 : 1'b0;
        Underflow = (ExpDiff < -126) ? 1'b1 : 1'b0;
        DivideByZero = (InputExc[0]) ? 1'b1 : 1'b0;
        InvalidOp = (InputExc[1]) ? 1'b1 : 1'b0;
        Inexact = (R | S | G) ? 1'b1 : 1'b0;
    end

    // Construct result
    assign P = {ResultSign, ResultExp, ResultMant};

    // Set flags
    assign Flags = {Overflow, Underflow, DivideByZero, InvalidOp, Inexact};

endmodule

