module top(
    input wire clk,
    input wire [2:0] sel_i,
    input wire [7:0] data_in_i,
    input wire write_i,
    output wire [10:0] data_out_o
);

    // Internal registers
    reg [7:0] regA, regB, regC, regD, regE, regF, regG, regH;

    // Initialize registers to zero
    initial begin
        regA = 8'b0;
        regB = 8'b0;
        regC = 8'b0;
        regD = 8'b0;
        regE = 8'b0;
        regF = 8'b0;
        regG = 8'b0;
        regH = 8'b0;
    end

    // Register update logic
    always @(posedge clk) begin
        if (write_i) begin
            case (sel_i)
                3'b000: regA <= data_in_i;
                3'b001: regB <= data_in_i;
                3'b010: regC <= data_in_i;
                3'b011: regD <= data_in_i;
                3'b100: regE <= data_in_i;
                3'b101: regF <= data_in_i;
                3'b110: regG <= data_in_i;
                3'b111: regH <= data_in_i;
                default: ; // No action for invalid sel_i
            endcase
        end
    end

    // Instance of the adder module
    wire [10:0] sum;
    adder_seq adder_inst (
        .a_i(regA),
        .b_i(regB),
        .c_i(regC),
        .d_i(regD),
        .e_i(regE),
        .f_i(regF),
        .g_i(regG),
        .h_i(regH),
        .sum_o(sum)
    );

    // Assign the sum to the output
    assign data_out_o = sum;

endmodule

