module vCounter4DigitBCD(
    input clk,
    output reg [15:0] count,
    input enable,
    output reg cout,
    input grst
);

    // Parameters for the number of digits and bits per digit
    parameter NUM_DIGITS = 4;
    parameter BITS_PER_DIGIT = 4;

    // Internal signals for each digit's count and carry-out
    reg [BITS_PER_DIGIT-1:0] digit [0:NUM_DIGITS-1];
    wire rco0, rco1, rco2, rco3;

    // Instantiate four BCD counters
    genvar i;
    generate
        for (i = 0; i < NUM_DIGITS; i = i + 1) begin : bcd_counters
            if (i == 0) begin
                // First digit, no carry-in
                bcd_counter bcd_inst (
                    .clk(clk),
                    .enable(enable),
                    .reset(grst),
                    .count(digit[i]),
                    .carryout(rco0)
                );
            end else begin
                // Subsequent digits, carry-in from previous digit's carry-out
                bcd_counter bcd_inst (
                    .clk(clk),
                    .enable(rco0),
                    .reset(grst),
                    .count(digit[i]),
                    .carryout(rco0)
                );
            end
        end
    endgenerate

    // Assign the final count by concatenating all digits
    always @(*) begin
        count = {digit[3], digit[2], digit[1], digit[0]};
    end

    // Assign the carry-out to the last digit's carry-out
    assign cout = rco3;

endmodule

// Submodule for a single BCD counter
module bcd_counter(
    input clk,
    input enable,
    input reset,
    output reg [3:0] count,
    output reg carryout
);

    // Sequential logic for the BCD counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
            carryout <= 1'b0;
        end else if (enable) begin
            if (count == 4'b1001) begin
                count <= 4'b0000;
                carryout <= 1'b1;
            end else begin
                count <= count + 1;
                carryout <= 1'b0;
            end
        end
    end

endmodule

