module full_adder (i_a, i_b, i_carry, o_sum, o_carry);
 input [1:0] i_a;
 input [1:0] i_b;
 input i_carry;
 output [1:0] o_sum;
 output o_carry;

 // Internal wires for intermediate calculations
 wire carry_0;
 wire carry_1;

 // Lower bit (bit 0) calculations
 assign o_sum[0] = i_a[0] ^ i_b[0] ^ i_carry;
 assign carry_0 = (i_a[0] & i_b[0]) | (i_a[0] & i_carry) | (i_b[0] & i_carry);

 // Higher bit (bit 1) calculations
 assign o_sum[1] = i_a[1] ^ i_b[1] ^ carry_0;
 assign carry_1 = (i_a[1] & i_b[1]) | (i_a[1] & carry_0) | (i_b[1] & carry_0);

 // Final carry-out
 assign o_carry = carry_1;

endmodule

