module registers(clk, read1, read2, data1, data2, regwrite, wrreg, wrdata, rst, of_control);
    input clk, rst;
    input [1:0] of_control;
    input [4:0] read1, read2;
    output [31:0] data1, data2;
    input regwrite;
    input [4:0] wrreg;
    input [31:0] wrdata;

    reg [31:0] registers [0:31];
    reg [31:0] read_data1, read_data2;

    // Initialize registers to zero on reset
    always @(posedge rst) begin
        for (int i = 0; i < 32; i = i + 1) begin
            registers[i] <= 32'b0;
        end
    end

    // Combinational logic for read operations
    always @(*) begin
        read_data1 = (read1 == 5'b0) ? 32'b0 : registers[read1];
        read_data2 = (read2 == 5'b0) ? 32'b0 : registers[read2];
    end

    // Sequential logic for write operations
    always @(negedge clk or posedge rst) begin
        if (rst) begin
            for (int i = 0; i < 32; i = i + 1) begin
                registers[i] <= 32'b0;
            end
        end else if (regwrite && wrreg != 5'b0) begin
            // Write bypassing and overflow control
            if (of_control == 2'b00) begin
                registers[wrreg] <= wrdata;
            end else if (of_control == 2'b01) begin
                registers[wrreg] <= wrdata[30:0] << 1;
            end else if (of_control == 2'b10) begin
                registers[wrreg] <= wrdata[30:0] >> 1;
            end else if (of_control == 2'b11) begin
                registers[wrreg] <= wrdata[30:0] + 1;
            end
        end
    end

    // Assign output data
    assign data1 = read_data1;
    assign data2 = read_data2;
endmodule

module gng_smul_16_18 (
    input clk,                   // Clock signal
    input [15:0] a,              // 16-bit signed input
    input [17:0] b,              // 18-bit signed input
    output [33:0] p              // 34-bit signed product
);

    // Registers to latch input values
    reg [15:0] a_reg;
    reg [17:0] b_reg;

    // Register to store the product
    reg [33:0] prod;

    // Latch inputs on the positive edge of the clock
    always @(posedge clk) begin
        a_reg <= a;
        b_reg <= b;
    end

    // Compute the product and assign it to the output
    always @(posedge clk) begin
        prod <= a_reg * b_reg;
        p <= prod;
    end

endmodule

module addmuland_1_stage_signed_14_bit(
	input signed [13:0] a,
	input signed [13:0] b,
	input signed [13:0] c,
	input signed [13:0] d,
	output [13:0] out,
	input clk);

	// Internal 28-bit register to store intermediate results
	reg signed [27:0] intermediate_result;

	// Combinational logic for the arithmetic and logical operations
	always @(*) begin
		// Step 1: Add inputs a and b
		signed [13:0] sum = a + b;

		// Step 2: Multiply the sum by input c
		signed [27:0] product = sum * c;

		// Step 3: Perform bitwise AND with input d
		signed [13:0] result = product & d;

		// Assign the result to the intermediate register
		intermediate_result = product;
		out = result;
	end

	// Sequential logic to update the output on the clock edge
	always @(posedge clk) begin
		out <= intermediate_result[13:0];
	end

endmodule

module tb_ALU();
    // Parameters
    parameter CLK_PERIOD = 10;
    parameter RESET_ASSERT_TIME = 27;
    parameter TEST_VECTOR_SIZE = 27;
    parameter NUM_TEST_VECTORS = 10001;

    // Inputs
    reg clk;
    reg reset;
    reg [TEST_VECTOR_SIZE-1:0] testvectors [0:NUM_TEST_VECTORS-1];

    // Outputs
    wire [31:0] Result;
    wire zeroflag;
    reg error;

    // ALU instance
    ALU uut (
        .clk(clk),
        .reset(reset),
        .A(testvectors[0][26:19]),
        .B(testvectors[0][18:11]),
        .ALUControl(testvectors[0][10:8]),
        .Result(Result),
        .Zero(zeroflag)
    );

    // Clock generation
    always begin
        #CLK_PERIOD / 2 clk = ~clk;
    end

    // Testbench process
    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        error = 0;

        // Read test vectors from file
        $readmemh("testvectors.mem", testvectors);

        // Apply reset
        #RESET_ASSERT_TIME reset = 0;

        // Iterate through test vectors
        for (int i = 0; i < NUM_TEST_VECTORS; i = i + 1) begin
            // Apply inputs
            uut.A = testvectors[i][26:19];
            uut.B = testvectors[i][18:11];
            uut.ALUControl = testvectors[i][10:8];

            // Wait for one clock cycle
            #CLK_PERIOD;

            // Check outputs
            if (Result !== testvectors[i][31:0]) begin
                $display("Error at test vector %d: Expected %h, got %h", i, testvectors[i][31:0], Result);
                error = 1;
            end
            if (zeroflag !== testvectors[i][32]) begin
                $display("Error at test vector %d: Zero flag mismatch", i);
                error = 1;
            end
        end

        // Report results
        if (error) begin
            $display("Testbench completed with errors.");
        end else begin
            $display("All tests passed successfully.");
        end

        // Finish simulation
        $finish;
    end
endmodule

