module add_saturate(
    input wire [15:0] a_i,
    input wire [15:0] b_i,
    output wire [15:0] s_o
);

    // Internal 17-bit wire to store the extended sum
    wire [16:0] ext_sum;

    // Sign-extend the inputs to 17 bits
    wire [16:0] ext_a = {a_i[15], a_i};
    wire [16:0] ext_b = {b_i[15], b_i};

    // Perform the addition
    assign ext_sum = ext_a + ext_b;

    // Apply saturation logic
    assign s_o = (ext_sum > 16'h7FFF) ? 16'h7FFF : // Clamp to 32767 if overflow
                 (ext_sum < 16'h8000) ? 16'h8000 : // Clamp to -32768 if underflow
                 ext_sum[15:0]; // Otherwise, take the lower 16 bits

endmodule

module memArray16_73814 #(
    parameter width = 32,
    parameter logDepth = 10,
    parameter numBanks = 8
)(
    input     clk, next, reset,
    input    inFlip, outFlip,

    input [width-1:0]   x0,
    output [width-1:0]  y0,
    input [logDepth-1:0] inAddr0, outAddr0,
    input [width-1:0]   x1,
    output [width-1:0]  y1,
    input [logDepth-1:0] inAddr1, outAddr1,
    input [width-1:0]   x2,
    output [width-1:0]  y2,
    input [logDepth-1:0] inAddr2, outAddr2,
    input [width-1:0]   x3,
    output [width-1:0]  y3,
    input [logDepth-1:0] inAddr3, outAddr3,
    input [width-1:0]   x4,
    output [width-1:0]  y4,
    input [logDepth-1:0] inAddr4, outAddr4,
    input [width-1:0]   x5,
    output [width-1:0]  y5,
    input [logDepth-1:0] inAddr5, outAddr5,
    input [width-1:0]   x6,
    output [width-1:0]  y6,
    input [logDepth-1:0] inAddr6, outAddr6,
    input [width-1:0]   x7,
    output [width-1:0]  y7,
    input [logDepth-1:0] inAddr7, outAddr7
);

    // Memory module instance
    module memMod (
        input clk, reset,
        input [width-1:0] dataIn,
        input [logDepth-1:0] addr,
        output [width-1:0] dataOut
    );
        reg [width-1:0] mem [0:(1<<logDepth)-1];
        reg [width-1:0] dataOutReg;

        always @(posedge clk or posedge reset) begin
            if (reset) begin
                dataOutReg <= 0;
            end else begin
                mem[addr] <= dataIn;
                dataOutReg <= mem[addr];
            end
        end

        assign dataOut = dataOutReg;
    endmodule

    // Instantiate memory banks
    genvar i;
    generate
        for (i = 0; i < numBanks; i = i + 1) begin : bank_gen
            memMod bank (
                .clk(clk),
                .reset(reset),
                .dataIn((i == 0) ? x0 : (i == 1) ? x1 : (i == 2) ? x2 : (i == 3) ? x3 : (i == 4) ? x4 : (i == 5) ? x5 : (i == 6) ? x6 : x7),
                .addr((i == 0) ? inAddr0 : (i == 1) ? inAddr1 : (i == 2) ? inAddr2 : (i == 3) ? inAddr3 : (i == 4) ? inAddr4 : (i == 5) ? inAddr5 : (i == 6) ? inAddr6 : inAddr7),
                .dataOut((i == 0) ? y0 : (i == 1) ? y1 : (i == 2) ? y2 : (i == 3) ? y3 : (i == 4) ? y4 : (i == 5) ? y5 : (i == 6) ? y6 : y7)
            );
        end
    endgenerate

    // FIFO for managing timing and flow control
    reg [numBanks-1:0] fifo;
    reg [numBanks-1:0] fifoNext;
    reg fifoFull, fifoEmpty;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fifo <= 0;
            fifoFull <= 0;
            fifoEmpty <= 1;
        end else begin
            if (next && !fifoFull) begin
                fifoNext = fifo << 1;
                fifoNext[0] = 1;
                fifo <= fifoNext;
                fifoEmpty <= 0;
                if (fifoNext == (1 << numBanks) - 1) begin
                    fifoFull <= 1;
                end
            end else if (next && fifoFull) begin
                fifo <= fifoNext;
            end
        end
    end

endmodule

module bsg_two_fifo_width_p620
(
  clk_i,
  reset_i,
  ready_o,
  data_i,
  v_i,
  v_o,
  data_o,
  yumi_i
);
  parameter DEPTH = 16; // Example depth, can be adjusted
  parameter WIDTH = 620;

  input [WIDTH-1:0] data_i;
  output [WIDTH-1:0] data_o;
  input clk_i;
  input reset_i;
  input v_i;
  input yumi_i;
  output ready_o;
  output v_o;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [3:0] w_ptr, r_ptr;
  reg full, empty;

  always @(posedge clk_i or posedge reset_i) begin
    if (reset_i) begin
      w_ptr <= 0;
      r_ptr <= 0;
      full <= 0;
      empty <= 1;
    end else begin
      if (v_i && !full) begin
        mem[w_ptr] <= data_i;
        w_ptr <= (w_ptr + 1) % DEPTH;
        if (w_ptr == r_ptr)
          full <= 1;
        empty <= 0;
      end

      if (yumi_i && !empty) begin
        r_ptr <= (r_ptr + 1) % DEPTH;
        if (w_ptr == r_ptr)
          empty <= 1;
        full <= 0;
      end
    end
  end

  always @(posedge clk_i) begin
    if (reset_i) begin
      data_o <= 0;
      v_o <= 0;
    end else begin
      if (!empty)
        data_o <= mem[r_ptr];
      v_o <= !empty;
    end
  end

  assign ready_o = !full;

endmodule

module ACCUM (
