  reg [15:0] S_reg;

  // Always block for sequential logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      S_reg <= 16'b0;
    end else if (clear) begin
      S_reg <= 16'b0;
    end else begin
      S_reg <= S_reg + W;
    end
  end

  // Assign the output S to the internal register
  assign S = S_reg;

  // Scan chain logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      scan_out0 <= 1'b0;
      scan_out1 <= 1'b0;
      scan_out2 <= 1'b0;
      scan_out3 <= 1'b0;
      scan_out4 <= 1'b0;
    end else if (scan_enable) begin
      scan_out0 <= scan_in0;
      scan_out1 <= scan_in1;
      scan_out2 <= scan_in2;
      scan_out3 <= scan_in3;
      scan_out4 <= scan_in4;
    end else if (test_mode) begin
      scan_out0 <= S_reg[0];
      scan_out1 <= S_reg[1];
      scan_out2 <= S_reg[2];
      scan_out3 <= S_reg[3];
      scan_out4 <= S_reg[4];
    end
  end

