module BaudTickGen(
	input clk, enable,
	output tick  
);

	parameter ClkFrequency = 50000000; // Example clock frequency in Hz
	parameter Baud = 9600; // Example baud rate in bps
	parameter Oversampling = 16; // Example oversampling factor

	// Calculate the number of bits needed for the accumulator
	localparam AccWidth = $clog2(ClkFrequency / (Baud * Oversampling));

	// Internal registers and wires
	reg [AccWidth-1:0] Acc;
	wire [AccWidth-1:0] Inc;

	// Calculate the increment value
	assign Inc = ClkFrequency / (Baud * Oversampling);

	// Sequential logic
	always @(posedge clk) begin
		if (!enable) begin
			// Reset the accumulator if enable is low
			Acc <= 0;
		end else begin
			// Update the accumulator
			Acc <= Acc + Inc;
		end
	end

	// Output logic
	assign tick = Acc[AccWidth-1]; // Tick when the most significant bit overflows

endmodule

