module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);

    // Parameters for VGA timing
    parameter H_TOTAL = 800;          // Total number of columns in a frame
    parameter H_ACTIVE = 640;        // Active display area in columns
    parameter H_SYNC_START = 656;    // Horizontal sync start
    parameter H_SYNC_END = 752;      // Horizontal sync end
    parameter V_TOTAL = 525;          // Total number of rows in a frame
    parameter V_ACTIVE = 480;        // Active display area in rows
    parameter V_SYNC_START = 490;    // Vertical sync start
    parameter V_SYNC_END = 492;      // Vertical sync end

    // Internal signals
    reg hsync_int;
    reg vsync_int;

    // Horizontal synchronization pulse generation
    always @(posedge i_clk) begin
        if (o_col_count == H_TOTAL - 1) begin
            o_col_count <= 0;
        end else begin
            o_col_count <= o_col_count + 1;
        end

        if (o_col_count >= H_SYNC_START && o_col_count < H_SYNC_END) begin
            hsync_int <= 1'b0;  // Hsync active low
        end else begin
            hsync_int <= 1'b1;
        end
    end

    // Vertical synchronization pulse generation
    always @(posedge i_clk) begin
        if (o_col_count == 0) begin
            if (o_row_count == V_TOTAL - 1) begin
                o_row_count <= 0;
            end else begin
                o_row_count <= o_row_count + 1;
            end
        end

        if (o_row_count >= V_SYNC_START && o_row_count < V_SYNC_END) begin
            vsync_int <= 1'b0;  // Vsync active low
        end else begin
            vsync_int <= 1'b1;
        end
    end

    // Assign output signals
    assign o_hsync = hsync_int;
    assign o_vsync = vsync_int;

endmodule

