    reg [31:0] cpu_data_rdata_reg;

    // Sequential logic for selection
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            sel_sram <= 1'b0;
            sel_conf <= 1'b0;
        end else begin
            if (cpu_data_addr >= CONF_ADDR_BASE && cpu_data_addr < CONF_ADDR_BASE + CONF_ADDR_MASK) begin
                sel_sram <= 1'b0;
                sel_conf <= 1'b1;
            end else begin
                sel_sram <= 1'b1;
                sel_conf <= 1'b0;
            end
        end
    end

    // Output assignments
    assign data_sram_en = cpu_data_en & sel_sram;
    assign data_sram_wen = cpu_data_wen & sel_sram;
    assign data_sram_addr = cpu_data_addr & {32{sel_sram}};
    assign data_sram_wdata = cpu_data_wdata;

