    assign conf_wen = cpu_data_wen & sel_conf;
    assign conf_addr = cpu_data_addr & {32{sel_conf}};
    assign conf_wdata = cpu_data_wdata;

    // Read data multiplexing
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            cpu_data_rdata_reg <= 32'h0;
        end else begin
            if (sel_sram) begin
                cpu_data_rdata_reg <= data_sram_rdata;
            end else if (sel_conf) begin
                cpu_data_rdata_reg <= conf_rdata;
            end
        end
    end

    assign cpu_data_rdata = cpu_data_rdata_reg;

endmodule

module table_011101010(input clk, input rst, input [7:0] addr, output reg match);
    // Define the specific value to compare against
    localparam [7:0] COMPARE_VALUE = 8'h74; // 01110100 in hexadecimal

    // Synchronous process triggered by the positive edge of the clock
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // If reset is high, clear the match signal
            match <= 1'b0;
        end else begin
            // Compare the address with the specific value
            if (addr == COMPARE_VALUE) begin
                // If they match, set the match signal to 1
                match <= 1'b1;
            end else begin
                // Otherwise, set the match signal to 0
                match <= 1'b0;
            end
        end
    end
endmodule

module rggen_apb_bridge #(
  parameter ADDRESS_WIDTH = 8,
  parameter BUS_WIDTH     = 32
)(
  input                             i_clk,
  input                             i_rst_n,
  input                             i_bus_valid,
  input   [1:0]                     i_bus_access,
  input   [ADDRESS_WIDTH-1:0]       i_bus_address,
  input   [BUS_WIDTH-1:0]           i_bus_write_data,
  input   [BUS_WIDTH/8-1:0]         i_bus_strobe,
  output                            o_bus_ready,
  output  [1:0]                     o_bus_status,
  output  [BUS_WIDTH-1:0]           o_bus_read_data,
  output                            o_psel,
  output                            o_penable,
  output  [ADDRESS_WIDTH-1:0]       o_paddr,
  output  [2:0]                     o_pprot,
  output                            o_pwrite,
  output  [BUS_WIDTH/8-1:0]         o_pstrb,
  output  [BUS_WIDTH-1:0]           o_pwdata,
  input                             i_pready,
  input   [BUS_WIDTH-1:0]           i_prdata,
  input                             i_pslverr
);

  // State encoding
  typedef enum logic [1:0] {
    IDLE,
    ACCESS,
    WAIT
  } state_t;

  state_t state, next_state;

  // Internal registers
  logic busy;
  logic [1:0] access_type;
  logic [ADDRESS_WIDTH-1:0] address;
  logic [BUS_WIDTH-1:0] write_data;
  logic [BUS_WIDTH/8-1:0] strobe;

  // Control signals
  logic psel;
  logic penable;
  logic pwrite;
  logic [2:0] pprot;

  // Intermediate signals
  logic bus_ready;
  logic [1:0] bus_status;
  logic [BUS_WIDTH-1:0] bus_read_data;

  // State transition logic
  always_ff @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
      state <= IDLE;
      busy <= 0;
    end else begin
      state <= next_state;
      case (next_state)
        IDLE: busy <= 0;
        ACCESS: busy <= 1;
        WAIT: busy <= 1;
        default: busy <= busy;
      endcase
    end
  end

  // Next state logic
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (i_bus_valid) begin
          next_state = ACCESS;
        end
      end
      ACCESS: begin
        if (i_pready) begin
          next_state = WAIT;
        end
      end
      WAIT: begin
        if (i_pready) begin
          next_state = IDLE;
        end
      end
    endcase
  end

  // Output assignments
  assign o_bus_ready = !busy;
  assign o_bus_status = i_pslverr ? 2'b10 : (i_pready ? 2'b01 : 2'b00);
  assign o_bus_read_data = i_prdata;

  assign o_psel = busy;
  assign o_penable = busy;
  assign o_paddr = address;
  assign o_pprot = 3'b000;
  assign o_pwrite = access_type;
  assign o_pstrb = strobe;
  assign o_pwdata = write_data;

  // Input assignments
  always_ff @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
      access_type <= 2'b00;
      address <= {ADDRESS_WIDTH{1'b0}};
      write_data <= {BUS_WIDTH{1'b0}};
      strobe <= {BUS_WIDTH/8{1'b0}};
    end else if (i_bus_valid) begin
      access_type <= i_bus_access;
      address <= i_bus_address;
      write_data <= i_bus_write_data;
      strobe <= i_bus_strobe;
    end
  end

endmodule

module preaddmul_2_stage_unsigned_10_bit(
