	input  [9:0] b,
	input  [9:0] d,
	output [9:0] out,
	input clk);

	// Internal 20-bit registers for storing intermediate results
	reg [19:0] stage0;
	reg [19:0] stage1;

	// Internal wire for storing the sum of d and a
	wire [19:0] sum;

	// Compute the sum of d and a
	assign sum = {10'b0, d} + {10'b0, a};

	// First stage: compute (d + a) * b and store in stage0
	always @(posedge clk) begin
		stage0 <= sum * {10'b0, b};
	end

	// Second stage: hold the result from stage0 in stage1
	always @(posedge clk) begin
		stage1 <= stage0;
	end

	// Output the final result from stage1, truncated to 10 bits
	assign out = stage1[19:10];

endmodule

