module db (
        input clk, n_reset, button_in,
        output reg out
    );

    parameter maxbit = 10; // Width of internal registers
    reg [maxbit-1:0] q_reg, q_next; // Counter registers
    reg f1, f2; // Input state capture registers
    wire q_add, q_reset; // Control signals for counter

    // Always block for input capture and counter update
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
            f1 <= 0;
            f2 <= 0;
            out <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
            q_next <= q_reg;

            // Counter control logic
            if (q_reset)
                q_next <= 0;
            else if (q_add)
                q_next <= q_reg + 1;

            q_reg <= q_next;
        end
    end

    // Control signals for counter
    assign q_add = (f1 == f2) & (q_reg < (1 << maxbit) - 1);
    assign q_reset = (f1 != f2) | (q_reg == (1 << maxbit) - 1);

    // Output update
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset)
            out <= 0;
        else if (q_reg == (1 << maxbit) - 1)
            out <= f1;
    end

endmodule

