module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output reg [7 : 0] q
);
    // Internal memory for the FIFO
    reg [7 : 0] mem [0 : 15];
    // Write and read pointers
    reg [3 : 0] wp, rp;
    // Write and read flags
    reg w_flag, r_flag;

    // Sequential logic for pointer updates and data storage
    always @(posedge clock or posedge sclr) begin
        if (sclr) begin
            // Reset pointers and flags
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
            full <= 0;
            empty <= 1;
        end else begin
            // Write operation
            if (wrreq && !full) begin
                mem[wp] <= data;
                wp <= wp + 1;
                if (wp == 15) begin
                    wp <= 0;
                    w_flag <= ~w_flag;
                end
                // Check if buffer is full
                if (wp == rp && w_flag != r_flag) begin
                    full <= 1;
                end else begin
                    full <= 0;
                end
            end
            // Read operation
            if (rdreq && !empty) begin
                q <= mem[rp];
                rp <= rp + 1;
                if (rp == 15) begin
                    rp <= 0;
                    r_flag <= ~r_flag;
                end
                // Check if buffer is empty
                if (wp == rp && w_flag == r_flag) begin
                    empty <= 1;
                end else begin
                    empty <= 0;
                end
            end
        end
    end
endmodule

