module bit_Adder(a, b, carryIn, sum, carryOut);
    input a, b, carryIn;
    output sum, carryOut;
    assign sum = a ^ b ^ carryIn;
    assign carryOut = (a & b) | (b & carryIn) | (a & carryIn);
endmodule

module Select_Carry_Adder(a, b, carryIn, carryOut, sum);
    input [15:0] a;
    input [15:0] b;
    input carryIn;
    output carryOut;
    output [15:0] sum;

    wire [3:0] carry1, carry2, carry3, carry4;
    wire [3:0] sum1, sum2, sum3, sum4;
    wire [3:0] sum1_mux, sum2_mux, sum3_mux, sum4_mux;

    // First 4-bit segment
    bit_Adder u0 (a[3:0], b[3:0], carryIn, sum1, carry1[0]);
    bit_Adder u1 (a[3:0], b[3:0], 1'b1, sum2, carry1[1]);
    assign sum1_mux = carryIn ? sum2 : sum1;
    assign carry1[2] = carryIn ? carry1[1] : carry1[0];

    // Second 4-bit segment
    bit_Adder u2 (a[7:4], b[7:4], carry1[2], sum3, carry2[0]);
    bit_Adder u3 (a[7:4], b[7:4], 1'b1, sum4, carry2[1]);
    assign sum2_mux = carry1[2] ? sum4 : sum3;
    assign carry2[2] = carry1[2] ? carry2[1] : carry2[0];

    // Third 4-bit segment
    bit_Adder u4 (a[11:8], b[11:8], carry2[2], sum1, carry3[0]);
    bit_Adder u5 (a[11:8], b[11:8], 1'b1, sum2, carry3[1]);
    assign sum3_mux = carry2[2] ? sum2 : sum1;
    assign carry3[2] = carry2[2] ? carry3[1] : carry3[0];

    // Fourth 4-bit segment
    bit_Adder u6 (a[15:12], b[15:12], carry3[2], sum1, carry4[0]);
    bit_Adder u7 (a[15:12], b[15:12], 1'b1, sum2, carry4[1]);
    assign sum4_mux = carry3[2] ? sum2 : sum1;
    assign carry4[2] = carry3[2] ? carry4[1] : carry4[0];

    // Combine results
    assign sum = {sum4_mux, sum3_mux, sum2_mux, sum1_mux};
    assign carryOut = carry4[2];
