module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAY_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);

// Internal signals
reg signed [OUT_WIDTH-1:0] sum;
reg [DELAY_STAGES:0] delay_counter;

// Function to recursively split and add addends
function signed [OUT_WIDTH-1:0] add_recursive;
    input signed [DATA_WIDTH-1:0] addends [];
    integer i, len;
    begin
        len = $size(addends);
        if (len == 1) begin
            add_recursive = addends[0];
        end else begin
            signed [DATA_WIDTH-1:0] left_addends [len/2-1:0];
            signed [DATA_WIDTH-1:0] right_addends [len/2-1:0];
            for (i = 0; i < len/2; i = i + 1) begin
                left_addends[i] = addends[i];
                right_addends[i] = addends[i + len/2];
            end
            add_recursive = add_recursive(left_addends) + add_recursive(right_addends);
        end
    end
endfunction

// Main logic
always @(posedge clk or posedge rst) begin
    if (rst) begin
        sum <= 0;
        delay_counter <= 0;
    end else if (in_advance) begin
        if (delay_counter < DELAY_STAGES) begin
            delay_counter <= delay_counter + 1;
        end else begin
            // Convert input vector to array for function call
            signed [DATA_WIDTH-1:0] addends [LENGTH-1:0];
            integer i;
            for (i = 0; i < LENGTH; i = i + 1) begin
                addends[i] = in_addends[(i+1)*DATA_WIDTH-1:i*DATA_WIDTH];
            end
            sum <= add_recursive(addends);
        end
    end
end

assign out_sum = sum;

endmodule

