    assign w1 = a & b & c;

    // NOT gate: w2 is high when c is low
    assign w2 = ~c;

    // OR gate: out is high if either w1 or w2 is high
    assign out = w1 | w2;
endmodule

module partsel_00126(ctrl, s0, s1, s2, s3, x0, x1, x2, x3, y);
