  input [2:0] s2;
  input [2:0] s3;
  input signed [31:0] x0;
  input signed [31:0] x1;
  input signed [31:0] x2;
  input [31:0] x3;
  output [127:0] y;

  // Local parameters
  parameter CONST1 = 32'd100;
  parameter CONST2 = 32'd200;
  parameter CONST3 = 32'd300;
  parameter CONST4 = 32'd400;

  // Intermediate wires
  wire [31:0] w0, w1, w2, w3;
  wire [31:0] w4, w5, w6, w7;
  wire [31:0] w8, w9, w10, w11;
  wire [31:0] w12, w13, w14, w15;

  // Control signal decoding
  wire [1:0] op_code = ctrl[3:2];
  wire [1:0] sel_code = ctrl[1:0];

  // Operation selection
  always @(*) begin
    case (op_code)
      2'b00: begin // Addition
        w0 = x0 + CONST1;
        w1 = x1 + CONST2;
        w2 = x2 + CONST3;
        w3 = x3 + CONST4;
      end
      2'b01: begin // Subtraction
        w0 = x0 - CONST1;
        w1 = x1 - CONST2;
        w2 = x2 - CONST3;
        w3 = x3 - CONST4;
      end
      2'b10: begin // XOR
        w0 = x0 ^ CONST1;
        w1 = x1 ^ CONST2;
        w2 = x2 ^ CONST3;
        w3 = x3 ^ CONST4;
      end
      2'b11: begin // AND
        w0 = x0 & CONST1;
        w1 = x1 & CONST2;
        w2 = x2 & CONST3;
        w3 = x3 & CONST4;
      end
    endcase
  end

  // Selector logic
  always @(*) begin
    case (sel_code)
      2'b00: begin
        w4 = w0;
        w5 = w1;
        w6 = w2;
        w7 = w3;
      end
      2'b01: begin
        w4 = w0 << s0;
        w5 = w1 << s1;
        w6 = w2 << s2;
        w7 = w3 << s3;
      end
      2'b10: begin
        w4 = w0 >> s0;
        w5 = w1 >> s1;
        w6 = w2 >> s2;
        w7 = w3 >> s3;
      end
      2'b11: begin
        w4 = w0[31:0];
        w5 = w1[31:0];
        w6 = w2[31:0];
        w7 = w3[31:0];
      end
    endcase
  end

  // Final output assembly
  assign y = {w7, w6, w5, w4};

endmodule

module multi_seven_seg_6 (
    input clk,
    input rst,
    input [15:0] value,
    output reg [6:0] segs,
    output reg [3:0] sel
  );

  // Parameters
  parameter NUM_DIGITS = 4;
  parameter DIV_FACTOR = 1000000; // Example division factor for 1MHz clock to update every 1ms
  parameter CNT_WIDTH = $clog2(NUM_DIGITS);
  parameter DIG_WIDTH = 4; // Assuming 4-bit digits for simplicity

  // Internal signals
  reg [CNT_WIDTH-1:0] digit_cnt;
  reg [DIG_WIDTH-1:0] current_digit;
  reg [3:0] digit_sel;

  // Counter to cycle through digits
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      digit_cnt <= 0;
    end else if (digit_cnt == NUM_DIGITS - 1) begin
      digit_cnt <= 0;
    end else begin
      digit_cnt <= digit_cnt + 1;
    end
  end

  // Select the current digit based on the counter
  always @(*) begin
    case (digit_cnt)
      0: current_digit = value[3:0];
      1: current_digit = value[7:4];
      2: current_digit = value[11:8];
      3: current_digit = value[15:12];
      default: current_digit = 0;
    endcase
  end

  // Seven-segment decoder
  always @(*) begin
    case (current_digit)
      4'b0000: segs = 7'b0000001; // 0
      4'b0001: segs = 7'b1001111; // 1
      4'b0010: segs = 7'b0010010; // 2
      4'b0011: segs = 7'b0000110; // 3
      4'b0100: segs = 7'b1001100; // 4
      4'b0101: segs = 7'b0100100; // 5
      4'b0110: segs = 7'b0100000; // 6
      4'b0111: segs = 7'b0001111; // 7
      4'b1000: segs = 7'b0000000; // 8
      4'b1001: segs = 7'b0000100; // 9
      default: segs = 7'b1111111; // Blank
    endcase
  end

  // Digit selection
  always @(*) begin
    case (digit_cnt)
      0: digit_sel = 4'b1110;
      1: digit_sel = 4'b1101;
      2: digit_sel = 4'b1011;
      3: digit_sel = 4'b0111;
      default: digit_sel = 4'b1111;
    endcase
  end

  // Assign the selection signal
  assign sel = digit_sel;

endmodule

