module timer_variable(
    input wire zedboard_clk,
    input wire enable,
    input wire reset,
    output reg timerOutput
);

    // 32-bit register to keep track of the current count
    reg [31:0] timer_value;

    // Maximum value for the timer
    localparam MAX_VALUE = 100000;

    // Sequential logic to update timer_value and timerOutput
    always @(posedge zedboard_clk or posedge reset) begin
        if (reset) begin
            // Reset timer_value to zero and set timerOutput to low
            timer_value <= 0;
            timerOutput <= 0;
        end else begin
            if (timer_value == MAX_VALUE) begin
                // When timer_value reaches MAX_VALUE, set timerOutput high for one cycle
                timer_value <= 0;
                timerOutput <= 1;
            end else begin
                // Increment timer_value and keep timerOutput low
                timer_value <= timer_value + 1;
                timerOutput <= 0;
            end
        end
    end

endmodule

