module adder16 (
	input [15:0] A, B,
	input Cin,
	output [15:0] S,
	output Cout
);

// Instantiate the parameterized adder module for 16-bit operations
p_adder #(.WIDTH(16)) uut (
	.A(A),
	.B(B),
	.Cin(Cin),
	.S(S),
	.Cout(Cout)
