endmodule

// Definition of the parameterized adder module
module p_adder #(
	parameter WIDTH = 16
)(
	input [WIDTH-1:0] A, B,
	input Cin,
	output [WIDTH-1:0] S,
	output Cout
);

// Internal wire to hold the carry signal
wire [WIDTH:0] carry;

// Generate block to create a ripple carry adder
generate
	for (genvar i = 0; i < WIDTH; i = i + 1) begin : ripple_carry
		// Full adder instantiation for each bit position
		full_adder fa (
			.A(A[i]),
			.B(B[i]),
			.Cin(carry[i]),
			.S(S[i]),
			.Cout(carry[i+1])
		);
	end
endgenerate

// Assign the final carry-out
assign Cout = carry[WIDTH];

endmodule

// Definition of the full adder module
module full_adder (
	input A, B, Cin,
	output S, Cout
);

// Sum output is the XOR of A, B, and Cin
assign S = A ^ B ^ Cin;

// Carry-out is the OR of the ANDs of the input pairs
assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

module conv_apb 
  (
    input wire PCLK,           
    input wire PRESETB,        
    input wire [31:0] PADDR,   
    input wire PSEL,           
    input wire PENABLE,        
    input wire PWRITE,         
    input wire [31:0] PWDATA,  
    output wire [31:0] PRDATA,
    input wire [31:0] clk_counter,
    input wire conv_done,
    output reg conv_start,
    output reg [2:0]  COMMAND,
    output reg [8:0]  InCh,
    output reg [8:0]  OutCh,
    output reg [5:0]  FLength,
    input wire  F_writedone,
    output reg  F_writedone_respond,
    input wire  B_writedone,
    output reg  B_writedone_respond,
    input wire  rdy_to_transmit,
    output reg  rdy_to_transmit_respond,
    input wire  transmit_done,
    output reg  transmit_done_respond 
  );

  reg [31:0] reg_control;
  reg [31:0] reg_status;

  // Reset logic
  always @(posedge PCLK or negedge PRESETB) begin
    if (!PRESETB) begin
      conv_start <= 0;
      COMMAND <= 0;
      InCh <= 0;
      OutCh <= 0;
      FLength <= 0;
      F_writedone_respond <= 0;
      B_writedone_respond <= 0;
      rdy_to_transmit_respond <= 0;
      transmit_done_respond <= 0;
      reg_control <= 0;
      reg_status <= 0;
    end else begin
      // Write operations
      if (PSEL && PENABLE && PWRITE) begin
        case (PADDR[7:2])
          6'h00: reg_control <= PWDATA;
          6'h01: InCh <= PWDATA[8:0];
          6'h02: OutCh <= PWDATA[8:0];
          6'h03: FLength <= PWDATA[5:0];
          default: ;
        endcase
      end

      // Update control signals based on reg_control
      conv_start <= reg_control[0];
      COMMAND <= reg_control[3:1];
      F_writedone_respond <= F_writedone;
      B_writedone_respond <= B_writedone;
      rdy_to_transmit_respond <= rdy_to_transmit;
      transmit_done_respond <= transmit_done;
    end
  end

  // Read operations
  always @(*) begin
    case (PADDR[7:2])
      6'h00: PRDATA = reg_control;
      6'h01: PRDATA = {23'b0, InCh};
      6'h02: PRDATA = {23'b0, OutCh};
      6'h03: PRDATA = {26'b0, FLength};
      6'h04: PRDATA = {23'b0, F_writedone_respond, B_writedone_respond, rdy_to_transmit_respond, transmit_done_respond, conv_done};
      default: PRDATA = 32'b0;
    endcase
  end

endmodule

