module uart(input wire [7:0] din,
	    input wire wr_en,
	    input wire clk,
	    output wire tx,
	    output wire tx_busy,
	    input wire rx,
	    output wire rdy,
	    input wire rdy_clr,
	    output wire [7:0] dout);

    // Baud rate generator
    reg [15:0] baud_counter;
    reg baud_tick;
    reg [15:0] baud_rate_divisor = 16'd15625; // Example divisor for 9600 baud rate at 16 MHz clock

    always @(posedge clk) begin
        if (baud_counter == baud_rate_divisor) begin
            baud_counter <= 16'd0;
            baud_tick <= ~baud_tick;
        end else begin
            baud_counter <= baud_counter + 1;
        end
    end

    // Transmitter
    reg [7:0] tx_data;
    reg [3:0] tx_bit_count;
    reg tx_shift_reg;
    reg tx_start;

    always @(posedge clk) begin
        if (wr_en && !tx_busy) begin
            tx_data <= din;
            tx_bit_count <= 4'd0;
            tx_shift_reg <= 1'b1; // Start bit
            tx_start <= 1'b1;
            tx_busy <= 1'b1;
        end else if (tx_start) begin
            tx <= tx_shift_reg;
            tx_shift_reg <= tx_data[0];
            tx_data <= {tx_data[6:0], 1'b0};
            tx_bit_count <= tx_bit_count + 1;
            tx_start <= 1'b0;
        end else if (tx_bit_count < 4'd8) begin
            tx <= tx_shift_reg;
            tx_shift_reg <= tx_data[0];
            tx_data <= {tx_data[6:0], 1'b0};
            tx_bit_count <= tx_bit_count + 1;
        end else if (tx_bit_count == 4'd8) begin
            tx <= 1'b0; // Stop bit
            tx_bit_count <= tx_bit_count + 1;
        end else begin
            tx_busy <= 1'b0;
        end
    end

    // Receiver
    reg [7:0] rx_data;
    reg [3:0] rx_bit_count;
    reg rx_shift_reg;
    reg rx_start;

    always @(posedge clk) begin
        if (rx && !rx_start) begin
            rx_start <= 1'b1;
            rx_bit_count <= 4'd0;
        end else if (rx_start) begin
            rx_shift_reg <= rx;
            rx_data <= {rx_data[6:0], rx_shift_reg};
            rx_bit_count <= rx_bit_count + 1;
            if (rx_bit_count == 4'd8) begin
                rx_start <= 1'b0;
                rdy <= 1'b1;
            end
        end
    end

    // Clear ready signal
    always @(posedge clk) begin
        if (rdy_clr) begin
            rdy <= 1'b0;
        end
    end

    // Assign output
    assign dout = rx_data;

endmodule

module Multiplication(
    input wire [7:0] Input1,
    input wire [7:0] Input2,
    input wire Op,
    output wire [7:0] Output1,
    output wire [7:0] Output2,
    output wire N
);

    // Internal wire to store the signed multiplication result
    wire signed [15:0] SignedMult;
    // Internal wire to store the final multiplication result
    wire [15:0] MultAns;

    // Perform signed multiplication
    assign SignedMult = Input1 * Input2;

    // Select between signed and unsigned multiplication based on Op
    assign MultAns = (Op == 0) ? SignedMult : (Input1 * Input2);

    // Assign the lower 8 bits of MultAns to Output1
    assign Output1 = MultAns[7:0];
    // Assign the upper 8 bits of MultAns to Output2
    assign Output2 = MultAns[15:8];
    // Assign the sign bit N from the 15th bit of MultAns if Op is 0
    assign N = (Op == 0) ? MultAns[15] : 0;

endmodule

module fft2(
    input [31:0] a_re,
    input [31:0] a_img,
    input [31:0] b_re,
    input [31:0] b_img,
    input clk,
    output [31:0] x0_re,
    output [31:0] x0_img,
    output [31:0] x1_re,
    output [31:0] x1_img
);

    // Internal wires for intermediate values
    wire [31:0] scaled_a_re, scaled_a_img, scaled_b_re, scaled_b_img;
    wire [31:0] sum_re, sum_img, diff_re, diff_img;

    // Multipliers for scaling inputs
    assign scaled_a_re = a_re * 0.707; // cos(pi/4) = 0.707
    assign scaled_a_img = a_img * 0.707;
    assign scaled_b_re = b_re * 0.707;
    assign scaled_b_img = b_img * 0.707;

    // buf11 module for data preparation (assuming it's a simple buffer)
    buf11 buf11_a (
        .in(scaled_a_re),
        .out(scaled_a_re)
    );
    buf11 buf11_b (
        .in(scaled_a_img),
        .out(scaled_a_img)
    );
    buf11 buf11_c (
        .in(scaled_b_re),
        .out(scaled_b_re)
    );
    buf11 buf11_d (
        .in(scaled_b_img),
        .out(scaled_b_img)
    );

    // Complex_adder modules for computing final outputs
    complex_adder adder1 (
        .a_re(scaled_a_re),
        .a_img(scaled_a_img),
        .b_re(scaled_b_re),
        .b_img(scaled_b_img),
        .sum_re(sum_re),
        .sum_img(sum_img)
    );

    complex_adder adder2 (
        .a_re(scaled_a_re),
        .a_img(scaled_a_img),
        .b_re(-scaled_b_re),
        .b_img(-scaled_b_img),
        .sum_re(diff_re),
        .sum_img(diff_img)
    );

    // Assigning outputs
    assign x0_re = sum_re;
    assign x0_img = sum_img;
    assign x1_re = diff_re;
    assign x1_img = diff_img;

endmodule

