module motor_rpm_count(
	input clk,
	input motor_rot_pulse,
	output wire [15:0] rpm_output
);

reg [31:0] pulse_count;
reg last_scan_value;
reg [15:0] pulse_count_qty;
reg [15:0] output_count_qty;

always @(posedge clk) begin
	// Initialize pulse_count to 50,000,000 - 1
	if (pulse_count == 0) begin
		pulse_count <= 49999999;
		output_count_qty <= pulse_count_qty;
		pulse_count_qty <= 0;
	end else begin
		pulse_count <= pulse_count - 1;
	end

	// Detect rising edge on motor_rot_pulse
	if (motor_rot_pulse && !last_scan_value) begin
		pulse_count_qty <= pulse_count_qty + 1;
	end

	last_scan_value <= motor_rot_pulse;
end

assign rpm_output = output_count_qty;

endmodule

module edge_detect (
  input clk,
  input rst_n,
  input a,
  output reg rise,
  output reg down
);

  reg a_prev;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      // Reset all internal registers and output signals to zero
      a_prev <= 0;
      rise <= 0;
      down <= 0;
    end else begin
      // Detect rising and falling edges
      if (a && !a_prev) begin
        // Rising edge detected
        rise <= 1;
        down <= 0;
      end else if (!a && a_prev) begin
        // Falling edge detected
        rise <= 0;
        down <= 1;
      end else begin
        // No edge detected
        rise <= 0;
        down <= 0;
      end
      // Update the previous state of the input signal
      a_prev <= a;
    end
  end

endmodule

