// Compute the partial products
assign sig_222 = A[7] & B[6];
assign sig_223 = A[5] & B[4];
assign sig_240 = A[6] & B[5];

// Assign the partial products to their respective positions in the output
assign O[14] = sig_222;
assign O[13] = sig_240;
assign O[12] = sig_223;

// Set the remaining bits of O to zero
assign O[11:0] = 12'b0;

endmodule

module I_SQRT_2(
    input wire [31:0] n,
    input wire CLK,
    input wire RST_n,
    input wire EN,
    input wire SEL,
    output wire VAL,
    output wire Z,
    output wire [31:0] out_sqrt
);

    // Internal registers and wires
    reg [31:0] x_0;
    reg [31:0] x_i;
    reg [31:0] x_i_mux;
    reg [31:0] x_next;
    reg [31:0] sqrt;
    reg [31:0] out_sqrt_reg;
    reg val_comb;
    reg z_comb;
    reg val_ff;
    reg z_ff;

    // Initial guess for the square root (1.0 in floating-point format)
    initial x_0 = 32'h3f800000; // 1.0 in single-precision floating-point

    // Multiplexer for selecting between the initial guess and the next iteration value
    always @(*) begin
        if (SEL)
            x_i_mux = x_0;
        else
            x_i_mux = x_i;
    end

    // Compute the next guess
    always @(*) begin
        if (n == 0) begin
            sqrt = 32'h00000000;
            val_comb = 0;
            z_comb = 1;
        end else begin
            x_next = (x_i + (n / x_i)) >> 1;
            if (x_next >= x_i) begin
                sqrt = x_i;
                val_comb = 1;
                z_comb = 0;
            end else begin
                val_comb = 0;
                z_comb = 0;
            end
        end
    end

    // Control logic
    always @(posedge CLK or negedge RST_n) begin
        if (!RST_n) begin
            x_i <= 32'h00000000;
            out_sqrt_reg <= 32'h00000000;
            val_ff <= 0;
            z_ff <= 0;
        end else if (EN) begin
            x_i <= x_i_mux;
            out_sqrt_reg <= sqrt;
            val_ff <= val_comb;
            z_ff <= z_comb;
        end
    end

    // Assign output signals
    assign out_sqrt = out_sqrt_reg;
    assign VAL = val_ff;
    assign Z = z_ff;

endmodule

