  input [0:0] u0;
  input [1:0] u1;
  input [2:0] u2;
  input [3:0] u3;
  input [4:0] u4;
  input [5:0] u5;
  input [6:0] u6;
  input [7:0] u7;
  input signed [0:0] s0;
  input signed [1:0] s1;
  input signed [2:0] s2;
  input signed [3:0] s3;
  input signed [4:0] s4;
  input signed [5:0] s5;
  input signed [6:0] s6;
  input signed [7:0] s7;
  output [127:0] y;

  // Intermediate signals
  wire [15:0] y0, y1, y2, y3, y4, y5, y6, y7;

  // Operation selection based on ctrl
  always @(*) begin
    case (ctrl)
      8'h00: begin
        y0 = u0 + s0;
        y1 = u1 & s1;
        y2 = u2 | s2;
        y3 = u3 ^ s3;
        y4 = u4 << s4;
        y5 = u5 >> s5;
        y6 = u6 + s6;
        y7 = u7 - s7;
      end
      8'h01: begin
        y0 = u0 - s0;
        y1 = u1 | s1;
        y2 = u2 ^ s2;
        y3 = u3 & s3;
        y4 = u4 >> s4;
        y5 = u5 << s5;
        y6 = u6 - s6;
        y7 = u7 + s7;
      end
      8'h02: begin
        y0 = u0 & s0;
        y1 = u1 ^ s1;
        y2 = u2 + s2;
        y3 = u3 | s3;
        y4 = u4 + s4;
        y5 = u5 - s5;
        y6 = u6 << s6;
        y7 = u7 >> s7;
      end
      default: begin
        y0 = 16'b0;
        y1 = 16'b0;
        y2 = 16'b0;
        y3 = 16'b0;
        y4 = 16'b0;
        y5 = 16'b0;
        y6 = 16'b0;
        y7 = 16'b0;
      end
    endcase
  end

  // Concatenate the intermediate results to form the final output
  assign y = {y7, y6, y5, y4, y3, y2, y1, y0};

