module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

    reg [7:0] shift_reg; // Internal shift register to store serial bits
    reg [2:0] bit_count; // Counter to track the number of bits received

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset the shift register and bit counter
            shift_reg <= 8'b0;
            bit_count <= 3'b0;
            dout_parallel <= 8'b0;
            dout_valid <= 1'b0;
        end else if (din_valid) begin
            // Shift the incoming serial bit into the shift register
            shift_reg <= {shift_reg[6:0], din_serial};
            // Increment the bit counter
            bit_count <= bit_count + 1;
            // If 8 bits have been received, output the parallel data
            if (bit_count == 3'b111) begin
                dout_parallel <= shift_reg;
                dout_valid <= 1'b1;
                // Reset the shift register and bit counter for the next byte
                shift_reg <= 8'b0;
                bit_count <= 3'b0;
            end else begin
                dout_valid <= 1'b0;
            end
        end
    end

endmodule

module NV_NVDLA_HLS_shiftrightsatsu (
   data_in
  ,shift_num
  ,data_out
  ,sat_out
  );
parameter IN_WIDTH = 49;
parameter SHIFT_WIDTH = 6;
parameter OUT_WIDTH = 32;

input [IN_WIDTH-1:0] data_in;
input [SHIFT_WIDTH-1:0] shift_num;
output [OUT_WIDTH-1:0] data_out;
output sat_out;

reg [OUT_WIDTH-1:0] shifted_data;
reg sat_flag;

always @(*) begin
    // Sign extend the input data
    reg [IN_WIDTH+1:0] sign_extended_data;
    sign_extended_data = {{(IN_WIDTH+1){data_in[IN_WIDTH-1]}}, data_in};

    // Perform the right shift
    shifted_data = sign_extended_data >> shift_num;

    // Determine saturation
    if (shift_num > 0) begin
        // Check for overflow/underflow
        if (shifted_data[OUT_WIDTH] != sign_extended_data[IN_WIDTH]) begin
            sat_flag = 1'b1;
            // Saturate to max or min value
            if (sign_extended_data[IN_WIDTH] == 1'b1) begin
                data_out = {OUT_WIDTH{1'b1}}; // Saturate to -1 (all 1s)
            end else begin
                data_out = {OUT_WIDTH{1'b0}}; // Saturate to 0
            end
        end else begin
            sat_flag = 1'b0;
            data_out = shifted_data[OUT_WIDTH-1:0];
        end
    end else begin
        // No shift, no saturation
        sat_flag = 1'b0;
        data_out = data_in[OUT_WIDTH-1:0];
    end
end

assign sat_out = sat_flag;

endmodule

