module muladd_3_stage_unsigned_15_bit_xor_reduction(
	input  [14:0] a,
	input  [14:0] b,
	input  [14:0] c,
	output [14:0] out,
	input clk);

// Internal signals to hold the results of each stage
reg [29:0] stage0;
reg [29:0] stage1;
reg [29:0] stage2;

// Internal signal to hold the XOR reduction result
reg [14:0] xor_reduction;

// Pipeline stages
always @(posedge clk) begin
	// First stage: compute a * b + c
	stage0 <= (a * b) + c;

	// Second stage: pass the result from stage0 to stage1
	stage1 <= stage0;

	// Third stage: pass the result from stage1 to stage2
	stage2 <= stage1;
end

// XOR reduction on the 30-bit value in stage2
always @(*) begin
	xor_reduction = 0;
	for (int i = 0; i < 30; i = i + 1) begin
		xor_reduction = xor_reduction ^ stage2[i];
	end
end

// Assign the XOR reduction result to the output
assign out = xor_reduction;

endmodule

