module delay (
	input clk,
	input reset,
	input [3:0] variable_pulse_index,
	output reg slow_pulse,
	output reg fast_pulse,
	output reg variable_pulse
);

reg [31:0] counter;
reg [31:0] variable_threshold;

// Base value for variable pulse threshold calculation
localparam BASE_VARIABLE_THRESHOLD = 2000000;
// Maximum value for variable pulse threshold calculation
localparam MAX_VARIABLE_THRESHOLD = 24000000;
// Fixed threshold for slow pulse
localparam SLOW_PULSE_THRESHOLD = 18000000;
// Fixed threshold for fast pulse
localparam FAST_PULSE_THRESHOLD = 4800000;

always @(posedge clk or posedge reset) begin
	if (reset) begin
		counter <= 0;
		slow_pulse <= 0;
		fast_pulse <= 0;
		variable_pulse <= 0;
	end else begin
		// Increment the counter on each clock cycle
		counter <= counter + 1;

		// Calculate the variable threshold based on the variable_pulse_index
		variable_threshold <= BASE_VARIABLE_THRESHOLD + (variable_pulse_index * (MAX_VARIABLE_THRESHOLD - BASE_VARIABLE_THRESHOLD) / 15);

		// Generate slow pulse
		if (counter == SLOW_PULSE_THRESHOLD) begin
			slow_pulse <= 1;
		end else begin
			slow_pulse <= 0;
		end

