module FSM_game(
    input wire iRST,
    input wire iCLK,
    input wire [1:0] iA,
    input wire [1:0] iB,
    output wire oA,
    output wire oB
);

    // Define states
    typedef enum reg [2:0] {
        DRAW = 3'b000,
        B_LEAD = 3'b001,
        B_WIN = 3'b010,
        A_LEAD = 3'b011,
        A_WIN = 3'b100
    } state_t;

    // State registers
    state_t sSTATE, sNEXT_STATE;

    // Combinational logic to determine the next state
    always @(*) begin
        case (sSTATE)
            DRAW: begin
                if (iA > iB)
                    sNEXT_STATE = A_LEAD;
                else if (iB > iA)
                    sNEXT_STATE = B_LEAD;
                else
                    sNEXT_STATE = DRAW;
            end
            B_LEAD: begin
                if (iA > iB)
                    sNEXT_STATE = A_LEAD;
                else if (iB > iA)
                    sNEXT_STATE = B_WIN;
                else
                    sNEXT_STATE = DRAW;
            end
            B_WIN: begin
                sNEXT_STATE = B_WIN; // Stay in B_WIN state once won
            end
            A_LEAD: begin
                if (iA > iB)
                    sNEXT_STATE = A_WIN;
                else if (iB > iA)
                    sNEXT_STATE = B_LEAD;
                else
                    sNEXT_STATE = DRAW;
            end
            A_WIN: begin
                sNEXT_STATE = A_WIN; // Stay in A_WIN state once won
            end
            default: begin
                sNEXT_STATE = DRAW; // Default state
            end
        endcase
    end

    // State register update on clock edge
    always @(posedge iCLK or posedge iRST) begin
        if (iRST)
            sSTATE <= DRAW;
        else
            sSTATE <= sNEXT_STATE;
    end

    // Output logic to determine winners
    always @(*) begin
        case (sSTATE)
            A_WIN: begin
                oA = 1'b1;
                oB = 1'b0;
            end
            B_WIN: begin
                oA = 1'b0;
                oB = 1'b1;
            end
            default: begin
                oA = 1'b0;
                oB = 1'b0;
            end
        endcase
    end

endmodule

