    reg       stage1_clk;
    reg       stage2_clk;
    reg       stage3_clk;

    // Clock generation logic
    always @(posedge init or posedge dk) begin
        if (init) begin
            stage1_clk <= 0;
            stage2_clk <= 0;
            stage3_clk <= 0;
        end else begin
            stage1_clk <= ~stage1_clk;
            stage2_clk <= ~stage2_clk;
