module tb_fixed_reciprocal();
    // Parameters for fixed-point and floating-point formats
    parameter integer WORD_WIDTH = 32;
    parameter integer INTEGER_WIDTH = 16;
    parameter integer FRACTIONAL_WIDTH = WORD_WIDTH - INTEGER_WIDTH;
    parameter real CLOCK_PERIOD = 10.0; // in nanoseconds

    // Clock and reset signals
    reg clk;
    reg rst;

    // Input and output signals
    reg [WORD_WIDTH-1:0] input_fixed;
    wire [WORD_WIDTH-1:0] output_fixed;
    wire valid;

    // Instantiate the DUT
    fixed_reciprocal #(
        .WORD_WIDTH(WORD_WIDTH),
        .INTEGER_WIDTH(INTEGER_WIDTH),
        .FRACTIONAL_WIDTH(FRACTIONAL_WIDTH)
    ) dut (
        .clk(clk),
        .rst(rst),
        .input_fixed(input_fixed),
        .output_fixed(output_fixed),
        .valid(valid)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #((CLOCK_PERIOD / 2)) clk = ~clk;
    end

    // Reset generation
    initial begin
        rst = 1;
        #10 rst = 0;
    end

    // Helper function to convert real to fixed-point
    function [WORD_WIDTH-1:0] real_to_fixed(real value);
        real_to_fixed = $rtoi(value * (2 ** FRACTIONAL_WIDTH));
    endfunction

    // Helper function to convert fixed-point to real
    function real fixed_to_real([WORD_WIDTH-1:0] value);
        fixed_to_real = value / (2 ** FRACTIONAL_WIDTH);
    endfunction

    // Test sequence
    initial begin
        // Test case 1: Normal value
        input_fixed = real_to_fixed(0.5);
        #10;
        assert (valid) else $error("Test case 1 failed: valid signal not asserted");
        assert (fixed_to_real(output_fixed) == 2.0) else $error("Test case 1 failed: incorrect output");

        // Test case 2: Edge case (division by zero)
        input_fixed = real_to_fixed(0.0);
        #10;
        assert (!valid) else $error("Test case 2 failed: valid signal should not be asserted");

        // Test case 3: Large value
        input_fixed = real_to_fixed(0.001);
        #10;
        assert (valid) else $error("Test case 3 failed: valid signal not asserted");
        assert (fixed_to_real(output_fixed) == 1000.0) else $error("Test case 3 failed: incorrect output");

        // Test case 4: Small value
        input_fixed = real_to_fixed(1.0);
        #10;
        assert (valid) else $error("Test case 4 failed: valid signal not asserted");
        assert (fixed_to_real(output_fixed) == 1.0) else $error("Test case 4 failed: incorrect output");

        $finish;
    end
endmodule

