    assign _and[2] = a[0] & b[2];
    assign _and[3] = a[0] & b[3];
    assign _and[4] = a[1] & b[0];
    assign _and[5] = a[1] & b[1];
    assign _and[6] = a[1] & b[2];
    assign _and[7] = a[1] & b[3];
    assign _and[8] = a[2] & b[0];
    assign _and[9] = a[2] & b[1];
    assign _and[10] = a[2] & b[2];
    assign _and[11] = a[2] & b[3];
    assign _and[12] = a[3] & b[0];
    assign _and[13] = a[3] & b[1];
    assign _and[14] = a[3] & b[2];
    assign _and[15] = a[3] & b[3];

    // Internal wires for sum and carry
    wire [7:0] sum;
    wire [7:0] carry;

    // Half adder for the least significant bit
    half_adder ha0 (
        .a(_and[0]),
        .b(1'b0),
        .sum(sum[0]),
        .carry(carry[0])
    );

    // Full adders for the rest of the bits
    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : fa_gen
            full_adder fa (
                .a(_and[i]),
                .b(sum[i-1]),
                .cin(carry[i-1]),
                .sum(sum[i]),
                .carry(carry[i])
            );
        end
    endgenerate

    // Assign the final product
    assign prod = {carry[7], sum[7:0]};

    // Half adder module
    module half_adder(a, b, sum, carry);
        input a, b;
        output sum, carry;
        assign sum = a ^ b;
        assign carry = a & b;
    endmodule

    // Full adder module
    module full_adder(a, b, cin, sum, carry);
        input a, b, cin;
        output sum, carry;
        wire p, g;
        assign p = a ^ b;
        assign g = a & b | p & cin;
        assign sum = p ^ cin;
        assign carry = g;
    endmodule

endmodule

module isqrt
(
    input      [31:0] x,
    output reg [15:0] y
);

reg [31:0] remainder;
reg [31:0] result;
reg [31:0] bit_test;

integer i;

always @(*) begin
    // Initialize registers
    remainder = x;
    result = 0;
    bit_test = 1 << 30; // Start with the highest bit

    // Iterate over each bit position
    for (i = 0; i < 16; i = i + 1) begin
        if (remainder >= bit_test) begin
            remainder = remainder - bit_test;
            result = result | bit_test;
        end
        bit_test = bit_test >> 2; // Shift right by 2 to test the next bit pair
    end

    // Assign the lower 16 bits of the result to the output
    y = result[15:0];
end

endmodule

