module rx_dcoffset 
  #(parameter WIDTH=16,
    parameter ADDR=8'd0,
    parameter alpha_shift=20)
   (input clk, input rst, 
    input set_stb, input [7:0] set_addr, input [31:0] set_data,
    input [WIDTH-1:0] in, output [WIDTH-1:0] out);

  reg [WIDTH-1:0] offset;
  reg [WIDTH+1:0] integrator;
  reg [WIDTH-1:0] integrator_rounded;
  reg [WIDTH-1:0] corrected_out;

  // Sub-module for rounding
  always @(posedge clk or posedge rst) begin
    if (rst)
      integrator_rounded <= {WIDTH{1'b0}};
    else
      integrator_rounded <= integrator >> 1; // Simple rounding by shifting right
  end

  // Sub-module for addition with clipping
  always @(posedge clk or posedge rst) begin
    if (rst)
      corrected_out <= {WIDTH{1'b0}};
    else begin
      reg [WIDTH+1:0] temp;
      temp = in + integrator_rounded;
      if (temp > {WIDTH{1'b1}})
        corrected_out <= {WIDTH{1'b1}};
      else if (temp < {WIDTH{1'b0}})
        corrected_out <= {WIDTH{1'b0}};
      else
        corrected_out <= temp[WIDTH-1:0];
    end
  end

  // Main logic for DC offset correction
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      offset <= {WIDTH{1'b0}};
      integrator <= {WIDTH+2{1'b0}};
    end else if (set_stb && set_addr == ADDR) begin
      offset <= set_data[WIDTH-1:0];
    end else begin
      reg [WIDTH:0] integrator_in;
      integrator_in = (corrected_out[WIDTH-1] == 1'b1) ? {WIDTH{1'b1}} : {WIDTH{1'b0}};
      integrator <= integrator + (integrator_in << alpha_shift);
    end
  end

  assign out = corrected_out - offset;

endmodule

module testbench;

    // Clock and reset signals
    reg clk;
