    // Memory module signals
    reg [7:0] mem_addr;
    reg [7:0] mem_data_in;
    reg mem_write_en;
    wire [7:0] mem_data_out;

    // Microcontroller module signals
    reg [7:0] mcu_data_in;
    wire [7:0] mcu_data_out;

    // Instantiate the memory module
    memory mem (
        .clk(clk),
        .data_in(mem_data_in),
        .address(mem_addr),
        .write_enable(mem_write_en),
        .data_out(mem_data_out)
    );

    // Instantiate the microcontroller module
    microcontroller mcu (
        .clk(clk),
        .rst(rst),
        .data_in(mcu_data_in),
        .data_out(mcu_data_out)
    );

    // Clock generation
    always #5 clk = ~clk;

    // Reset generation
    initial begin
        rst = 1;
        #12 rst = 0;
    end

    // Testbench process
    initial begin
        // Initialize signals
        clk = 0;
        rst = 1;
        mem_addr = 0;
        mem_data_in = 0;
        mem_write_en = 0;

        // Wait for reset to deassert
        #13;

        // Test write operation
        mem_addr = 8'h01;
        mem_data_in = 8'hA5;
        mem_write_en = 1;
        #10;
        mem_write_en = 0;
