        mem_write_en = 0;
        #10;

        // Display results
        $display("Time: %0t, Address: %0h, Data: %0h", $time, mem_addr, mem_data_out);

        // Finish simulation
        $finish;
    end

    // Monitor memory transactions
    always @(posedge clk) begin
        if (mem_write_en) begin
            $display("Time: %0t, Write to Address: %0h, Data: %0h", $time, mem_addr, mem_data_in);
        end else begin
