module mii_if(
	input	aclk,
	input	aresetn,

	output	reg [7:0] tx_tdata,
	output	reg tx_tvalid,
	output	reg tx_tlast,
	input	tx_tready, 

	input	[7:0] rx_tdata,
	input	rx_tvalid,
	input	rx_tlast,
	output	reg rx_tready,

	output	mii_tx_clk,
	input	mii_tx_en,
	input	mii_tx_er,
	input	[3:0] mii_tx_data,

	output	mii_rx_clk,
	output	reg mii_rx_dv,
	output	reg mii_rx_er,
	output	reg [3:0] mii_rx_data,

	output	mii_crs,
	output	mii_col
);

// Transmit direction
reg [7:0] tx_buffer;
reg tx_buffer_valid;
reg tx_buffer_last;

always @(posedge aclk or negedge aresetn) begin
	if (!aresetn) begin
		tx_tdata <= 8'b0;
		tx_tvalid <= 1'b0;
		tx_tlast <= 1'b0;
		tx_buffer <= 8'b0;
		tx_buffer_valid <= 1'b0;
		tx_buffer_last <= 1'b0;
	end else begin
		if (tx_tready && tx_tvalid) begin
			tx_tvalid <= 1'b0;
			tx_tlast <= 1'b0;
		end else if (tx_buffer_valid) begin
			tx_tdata <= tx_buffer;
			tx_tvalid <= 1'b1;
			tx_tlast <= tx_buffer_last;
			tx_buffer_valid <= 1'b0;
		end
	end
end

always @(posedge aclk or negedge aresetn) begin
	if (!aresetn) begin
		mii_tx_clk <= 1'b0;
	end else begin
		mii_tx_clk <= ~mii_tx_clk;
	end
end

always @(posedge mii_tx_clk or negedge aresetn) begin
	if (!aresetn) begin
		mii_crs <= 1'b0;
		mii_col <= 1'b0;
	end else begin
		if (mii_tx_en) begin
			mii_crs <= 1'b1;
			mii_col <= 1'b0;
		end else if (mii_tx_er) begin
			mii_crs <= 1'b0;
			mii_col <= 1'b1;
		end
	end
end

// Receive direction
reg [7:0] rx_buffer;
reg rx_buffer_valid;
reg rx_buffer_last;
reg [3:0] rx_data_shift;
reg rx_data_shift_valid;
reg [3:0] rx_data_shift_count;

typedef enum {IDLE, STROBE, INTER_FRAME_GAP, UNDERFLOW, RECOVERY} rx_state_t;
rx_state_t rx_state;

always @(posedge aclk or negedge aresetn) begin
	if (!aresetn) begin
		rx_tdata <= 8'b0;
		rx_tvalid <= 1'b0;
		rx_tlast <= 1'b0;
		rx_buffer <= 8'b0;
		rx_buffer_valid <= 1'b0;
		rx_buffer_last <= 1'b0;
		rx_data_shift <= 4'b0;
		rx_data_shift_valid <= 1'b0;
		rx_data_shift_count <= 4'b0;
		rx_state <= IDLE;
	end else begin
		case (rx_state)
			IDLE: begin
				if (rx_tvalid) begin
					rx_buffer <= rx_tdata;
					rx_buffer_valid <= 1'b1;
					rx_buffer_last <= rx_tlast;
					rx_state <= STROBE;
				end
			end
			STROBE: begin
				if (rx_data_shift_valid) begin
					rx_tdata <= {rx_data_shift, rx_buffer[3:0]};
					rx_tvalid <= 1'b1;
					rx_tlast <= rx_buffer_last;
					rx_buffer <= {rx_buffer[7:4], 4'b0};
					rx_data_shift_valid <= 1'b0;
					if (rx_buffer == 8'b0) begin
						rx_state <= INTER_FRAME_GAP;
					end
				end else if (rx_data_shift_count < 4) begin
					rx_data_shift_count <= rx_data_shift_count + 1;
				end else begin
					rx_data_shift <= mii_rx_data;
					rx_data_shift_valid <= 1'b1;
					rx_data_shift_count <= 4'b0;
				end
			end
			INTER_FRAME_GAP: begin
				if (rx_tvalid) begin
					rx_state <= IDLE;
				end
			end
			default: begin
				rx_state <= IDLE;
			end
		endcase
	end
end

always @(posedge mii_rx_clk or negedge aresetn) begin
	if (!aresetn) begin
		mii_rx_dv <= 1'b0;
		mii_rx_er <= 1'b0;
		mii_rx_data <= 4'b0;
	end else begin
		mii_rx_dv <= rx_tvalid;
		mii_rx_er <= 1'b0; // Error detection not implemented
		mii_rx_data <= rx_tdata[3:0];
	end
end

endmodule

