module UART_rx(
    input wire clk,
    input wire reset,
    input wire rx_data_in,
    output reg [7:0] rx_data_out
);

    parameter BAUD_RATE = 9600; // Example baud rate, adjust as needed
    parameter CLK_FREQ = 50000000; // Example clock frequency, adjust as needed
    parameter OVERSAMPLE = 16; // Oversampling factor

    // Calculate the number of clock cycles for one bit period
    localparam CLK_PER_BIT = CLK_FREQ / (BAUD_RATE * OVERSAMPLE);

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [7:0] data_register;
    reg [15:0] baud_counter;

    // State definitions
    localparam IDLE = 4'b0000;
    localparam START = 4'b0001;
    localparam DATA = 4'b0010;
    localparam STOP = 4'b0011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 0;
            data_register <= 0;
            baud_counter <= 0;
            rx_data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (rx_data_in == 0) begin
                        state <= START;
                        baud_counter <= 0;
                    end
                end
                START: begin
                    if (baud_counter == CLK_PER_BIT - 1) begin
                        state <= DATA;
                        bit_count <= 0;
                        baud_counter <= 0;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                DATA: begin
                    if (baud_counter == CLK_PER_BIT - 1) begin
                        data_register[bit_count] <= rx_data_in;
                        bit_count <= bit_count + 1;
                        baud_counter <= 0;
                        if (bit_count == 7) begin
                            state <= STOP;
                        end
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                STOP: begin
                    if (baud_counter == CLK_PER_BIT - 1) begin
                        state <= IDLE;
                        rx_data_out <= data_register;
                        baud_counter <= 0;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
            endcase
        end
    end

endmodule

module serial(clk, reset, rxD, sout, signal, counter);
    parameter n = 30;
    parameter count = 4;

    input clk;
    input reset;
    input rxD;

    output reg [n-1:0] sout;
    output reg signal;
    output reg [31:0] counter;

    reg [7:0] s_in;
    reg [2:0] delay;

    // Top-level sub-module to handle data formatting
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            s_in <= 8'b0;
        end else begin
            // Simulate data formatting or encoding
            s_in <= {s_in[6:0], rxD};
        end
    end

    // Main module state machine
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sout <= {n{1'b0}};
            signal <= 1'b0;
            counter <= 32'b0;
            delay <= 3'b0;
        end else begin
            if (counter == count) begin
                // Generate signal pulse for one clock cycle
                signal <= 1'b1;
                delay <= 3'b1;
            end else if (delay == 3'b1) begin
                // Reset signal and delay after one clock cycle
                signal <= 1'b0;
                delay <= 3'b0;
                // Shift data into sout
                sout <= {sout[n-9:0], s_in};
                // Increment counter
                counter <= counter + 1;
            end else begin
                // Continue shifting data and incrementing counter
                sout <= {sout[n-9:0], s_in};
                counter <= counter + 1;
            end

            // Reset counter after reaching count
            if (counter == count) begin
                counter <= 32'b0;
            end
        end
    end
endmodule

