module rx_tb;

    // Parameters
    parameter REF_CLK_PERIOD = 10; // Reference clock period in ns
    parameter BAUD_PERIOD = 10416; // Baud period in ns (9600 baud rate)
    parameter CLK_PER_BAUD = 10416 / REF_CLK_PERIOD; // Number of reference clock cycles per baud period
    parameter NUM_SAMPLES = 10; // Number of data samples to be tested

    // Signals
    reg ref_clk;
    reg baud_clk;
    reg reset;
    reg ser_in;
    wire [7:0] par_out;
    wire Rx_valid;
    wire err_par;
    wire err_stop;

    // Instantiate the UART_Rx module
    UART_Rx uart_rx (
        .ref_clk(ref_clk),
        .baud_clk(baud_clk),
        .reset(reset),
        .ser_in(ser_in),
        .par_out(par_out),
        .Rx_valid(Rx_valid),
        .err_par(err_par),
        .err_stop(err_stop)
    );

    // Instantiate the baud_gen module
    baud_gen baud_generator (
        .ref_clk(ref_clk),
        .baud_clk(baud_clk)
    );

    // Memory to store sample data
    reg [7:0] sample_data [0:NUM_SAMPLES-1];
    initial begin
        // Load sample data from a memory file
        $readmemh("sample_data.mem", sample_data);
    end

    // Reference clock generation
    always begin
        #REF_CLK_PERIOD / 2 ref_clk = ~ref_clk;
    end

    // Testbench process
    initial begin
        // Initialize signals
        ref_clk = 0;
        baud_clk = 0;
        reset = 1;
        ser_in = 0;

        // Apply reset pulse
        #REF_CLK_PERIOD reset = 0;
        #REF_CLK_PERIOD reset = 1;

        // Transmit sample data
        for (int i = 0; i < NUM_SAMPLES; i = i + 1) begin
            // Start bit
            ser_in = 0;
            repeat (CLK_PER_BAUD) @(posedge ref_clk);

            // Data bits
            for (int j = 0; j < 8; j = j + 1) begin
                ser_in = sample_data[i][7 - j];
                repeat (CLK_PER_BAUD) @(posedge ref_clk);
            end

            // Stop bit
            ser_in = 1;
            repeat (CLK_PER_BAUD) @(posedge ref_clk);

            // Wait for data to be received
            while (!Rx_valid) @(posedge ref_clk);

            // Check received data
            if (par_out !== sample_data[i] || err_par || err_stop) begin
                $display("Error: Sample %0d, Received: %0h, Expected: %0h", i, par_out, sample_data[i]);
            end else begin
                $display("Sample %0d received correctly", i);
            end
        end

        // Finish simulation
        $finish;
    end

endmodule

