module NAND3C(Y, A, B, C);
    input A, B, C;
    output Y;

    wire notA, notB, andAB, nandABC;

    // Invert inputs A and B
    not #1 notA (notA, A);
    not #1 notB (notB, B);

    // AND gate on inverted A and B
    and #1 andAB (andAB, notA, notB);

    // NAND gate on the result of AND and inverted C
    nand #1 nandABC (nandABC, andAB, notC);

    // Final output Y is the result of the NAND gate
    assign Y = nandABC;

    // Specify block for propagation delays
    specify
        // Propagation delay from A to Y
        (A => Y) = (10, 20);
        // Propagation delay from B to Y
        (B => Y) = (10, 20);
        // Propagation delay from C to Y
        (C => Y) = (10, 20);
    endspecify
endmodule

