module ACC_v2 #(
    parameter PE_SIZE           = 14,
    parameter DATA_WIDTH        = 8,
    parameter PSUM_WIDTH        = 32,
    parameter SLICING_IDX       = 32,
    parameter WEIGHT_ROW_NUM    = 70,
    parameter WEIGHT_COL_NUM    = 294
)(
    input   clk,
    input   rst_n,
    input   [PE_SIZE-1:0]   psum_en_row_i,
    input   [PSUM_WIDTH*PE_SIZE-1:0]    psum_row_i,
    output  [DATA_WIDTH*PE_SIZE-1:0]    ofmap_row_o,
    output                              ofmap_valid_o
);

// Internal signals
reg [PSUM_WIDTH*PE_SIZE-1:0] accumulated_psum;
reg [DATA_WIDTH*PE_SIZE-1:0] ofmap_row;
reg ofmap_valid;

// FIFOs for managing accumulation
reg [PSUM_WIDTH-1:0] fifo_data [0:PE_SIZE-1];
reg fifo_full [0:PE_SIZE-1];
reg fifo_empty [0:PE_SIZE-1];
reg [PE_SIZE-1:0] fifo_wr_en;
reg [PE_SIZE-1:0] fifo_rd_en;

// Initialize FIFOs
initial begin
    foreach (fifo_data[i]) fifo_data[i] = 0;
    foreach (fifo_full[i]) fifo_full[i] = 0;
    foreach (fifo_empty[i]) fifo_empty[i] = 1;
end

// FIFO write logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        foreach (fifo_full[i]) fifo_full[i] <= 0;
    end else begin
        foreach (fifo_full[i]) begin
            if (fifo_wr_en[i] && !fifo_full[i]) begin
                fifo_full[i] <= 1;
            end
        end
    end
end

// FIFO read logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        foreach (fifo_empty[i]) fifo_empty[i] <= 1;
    end else begin
        foreach (fifo_empty[i]) begin
            if (fifo_rd_en[i] && !fifo_empty[i]) begin
                fifo_empty[i] <= 0;
            end
        end
    end
end

// FIFO data handling
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        foreach (fifo_data[i]) fifo_data[i] <= 0;
    end else begin
        foreach (fifo_data[i]) begin
            if (fifo_wr_en[i] && !fifo_full[i]) begin
                fifo_data[i] <= psum_row_i[(i+1)*PSUM_WIDTH-1:i*PSUM_WIDTH];
            end
        end
    end
end

// Accumulation logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulated_psum <= 0;
    end else begin
        for (int i = 0; i < PE_SIZE; i = i + 1) begin
            if (psum_en_row_i[i] && !fifo_full[i]) begin
                accumulated_psum[(i+1)*PSUM_WIDTH-1:i*PSUM_WIDTH] <=
                    accumulated_psum[(i+1)*PSUM_WIDTH-1:i*PSUM_WIDTH] + fifo_data[i];
            end
        end
    end
end

// Output feature map generation
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ofmap_row <= 0;
        ofmap_valid <= 0;
    end else begin
        ofmap_row <= accumulated_psum;
        ofmap_valid <= 1;
    end
end

// Assign outputs
assign ofmap_row_o = ofmap_row;
assign ofmap_valid_o = ofmap_valid;

endmodule

module pcm(set, clk, q1, q2, q3);
    input set, clk;
    output reg q1, q2, q3;
    reg [4:0] count;

    always @(posedge clk) begin
        if (set) begin
            count <= 5'b1001; // Set count to 9
        end else if (count > 0) begin
            count <= count - 1; // Decrement count
        end
    end

    always @(count) begin
        case (count)
            7: begin
                q1 <= 1;
                q2 <= 0;
                q3 <= 0;
            end
            8: begin
                q1 <= 1;
                q2 <= 0;
                q3 <= 0;
            end
            9: begin
                q1 <= 1;
                q2 <= 0;
                q3 <= 0;
            end
            4: begin
                q1 <= 0;
                q2 <= 1;
                q3 <= 0;
            end
            5: begin
                q1 <= 0;
                q2 <= 1;
                q3 <= 0;
            end
            6: begin
                q1 <= 0;
                q2 <= 1;
                q3 <= 0;
            end
            1: begin
                q1 <= 0;
                q2 <= 0;
                q3 <= 1;
            end
            2: begin
                q1 <= 0;
                q2 <= 0;
                q3 <= 1;
            end
            3: begin
                q1 <= 0;
                q2 <= 0;
                q3 <= 1;
            end
            default: begin
                q1 <= 0;
                q2 <= 0;
                q3 <= 0;
            end
        endcase
    end
