module datamemory(
    input wire [31:0] Address,
    input wire [31:0] WriteData,
    input wire MemWrite,
    input wire MemRead,
    output reg [31:0] ReadData,
    output reg [3:0] O_LMotor,
    output reg [3:0] O_RMotor,
    input wire [6:0] I_Sensors,
    output reg [6:0] O_Leds,
    input wire [2:0] I_Rf,
    output reg O_Buzzer,
    output reg [7:0] O_Seg,
    output reg [2:0] O_El_7l,
    input wire [5:0] I_St_7l,
    input wire I_Clock
);

always @(posedge I_Clock) begin
    if (MemWrite) begin
        case (Address)
            32'h00000000: O_LMotor <= WriteData[3:0];
            32'h00000004: O_RMotor <= WriteData[3:0];
            32'h00000008: O_Leds <= WriteData[6:0];
            32'h0000000C: O_Buzzer <= WriteData[0];
            32'h00000010: O_Seg <= WriteData[7:0];
            32'h00000014: O_El_7l <= WriteData[2:0];
        endcase
    end

    if (MemRead) begin
        case (Address)
            32'h00000000: ReadData <= {28'b0, O_LMotor};
            32'h00000004: ReadData <= {28'b0, O_RMotor};
            32'h00000008: ReadData <= {25'b0, O_Leds};
            32'h0000000C: ReadData <= {31'b0, O_Buzzer};
            32'h00000010: ReadData <= {24'b0, O_Seg};
            32'h00000014: ReadData <= {29'b0, O_El_7l};
            32'h00000018: ReadData <= {25'b0, I_Sensors};
            32'h0000001C: ReadData <= {29'b0, I_Rf};
            32'h00000020: ReadData <= {26'b0, I_St_7l};
            default: ReadData <= 32'b0;
        endcase
    end
end

endmodule

