module table_101110101(input clk, input rst, input [8:0] addr, output reg match);
    // Define the target pattern to match against
    localparam TARGET_PATTERN = 9'b011001100;

    // Clocked always block to update the match output
    always @(posedge clk) begin
        if (rst) begin
            // Reset the match output to 0 when reset is active
