module ControlUnit(input[5:0] opcode,
		input[5:0] funct,
		output reg reg_dst,
		output reg reg_write,
		output reg[1:0] alu_src,
		output reg[3:0] alu_op,
		output reg branch,
		output reg mem_write,
		output reg mem_to_reg,
        	output reg zero_sign_ext,
		output reg mult_op,
		output reg mfhi,
		output reg mflo);

always @(*) begin
    // Initialize all outputs to zero
    reg_dst = 0;
    reg_write = 0;
    alu_src = 2'b00;
    alu_op = 4'b0000;
    branch = 0;
    mem_write = 0;
    mem_to_reg = 0;
    zero_sign_ext = 0;
    mult_op = 0;
    mfhi = 0;
    mflo = 0;

    // R-type instructions
    if (opcode == 6'b000000) begin
        reg_dst = 1;
        reg_write = 1;
        alu_src = 2'b00;
        case (funct)
            6'b100000: alu_op = 4'b0010; // add
            6'b100010: alu_op = 4'b0011; // sub
            6'b100100: alu_op = 4'b0100; // and
            6'b100101: alu_op = 4'b0101; // or
            6'b011000: alu_op = 4'b0110; // mult
            6'b011010: alu_op = 4'b0111; // div
            6'b010000: begin // mfhi
                alu_op = 4'b0000;
                mfhi = 1;
            end
            6'b010010: begin // mflo
                alu_op = 4'b0000;
                mflo = 1;
            end
            default: alu_op = 4'b0000;
        endcase
    end
    // I-type instructions
    else if (opcode == 6'b100011) begin // lw
        reg_write = 1;
        alu_src = 2'b10;
        mem_to_reg = 1;
        zero_sign_ext = 1;
    end
    else if (opcode == 6'b101011) begin // sw
        alu_src = 2'b10;
        mem_write = 1;
    end
    else if (opcode == 6'b000100) begin // beq
        alu_src = 2'b01;
        branch = 1;
    end
end

endmodule

module BranchLogic (zf, cf, nf, sel, branch, branch_out, flag_reg);
    input zf, cf, nf, branch;
    input [1:0] sel;
    output branch_out;
    output [2:0] flag_reg;

    // Internal signal to hold the selected flag
    wire selected_flag;

    // Mux to select the flag based on the sel input
    assign selected_flag = (sel == 2'b00) ? zf :
                          (sel == 2'b01) ? cf :
                          (sel == 2'b10) ? nf : 1'b0;

    // Determine if the branch should be taken
    assign branch_out = branch & selected_flag;

    // Update the flag register based on the selected condition
    assign flag_reg = {branch_out, selected_flag, ~selected_flag};
endmodule

module partsel_00076(ctrl, s0, s1, s2, s3, x0, x1, x2, x3, y);
  input [3:0] ctrl;
  input [2:0] s0;
  input [2:0] s1;
  input [2:0] s2;
  input [2:0] s3;
  input signed [31:0] x0;
  input [31:0] x1;
  input signed [31:0] x2;
  input signed [31:0] x3;
  output [127:0] y;

  // Internal signals
  wire [31:0] part0, part1, part2, part3;
  wire [31:0] temp0, temp1, temp2, temp3;

  // Bit selection based on s0, s1, s2, s3
  assign part0 = x0 >> s0;
  assign part1 = x1 >> s1;
  assign part2 = x2 >> s2;
  assign part3 = x3 >> s3;

  // Conditional operations based on ctrl
  always @(*) begin
    case (ctrl)
      4'b0000: begin
        temp0 = part0 & part1;
        temp1 = part2 | part3;
        temp2 = part0 ^ part2;
        temp3 = part1 ^ part3;
      end
      4'b0001: begin
        temp0 = part0 + part1;
        temp1 = part2 - part3;
        temp2 = part0 * part2;
        temp3 = part1 * part3;
      end
      4'b0010: begin
        temp0 = part0 << s0;
        temp1 = part1 << s1;
        temp2 = part2 << s2;
        temp3 = part3 << s3;
      end
      4'b0011: begin
        temp0 = part0 >> s0;
        temp1 = part1 >> s1;
        temp2 = part2 >> s2;
        temp3 = part3 >> s3;
      end
      default: begin
        temp0 = part0;
        temp1 = part1;
        temp2 = part2;
        temp3 = part3;
      end
    endcase
  end

  // Concatenate the results to form the 128-bit output
  assign y = {temp3, temp2, temp1, temp0};

endmodule

module chose(output reg [17:0] choout,
             input [16:0] choin,
             input resreg,
             input clk);

    reg [15:0] chotmp;

    always @(posedge clk) begin
        if (resreg == 1'b0) begin
            // Direct assignment with duplication of the 16th bit
            choout[16:0] <= choin;
            choout[17] <= choin[16];
        end else begin
            // Invert the lower 16 bits of choin
            chotmp <= ~choin[15:0];
            // Add 1 to perform two's complement
            chotmp <= chotmp + 1;
            // Assign the result to the lower 16 bits of choout
            choout[15:0] <= chotmp;
            // Set the upper two bits to the inverse of choin's 16th bit
            choout[17:16] <= {2{~choin[16]}};
        end
    end

endmodule

