assign s2 = OP_5to0[5] & OP_5to0[2];

// Combinational logic to generate Operation
assign Operation[3] = s1 | (s2 & ALU_op[1]);
assign Operation[2] = s1 | (s2 & ALU_op[0]);
assign Operation[1] = s1 | (s2 & ~ALU_op[1]);
