module alu_control (alu_op, func, alu_ctrl);
    input [2:0] alu_op;
    input [2:0] func;
    output [2:0] alu_ctrl;

    // Invert the input bits
    wire not_alu_op0 = ~alu_op[0];
    wire not_alu_op1 = ~alu_op[1];
    wire not_alu_op2 = ~alu_op[2];
    wire not_func0 = ~func[0];
    wire not_func1 = ~func[1];
    wire not_func2 = ~func[2];

    // Generate control signals using AND and OR gates
    wire and0 = alu_op[2] & not_alu_op1 & not_alu_op0; // R-type operations
    wire and1 = alu_op[2] & alu_op[1] & not_alu_op0; // I-type operations
    wire and2 = alu_op[2] & alu_op[1] & alu_op[0]; // J-type operations
    wire and3 = not_alu_op2 & not_alu_op1 & not_alu_op0 & func[2]; // ADD
    wire and4 = not_alu_op2 & not_alu_op1 & not_alu_op0 & not_func[2]; // SUB
    wire and5 = not_alu_op2 & not_alu_op1 & alu_op[0] & func[1]; // AND
    wire and6 = not_alu_op2 & not_alu_op1 & alu_op[0] & not_func[1]; // OR
    wire and7 = not_alu_op2 & alu_op[1] & not_alu_op0 & func[0]; // SLT

    // Combine the results using OR gates to produce the final control signals
    assign alu_ctrl[0] = and3 | and4 | and5 | and6 | and7;
    assign alu_ctrl[1] = and3 | and4 | and5 | and6;
    assign alu_ctrl[2] = and0 | and1 | and2;

endmodule

