module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);

always @(*) begin
    // Initialize BCD digits to zero
    Digit3 = 4'b0000;
    Digit2 = 4'b0000;
    Digit1 = 4'b0000;
    Digit0 = 4'b0000;

    // Iterate over each bit of the input binary number
    for (int i = 0; i < INPUT_BIT_WIDTH; i = i + 1) begin
        // Shift BCD digits left to make room for the next bit
        Digit3 = {Digit3[2:0], Digit2[3]};
        Digit2 = {Digit2[2:0], Digit1[3]};
        Digit1 = {Digit1[2:0], Digit0[3]};
        Digit0 = {Digit0[2:0], Input[i]};

        // Adjust BCD digits if they exceed 9
        if (Digit0 > 4'b1001) begin
            Digit0 = Digit0 + 4'b0110;
        end
        if (Digit1 > 4'b1001) begin
            Digit1 = Digit1 + 4'b0110;
        end
        if (Digit2 > 4'b1001) begin
            Digit2 = Digit2 + 4'b0110;
        end
        if (Digit3 > 4'b1001) begin
            Digit3 = Digit3 + 4'b0110;
        end
    end
end

endmodule

