module dac_write(clk, resetn, ch0, ch1, ch2, ch3, start, pwr, ready, clear, num_of_channels,
					CS, WR, DATA, GAIN, LDAC, CLR, PD, A0, A1);

input			clk, resetn;
input	[7:0]	ch0, ch1, ch2, ch3;
input			start, pwr, clear;
input	[1:0]	num_of_channels;
output			ready;

output			CS, WR, GAIN, LDAC, CLR, PD;
output	[7:0]	DATA;
output			A0, A1;

// State definitions
typedef enum reg [2:0] {
    IDLE,
    INIT,
    PREPARE_DATA,
    WRITE_DATA,
    UPDATE_DAC,
    POWER_DOWN
} state_t;

state_t current_state, next_state;

// Internal registers
reg [7:0] data_reg;
reg [1:0] channel_counter;
reg [2:0] state_counter;

// Assign outputs based on current state
assign CS = (current_state == WRITE_DATA) ? 1'b0 : 1'b1;
assign WR = (current_state == WRITE_DATA) ? 1'b0 : 1'b1;
assign GAIN = 1'b0; // Assuming GAIN is always 0 for simplicity
assign LDAC = (current_state == UPDATE_DAC) ? 1'b0 : 1'b1;
assign CLR = (current_state == POWER_DOWN) ? 1'b0 : 1'b1;
assign PD = (current_state == POWER_DOWN) ? 1'b0 : 1'b1;
assign A0 = channel_counter[0];
assign A1 = channel_counter[1];
assign DATA = data_reg;
assign ready = (current_state == IDLE);

// State machine logic
always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        current_state <= IDLE;
        channel_counter <= 2'b00;
        state_counter <= 3'b000;
        data_reg <= 8'b0;
    end else begin
        current_state <= next_state;
        case (current_state)
            IDLE: begin
                if (start) begin
                    next_state <= INIT;
                end else begin
                    next_state <= IDLE;
                end
            end
            INIT: begin
                next_state <= PREPARE_DATA;
                channel_counter <= 2'b00;
                state_counter <= 3'b000;
            end
            PREPARE_DATA: begin
                case (channel_counter)
                    2'b00: data_reg <= ch0;
                    2'b01: data_reg <= ch1;
                    2'b10: data_reg <= ch2;
                    2'b11: data_reg <= ch3;
                endcase
                if (channel_counter < num_of_channels) begin
                    next_state <= WRITE_DATA;
                    channel_counter <= channel_counter + 1;
                end else begin
                    next_state <= UPDATE_DAC;
                end
            end
            WRITE_DATA: begin
                next_state <= PREPARE_DATA;
            end
            UPDATE_DAC: begin
                next_state <= POWER_DOWN;
            end
            POWER_DOWN: begin
                if (clear) begin
                    next_state <= IDLE;
                end else begin
                    next_state <= POWER_DOWN;
                end
            end
            default: next_state <= IDLE;
        endcase
    end
end

endmodule

