    reg [27:0] counter;

    always @(posedge clock_in) begin
        // Increment the counter
        counter <= counter + 1;

        // Check if the counter has reached the divisor value
        if (counter == DIVISOR - 1) begin
            // Reset the counter
            counter <= 0;
        end

        // Generate the output clock with a 50% duty cycle
        if (counter < (DIVISOR / 2)) begin
            clock_out <= 1;
        end else begin
            clock_out <= 0;
        end
    end
