module noise(
  input i_clk,
  output reg signed [15:0] o_data
);

  // 16-bit register to store the LFSR state
  reg [15:0] r_shift16;

  // Initialize the LFSR state to 0xDEAD
  initial begin
    r_shift16 = 16'hDEAD;
  end

  // Sequential block to update the LFSR state and generate noise data
  always @(posedge i_clk) begin
    // Calculate the new bit by XORing specific bits of the current state
    reg new_bit;
    new_bit = r_shift16[15] ^ r_shift16[14] ^ r_shift16[12] ^ r_shift16[3];

    // Shift the LFSR state to the left and insert the new bit at the LSB
    r_shift16 <= {r_shift16[14:0], new_bit};

    // Assign the output data
    if (r_shift16 == 16'h8000) begin
      o_data <= 16'h8001; // Modify the output when the state is 0x8000
    end else begin
      o_data <= r_shift16; // Otherwise, output the current state
    end
  end

endmodule

