module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);

// Internal signals
reg [counterSize-1:0] counts[numOfCounters];
reg terminalCounts[numOfCounters];

// Generate loop to create the chain of counters
genvar i;
generate
   for (i = 0; i < numOfCounters; i = i + 1) begin : counter_chain
      // Enable signal for each counter
      wire enable;
      if (i == 0) begin
         assign enable = ~reset; // First counter is always enabled unless reset
      end else begin
         assign enable = terminalCounts[i-1]; // Subsequent counters are enabled by the previous counter's terminal count
      end

      // Counter logic
      always @(posedge clk or posedge reset) begin
         if (reset) begin
            counts[i] <= 0;
            terminalCounts[i] <= 0;
         end else if (enable) begin
            if (counts[i] == (1 << counterSize) - 1) begin
               counts[i] <= 0;
               terminalCounts[i] <= 1;
            end else begin
               counts[i] <= counts[i] + 1;
               terminalCounts[i] <= 0;
            end
         end
      end
   end
endgenerate

// Assign the output to the count of the last counter
assign outCount = counts[numOfCounters - 1];

endmodule

