    input [WIDTH-1:0] A;
    input [WIDTH-1:0] B;
    output reg [WIDTH-1:0] Res = 0;

    reg [WIDTH-1:0] a1;
    reg [WIDTH-1:0] b1;
    reg [WIDTH:0] p1;

    always @(A or B) begin
        a1 = A;
        b1 = B;
        p1 = {1'b0, A};

        for (integer i = 0; i < WIDTH; i = i + 1) begin
            if (p1[WIDTH:1] >= b1) begin
                p1 = p1 - {1'b0, b1};
                Res[i] = 1'b1;
            end else begin
                Res[i] = 1'b0;
            end
            p1 = {p1[WIDTH-1:0], 1'b0};
        end
    end
