    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset the counter to 1 (0001 in binary)
            count <= 4'b0001;
        end else begin
            // Increment the counter
            count <= count + 1;
            // Wrap around if the counter reaches 10 (1010 in binary)
            if (count == 4'b1010) begin
                count <= 4'b0001;
            end
        end
    end

    // Assign the counter value to the output
    assign q = count;

endmodule

