    // Detect any edge for each bit in the input vector
    always @(posedge clk) begin
        // Update the previous input value
        in_prev <= in;

        // Detect edges and set the corresponding bit in anyedge
        for (int i = 0; i < 8; i = i + 1) begin
            if (in[i] != in_prev[i]) begin
                anyedge[i] <= 1'b1;
