module TopModule (
    input  clk,
    input  j,
    input  k,
    output reg Q
);

always @(posedge clk) begin
    if (j == 1'b0 && k == 1'b0) begin
        // J = 0, K = 0: Q remains the same
        Q <= Q;
    end else if (j == 1'b0 && k == 1'b1) begin
        // J = 0, K = 1: Q becomes 0
        Q <= 1'b0;
    end else if (j == 1'b1 && k == 1'b0) begin
        // J = 1, K = 0: Q becomes 1
        Q <= 1'b1;
    end else if (j == 1'b1 && k == 1'b1) begin
        // J = 1, K = 1: Q becomes the complement of Qold
        Q <= ~Q;
    end
end

