    input  count_ena,
    input  data,
    output reg [3:0] q
);

always @(posedge clk) begin
    if (shift_ena) begin
        // Shift data in most-significant-bit first
        q <= {data, q[3:1]};
    end else if (count_ena) begin
        // Decrement the current value in the shift register
        q <= q - 1;
    end
    // If neither shift_ena nor count_ena is active, q remains unchanged
end

endmodule

module TopModule (
    input  [4:0] a,
    input  [4:0] b,
    input  [4:0] c,
    input  [4:0] d,
    input  [4:0] e,
    input  [4:0] f,
    output [7:0] w,
    output [7:0] x,
    output [7:0] y,
    output [7:0] z
);

    // Concatenate the input vectors
    wire [29:0] concatenated_input;
    assign concatenated_input = {a, b, c, d, e, f, 1'b1, 1'b1};

    // Split the concatenated input into four 8-bit output vectors
    assign w = concatenated_input[31:24];
    assign x = concatenated_input[23:16];
    assign y = concatenated_input[15:8];
    assign z = concatenated_input[7:0];

endmodule

module TopModule (
    input  p1a,
    input  p1b,
    input  p1c,
    input  p1d,
    input  p2a,
    input  p2b,
    input  p2c,
    input  p2d,
    output p1y,
    output p2y
);

// Implementing the first 4-input NAND gate
assign p1y = ~(p1a & p1b & p1c & p1d);

// Implementing the second 4-input NAND gate
assign p2y = ~(p2a & p2b & p2c & p2d);

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [31:0] in,
    output [31:0] out
);

reg [31:0] out_reg;
reg [31:0] in_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        out_reg <= 32'b0;
    end else begin
        for (integer i = 0; i < 32; i = i + 1) begin
            if (in_reg[i] == 1'b1 && in[i] == 1'b0) begin
                out_reg[i] <= 1'b1;
            end
        end
    end
end

always @(posedge clk) begin
    in_reg <= in;
end

assign out = out_reg;

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  slowena,
    output reg [3:0] q
);

    // Internal register to hold the counter value
    reg [3:0] count;

    // Synchronous reset and slow enable logic
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000; // Reset counter to 0
        end else if (slowena) begin
            count <= count + 1; // Increment counter if slowena is high
            if (count == 4'b1001) begin
                count <= 4'b0000; // Wrap around to 0 after 9
            end
        end
    end

    // Assign the counter value to the output
    assign q = count;

endmodule

module TopModule (
    input  clk,
    input  reset,
    output reg [2:0] ena,
    output reg [15:0] q
);

    // Internal signals
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // Counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            thousands <= 4'b0000;
            ena <= 3'b000;
        end else begin
            // Increment the ones place
            if (ones == 4'b1001) begin
                ones <= 4'b0000;
                ena[0] <= 1'b1;
            end else begin
                ones <= ones + 1;
                ena[0] <= 1'b0;
            end

            // Increment the tens place
            if (ena[0] && tens == 4'b1001) begin
                tens <= 4'b0000;
                ena[1] <= 1'b1;
            end else if (ena[0]) begin
                tens <= tens + 1;
                ena[1] <= 1'b0;
            end else begin
                ena[1] <= 1'b0;
            end

            // Increment the hundreds place
            if (ena[1] && hundreds == 4'b1001) begin
                hundreds <= 4'b0000;
                ena[2] <= 1'b1;
            end else if (ena[1]) begin
                hundreds <= hundreds + 1;
                ena[2] <= 1'b0;
            end else begin
                ena[2] <= 1'b0;
            end

            // Increment the thousands place
            if (ena[2] && thousands == 4'b1001) begin
                thousands <= 4'b0000;
            end else if (ena[2]) begin
                thousands <= thousands + 1;
            end
        end
    end

    // Assign the output
    assign q = {thousands, hundreds, tens, ones};

endmodule

module TopModule (
    input  x3,
    input  x2,
    input  x1,
    output f
);

assign f = (x2 & (~x3 | x1)) | (x3 & x1);

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

// Minimum Sum-of-Products (SOP) form for out_sop
// out_sop = a'b'c'd' + a'b'c'd + a'bc'd + a'bcd + ab'c'd + ab'cd + abc'd
assign out_sop = (~a & ~b & ~c & ~d) | 
                 (~a & ~b & ~c & d)  | 
                 (~a & ~b & c & ~d)  | 
                 (~a & ~b & c & d)   | 
                 (~a & b & ~c & ~d)  | 
                 (~a & b & ~c & d)   | 
                 (~a & b & c & ~d);

// Minimum Product-of-Sums (POS) form for out_pos
// out_pos = (a + b + c + d)(a + b + c' + d)(a + b' + c + d)(a' + b + c + d)
assign out_pos = (a | b | c | d) & 
                 (a | b | ~c | d) & 
                 (a | ~b | c | d) & 
                 (~a | b | c | d);

endmodule

module TopModule (
    input  mode,
    input  too_cold,
    input  too_hot,
    input  fan_on,
    output heater,
    output aircon,
    output fan
);

    // Assign heater based on mode and too_cold signal
    assign heater = (mode == 1) && too_cold;

    // Assign aircon based on mode and too_hot signal
    assign aircon = (mode == 0) && too_hot;

    // Assign fan based on heater, aircon, or fan_on signal
    assign fan = heater || aircon || fan_on;

endmodule

module TopModule (
    input  wire clk,
    input  wire resetn,
    input  wire [1:0] byteena,
    input  wire [15:0] d,
    output reg [15:0] q
);

    // Lower byte flip-flops (d[7:0])
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            q[7:0] <= 8'b0;
        end else if (byteena[0]) begin
            q[7:0] <= d[7:0];
        end
    end

    // Upper byte flip-flops (d[15:8])
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            q[15:8] <= 8'b0;
        end else if (byteena[1]) begin
            q[15:8] <= d[15:8];
        end
    end

endmodule

module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals
    reg xor_ff, and_ff, or_ff;

    // XOR gate
    wire xor_out;
    assign xor_out = x ^ xor_ff;

    // AND gate
    wire and_out;
    assign and_out = x & (~and_ff);

    // OR gate
    wire or_out;
    assign or_out = x | (~or_ff);

    // D flip-flops
    always @(posedge clk) begin
        xor_ff <= xor_out;
        and_ff <= and_out;
        or_ff  <= or_out;
    end

    // NOR gate
    assign z = ~(xor_ff | and_ff | or_ff);

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);

    // Intermediate wires
    wire and1_out;
    wire and2_out;

    // First layer: AND gates
    and and1 (.a(a), .b(b), .y(and1_out));
    and and2 (.a(c), .b(d), .y(and2_out));

    // Second layer: OR gate
    or or1 (.a(and1_out), .b(and2_out), .y(out));

    // Inverted output
    not not1 (.a(out), .y(out_n));

endmodule

module TopModule (
    input  clk,
    input  d,
    output q
);

reg q_posedge;
reg q_negedge;

// Single-edge triggered flip-flop on the rising edge
always @(posedge clk) begin
    q_posedge <= d;
end

// Single-edge triggered flip-flop on the falling edge
always @(negedge clk) begin
    q_negedge <= d;
end

// Multiplexer to select the output based on the current clock edge
assign q = (clk) ? q_posedge : q_negedge;

endmodule

module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);

// State transition logic
always_comb begin
    case (state)
        4'b0001: // State A
            next_state = (in == 0) ? 4'b0001 : 4'b0010;
        4'b0010: // State B
            next_state = (in == 0) ? 4'b0100 : 4'b0010;
        4'b0100: // State C
            next_state = (in == 0) ? 4'b0001 : 4'b1000;
        4'b1000: // State D
            next_state = (in == 0) ? 4'b0100 : 4'b0010;
        default:
            next_state = 4'b0000; // Should never happen with one-hot encoding
    endcase
end

// Output logic
always_comb begin
    case (state)
        4'b0001: // State A
            out = 0;
        4'b0010: // State B
            out = 0;
        4'b0100: // State C
            out = 0;
        4'b1000: // State D
            out = 1;
        default:
            out = 0; // Should never happen with one-hot encoding
    endcase
end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [9:0] data,
    output tc
);

    reg [9:0] counter;
    reg tc_reg;

    always @(posedge clk) begin
        if (load) begin
            counter <= data;
            tc_reg <= 0;
        end else if (counter > 0) begin
            counter <= counter - 1;
            tc_reg <= 0;
        end else begin
            tc_reg <= 1;
        end
    end

    assign tc = tc_reg;

endmodule

module TopModule (
    input  p1a,
