    input  A,
    input  B,
    input  C,
    output Z
);

    // Internal signals for the shift register
    reg [7:0] Q;

    // Shift register logic
    always @(posedge clk) begin
        if (enable) begin
            Q <= {S, Q[7:1]}; // Shift S into the MSB of Q
        end
    end

    // Multiplexer to select the appropriate output based on A, B, C
    assign Z = Q[{A, B, C}];

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  load,
    input  ena,
    input  [3:0] data,
    output [3:0] q
);

    reg [3:0] shift_reg;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            shift_reg <= 4'b0000;
        end else begin
            if (load) begin
                shift_reg <= data;
            end else if (ena) begin
                shift_reg <= {shift_reg[2:0], 1'b0};
            end
        end
    end

    assign q = shift_reg;

endmodule

module TopModule (
    input  clk,
    input  reset,
    output reg [4:0] q
);

// Define the tap positions
parameter TAP1 = 4; // Bit position 5 (0-based index)
parameter TAP2 = 2; // Bit position 3 (0-based index)

always @(posedge clk or posedge reset) begin
    if (reset) begin
        // Reset the LFSR to 1 (00001 in 5-bit representation)
        q <= 5'b00001;
    end else begin
        // Calculate the next state of the LFSR
        reg next_q;
        next_q = q[TAP1] ^ q[TAP2]; // XOR the tap bits
        q <= {q[3:0], next_q}; // Shift right and insert the new bit
    end
end

endmodule

module TopModule (
    input  a,
    input  b,
    output out_and,
    output out_or,
    output out_xor,
    output out_nand,
    output out_nor,
    output out_xnor,
    output out_anotb
);

    // AND gate
    assign out_and = a & b;

    // OR gate
    assign out_or = a | b;

    // XOR gate
    assign out_xor = a ^ b;

    // NAND gate
    assign out_nand = ~(a & b);

    // NOR gate
    assign out_nor = ~(a | b);

    // XNOR gate
    assign out_xnor = ~(a ^ b);

    // AND-NOT gate (a and-not b)
    assign out_anotb = a & ~b;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // State encoding: A = 2'b01, B = 2'b10
    reg [1:0] current_state, next_state;

    // Output logic
    assign z = (current_state == 2'b10);

    // State transition logic
    always @(*) begin
        case (current_state)
            2'b01: // State A
                if (x == 0)
                    next_state = 2'b01; // Stay in A
                else
                    next_state = 2'b10; // Go to B
            2'b10: // State B
                next_state = 2'b10; // Stay in B
            default:
                next_state = 2'b01; // Default to A
        endcase
    end

    // Sequential logic with asynchronous reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            current_state <= 2'b01; // Reset to state A
        else
            current_state <= next_state;
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // Define states for the Moore machine
    typedef enum logic [1:0] {
        IDLE,
        PROCESSING,
        DONE
    } state_t;

    state_t current_state, next_state;

    // Internal registers
    logic [1:0] count;
    logic [1:0] temp_z;

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= IDLE;
            count <= 2'b00;
            temp_z <= 1'b0;
        end else begin
            current_state <= next_state;
            if (next_state == PROCESSING) begin
                count <= count + 1;
            end
            if (next_state == DONE) begin
                count <= 2'b00;
            end
        end
    end

    // Next state logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (!areset) begin
                    next_state = PROCESSING;
                end
            end
            PROCESSING: begin
                if (count == 2'b11) begin
                    next_state = DONE;
                end
            end
            DONE: begin
                if (areset) begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Output logic
    always_comb begin
        z = 1'b0;
        case (current_state)
            IDLE: begin
                z = 1'b0;
            end
            PROCESSING: begin
                if (count == 2'b00) begin
                    temp_z = ~x;
                end else begin
                    temp_z = temp_z ^ x;
                end
                z = temp_z;
            end
            DONE: begin
                z = temp_z;
            end
        endcase
    end

endmodule

module TopModule (
    input  a,
