module TopModule (
    input  [5:0] y,  // 6-bit one-hot encoded state
    input  w,        // input signal
    output Y1,       // output for state flip-flop y[1]
    output Y3        // output for state flip-flop y[3]
);

// State output logic for Y1
assign Y1 = (y == 6'b000010) || (y == 6'b001000) || (y == 6'b100000);

// State output logic for Y3
assign Y3 = (y == 6'b000100) || (y == 6'b010000);

endmodule

module TopModule (
    input  c,
    input  d,
    output [3:0] mux_in
);

// Internal signals for 2-to-1 multiplexers
wire w0, w1, w2, w3;

// First level of 2-to-1 multiplexers
assign w0 = 1'b0; // From K-map: 00, 01, 11, 10 -> 0
assign w1 = c;   // From K-map: 00, 01, 11, 10 -> c
assign w2 = c;   // From K-map: 00, 01, 11, 10 -> c
assign w3 = 1'b1; // From K-map: 00, 01, 11, 10 -> 1

// Assigning the outputs to the 4-to-1 multiplexer inputs
assign mux_in[0] = w0;
assign mux_in[1] = w1;
assign mux_in[2] = w2;
assign mux_in[3] = w3;

