module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

assign out_both[3] = 1'b0; // in[3] has no neighbour to the left
assign out_both[2] = in[2] & in[3];
assign out_both[1] = in[1] & in[2];
assign out_both[0] = in[0] & in[1];

assign out_any[0] = 1'b0; // in[0] has no neighbour to the right
assign out_any[1] = in[1] | in[0];
assign out_any[2] = in[2] | in[1];
assign out_any[3] = in[3] | in[2];

assign out_different[0] = in[0] ^ in[3]; // in[0]'s neighbour to the left is in[3]
assign out_different[1] = in[1] ^ in[0];
assign out_different[2] = in[2] ^ in[1];
assign out_different[3] = in[3] ^ in[2];

endmodule

module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);

    // Define states for the FSM
    typedef enum logic [1:0] {
        IDLE,
        SHIFT_ENABLE_1,
        SHIFT_ENABLE_2,
        SHIFT_ENABLE_3,
        SHIFT_ENABLE_4
    } state_t;

    state_t current_state, next_state;

    // State register
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (reset) begin
                    next_state = SHIFT_ENABLE_1;
                end
            end
            SHIFT_ENABLE_1: begin
                next_state = SHIFT_ENABLE_2;
            end
            SHIFT_ENABLE_2: begin
                next_state = SHIFT_ENABLE_3;
            end
            SHIFT_ENABLE_3: begin
                next_state = SHIFT_ENABLE_4;
            end
            SHIFT_ENABLE_4: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always_comb begin
        shift_ena = 0;
        case (current_state)
            SHIFT_ENABLE_1,
            SHIFT_ENABLE_2,
            SHIFT_ENABLE_3,
            SHIFT_ENABLE_4: begin
                shift_ena = 1;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg start_shifting
);

    // Define states for the finite-state machine
    typedef enum logic [3:0] {
        IDLE,
        S1,
        S2,
        S3
    } state_t;

    // State register
    state_t current_state, next_state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            start_shifting <= 0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = IDLE;
            end

            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = IDLE;
            end

            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else
                    next_state = IDLE;
            end

            S3: begin
                if (data == 1'b1) begin
                    next_state = IDLE;
                    start_shifting = 1; // Sequence found
                end else
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

module TopModule (
