module TopModule (
    input  clk,
    input  a,
    output q
);

reg [1:0] count;
reg q_reg;

always @(posedge clk) begin
    if (a == 1) begin
        count <= count + 1;
    end else begin
        count <= 0;
    end

    if (count == 3) begin
        q_reg <= 1;
    end else if (a == 0) begin
        q_reg <= 0;
    end
end

assign q = q_reg;

endmodule

module TopModule (
    input  [5:0] y,
    input  w,
    output reg Y1,
    output reg Y3
);

    // State encoding
    // y[5:0] = 000001 for state A
    // y[5:0] = 000010 for state B
    // y[5:0] = 000100 for state C
    // y[5:0] = 001000 for state D
    // y[5:0] = 010000 for state E
    // y[5:0] = 100000 for state F

    // Next state logic
    always @(*) begin
        case (y)
            6'b000001: begin // State A
                Y1 = 1'b0; // Next state is B
                Y3 = 1'b0;
            end
            6'b000010: begin // State B
                if (w == 1'b0) begin
                    Y1 = 1'b0; // Next state is C
                    Y3 = 1'b0;
                end else begin
                    Y1 = 1'b0; // Next state is D
                    Y3 = 1'b1;
                end
            end
            6'b000100: begin // State C
                if (w == 1'b0) begin
                    Y1 = 1'b0; // Next state is E
                    Y3 = 1'b1;
                end else begin
                    Y1 = 1'b0; // Next state is D
                    Y3 = 1'b1;
                end
            end
            6'b001000: begin // State D
                if (w == 1'b0) begin
                    Y1 = 1'b0; // Next state is F
                    Y3 = 1'b1;
                end else begin
                    Y1 = 1'b0; // Next state is A
                    Y3 = 1'b0;
                end
            end
            6'b010000: begin // State E
                if (w == 1'b0) begin
                    Y1 = 1'b1; // Next state is E
                    Y3 = 1'b1;
                end else begin
                    Y1 = 1'b0; // Next state is D
                    Y3 = 1'b1;
                end
            end
            6'b100000: begin // State F
                if (w == 1'b0) begin
                    Y1 = 1'b0; // Next state is C
                    Y3 = 1'b1;
                end else begin
                    Y1 = 1'b0; // Next state is D
                    Y3 = 1'b1;
                end
            end
            default: begin
                Y1 = 1'b0;
                Y3 = 1'b0;
            end
        endcase
    end

endmodule

