    state_t current_state, next_state;

    // Output register
    logic out_reg;

    // State transition logic
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_B;
            out_reg <= 1'b1;
        end else begin
            current_state <= next_state;
            out_reg <= (next_state == STATE_B) ? 1'b1 : 1'b0;
        end
    end

    // Next state logic
    always_comb begin
        case (current_state)
            STATE_B: begin
                if (in == 0)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end
            STATE_A: begin
                if (in == 0)
                    next_state = STATE_B;
                else
                    next_state = STATE_A;
            end
            default: begin
                next_state = STATE_B;
            end
        endcase
    end

    // Assign output
    assign out = out_reg;

