        ONE,
        ONE_ZERO
    } state_t;

    // State register
    state_t state, next_state;

    // Output register
    logic z_reg, z_next;

    // State transition logic
    always_comb begin
        next_state = state;
        z_next = z_reg;

        case (state)
            IDLE: begin
                if (x == 1'b1) begin
                    next_state = ONE;
                end
            end

            ONE: begin
                if (x == 1'b0) begin
                    next_state = ONE_ZERO;
                end else if (x == 1'b1) begin
                    next_state = ONE;
                end else begin
                    next_state = IDLE;
                end
