            ONE_ZERO: begin
                if (x == 1'b1) begin
                    next_state = ONE;
                    z_next = 1'b1; // Sequence "101" detected
                end else if (x == 1'b0) begin
                    next_state = ONE_ZERO;
                end else begin
                    next_state = IDLE;
                end
            end
        endcase
    end

    // Sequential logic
    always_ff @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= IDLE;
            z_reg <= 1'b0;
        end else begin
            state <= next_state;
            z_reg <= z_next;
        end
    end

    // Output assignment
    assign z = z_reg;

