    .sum(sum[2]),
    .cout(carry[2])
  );

  // Instantiate the fourth full adder
  FullAdder fa3 (
    .a(x[3]),
    .b(y[3]),
    .cin(carry[2]),
    .sum(sum[3]),
    .cout(sum[4]) // The carry out of the last full adder is the overflow bit
  );

endmodule

