module TopModule (
  input [254:0] in,
  output reg [7:0] out
);

  // Internal signals to hold intermediate population counts
  reg [7:0] count1 [0:127];
  reg [7:0] count2 [0:63];
  reg [7:0] count3 [0:31];
  reg [7:0] count4 [0:15];
  reg [7:0] count5 [0:7];
  reg [7:0] count6 [0:3];
  reg [7:0] count7 [0:1];

  // First level of population count: count each 2-bit segment
  genvar i;
  generate
    for (i = 0; i < 128; i = i + 1) begin : count1_gen
      assign count1[i] = in[2*i] + in[2*i+1];
    end
  endgenerate

  // Second level of population count: count each 4-bit segment
  generate
    for (i = 0; i < 64; i = i + 1) begin : count2_gen
      assign count2[i] = count1[2*i] + count1[2*i+1];
    end
  endgenerate

  // Third level of population count: count each 8-bit segment
  generate
    for (i = 0; i < 32; i = i + 1) begin : count3_gen
      assign count3[i] = count2[2*i] + count2[2*i+1];
    end
  endgenerate

  // Fourth level of population count: count each 16-bit segment
  generate
    for (i = 0; i < 16; i = i + 1) begin : count4_gen
      assign count4[i] = count3[2*i] + count3[2*i+1];
    end
  endgenerate

  // Fifth level of population count: count each 32-bit segment
  generate
    for (i = 0; i < 8; i = i + 1) begin : count5_gen
      assign count5[i] = count4[2*i] + count4[2*i+1];
    end
  endgenerate

  // Sixth level of population count: count each 64-bit segment
  generate
    for (i = 0; i < 4; i = i + 1) begin : count6_gen
      assign count6[i] = count5[2*i] + count5[2*i+1];
    end
  endgenerate

  // Seventh level of population count: count each 128-bit segment
  generate
    for (i = 0; i < 2; i = i + 1) begin : count7_gen
      assign count7[i] = count6[2*i] + count6[2*i+1];
    end
  endgenerate

  // Final population count: count the two 128-bit segments
  assign out = count7[0] + count7[1];

endmodule

