module TopModule (
  input clk,
  input reset,
  output [3:1] ena,
  output reg [15:0] q
);

  // Internal signals for each BCD digit
  reg [3:0] ones;
  reg [3:0] tens;
  reg [3:0] hundreds;
  reg [3:0] thousands;

  // Enable signals for each digit
  assign ena[1] = (ones == 9);
  assign ena[2] = (tens == 9);
  assign ena[3] = (hundreds == 9);

  // Synchronous active-high reset
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      ones <= 4'b0000;
      tens <= 4'b0000;
      hundreds <= 4'b0000;
      thousands <= 4'b0000;
    end else begin
      // Increment the ones digit
      if (ena[1]) begin
        ones <= 4'b0000;
        if (ena[2]) begin
          tens <= tens + 1;
          if (ena[3]) begin
            hundreds <= hundreds + 1;
            if (thousands == 9) begin
              thousands <= 4'b0000;
            end else begin
              thousands <= thousands + 1;
            end
          end else begin
            hundreds <= 4'b0000;
          end
        end else begin
          tens <= 4'b0000;
        end
      end else begin
        ones <= ones + 1;
      end
    end
  end

  // Assign the BCD digits to the output
  assign q[3:0] = ones;
  assign q[7:4] = tens;
  assign q[11:8] = hundreds;
  assign q[15:12] = thousands;

endmodule

