  assign out_pos = (~a | ~b | ~c | ~d) & (~a | ~b | ~c | d) & (~a | b | ~c | ~d) & (~a | b | ~c | d) & (~a | b | c | ~d) & (a | ~b | ~c | d) & (a | ~b | c | ~d) & (a | b | ~c | d) & (a | b | c | ~d);

