module TopModule (
  input clk,
  input x,
  output z
);

  // Internal signals for flip-flops
  reg ff1_q, ff2_q, ff3_q;

  // Internal signals for gates
  wire xor_out, and_out, or_out;

  // XOR gate
  assign xor_out = x ^ ff1_q;

  // AND gate
  assign and_out = x & (~ff2_q);

  // OR gate
  assign or_out = x | (~ff3_q);

  // D flip-flops
  always @(posedge clk) begin
    ff1_q <= xor_out;
    ff2_q <= and_out;
    ff3_q <= or_out;
  end

  // NOR gate
  assign z = ~(xor_out | and_out | or_out);

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // Internal state register
  logic [1:0] state_reg;
  logic [1:0] state_next;

  // Asynchronous reset
  always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
      state_reg <= 2'b01; // Weakly not-taken
    end else begin
      state_reg <= state_next;
    end
  end

  // Next state logic
  always_comb begin
    state_next = state_reg;

    if (train_valid) begin
      if (train_taken) begin
        // Increment counter, saturate at 3
        if (state_reg < 2'b11) begin
          state_next = state_reg + 1;
        end
      end else begin
        // Decrement counter, saturate at 0
        if (state_reg > 2'b00) begin
          state_next = state_reg - 1;
        end
      end
    end
  end

  // Output assignment
  assign state = state_reg;

endmodule

