  reg tc_reg;

  always @(posedge clk) begin
    if (load) begin
      counter <= data;
      tc_reg <= 0;
    end else if (counter > 0) begin
      counter <= counter - 1;
      tc_reg <= 0;
    end else begin
      tc_reg <= 1;
    end
  end

  assign tc = tc_reg;

endmodule

