module TopModule (
  input clk,
  input reset,
  output reg [31:0] q
);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q <= 32'h1;
    end else begin
      // Calculate the next state of the LFSR
      reg next_q;
      next_q = q[0] ^ q[1] ^ q[22] ^ q[31]; // XOR the tapped bits
      q <= {q[30:0], next_q}; // Shift right and insert the new bit at the MSB
    end
  end

endmodule

