          next_state = STATE_A;
        end
      end
      default: begin
        next_state = STATE_B;
      end
    endcase
  end

  // Output logic
  always_comb begin
    case (current_state)
      STATE_B: begin
        out = 1;
      end
      STATE_A: begin
        out = 0;
      end
      default: begin
        out = 1;
      end
    endcase
  end

