  state_t current_state, next_state;

  // State register
  always_ff @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= LEFT;
    else
      current_state <= next_state;
  end

  // Next state logic
  always_comb begin
    case (current_state)
      LEFT: begin
        if (bump_left || bump_right)
          next_state = RIGHT;
        else
