  // Sequential logic for state and done signal
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      done <= 0;
    end else begin
      state <= next_state;
      if (next_state == IDLE) begin
        done <= 0;
      end else if (next_state == BYTE2) begin
        done <= 1;
      end
    end
  end

  // Combinational logic for state transitions
  always_comb begin
    next_state = state;

    case (state)
      IDLE: begin
        if (in[3] == 1) begin
          next_state = BYTE1;
        end
      end
      BYTE1: begin
        next_state = BYTE2;
      end
      BYTE2: begin
        if (in[3] == 1) begin
          next_state = BYTE1;
        end else begin
          next_state = IDLE;
        end
      end
    endcase
  end

endmodule

