  logic [2:0] data_bit_count;
  logic [7:0] received_data;

  // State register
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      data_bit_count <= 3'b000;
      received_data <= 8'b00000000;
      done <= 1'b0;
    end else begin
      state <= next_state;
      if (next_state == DATA_BITS) begin
        received_data <= {received_data[6:0], in};
      end
      if (next_state == IDLE) begin
        data_bit_count <= 3'b000;
        done <= 1'b0;
      end
      if (next_state == DONE) begin
        done <= 1'b1;
      end
    end
  end

  // Next state logic
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (in == 0) begin
          next_state = START_BIT;
        end
      end
      START_BIT: begin
        next_state = DATA_BITS;
        data_bit_count <= 3'b001;
      end
      DATA_BITS: begin
        if (data_bit_count < 8) begin
          next_state = DATA_BITS;
          data_bit_count <= data_bit_count + 1;
        end else begin
          next_state = STOP_BIT;
        end
      end
      STOP_BIT: begin
        if (in == 1) begin
          next_state = IDLE;
        end else begin
          next_state = ERROR;
        end
      end
      ERROR: begin
        if (in == 1) begin
          next_state = IDLE;
        end
      end
    endcase
  end

