  input clk,
  input reset,
  input in,
  output disc,
  output flag,
  output err
);

  // Define states for the Moore FSM
  typedef enum logic [3:0] {
    S0,  // Initial state
    S1,  // 1 detected
    S2,  // 11 detected
    S3,  // 111 detected
    S4,  // 1111 detected
    S5,  // 11111 detected
    S6,  // 111111 detected
    S7   // 1111111 detected
  } state_t;

  state_t current_state, next_state;

  // Output signals
  assign disc = (current_state == S6);
  assign flag = (current_state == S7);
  assign err  = (current_state == S7);

  // State transition logic
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always_comb begin
    case (current_state)
      S0: begin
        if (in) begin
          next_state = S1;
        end else begin
          next_state = S0;
        end
      end
      S1: begin
        if (in) begin
          next_state = S2;
        end else begin
          next_state = S0;
        end
      end
      S2: begin
        if (in) begin
          next_state = S3;
        end else begin
          next_state = S0;
        end
      end
      S3: begin
        if (in) begin
          next_state = S4;
        end else begin
          next_state = S0;
        end
      end
      S4: begin
        if (in) begin
          next_state = S5;
        end else begin
          next_state = S0;
        end
      end
      S5: begin
        if (in) begin
          next_state = S6;
        end else begin
          next_state = S0;
        end
      end
      S6: begin
        if (in) begin
          next_state = S7;
        end else begin
          next_state = S0;
        end
      end
      S7: begin
        if (in) begin
          next_state = S7;
        end else begin
          next_state = S0;
        end
      end
      default: begin
        next_state = S0;
      end
    endcase
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // Define states
  typedef enum logic [1:0] {
    WALK_LEFT,
    WALK_RIGHT,
    FALL
  } state_t;

  // State register
  state_t state, next_state;

  // Output logic
  always_comb begin
    walk_left = 0;
    walk_right = 0;
    aaah = 0;

    case (state)
      WALK_LEFT: begin
        walk_left = 1;
        if (!ground) begin
          aaah = 1;
          next_state = FALL;
        end else if (bump_left || bump_right) begin
          next_state = WALK_RIGHT;
        end else begin
          next_state = WALK_LEFT;
        end
      end

      WALK_RIGHT: begin
        walk_right = 1;
        if (!ground) begin
          aaah = 1;
          next_state = FALL;
        end else if (bump_left || bump_right) begin
          next_state = WALK_LEFT;
        end else begin
          next_state = WALK_RIGHT;
        end
      end

      FALL: begin
        aaah = 1;
        if (ground) begin
          next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
        end else begin
          next_state = FALL;
        end
      end
    endcase
  end

  // State transition logic
  always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= WALK_LEFT;
    end else begin
      state <= next_state;
    end
  end

endmodule

module TopModule (
  input in,
  input [9:0] state,
  output [9:0] next_state,
  output out1,
  output out2
);

  // Initialize next_state to 0
  assign next_state = 10'b0;

  // Initialize outputs to 0
  assign out1 = 0;
  assign out2 = 0;

  // State transition logic
  always @(*) begin
    if (state[0]) begin // S0
      if (in == 0) next_state[0] = 1;
      else next_state[1] = 1;
    end
    if (state[1]) begin // S1
      if (in == 0) next_state[0] = 1;
      else next_state[2] = 1;
    end
    if (state[2]) begin // S2
      if (in == 0) next_state[0] = 1;
      else next_state[3] = 1;
    end
    if (state[3]) begin // S3
      if (in == 0) next_state[0] = 1;
      else next_state[4] = 1;
    end
    if (state[4]) begin // S4
      if (in == 0) next_state[0] = 1;
      else next_state[5] = 1;
    end
    if (state[5]) begin // S5
      if (in == 0) next_state[8] = 1;
      else next_state[6] = 1;
    end
    if (state[6]) begin // S6
      if (in == 0) next_state[9] = 1;
      else next_state[7] = 1;
    end
    if (state[7]) begin // S7
      if (in == 0) next_state[0] = 1;
      else next_state[7] = 1;
    end
    if (state[8]) begin // S8
      if (in == 0) next_state[0] = 1;
      else next_state[1] = 1;
    end
    if (state[9]) begin // S9
      if (in == 0) next_state[0] = 1;
      else next_state[1] = 1;
    end
  end

  // Output logic
  always @(*) begin
    if (state[7]) begin // S7
      out1 = 0;
      out2 = 1;
    end else if (state[8]) begin // S8
      out1 = 1;
      out2 = 0;
    end else if (state[9]) begin // S9
      out1 = 1;
      out2 = 1;
    end else begin
      out1 = 0;
      out2 = 0;
    end
  end

endmodule

module TopModule (
  input clk,
  input load,
  input [255:0] data,
  output reg [255:0] q
);

  // Internal signal to store the next state
  reg [255:0] next_q;

  // Function to calculate the number of neighbors for a given cell
  function integer count_neighbors;
    input [255:0] state;
    input [7:0] row;
    input [7:0] col;
    integer count;
    integer r, c;

    count = 0;
    for (r = -1; r <= 1; r = r + 1) begin
      for (c = -1; c <= 1; c = c + 1) begin
        if (r == 0 && c == 0) continue; // Skip the cell itself
        count = count + state[(16 * ((row + r) % 16) + (col + c) % 16)];
      end
    end
    count_neighbors = count;
  endfunction

  // Sequential logic to update the state
  always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      q <= next_q;
    end
  end

  // Combinatorial logic to calculate the next state
  always @(*) begin
    for (integer i = 0; i < 256; i = i + 1) begin
      integer row = i / 16;
      integer col = i % 16;
      integer neighbors = count_neighbors(q, row, col);

      case (neighbors)
        0, 1: next_q[i] = 0;
        2: next_q[i] = q[i];
        3: next_q[i] = 1;
        default: next_q[i] = 0;
      endcase
    end
  end

endmodule

module TopModule (
  input clock,
  input a,
  output reg p,
  output reg q
);

  always @(posedge clock) begin
    if (a == 1'b1) begin
      p <= 1'b1;
      q <= 1'b0;
    end else begin
      p <= 1'b0;
      q <= 1'b1;
    end
  end

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output [7:0] out_byte,
  output done
);

  // Define states for the FSM
  typedef enum logic [2:0] {
    IDLE,
    START_BIT,
    DATA_BITS,
    STOP_BIT
  } state_t;

  state_t state, next_state;
  logic [2:0] bit_count;
  logic [7:0] data_byte;

  // State register
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      bit_count <= 0;
      data_byte <= 0;
      done <= 0;
    end else begin
      state <= next_state;
      if (next_state == DATA_BITS) begin
        data_byte <= {data_byte[6:0], in};
      end
      if (next_state == STOP_BIT) begin
        done <= 1;
      end else if (next_state == IDLE) begin
        done <= 0;
      end
    end
  end

  // Next state logic
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (in == 0) begin
          next_state = START_BIT;
        end
      end
      START_BIT: begin
        next_state = DATA_BITS;
        bit_count = 0;
      end
      DATA_BITS: begin
        if (bit_count < 7) begin
          next_state = DATA_BITS;
          bit_count = bit_count + 1;
        end else begin
          next_state = STOP_BIT;
        end
      end
      STOP_BIT: begin
        if (in == 1) begin
          next_state = IDLE;
        end
      end
    endcase
  end

  // Output assignment
  assign out_byte = data_byte;

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output q,
  output state
);

  reg state_reg;
  reg q_reg;

  always @(posedge clk) begin
    case ({state_reg, a, b})
      3'b000: begin
        state_reg <= 0;
        q_reg <= 0;
      end
      3'b001: begin
        state_reg <= 0;
        q_reg <= 0;
      end
      3'b010: begin
        state_reg <= 0;
        q_reg <= 0;
      end
      3'b011: begin
        state_reg <= 0;
        q_reg <= 0;
      end
      3'b100: begin
        state_reg <= 1;
        q_reg <= 1;
      end
      3'b101: begin
        state_reg <= 0;
        q_reg <= 1;
      end
      3'b110: begin
        state_reg <= 0;
        q_reg <= 0;
      end
      3'b111: begin
        state_reg <= 1;
        q_reg <= 0;
      end
      default: begin
        state_reg <= 0;
        q_reg <= 0;
      end
    endcase
  end

  assign state = state_reg;
  assign q = q_reg;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // State encoding
  typedef enum logic [1:0] {
    STATE_A = 2'b00,
    STATE_B = 2'b01,
    STATE_C = 2'b10,
    STATE_D = 2'b11
  } state_t;

  state_t current_state, next_state;

  // State flip-flops
  always_ff @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      current_state <= STATE_A;
    end else begin
      current_state <= next_state;
    end
  end

  // State transition logic
  always_comb begin
    next_state = current_state;

    case (current_state)
      STATE_A: begin
        if (r[0] == 1'b1) begin
          next_state = STATE_B;
        end else if (r[1] == 1'b1) begin
          next_state = STATE_C;
        end else if (r[2] == 1'b1) begin
          next_state = STATE_D;
        end
      end

      STATE_B: begin
        if (r[0] == 1'b1) begin
          next_state = STATE_B;
        end else begin
          next_state = STATE_A;
        end
      end

      STATE_C: begin
        if (r[1] == 1'b1) begin
          next_state = STATE_C;
        end else begin
          next_state = STATE_A;
        end
      end

      STATE_D: begin
        next_state = STATE_A;
      end

      default: begin
        next_state = STATE_A;
      end
    endcase
  end

  // Output logic
  always_comb begin
    g = 3'b000;

    case (current_state)
      STATE_B: begin
        g[0] = 1'b1;
      end

      STATE_C: begin
        g[1] = 1'b1;
      end

      STATE_D: begin
        g[2] = 1'b1;
      end

      default: begin
        g = 3'b000;
      end
    endcase
  end

endmodule

module TopModule (
  input clk,
  input reset,
  input [2:0] s,
  output reg fr2,
  output reg fr1,
  output reg fr0,
  output reg dfr
);

  // Internal state to track the previous sensor state
  reg [2:0] prev_s;

  // State machine states
  typedef enum reg [1:0] {
    LOW_LEVEL,
    BETWEEN_S1_S0,
    BETWEEN_S2_S1,
    ABOVE_S2
  } state_t;

  state_t current_state, next_state;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= LOW_LEVEL;
      prev_s <= 3'b000;
    end else begin
      current_state <= next_state;
      prev_s <= s;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      LOW_LEVEL: begin
        if (s == 3'b000) begin
          next_state = LOW_LEVEL;
        end else if (s == 3'b001) begin
          next_state = BETWEEN_S1_S0;
        end else if (s == 3'b011) begin
          next_state = BETWEEN_S2_S1;
        end else if (s == 3'b111) begin
          next_state = ABOVE_S2;
        end
      end
      BETWEEN_S1_S0: begin
        if (s == 3'b001) begin
          next_state = BETWEEN_S1_S0;
        end else if (s == 3'b000) begin
          next_state = LOW_LEVEL;
        end else if (s == 3'b011) begin
          next_state = BETWEEN_S2_S1;
        end else if (s == 3'b111) begin
          next_state = ABOVE_S2;
        end
      end
      BETWEEN_S2_S1: begin
        if (s == 3'b011) begin
          next_state = BETWEEN_S2_S1;
        end else if (s == 3'b001) begin
          next_state = BETWEEN_S1_S0;
        end else if (s == 3'b000) begin
          next_state = LOW_LEVEL;
        end else if (s == 3'b111) begin
          next_state = ABOVE_S2;
        end
      end
      ABOVE_S2: begin
        if (s == 3'b111) begin
          next_state = ABOVE_S2;
        end else if (s == 3'b011) begin
          next_state = BETWEEN_S2_S1;
        end else if (s == 3'b001) begin
          next_state = BETWEEN_S1_S0;
        end else if (s == 3'b000) begin
          next_state = LOW_LEVEL;
        end
      end
      default: begin
        next_state = LOW_LEVEL;
      end
    endcase
  end

  // Output logic
  always @(*) begin
    fr2 = 1'b0;
    fr1 = 1'b0;
    fr0 = 1'b0;
    dfr = 1'b0;

    case (current_state)
      LOW_LEVEL: begin
        fr2 = 1'b1;
        fr1 = 1'b1;
        fr0 = 1'b1;
        dfr = 1'b1;
      end
      BETWEEN_S1_S0: begin
        fr0 = 1'b1;
        if (prev_s < s) begin
          dfr = 1'b1;
        end
      end
      BETWEEN_S2_S1: begin
        fr0 = 1'b1;
        fr1 = 1'b1;
        if (prev_s < s) begin
          dfr = 1'b1;
        end
      end
      ABOVE_S2: begin
        // No flow rate
      end
      default: begin
        fr2 = 1'b1;
        fr1 = 1'b1;
        fr0 = 1'b1;
        dfr = 1'b1;
      end
    endcase
  end

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // Next state logic
  always @(*) begin
    case (state)
      10'b0000000001: // State S
        if (d == 0)
          B3_next = 1'b0;
        else
          B3_next = 1'b0;
        S_next = 1'b1;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0000000010: // State S1
        if (d == 0)
          B3_next = 1'b0;
        else
          B3_next = 1'b0;
        S_next = 1'b1;
        S1_next = 1'b1;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0000000100: // State S11
        if (d == 0)
          B3_next = 1'b0;
        else
          B3_next = 1'b0;
        S_next = 1'b0;
        S1_next = 1'b1;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0000001000: // State S110
        if (d == 0)
          B3_next = 1'b0;
        else
          B3_next = 1'b0;
        S_next = 1'b1;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0000010000: // State B0
        B3_next = 1'b0;
        S_next = 1'b0;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0000100000: // State B1
        B3_next = 1'b0;
        S_next = 1'b0;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0001000000: // State B2
        B3_next = 1'b0;
        S_next = 1'b0;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0010000000: // State B3
        B3_next = 1'b1;
        S_next = 1'b0;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;

      10'b0100000000: // State Count
        B3_next = 1'b0;
        S_next = 1'b0;
        S1_next = 1'b0;
        Count_next = 1'b1;
        Wait_next = 1'b0;

      10'b1000000000: // State Wait
        B3_next = 1'b0;
        S_next = 1'b1;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b1;

      default:
        B3_next = 1'b0;
        S_next = 1'b0;
        S1_next = 1'b0;
        Count_next = 1'b0;
        Wait_next = 1'b0;
    endcase
  end

  // Output logic
  assign shift_ena = state[4] | state[5] | state[6] | state[7];
  assign counting = state[8];
  assign done = state[9];

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output reg shift_ena,
  output reg counting,
  input done_counting,
  output reg done,
  input ack
);

  // Define states
  typedef enum reg [2:0] {
    IDLE,
    SEARCH_110,
    SEARCH_1101,
    SHIFT_IN,
    WAIT_COUNT,
    DONE_WAIT_ACK
  } state_t;

  state_t state, next_state;

  // State register
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    shift_ena = 1'b0;
    counting = 1'b0;
    done = 1'b0;

    case (state)
      IDLE: begin
        if (data == 1'b1) begin
          next_state = SEARCH_110;
        end
      end

      SEARCH_110: begin
        if (data == 1'b1) begin
          next_state = SEARCH_1101;
        end else if (data == 1'b0) begin
          next_state = IDLE;
        end else begin
          next_state = IDLE;
        end
      end

      SEARCH_1101: begin
        if (data == 1'b0) begin
          next_state = SHIFT_IN;
        end else if (data == 1'b1) begin
          next_state = SEARCH_110;
        end else begin
          next_state = IDLE;
        end
      end

      SHIFT_IN: begin
        shift_ena = 1'b1;
        if (data == 1'b1) begin
          next_state = SEARCH_110;
        end else if (data == 1'b0) begin
          next_state = IDLE;
        end else begin
          next_state = IDLE;
        end
      end

      WAIT_COUNT: begin
        counting = 1'b1;
        if (done_counting) begin
          next_state = DONE_WAIT_ACK;
        end
      end

      DONE_WAIT_ACK: begin
        done = 1'b1;
        if (ack) begin
          next_state = IDLE;
        end
      end

      default: begin
        next_state = IDLE;
      end
    endcase
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define states
  typedef enum logic [1:0] {
    WALK_LEFT,
    WALK_RIGHT,
    FALL,
    DIG_LEFT,
    DIG_RIGHT
  } state_t;

  state_t state, next_state;

  // State register
  always_ff @(posedge clk or posedge areset) begin
    if (areset)
      state <= WALK_LEFT;
    else
      state <= next_state;
  end

  // Next state logic
  always_comb begin
    case (state)
      WALK_LEFT: begin
        if (!ground)
          next_state = FALL;
        else if (dig)
          next_state = DIG_LEFT;
        else if (bump_left)
          next_state = WALK_RIGHT;
        else if (bump_right)
          next_state = WALK_LEFT;
        else
          next_state = WALK_LEFT;
      end

      WALK_RIGHT: begin
        if (!ground)
          next_state = FALL;
        else if (dig)
          next_state = DIG_RIGHT;
        else if (bump_right)
          next_state = WALK_LEFT;
        else if (bump_left)
          next_state = WALK_RIGHT;
        else
          next_state = WALK_RIGHT;
      end

      FALL: begin
        if (ground)
          next_state = (state == DIG_LEFT) ? WALK_LEFT : WALK_RIGHT;
        else
          next_state = FALL;
      end

      DIG_LEFT: begin
        if (!ground)
          next_state = FALL;
        else if (ground && (bump_left || bump_right))
          next_state = WALK_LEFT;
        else
          next_state = DIG_LEFT;
      end

      DIG_RIGHT: begin
        if (!ground)
          next_state = FALL;
        else if (ground && (bump_left || bump_right))
          next_state = WALK_RIGHT;
        else
          next_state = DIG_RIGHT;
      end

      default: next_state = WALK_LEFT;
    endcase
  end

  // Output logic
  always_comb begin
    walk_left = 0;
    walk_right = 0;
    aaah = 0;
    digging = 0;

    case (state)
      WALK_LEFT: walk_left = 1;
      WALK_RIGHT: walk_right = 1;
      FALL: aaah = 1;
      DIG_LEFT: digging = 1;
      DIG_RIGHT: digging = 1;
    endcase
  end

endmodule

module TopModule (
  input clk,
  input areset,

  input predict_valid,
  input [6:0] predict_pc,
  output predict_taken,
  output [6:0] predict_history,

  input train_valid,
  input train_taken,
  input train_mispredicted,
  input [6:0] train_history,
  input [6:0] train_pc
);

  // 128-entry table of two-bit saturating counters
  reg [1:0] pht [0:127];

  // 7-bit global branch history register
  reg [6:0] global_history;

  // Internal signals
  reg [6:0] predict_index;
  reg [6:0] train_index;
  reg [1:0] predict_counter;
  reg [1:0] train_counter;

  // Initialize PHT and global history on reset
  initial begin
    for (int i = 0; i < 128; i = i + 1) begin
      pht[i] = 2'b10; // Initialize counters to weakly taken
    end
    global_history = 7'b0;
  end

  // Asynchronous reset
  always @(posedge areset) begin
    for (int i = 0; i < 128; i = i + 1) begin
      pht[i] <= 2'b10; // Initialize counters to weakly taken
    end
    global_history <= 7'b0;
  end

  // Calculate indices
  assign predict_index = predict_pc ^ global_history;
  assign train_index = train_pc ^ train_history;

  // Read counter for prediction
  assign predict_counter = pht[predict_index];
  assign predict_taken = predict_counter[1]; // MSB indicates taken

  // Update global history register
  always @(posedge clk) begin
    if (train_valid) begin
      if (train_mispredicted) begin
        global_history <= train_history;
      end else begin
        global_history <= {global_history[5:0], train_taken};
      end
    end else if (predict_valid) begin
      global_history <= {global_history[5:0], predict_taken};
    end
  end

  // Update PHT on training
  always @(posedge clk) begin
    if (train_valid) begin
      case (train_counter)
        2'b00: pht[train_index] <= (train_taken) ? 2'b01 : 2'b00;
        2'b01: pht[train_index] <= (train_taken) ? 2'b10 : 2'b00;
        2'b10: pht[train_index] <= (train_taken) ? 2'b11 : 2'b01;
        2'b11: pht[train_index] <= (train_taken) ? 2'b11 : 2'b10;
      endcase
    end
  end

  // Assign output for prediction history
  assign predict_history = global_history;

endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output [23:0] out_bytes,
  output done
);

  // Define states for the FSM
  typedef enum logic [1:0] {
    IDLE,
    FIRST_BYTE,
    SECOND_BYTE,
    THIRD_BYTE
  } state_t;

  state_t state, next_state;

  // Registers for storing the received bytes
  reg [7:0] byte1, byte2, byte3;

  // Register for done signal
  reg done_reg;

  // FSM state transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      done_reg <= 0;
    end else begin
      state <= next_state;
      done_reg <= (next_state == IDLE) ? 0 : done_reg;
    end
  end

  // FSM next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (in[3] == 1) begin
          next_state = FIRST_BYTE;
          byte1 = in;
        end
      end
      FIRST_BYTE: begin
        next_state = SECOND_BYTE;
        byte2 = in;
      end
      SECOND_BYTE: begin
        next_state = THIRD_BYTE;
        byte3 = in;
      end
      THIRD_BYTE: begin
        next_state = IDLE;
      end
    endcase
  end

  // Output logic
  assign out_bytes = {byte1, byte2, byte3};
  assign done = done_reg;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  input dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  // Define states
  typedef enum logic [3:0] {
    WALK_LEFT,
    WALK_RIGHT,
    FALL,
    DIG_LEFT,
    DIG_RIGHT,
    SPLATTER
  } state_t;

  state_t state, next_state;
  logic fall_count;
  logic [3:0] fall_counter;

  // State register
  always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= WALK_LEFT;
      fall_counter <= 0;
    end else begin
      state <= next_state;
      if (next_state == FALL)
        fall_counter <= fall_counter + 1;
      else if (next_state == WALK_LEFT || next_state == WALK_RIGHT)
        fall_counter <= 0;
    end
  end

  // Next state logic
  always_comb begin
    next_state = state;
    case (state)
      WALK_LEFT: begin
        if (bump_left || bump_right)
          next_state = WALK_RIGHT;
        else if (!ground)
          next_state = FALL;
        else if (dig)
          next_state = DIG_LEFT;
      end
      WALK_RIGHT: begin
        if (bump_left || bump_right)
          next_state = WALK_LEFT;
        else if (!ground)
          next_state = FALL;
        else if (dig)
          next_state = DIG_RIGHT;
      end
      FALL: begin
        if (ground && fall_counter > 20)
          next_state = SPLATTER;
        else if (ground)
          next_state = (state == DIG_LEFT) ? WALK_LEFT : WALK_RIGHT;
      end
      DIG_LEFT: begin
        if (!ground)
          next_state = FALL;
        else if (bump_left || bump_right)
          next_state = state;
      end
      DIG_RIGHT: begin
        if (!ground)
          next_state = FALL;
        else if (bump_left || bump_right)
          next_state = state;
      end
      SPLATTER: begin
        next_state = SPLATTER;
      end
    endcase
  end

  // Output logic
  always_comb begin
    walk_left = 0;
    walk_right = 0;
    aaah = 0;
    digging = 0;

    case (state)
      WALK_LEFT: walk_left = 1;
      WALK_RIGHT: walk_right = 1;
      FALL: aaah = 1;
      DIG_LEFT: digging = 1;
      DIG_RIGHT: digging = 1;
      SPLATTER: begin
        walk_left = 0;
        walk_right = 0;
        aaah = 0;
        digging = 0;
      end
    endcase
  end

endmodule

module TopModule (
  input wire clk,
  input wire reset,
  input wire data,
  output wire [3:0] count,
  output reg counting,
  output reg done,
  input wire ack
);

  // State definitions
  typedef enum reg [2:0] {
    IDLE,
    SEARCH_1101,
    SHIFT_DELAY,
    COUNTING,
    DONE_WAIT
  } state_t;

  state_t state, next_state;

  // Internal signals
  reg [3:0] delay;
  reg [11:0] timer_count;
  reg [3:0] remaining_time;

  // State transition logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      counting <= 0;
      done <= 0;
      delay <= 0;
      timer_count <= 0;
      remaining_time <= 0;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: begin
        if (data == 1) begin
          next_state = SEARCH_1101;
        end
      end
      SEARCH_1101: begin
        case ({data, state})
          {1, SEARCH_1101}: next_state = SEARCH_1101;
          {1, SEARCH_1101}: next_state = SEARCH_1101;
          {0, SEARCH_1101}: next_state = IDLE;
          {1, SEARCH_1101}: next_state = SEARCH_1101;
          {0, SEARCH_1101}: next_state = IDLE;
          {1, SEARCH_1101}: next_state = SHIFT_DELAY;
          default: next_state = IDLE;
        endcase
      end
      SHIFT_DELAY: begin
        if (timer_count < 4) begin
          next_state = SHIFT_DELAY;
        end else begin
          next_state = COUNTING;
        end
      end
      COUNTING: begin
        if (timer_count == (delay + 1) * 1000) begin
          next_state = DONE_WAIT;
        end else begin
          next_state = COUNTING;
        end
      end
      DONE_WAIT: begin
        if (ack) begin
          next_state = IDLE;
        end else begin
          next_state = DONE_WAIT;
        end
      end
    endcase
  end

  // Output logic
  always @(*) begin
    counting = 0;
    done = 0;
    case (state)
      COUNTING: begin
        counting = 1;
        remaining_time = delay - (timer_count / 1000);
      end
      DONE_WAIT: begin
        done = 1;
      end
    endcase
  end

  // Data shift logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      timer_count <= 0;
      delay <= 0;
    end else begin
      case (state)
        SHIFT_DELAY: begin
          if (timer_count < 4) begin
            delay <= {delay[2:0], data};
            timer_count <= timer_count + 1;
          end
        end
        COUNTING: begin
          if (timer_count < (delay + 1) * 1000) begin
            timer_count <= timer_count + 1;
          end
        end
        DONE_WAIT: begin
          timer_count <= 0;
        end
        default: begin
          timer_count <= 0;
        end
      endcase
    end
  end

  // Assign count output
  assign count = remaining_time;

endmodule
